const A = fn(...Object.values(ctx));

/* ---- real data ---- */
const db = JSON.parse(fs.readFileSync(BAK, 'utf8'));
const mdb = A.ptList(db.pt_masterDB);
const base = A.ptList(db.pt_baseData);
const cut = A.ptList(db.pt_cuttingData);

const ptNumT = v => Number(v) || 0;
let pass = 0, fail = 0;
const ok = (name, cond, detail) => { if (cond) { pass++; console.log('  PASS ' + name); } else { fail++; console.log('  FAIL ' + name + (detail ? ' — ' + detail : '')); } };
const num = s => Number(String(s).replace(/,/g, ''));
/** pull the Nth .metric value out of the KPI html the app just wrote */
const metrics = html => [...html.matchAll(/<div class="v"[^>]*>([\d,]+)<\/div><div class="l">([^<]*?)\s*(?:✕)?\s*<\/div>/g)]
  .reduce((m, x) => (m[x[2].trim()] = num(x[1]), m), {});
/* only the tbody — the thead carries a <tr> of its own and counting it made every
 * expected row count one too high. */
const bodyRows = html => { const m = html.match(/<tbody>([\s\S]*)<\/tbody>/); return m ? (m[1].match(/<tr>/g) || []).length : 0; };

console.log('\n== the data the app is reading ==');
console.log(`   master DB ${mdb.length} · base data ${base.length} · cutting ${cut.length}`);

console.log('\n== dates are read day-first ==');
{
  const d = new Date(A.ptDtMs('26/08/2026, 15:20'));
  ok('26/08/2026 is 26 August', d.getDate() === 26 && d.getMonth() === 7 && d.getFullYear() === 2026,
    'got ' + d.toString());
  // The trap: 03/06/2026 is 3 June, not 6 March. Date.parse would say March.
  const e = new Date(A.ptDtMs('03/06/2026, 09:00'));
  ok('03/06/2026 is 3 June, not 6 March', e.getDate() === 3 && e.getMonth() === 5, 'got ' + e.toString());
  ok('a blank date is 0, not NaN', A.ptDtMs('') === 0 && A.ptDtMs(null) === 0);
}

console.log('\n== Master Database ==');
A.setPT(Object.assign(A.PT(), { mdb }));
A.renderPmdb();
{
  const k = metrics(els.ptmKpis.innerHTML);
  ok('every SKU is counted', k['SKUs shown'] === mdb.length, `card says ${k['SKUs shown']}, backup has ${mdb.length}`);
  const cutReq = mdb.filter(r => r.cuttingRequired).length;
  ok('"cutting required" matches the data', k['Cutting required'] === cutReq, `card ${k['Cutting required']} vs ${cutReq}`);
  const zip = mdb.filter(r => r.isZip).length;
  ok('"with zip" matches the data', k['With zip'] === zip, `card ${k['With zip']} vs ${zip}`);
  ok('the table is capped, not truncated silently', bodyRows(els.ptmTable.innerHTML) === 600 && /showing the first 600/.test(els.ptmMsg.textContent),
    `${bodyRows(els.ptmTable.innerHTML)} rows, msg="${els.ptmMsg.textContent}"`);
  ok('the message is plain text, no markup leaking through', !/[<>]/.test(els.ptmMsg.textContent), els.ptmMsg.textContent);
}
{ // a filter narrows the set, and the other dropdowns narrow with it
  const brand = mdb.find(r => r.brand)?.brand;
  els.ptmBrand.value = brand;
  A.renderPmdb();
  const expect = mdb.filter(r => String(r.brand).toLowerCase() === String(brand).toLowerCase()).length;
  const k = metrics(els.ptmKpis.innerHTML);
  ok(`brand "${brand}" narrows to its own SKUs`, k['SKUs shown'] === expect, `card ${k['SKUs shown']} vs ${expect}`);
  const artOpts = (els.ptmArt.innerHTML.match(/<option/g) || []).length - 1;
  const artAll = new Set(mdb.map(r => String(r.articleType || '').trim()).filter(Boolean)).size;
  const artForBrand = new Set(mdb.filter(r => String(r.brand).toLowerCase() === String(brand).toLowerCase())
    .map(r => String(r.articleType || '').trim()).filter(Boolean)).size;
  ok('the Article list shows only what this brand has', artOpts === artForBrand && artForBrand < artAll,
    `${artOpts} options, brand has ${artForBrand}, all brands have ${artAll}`);
  els.ptmBrand.value = '';
}
{ // a search that matches nothing must say so rather than showing everything
  els.ptmQ.value = 'zzzz-no-such-sku';
  A.renderPmdb();
  ok('a search with no matches shows no rows', bodyRows(els.ptmTable.innerHTML) === 0, els.ptmMsg.textContent);
  els.ptmQ.value = '';
  A.renderPmdb();
}

console.log('\n== Base Data ==');
A.setPT(Object.assign(A.PT(), { base }));
A.renderPbase();
{
  const k = metrics(els.pbKpis.innerHTML);
  const s = f => base.reduce((a, r) => a + A.ptNum(r[f]), 0);
  ok('entries counted', k['Entries'] === base.length, `${k['Entries']} vs ${base.length}`);
  ok('issued total matches the register', k['Issued'] === s('issuePieces'), `${k['Issued']} vs ${s('issuePieces')}`);
  ok('received total matches', k['Received'] === s('receivedPieces'), `${k['Received']} vs ${s('receivedPieces')}`);
  ok('rejected total matches', k['Rejected'] === s('rejectionPieces'), `${k['Rejected']} vs ${s('rejectionPieces')}`);
  ok('pending total matches', k['Pending pieces'] === s('pendingPieces'), `${k['Pending pieces']} vs ${s('pendingPieces')}`);
  ok('completed + open = every entry', k['Completed'] + k['Open'] === base.length,
    `${k['Completed']} + ${k['Open']} vs ${base.length}`);
  ok('completed = the frozen rows', k['Completed'] === base.filter(r => r.frozen).length);
}
{ // newest first
  const rows = A.PT()._pbaseRows;
  let sorted = true;
  for (let i = 1; i < rows.length; i++) if (A.ptDtMs(rows[i - 1].issueDate) < A.ptDtMs(rows[i].issueDate)) { sorted = false; break; }
  ok('the register reads newest issue first', sorted);
}
{ // clicking a KPI narrows the table but must NOT move the other figures
  const before = metrics(els.pbKpis.innerHTML);
  A.setBdKpi('pending');
  A.renderPbase();
  const after = metrics(els.pbKpis.innerHTML);
  ok('clicking Pending leaves every other figure where it was',
    JSON.stringify(before) === JSON.stringify(after), JSON.stringify(after));
  const shown = A.PT()._pbaseRows;
  ok('…and the rows shown are only the ones with pending pieces',
    shown.length === base.filter(r => A.ptNum(r.pendingPieces) > 0).length && shown.every(r => A.ptNum(r.pendingPieces) > 0),
    `${shown.length} rows`);
  A.setBdKpi(''); A.renderPbase();
}
{ // "same thing base data ke liye karo" — Issued, Received and Rejected are filters too, by a click
  const click = key => (els.pbKpis._listeners.click || []).forEach(fn => fn({ type: 'click',
    target: { closest: () => ({ getAttribute: () => key }) } }));
  const before = metrics(els.pbKpis.innerHTML);
  click('rejected');
  const rej = A.PT()._pbaseRows;
  ok('clicking Rejected shows only entries with rejected pieces',
    A.bdKpi() === 'rejected' && rej.length === base.filter(r => A.ptNum(r.rejectionPieces) > 0).length
    && rej.every(r => A.ptNum(r.rejectionPieces) > 0), `${rej.length} rows`);
  ok('…and says so under the filters', /only entries with Rejected/.test(els.pbMsg.textContent), els.pbMsg.textContent);
  ok('…without moving the figures', metrics(els.pbKpis.innerHTML)['Entries'] === before['Entries']);
  click('received');
  ok('clicking Received swaps to entries with pieces back',
    A.PT()._pbaseRows.length === base.filter(r => A.ptNum(r.receivedPieces) > 0).length);
  click('received');
  ok('clicking it again shows every entry', A.bdKpi() === '' && A.PT()._pbaseRows.length === base.length);
  click('issued'); click('');
  ok('clicking Entries shows every entry', A.bdKpi() === '' && A.PT()._pbaseRows.length === base.length);
  A.setBdKpi('rejected'); els.pbClear.onclick();
  ok('Clear lets the figure go', A.bdKpi() === '');
}
{ // date window, day-first
  const withDates = base.map(r => A.ptDtMs(r.issueDate)).filter(Boolean).sort((a, b) => a - b);
  const mid = new Date(withDates[Math.floor(withDates.length / 2)]);
  const iso = d => new Date(d.getTime() - d.getTimezoneOffset() * 60000).toISOString().slice(0, 10);
  els.pbD1.value = iso(mid);
  els.pbDBy.value = 'issue';          // by the issue date; the default also takes what came back after it
  A.renderPbase();
  const cutoff = new Date(iso(mid) + 'T00:00:00').getTime();
  const expect = base.filter(r => { const ms = A.ptDtMs(r.issueDate); return ms && ms >= cutoff; }).length;
  const k = metrics(els.pbKpis.innerHTML);
  ok(`"issued from ${iso(mid)}" keeps only later entries`, k['Entries'] === expect, `${k['Entries']} vs ${expect}`);
  els.pbD1.value = ''; els.pbDBy.value = ''; A.renderPbase();
}
{ // export covers every filtered row, not just the 600 painted
  DOWNLOADS = [];
  els.pbExport._listeners; // no-op, the app assigns .onclick
  A.renderPbase();
}

