console.log('\n== the order list follows the typed SKU ==');
{
  /* Four orders and three SKUs, so every answer the dropdown can give is on the table at once:
   *   ORD-A  wants FLT-1, untouched          -> offered, 100 issuable
   *   ORD-B  wants FLT-2                     -> not offered when FLT-1 is typed
   *   ORD-C  wants FLT-1, already all issued -> not offered: nothing left to issue against it
   *   ORD-D  wants FLT-3, which needs cutting and has none -> offered, but not yet issuable
   */
  A.setPTG(Object.assign(A.PTG(), {
    mdb: [{ sku: 'FLT-1', articleType: 'Pillow Cover', subtype: 'Piping', color: 'Blue', size: '18x18', cuttingRequired: false },
          { sku: 'FLT-2', articleType: 'Napkin', subtype: 'Border Napkin', color: 'Red', size: '20x20', cuttingRequired: false },
          { sku: 'FLT-3', articleType: 'Runner', subtype: 'Plain Runner', color: 'Green', size: '14x72', cuttingRequired: true }],
    ob: [{ orderNo: 'ORD-A', sku: 'FLT-1', qty: 100 }, { orderNo: 'ORD-B', sku: 'FLT-2', qty: 60 },
         { orderNo: 'ORD-C', sku: 'FLT-1', qty: 40 }, { orderNo: 'ORD-D', sku: 'FLT-3', qty: 50 }],
    press: [],
  }));
  A.setPT(Object.assign(A.PT(), {
    base: [{ id: 'bf1', orderNo: 'ORD-C', sku: 'FLT-1', issuePieces: 40, receivedPieces: 0 }], cut: [],
  }));
  A.setPTE(Object.assign(A.PTE(), { emp: [['Company Contractor', 'Lokesh Mahawar', 'Stitching', '']] }));
  els.bwCustom.checked = false;

  const render = (sku, typed) => {
    els.bwSku.value = sku;
    els.bwSku.dataset.typed = typed ? '1' : '';
    els.bwOrd.value = '';
    A.renderBdForm();
    return els.bwOrd.innerHTML;
  };

  /* With nothing typed the list is every open order — which is the right answer to "what is open". */
  const all = render('', false);
  ok('untyped, every open order is still offered',
    /ORD-A/.test(all) && /ORD-B/.test(all) && /ORD-D/.test(all), all);

  const one = render('FLT-1', true);
  ok('the order that wants this SKU is offered', /ORD-A/.test(one), one);
  ok('an order for a different SKU is NOT offered', !/ORD-B/.test(one), one);
  ok('an order already filled for this SKU is NOT offered', !/ORD-C/.test(one), one);
  ok('the balance shown is this SKU\'s, not the order\'s', /100 pcs issuable/.test(one), one);
  ok('the placeholder is still there to go back to', /Select Order ID/.test(one), one);

  /* Lower case in the box must not empty the list — every other SKU comparison here is case-blind. */
  ok('a lower-case SKU finds the same order', /ORD-A/.test(render('flt-1', true)), els.bwOrd.innerHTML);

  /* Ordered but not cut is NOT the same as not ordered, and the list must not conflate them. */
  const cutBound = render('FLT-3', true);
  ok('an order waiting on cutting is still offered', /ORD-D/.test(cutBound), cutBound);
  ok('…and says so rather than showing a figure that cannot be issued',
    /awaiting cutting/.test(cutBound), cutBound);

  /* Cut some, and the same order starts naming a number. */
  A.setPT(Object.assign(A.PT(), { cut: [{ id: 'c1', orderNo: 'ORD-D', sku: 'FLT-3', pieces: 20, rejected: false }] }));
  ok('once it is cut, the number appears', /20 pcs issuable/.test(render('FLT-3', true)), els.bwOrd.innerHTML);
  A.setPT(Object.assign(A.PT(), { cut: [] }));

  /* A SKU on no open order: an empty dropdown has to say why, or it reads as a broken form. */
  const none = render('FLT-NOWHERE', true);
  ok('a SKU on no open order offers no order', !/<option value="ORD/.test(none), none);
  ok('…and the form says so instead of leaving an empty box',
    /No open order is waiting for FLT-NOWHERE/.test(els.bwLeft.textContent), els.bwLeft.textContent);
  ok('…and it reads as a fact worth noticing', els.bwLeft.className === 'err', els.bwLeft.className);

  /* Typing it back in must clear that, not leave the warning standing. */
  render('FLT-1', true);
  ok('a SKU that does have an order clears the warning',
    !/No open order/.test(els.bwLeft.textContent), els.bwLeft.textContent);

  /* ORDER FIRST is the other way round this form is used: the SKU box is filled in BY the form from
   * the order already picked, and filtering on that would strand you on one order with no way back. */
  els.bwSku.value = 'FLT-1';
  els.bwSku.dataset.typed = '';
  els.bwOrd.value = '';
  A.renderBdForm();
  ok('a SKU the form filled in itself does not narrow the list',
    /ORD-B/.test(els.bwOrd.innerHTML), els.bwOrd.innerHTML);

  /* Custom mode has no Order ID at all — the filter must not reach into it. */
  els.bwCustom.checked = true;
  els.bwSku.value = 'FLT-NOWHERE';
  els.bwSku.dataset.typed = '1';
  A.renderBdForm();
  ok('Custom mode still saves without an order',
    /Custom order/.test(els.bwLeft.textContent), els.bwLeft.textContent);
  els.bwCustom.checked = false;
  els.bwSku.value = '';
  els.bwSku.dataset.typed = '';

  /* CLEAR. Until now the only way to empty this form was to close and reopen it, and even that left
   * the line underneath standing. */
  els.bwCustom.checked = true;
  els.bwOrd.value = 'ORD-A'; els.bwAt.value = 'Pillow Cover'; els.bwSub.value = 'Piping';
  els.bwCol.value = 'Blue'; els.bwSz.value = '18x18'; els.bwColTxt.value = 'Teal'; els.bwSzTxt.value = '9x9';
  els.bwSku.value = 'FLT-1'; els.bwSku.dataset.typed = '1';
  els.bwEmp.value = 'Lokesh Mahawar'; els.bwPcs.value = '12'; els.bwRemarks.value = 'note';
  els.bwDate.value = '2026-01-01';
  els.bwMsg.textContent = 'Reading the master database and the order book…';
  els.bwClear.onclick();

  ok('Clear empties the item fields',
    !els.bwOrd.value && !els.bwAt.value && !els.bwSub.value && !els.bwCol.value && !els.bwSz.value,
    [els.bwOrd.value, els.bwAt.value, els.bwSub.value, els.bwCol.value, els.bwSz.value].join('|'));
  ok('…and the SKU, and the fact that it was typed',
    !els.bwSku.value && !els.bwSku.dataset.typed, els.bwSku.value + '/' + els.bwSku.dataset.typed);
  ok('…and the employee, pieces and remarks',
    !els.bwEmp.value && !els.bwPcs.value && !els.bwRemarks.value,
    [els.bwEmp.value, els.bwPcs.value, els.bwRemarks.value].join('|'));
  ok('…and the free-text colour and size behind Custom mode',
    !els.bwColTxt.value && !els.bwSzTxt.value, els.bwColTxt.value + '|' + els.bwSzTxt.value);
  ok('…and it unticks Custom Order — Clear means back to how this opened', els.bwCustom.checked === false);
  ok('…and the date goes back to today, not blank', els.bwDate.value === '2026-09-04', els.bwDate.value);
  ok('…and the stale line underneath goes with it',
    /Cleared/.test(els.bwMsg.textContent) && !/Reading the master/.test(els.bwMsg.textContent),
    els.bwMsg.textContent);

  /* A save must NOT untick Custom, or a run of one-off entries re-ticks the box every time. */
  els.bwCustom.checked = true;
  A.bdClearForm();
  ok('a plain form-clear leaves Custom mode alone', els.bwCustom.checked === true);
  els.bwCustom.checked = false;

  A.setPTG(Object.assign(A.PTG(), { ob: A.ptList(db.pt_orderBook), mdb, press: A.ptList(db.pt_pressInventory) }));
  A.setPT(Object.assign(A.PT(), { base, cut }));
}

