console.log('\n== Master Database: what a row must have ==');
{
  const base = { sku: 'X-1', articleType: 'Napkin', subtype: 'Border Napkin', color: 'Red', size: '20x20' };
  ok('a complete row passes', A.mdbValidate(Object.assign({}, base), '') === '');
  ok('no SKU is refused', /SKU is required/.test(A.mdbValidate(Object.assign({}, base, { sku: '' }), '')));
  ok('no article type is refused', /Article type/.test(A.mdbValidate(Object.assign({}, base, { articleType: '' }), '')));
  ok('a duplicate SKU is refused', /already in the master database/.test(A.mdbValidate(Object.assign({}, base, { sku: 'MDB-FREE' }), '')));
  ok('…but editing a row keeps its own SKU', A.mdbValidate(Object.assign({}, base, { sku: 'MDB-FREE' }), 'MDB-FREE') === '');

  /* A Yes with no number is what makes a SKU look complete and behave as if it were not. */
  ok('zip Yes with no size is refused', /Zip size/.test(A.mdbValidate(Object.assign({}, base, { isZip: 'yes' }), '')));
  ok('zip Yes with a size passes', A.mdbValidate(Object.assign({}, base, { isZip: 'yes', chainLength: '20' }), '') === '');
  ok('ruffle Yes with no metres is refused', /Ruffle metres/.test(A.mdbValidate(Object.assign({}, base, { isRuffle: 'yes' }), '')));
  ok('filler Yes with no quantity is refused', /filling quantity/.test(A.mdbValidate(Object.assign({}, base, { fillerFabricRequired: 'yes' }), '')));
  ok('a negative valuation price is refused', /not negative/.test(A.mdbValidate(Object.assign({}, base, { inventoryValuationPrice: '-1' }), '')));
}

