console.log('\n== renaming a SKU moves every reference ==');
{
  /* This is the whole point: the master row alone would leave the live rows pointing at nothing. */
  const from = 'OLD-1', to = 'NEW-1';
  A.setPTG(Object.assign(A.PTG(), {
    mdb: [{ _key: 'k9', sku: from, articleType: 'A', subtype: 'B', color: 'C', size: 'D' }],
    ob: [{ id: 'o1', orderNo: 'O-1', sku: from, qty: 10 }],
    press: [{ id: 'p1', sku: from, pieces: 5 }],
  }));
  A.setPT(Object.assign(A.PT(), {
    base: [{ id: 'b1', sku: from }, { id: 'b2', sku: 'OTHER' }],
    cut: [{ id: 'c1', sku: from }],
    mdb: A.PTG().mdb,
  }));
  A.setQC({ checks: [{ id: 'q1', sku: from }], issue: [{ id: 'i1', sku: from }], err: '', busy: false, at: '' });

  const seen = [];
  ['pt_baseData', 'pt_cuttingData', 'pt_pressInventory', 'pt_qcChecks', 'pt_qcIssuance', 'pt_orderBook']
    .forEach(n => seen.push(n));
  // Build the same update map the rename builds, from the same data, and check what it touches.
  const upd = {};
  upd['pt_masterDB/k9/sku'] = to;
  [['pt_baseData', A.PT().base], ['pt_cuttingData', A.PT().cut], ['pt_pressInventory', A.PTG().press],
   ['pt_qcChecks', A.QC().checks], ['pt_qcIssuance', A.QC().issue], ['pt_orderBook', A.PTG().ob]]
    .forEach(([n, list]) => (list || []).filter(r => A.obUC(r.sku) === from)
      .forEach(r => { upd[`${n}/${r.id || r._key}/sku`] = to; }));
  ok('every register that holds the code is touched',
    seen.every(n => Object.keys(upd).some(k => k.startsWith(n + '/'))), Object.keys(upd).join(' | '));
  ok('a row with a different SKU is left alone', !Object.keys(upd).includes('pt_baseData/b2/sku'));
  ok('six live rows plus the master row', Object.keys(upd).length === 7, String(Object.keys(upd).length));
}


console.log('\n== every table: header and body must line up ==');
{
  /* A column added to the head and not the body shifts every value one place left, and nothing
   * throws. This has bitten this project before, on the Shopify Orders table. */
  const cols = html => {
    const h = (html.match(/<thead>[\s\S]*?<\/thead>/) || [''])[0];
    const b = (html.match(/<tbody>([\s\S]*?)<\/tbody>/) || ['', ''])[1];
    const firstRow = (b.match(/<tr[^>]*>[\s\S]*?<\/tr>/) || [''])[0];
    return { head: (h.match(/<th[\s>]/g) || []).length, body: (firstRow.match(/<td[\s>]/g) || []).length };
  };
  const check = (name, id) => {
    const c = cols(els[id].innerHTML);
    ok(`${name}: ${c.head} headers, ${c.body} cells`, c.body > 0 && c.head === c.body,
      c.body === 0 ? 'no rows rendered' : `${c.head} vs ${c.body}`);
  };

  ME.admin = true;
  A.setPTG(Object.assign(A.PTG(), { mdb, ob: A.ptList(db.pt_orderBook), press: A.ptList(db.pt_pressInventory),
    masters: db.pt_masters || {}, freeze: {}, err: '', busy: false }));
  A.setPT(Object.assign(A.PT(), { mdb, base, cut, err: { mdb: '', base: '', cut: '' },
    busy: { mdb: false, base: false, cut: false }, at: { mdb: '', base: '', cut: '' } }));
  A.setPP({ err: '', busy: false, at: '', freeze: {} });
  A.setQC({ checks: A.ptList(db.pt_qcChecks), issue: A.ptList(db.pt_qcIssuance), err: '', busy: false, at: '' });

  els.ptmView.value = 'master'; els.ptmQ.value = '';
  A.renderPmdb(); check('Master Database', 'ptmTable');
  A.renderPbase(); check('Base Data', 'pbTable');
  A.renderPcut(); check('Cutting Data', 'pcTable');
  A.renderPpress(); check('Press Inventory', 'ppTable');
  els.qcView.value = 'checks'; A.renderQc(); check('QC — checks', 'qcTable');
  els.qcView.value = 'issue'; A.renderQc(); check('QC — issued for alteration', 'qcTable');
  els.qcView.value = 'checks';
}

