console.log('\n== Order Console: the line, and what happened to it ==');
{
  A.setPTG(Object.assign(A.PTG(), {
    ob: [{ id: 'l1', orderNo: 'O-7', sku: 'S-7', qty: 100, orderDate: '2026-09-01',
           articleType: 'Napkin', articleSubtype: 'Border Napkin', color: 'Red', size: '20x20' },
         { id: 'l2', orderNo: 'O-7', sku: 'S-7', qty: 20, orderDate: '2026-09-01' }],
    press: [{ id: 'p1', orderNo: 'O-7', sku: 'S-7', pieces: 30 }],
    mdb: [{ sku: 'S-7', articleType: 'Napkin', subtype: 'Border Napkin', color: 'Red', size: '20x20', cuttingRequired: true }],
  }));
  A.setPT(Object.assign(A.PT(), {
    base: [{ id: 'b1', orderNo: 'O-7', sku: 'S-7', issuePieces: 50, receivedPieces: 40 }],
    cut: [{ id: 'c1', orderNo: 'O-7', sku: 'S-7', pieces: 95 }],
  }));
  A.setORD({ req: {}, busy: false, at: '', rows: [] });

  const l = A.ordLines();
  ok('two lines of the same order and SKU become one row', l.length === 1, String(l.length));
  ok('…with their quantities added', l[0].qty === 120, String(l[0].qty));
  ok('cut, issued, received and pressed are all reported',
    l[0].cut === 95 && l[0].issued === 50 && l[0].received === 40 && l[0].pressed === 30,
    JSON.stringify({ cut: l[0].cut, iss: l[0].issued, rec: l[0].received, pr: l[0].pressed }));
  ok('still to cut and still to make are the two different gaps',
    l[0].pendingCut === 25 && l[0].pendingMake === 80,
    JSON.stringify({ cut: l[0].pendingCut, make: l[0].pendingMake }));
  /* A PIECE THAT CAME BACK FROM THE STITCHER IS MADE. Pressing is the stage after making, not what
   * makes a piece exist — 40 came back and only 30 were pressed, so 40 are made, not 30. */
  ok('…and a piece received back counts as made, not as still to make',
    l[0].made === 40 && l[0].pendingMake === 120 - 40,
    JSON.stringify({ made: l[0].made, make: l[0].pendingMake }));
  /* Received alone — pressing is not added in, and does not stand in for a receipt either. */
  ok('…and pressing is not added to it', l[0].made === 40 && l[0].made !== 70, String(l[0].made));
  /* made - pressed, not ordered - pressed: 40 came back and 30 were pressed, so 10 are made and
   * waiting. Summing ordered - pressed across every line once produced a 'made' total larger than
   * the number of pieces that existed. */
  ok('what is made but not yet pressed is its own figure', l[0].madeToPress === 10, String(l[0].madeToPress));

  /* The threshold is the old tool's, and it exists because a cut is never exactly the ordered
   * number — the fabric decides. 120 pieces needs 90%. */
  ok('95 of 120 is 79% and not yet done', !l[0].cutDone, l[0].cutPct.toFixed(1));
  A.setPT(Object.assign(A.PT(), { cut: [{ id: 'c1', orderNo: 'O-7', sku: 'S-7', pieces: 108 }] }));
  ok('108 of 120 is 90% and counts as done', A.ordLines()[0].cutDone);
  A.setPTG(Object.assign(A.PTG(), { ob: [{ id: 'l1', orderNo: 'O-8', sku: 'S-7', qty: 300 }] }));
  A.setPT(Object.assign(A.PT(), { cut: [{ id: 'c2', orderNo: 'O-8', sku: 'S-7', pieces: 273 }] }));
  ok('over 250 the bar is 95%, so 91% is not done', !A.ordLines()[0].cutDone, A.ordLines()[0].cutPct.toFixed(1));
  A.setPT(Object.assign(A.PT(), { cut: [{ id: 'c2', orderNo: 'O-8', sku: 'S-7', pieces: 285 }] }));
  ok('…and 95% is', A.ordLines()[0].cutDone);
}

