console.log('\n== payout: paid on what came back, dated by when it came back ==');
{
  A.setHR({ emp: [['Company Contractor', 'Ramesh', 'Stitching', '']],
    rate: [['Napkin', 'Border Napkin', '20x20', 'Company Contractor', 10, 'NA'],
           ['Napkin', 'Border Napkin', '20x20', 'External Contractor', 8, 'NA']],
    eh: [], freeze: {}, freezes: {}, adv: [], err: '', busy: false, at: '', rows: [] });
  A.setPT(Object.assign(A.PT(), { base: [
    // issued in the first half, RETURNED in the second — it belongs to the second.
    { id: 'p1', empType: 'Company Contractor', empName: 'Ramesh', articleType: 'Napkin',
      articleSubtype: 'Border Napkin', size: '20x20', issuePieces: 50, receivedPieces: 50,
      issueDate: '05/09/2026, 10:00', receivingDate: '20/09/2026, 10:00' },
    // returned in the first half
    { id: 'p2', empType: 'Company Contractor', empName: 'Ramesh', articleType: 'Napkin',
      articleSubtype: 'Border Napkin', size: '20x20', issuePieces: 30, receivedPieces: 30,
      issueDate: '02/09/2026, 10:00', receivingDate: '10/09/2026, 10:00' },
    // issued but nothing back yet — pays nothing
    { id: 'p3', empType: 'Company Contractor', empName: 'Ramesh', articleType: 'Napkin',
      articleSubtype: 'Border Napkin', size: '20x20', issuePieces: 99, receivedPieces: 0,
      issueDate: '03/09/2026, 10:00', receivingDate: '' },
  ] }));

  const h1 = A.payRows('Company Contractor', 1, 2026, 9);
  const h2 = A.payRows('Company Contractor', 2, 2026, 9);
  ok('the first half holds only what came back in it', h1.length === 1 && h1[0].recvPcs === 30, JSON.stringify(h1));
  ok('work returned after the 15th falls in the second half', h2.length === 1 && h2[0].recvPcs === 50);
  ok('nothing received pays nothing', h1[0].recvPcs + h2[0].recvPcs === 80);
  ok('the amount is pieces times the rate', h1[0].amount === 300 && h2[0].amount === 500,
    JSON.stringify({ a: h1[0].amount, b: h2[0].amount }));

  const full = A.payRows('Company Contractor', 3, 2026, 9);
  ok('the full month merges both halves into one line', full.length === 1 && full[0].recvPcs === 80);
  ok('…and its amount is the sum', full[0].amount === 800, String(full[0].amount));
}

console.log('\n== a frozen fortnight does not move when a rate changes ==');
{
  /* This is the rule that protects money already paid. */
  A.setHR(Object.assign(A.HR(), { freezes: { 'Company Contractor|2026-09': {
    frozen: { 1: true },
    periods: { 1: [{ empName: 'Ramesh', articleType: 'Napkin', subtype: 'Border Napkin', size: '20x20', recvPcs: 30, rate: 10, amount: 300 }] },
  } } }));
  A.setHR(Object.assign(A.HR(), { rate: [['Napkin', 'Border Napkin', '20x20', 'Company Contractor', 999, 'NA']] }));
  const h1 = A.payRows('Company Contractor', 1, 2026, 9);
  ok('the frozen half still pays what it paid', h1[0].amount === 300, String(h1[0].amount));
  const h2 = A.payRows('Company Contractor', 2, 2026, 9);
  ok('the live half picks up the new rate', h2[0].rate === 999, String(h2[0].rate));
  const full = A.payRows('Company Contractor', 3, 2026, 9);
  /* The old tool re-multiplies the merged pieces by one rate here, which pays the frozen half at
   * today's price. Amounts are summed instead: 300 frozen + 50x999 live. */
  ok('the full month adds the frozen amount to the live one, it does not re-price it',
    full[0].amount === 300 + 50 * 999, String(full[0].amount));
  ok('…and reports the rate as mixed rather than inventing a blended one', full[0].rate === null, String(full[0].rate));
  ok('a frozen half reports itself as frozen', A.payFrozen('Company Contractor', 2026, 9, 1) === true);
  ok('…and the other half does not', A.payFrozen('Company Contractor', 2026, 9, 2) === false);
  ok('the month is only frozen when both halves are', A.payFrozen('Company Contractor', 2026, 9, 3) === false);
  A.setHR(Object.assign(A.HR(), { freezes: {}, rate: [['Napkin', 'Border Napkin', '20x20', 'Company Contractor', 10, 'NA']] }));
}

