console.log('\n== group drilldown: why a line is 86 and not 101 ==');
{
  A.setHR(Object.assign(A.HR(), {
    rate: [['Table Runner', 'Table Runner', '16X90', 'Company Contractor', 7, 'NA']], freezes: {}, adv: [] }));
  const g = { empName: 'Binod Kumar', articleType: 'Table Runner', subtype: 'Table Runner', size: '16X90' };
  const mk = (id, sku, issue, recv, iso, rd) => ({ id, empType: 'Company Contractor', empName: 'Binod Kumar',
    articleType: 'Table Runner', articleSubtype: 'Table Runner', size: '16X90', sku,
    issuePieces: issue, receivedPieces: recv, issueDate: iso, receivingDate: rd });
  A.setPT(Object.assign(A.PT(), { base: [
    mk('d1', 'RTR72-1690', 35, 35, '01/09/2026, 17:27', '04/09/2026, 15:58'),
    mk('d2', 'RTR41-1690', 12, 12, '04/09/2026, 16:15', '05/09/2026, 14:20'),
    mk('d3', 'CPCTR007-1690', 39, 39, '31/08/2026, 15:12', '02/09/2026, 14:40'),
    mk('d4', 'RTR298-1690', 2, 0, '05/09/2026, 18:23', ''),
    mk('d5', 'RTR72-1690', 15, 15, '27/08/2026, 18:47', '29/08/2026, 17:12'),
    mk('d6', 'RTR99-1690', 9, 9, '02/09/2026, 10:00', '20/09/2026, 10:00'),
    // a different person's row must not appear in a CC group
    Object.assign(mk('d7', 'RTR72-1690', 5, 5, '01/09/2026, 10:00', '03/09/2026, 10:00'), { empName: 'Someone Else' }),
  ] }));

  const rows = A.payDrill('Company Contractor', g, 1, 2026, 9);
  ok('only this person\'s rows are in the group', rows.length === 6 && !rows.some(x => x.r.id === 'd7'), String(rows.length));
  const paid = rows.filter(x => x.verdict === 'COUNTED');
  ok('three rows are counted in the first half', paid.length === 3, String(paid.length));
  ok('…and they add up to 86', paid.reduce((s, x) => s + x.recv, 0) === 86,
    String(paid.reduce((s, x) => s + x.recv, 0)));

  const why = id => (rows.find(x => x.r.id === id) || {}).why || '';
  ok('a row still out says so', /no receiving date/.test(why('d4')), why('d4'));
  ok('a row returned in another month says which', /different month/.test(why('d5')), why('d5'));
  ok('a row returned in the other fortnight says the window', /outside 2026-09-01 to 2026-09-15/.test(why('d6')), why('d6'));
  ok('a counted row says why it counted', /counted in the total/.test(why('d1')), why('d1'));

  /* The whole point: what was dropped explains the gap. */
  const recvAll = rows.reduce((s, x) => s + x.recv, 0);
  const dropped = rows.filter(x => x.verdict === 'EXCLUDED').reduce((s, x) => s + x.recv, 0);
  ok('counted plus excluded is everything received — the gap is never unexplained',
    paid.reduce((s, x) => s + x.recv, 0) + dropped === recvAll,
    JSON.stringify({ paid: 86, dropped, recvAll }));

  const w = A.payWindow(1, 2026, 9);
  ok('the first half is the 1st to the 15th', w.from === '2026-09-01' && w.to === '2026-09-15');
  const w2 = A.payWindow(2, 2026, 9);
  ok('the second half runs to the real end of the month', w2.from === '2026-09-16' && w2.to === '2026-09-30');
  const wf = A.payWindow(2, 2026, 2);
  ok('…including February', wf.to === '2026-02-28', wf.to);
}

