console.log('\n== fabric inventory: the balance is the ledger ==');
{
  const rows = A.ptList(db.pt_fabInvLedger);
  A.setFAB({ rows, err: '', busy: false, at: '', shown: [] });
  ok('the real ledger loads', rows.length === 511, String(rows.length));

  ok('a receipt adds', A.fabMove({ txnType: 'OPENING', qty: 20 }) === 20);
  ok('an issue subtracts', A.fabMove({ txnType: 'ISSUE_TO_CUTTING', qty: 20 }) === -20);
  ok('a receipt from the printer adds', A.fabMove({ txnType: 'RECEIVE_PRINTED', qty: 5 }) === 5);
  /* Cutting white cloth moves it between locations; the same metres still exist. */
  ok('cutting white moves nothing in total', A.fabMove({ txnType: 'CUT_WHITE', qty: 30 }) === 0);
  /* A correction of −20 must stay −20; flipping it would turn every write-down into a write-up. */
  ok('an adjustment keeps its own sign', A.fabMove({ txnType: 'ADJUST', qty: -20 }) === -20);
  ok('an unknown movement moves nothing rather than guessing',
    A.fabMove({ txnType: 'SOMETHING_NEW', qty: 99 }) === 0 && A.fabKnown('SOMETHING_NEW') === false);

  const bal = A.fabBalances(rows);
  ok('a balance line exists per fabric and colour', bal.length > 0 && bal.every(b => 'fabricType' in b && 'colour' in b));
  /* Every line must reconcile against its own rows — a balance nobody can trace is worthless. */
  const one = bal.find(b => b.n > 3) || bal[0];
  const mine = rows.filter(r => String(r.fabricType || '').trim() === one.fabricType
    && String(r.colour || '').trim() === one.colour);
  const sum = mine.reduce((s, r) => s + A.fabMove(r), 0);
  ok(`${one.fabricType} / ${one.colour} reconciles to its own rows`, Math.abs(one.qty - sum) < 1e-9,
    `${one.qty} vs ${sum}`);
  ok('in minus out is the balance', Math.abs((one.inQty - one.outQty) - one.qty) < 1e-9);

  const total = bal.reduce((s, b) => s + b.qty, 0);
  const gross = rows.reduce((s, r) => s + A.fabMove(r), 0);
  ok('every row is in exactly one balance line', Math.abs(total - gross) < 1e-9, `${total} vs ${gross}`);
}

