  let heads = (h.match(/<th\b/g) || []).length;
  let firstRow = (h.match(/<tr>(?:(?!<\/tr>)[\s\S])*<\/tr>/g) || []).filter(x => /<td/.test(x))[0] || '';
  let cells = (firstRow.match(/<td\b/g) || []).length;
  ok('by SKU: every header has exactly one cell under it', heads > 0 && heads === cells,
    heads + ' headers vs ' + cells + ' cells');
  ok('the Shopify order numbers are on the combined row', /#5001/.test(h) && /#5002/.test(h));

  h = show('shoporder');
