  firstRow = (h.match(/<tr>(?:(?!<\/tr>)[\s\S])*<\/tr>/g) || []).filter(x => /<td/.test(x))[0] || '';
  cells = (firstRow.match(/<td\b/g) || []).length;
  ok('by order: every header has exactly one cell under it', heads > 0 && heads === cells,
    heads + ' headers vs ' + cells + ' cells');
