console.log('\n== editing a placed order ==');
{
  const mkVO = () => A.setVO({ rows: [{ vendorCode: 'VND005', id: 'e1', orderNo: 'VPO-E1', orderType: 'cut',
    orderDate: '25/08/2026', status: 'Partially Dispatched', notes: 'first note', lines: [
      { sku: 'RTC301-6090', articleSubtype: 'Plain', color: 'Red', size: '60x90', qty: 10,
        deliveries: [{ qty: 4, date: '04/09/2026', by: 'p@x', at: '2026-09-04T00:00:00Z' }] },
      { sku: 'RCNBMIX', articleSubtype: 'Plain', color: 'Blue', size: '20x20', qty: 5, deliveries: [] },
    ] }], busy: false, err: '', at: '', shown: [] });

  /* The dialog's inputs, stubbed the way the browser would hand them back. Cancellation is NOT an
   * input: the row is redrawn every time a line is cancelled or restored, so a checkbox would lose
   * its state on the redraw — the dialog keeps it in VOE.cancel instead. */
  const put = (vals, cancels) => { Object.keys(QS).forEach(k => delete QS[k]);
    vals.forEach((v, i) => { QS['[data-voe="' + i + '"]'] = { value: String(v), disabled: false }; });
    const cx = new Set();
    (cancels || []).forEach((c, i) => { if (c) cx.add(i); });
    A.setVOE(Object.assign({}, A.VOE(), { cancel: cx })); };

  mkVO(); ME.admin = true; A.setVOE({ key: 'VND005/e1', lines: null, cancel: new Set() });
  put([12, 5], [false, false]);
  els.ptf_notes = els.ptf_notes || {}; els.ptf_notes.value = 'changed note';
  NET.on = true; NET.calls = [];
  const _r = await A.voEditSave();
  /* The cap is asked about the INCREASE. Raising 10 to 12 adds two, not twelve — its own message
   * used to say 'this adds 12, making 22', which double-counted the line against itself. */
  ok('the cap is asked about the increase, not the whole line', !/adds 12/.test(_r), _r);
  ok('a raised quantity saves where there is room', _r === '' || /Over the cap/.test(_r), _r);
  /* Lowering needs no cap at all, so this is where the write itself is proved. */
  A.setVOE({ key: 'VND005/e1', lines: null, cancel: new Set() }); put([8, 5], [false, false]);
  ok('a lowered quantity saves', (await A.voEditSave()) === '', els.voMsg.textContent);
  ok('the new quantity is written', (A.VO().rows[0].lines[0].qty) === 8, String(A.VO().rows[0].lines[0].qty));
  ok('the note comes with it', A.VO().rows[0].notes === 'changed note', A.VO().rows[0].notes);
  ok('and who changed it is recorded', !!A.VO().rows[0].staffUpdatedBy);

  /* THE ONE THAT MATTERS: 4 pieces are already delivered on that line. */
  mkVO(); A.setVOE({ key: 'VND005/e1', lines: null, cancel: new Set() }); put([2, 5], [false, false]);
  const err = await A.voEditSave();
  ok('a quantity below what is already delivered is refused', /already delivered/.test(err), err);
  ok('and nothing was written', A.VO().rows[0].lines[0].qty === 10, String(A.VO().rows[0].lines[0].qty));

  mkVO(); A.setVOE({ key: 'VND005/e1', lines: null, cancel: new Set() }); put(['abc', 5], [false, false]);
  ok('a quantity that is not a number is refused', /not a quantity/.test(await A.voEditSave()));

  /* A LINE WITH GOODS AGAINST IT CANNOT BE CANCELLED. voSummary counts only live lines, so its four
   * delivered pieces would leave the order while the challan for them stayed in History — the two
   * screens would disagree and neither would be wrong. */
  mkVO(); A.setVOE({ key: 'VND005/e1', lines: null, cancel: new Set() }); put([10, 5], [true, true]);
  ok('a line with deliveries against it cannot be cancelled',
    /already delivered against it/.test(await A.voEditSave()), await A.voEditSave());
  ok('…and nothing is written when it is refused',
    A.VO().rows[0].lines.every(l => !l.cancelled));

  /* And when nothing is in the way, cancelling the lot is still refused for its own reason. */
  {
    const clean = JSON.parse(JSON.stringify(A.VO().rows[0]));
    clean.lines[0].deliveries = [];
    A.setVO(Object.assign(A.VO(), { rows: [clean] }));
    A.setVOE({ key: 'VND005/e1', lines: null, cancel: new Set() }); put([10, 5], [true, true]);
    ok('cancelling every line is refused — cancel the order instead',
      /Every line is cancelled/.test(await A.voEditSave()), await A.voEditSave());
  }

  /* ---- CANCELLING WITHOUT OPENING ANYTHING. "edit window ko alag se open karni ki need nahi h bahi
   * option de dedo cancel ka and ek sath me multiple sku select krna ha." To cancel one SKU you
   * opened the order, scrolled a 113-line list inside a dialog, pressed Cancel, then Save. For five
   * you did that five times. ---- */
  {
    mkVO();
    const key = 'VND005/e1';
    ok('nothing ticked is said, not silently ignored',
       /Tick the line/.test(await A.voCancelPicked(key, true)));

    /* Line 1 has no deliveries; line 0 has four. */
    A.setVO(Object.assign(A.VO(), { pick: { [key]: new Set([1]) } }));
    ok('a ticked line is cancelled from the card, with no dialog at all',
       (await A.voCancelPicked(key, true)) === '');
    ok('…and it is marked cancelled, not removed',
       A.VO().rows[0].lines.length === 2 && A.VO().rows[0].lines[1].cancelled === true);
    ok('…and the ticks are cleared once it is done', !A.voPicked(key));

    /* Restoring is the same act in reverse, and needs no dialog either. */
    A.setVO(Object.assign(A.VO(), { pick: { [key]: new Set([1]) } }));
    ok('and a cancelled line can be restored the same way',
       (await A.voCancelPicked(key, false)) === '' && A.VO().rows[0].lines[1].cancelled === false);

    /* The same rule as the dialog, so the two cannot disagree about what may be cancelled. */
    mkVO();
    A.setVO(Object.assign(A.VO(), { pick: { [key]: new Set([0, 1]) } }));
    const e2 = await A.voCancelPicked(key, true);
    ok('a delivered line stops the whole press, rather than half of it going through',
       /already delivered against it/.test(e2) && /Nothing was changed/.test(e2), e2);
    ok('…and neither line was touched', A.VO().rows[0].lines.every(l => !l.cancelled));

    /* MANY AT ONCE is the point of it. */
    mkVO();
    const many = JSON.parse(JSON.stringify(A.VO().rows[0]));
    many.lines = [many.lines[0], many.lines[1],
      { sku: 'A', qty: 3, deliveries: [] }, { sku: 'B', qty: 4, deliveries: [] }];
    A.setVO(Object.assign(A.VO(), { rows: [many], pick: { [key]: new Set([1, 2, 3]) } }));
    ok('three ticked lines go in one press', (await A.voCancelPicked(key, true)) === '');
    ok('…all three of them', A.VO().rows[0].lines.filter(l => l.cancelled).length === 3);
    ok('…and the one that was not ticked is untouched', A.VO().rows[0].lines[0].cancelled !== true);

    /* An order with nothing live left is not an order — on a line that nothing else stops. */
    {
      const two = { vendorCode: 'VND005', id: 'e1', orderNo: 'VPO-E1', orderType: 'cut',
        orderDate: '25/08/2026', status: 'Placed', lines: [
          { sku: 'CLEAN-1', qty: 5, deliveries: [] },
          { sku: 'CLEAN-2', qty: 5, deliveries: [], cancelled: true }] };
      A.setVO(Object.assign(A.VO(), { rows: [two], pick: { [key]: new Set([0]) } }));
      ok('and the last live line cannot be cancelled from here either',
         /cancel every line/i.test(await A.voCancelPicked(key, true)), await A.voCancelPicked(key, true));
      ok('…and it is still live afterwards', A.VO().rows[0].lines[0].cancelled !== true);
    }

    ok('the rule itself names the reason', /already delivered/.test(A.voWhyNoCancel({ deliveries: [{ qty: 4 }] })));
    ok('…and a line with nothing against it has no reason', A.voWhyNoCancel({ qty: 5 }) === '');

    /* ---- CHANGING A QUANTITY WITHOUT THE POPUP, by the popup's own rules. Two ways into the same
     * order that disagree about what is allowed are worse than one way in. ---- */
    {
      mkVO();
      Object.keys(QS).forEach(k => { if (/data-voqty/.test(k)) delete QS[k]; });
      const q = (i, v) => { QS['[data-voqty="' + key + '"][data-i="' + i + '"]'] = { value: String(v) }; };

      q(0, 10); q(1, 5);
      ok('nothing typed differently is said, not written', /Nothing changed/.test(await A.voSaveQty(key)));

      /* Down, not up: RCNBMIX has no approved demand behind it, so its cap is nil and any increase
       * is over it. That is the cap doing its job, and it gets its own test below. */
      q(1, 4);
      const qe = await A.voSaveQty(key); ok('a changed quantity saves from the card', qe === '', qe);
      ok('…and it is the new figure that is stored', A.VO().rows[0].lines[1].qty === 4,
         String(A.VO().rows[0].lines[1].qty));

      /* Line 0 has 4 delivered. Below that is a contradiction, not a correction. */
      mkVO(); q(0, 2); q(1, 5);
      const e3 = await A.voSaveQty(key);
      ok('a figure below what is already delivered is refused here too',
         /already delivered/.test(e3) && /Nothing was changed/.test(e3), e3);
      ok('…and nothing was written', A.VO().rows[0].lines[0].qty === 10);

      mkVO(); q(0, 'abc'); q(1, 5);
      ok('something that is not a quantity is refused', /not a quantity/.test(await A.voSaveQty(key)));

      /* An increase answers to the printer cap, or editing an order would be the way around a limit
       * that placing one obeys. Nothing has been approved for RCNBMIX, so its cap is nil and even one
       * piece more is over it. */
      mkVO(); q(0, 10); q(1, 6);
      const e4 = await A.voSaveQty(key);
      ok('an increase past the cap is refused', /Over the cap/.test(e4), e4);
      ok('…and the cap says what the room actually is', /may go to printers is 0/.test(e4), e4);
      ok('…and nothing was written for that either', A.VO().rows[0].lines[1].qty === 5);

      ME.admin = false;
      mkVO(); q(1, 9);
      ok('and only an admin may change a quantity', /Only an admin/.test(await A.voSaveQty(key)));
      ME.admin = true;
    }
  }

  mkVO(); A.setVOE({ key: 'VND005/e1', lines: null, cancel: new Set() }); put([10, 5], [false, true]);
  ok('cancelling one line is fine', (await A.voEditSave()) === '');
  ok('and it is marked cancelled, not removed',
    A.VO().rows[0].lines.length === 2 && A.VO().rows[0].lines[1].cancelled === true);

  ME.admin = false; mkVO(); A.setVOE({ key: 'VND005/e1', lines: null, cancel: new Set() }); put([10, 5], [false, false]);
  ok('a non-admin cannot change a vendor order', /Only an admin/.test(await A.voEditSave()));
  ME.admin = true;
  NET.on = false; Object.keys(QS).forEach(k => delete QS[k]);
}

console.log('\n== deleting, and what it refuses to destroy ==');
{
  const two = () => A.setVO({ rows: [
    { vendorCode: 'VND005', id: 'd1', orderNo: 'VPO-D1', orderType: 'cut', orderDate: '25/08/2026',
      lines: [{ sku: 'A', qty: 5, deliveries: [] }] },
    { vendorCode: 'VND005', id: 'd2', orderNo: 'VPO-D2', orderType: 'cut', orderDate: '25/08/2026',
      lines: [{ sku: 'B', qty: 5, deliveries: [{ qty: 2, date: '04/09/2026', by: 'p@x', at: '2026-09-04T00:00:00Z' }] }] },
  ], busy: false, err: '', at: '', shown: [] });

  two(); NET.on = true; NET.calls = [];
  ok('an order nothing has been delivered against can be deleted',
    (await A.voDelete('VND005/d1')) === '');
  ok('and it is gone', !(A.VO().rows || []).some(o => o.id === 'd1'));

  /* Delete is not cancel. Removing an order removes the deliveries the logbook is built from. */
  two();
  const err = await A.voDelete('VND005/d2');
  ok('an order WITH deliveries is refused', /delivery\(ies\) recorded/.test(err), err);
  ok('and it says to cancel it instead', /Cancel it instead/.test(err));
  ok('nothing was deleted', (A.VO().rows || []).some(o => o.id === 'd2'));

  /* Bulk: the safe ones go, the ones holding history stay, and it says which. */
  two();
  A.VO_PICKED().clear(); A.VO_PICKED().add('VND005/d1'); A.VO_PICKED().add('VND005/d2');
  CONFIRM = true;
  await A.voDeletePicked();
  ok('the one with no deliveries is deleted', !(A.VO().rows || []).some(o => o.id === 'd1'));
  ok('the one holding delivery history is KEPT', (A.VO().rows || []).some(o => o.id === 'd2'));
  ok('and the message names what was kept and why',
    /kept because deliveries/.test(els.voMsg.textContent) && /VPO-D2/.test(els.voMsg.textContent),
    els.voMsg.textContent);

  /* If every ticked order holds history, nothing happens at all and it says so. */
  two(); A.VO_PICKED().clear(); A.VO_PICKED().add('VND005/d2');
  NET.calls = [];
  await A.voDeletePicked();
  ok('all-held is refused outright', /None of the/.test(els.voMsg.textContent), els.voMsg.textContent);
  ok('and no write was attempted', !NET.calls.some(c => c.method === 'PATCH'));

  ME.admin = false;
  A.VO_PICKED().clear(); A.VO_PICKED().add('VND005/d1');
  await A.voDeletePicked();
  ok('a non-admin cannot bulk delete', /Only an admin/.test(els.voMsg.textContent));
  ME.admin = true; A.VO_PICKED().clear();
  NET.on = false;
}


console.log('\n== pictures for an account that cannot reach the backend ==');
{
  /* A printer has perms.repl = false: no config/api, no Price Research backend, and no Firestore
   * image cache either. Every picture it will ever see has to come from the shared node. */
  A.setPTG(Object.assign(A.PTG(), { mdb: [{ sku: 'CPC004-120', imageUrl: '' }] }));
  A.setPTIMG({ map: { 'CPC004-120': 'https://m.media-amazon.com/img/a.jpg' }, loaded: true, dirty: {} });
  ok('a picture comes from the shared node', A.ptImgOf('CPC004-120') === 'https://m.media-amazon.com/img/a.jpg',
    String(A.ptImgOf('CPC004-120')));
  ok('a SKU nobody has a picture for is still undefined, not a broken image',
    A.ptImgOf('CPC004-12R') === undefined, String(A.ptImgOf('CPC004-12R')));
  ok('the cell shows a dash rather than a broken picture', /—|none/.test(A.ptImgCell('CPC004-12R')),
    A.ptImgCell('CPC004-12R'));
  ok('and a real one renders an img', /<img/.test(A.ptImgCell('CPC004-120')), A.ptImgCell('CPC004-120'));

  /* A master row's own picture still wins — that rule has not changed. */
  A.setPTG(Object.assign(A.PTG(), { mdb: [{ sku: 'CPC004-120', imageUrl: 'https://own/pic.jpg' }] }));
  ok('a picture typed on the master row still beats the shared one',
    A.ptImgOf('CPC004-120') === 'https://own/pic.jpg', String(A.ptImgOf('CPC004-120')));
  A.setPTG(Object.assign(A.PTG(), { mdb: [] }));
  A.setPTIMG({ map: {}, loaded: false, dirty: {} });
}


console.log('\n== the challan check: somebody confirms the goods arrived ==');
{
  const mk = () => A.setVO({ rows: [
    { vendorCode: 'VND005', id: 'k1', orderNo: 'VPO-K1', orderType: 'cut', orderDate: '25/08/2026',
      lines: [{ sku: 'TC211-70108', articleSubtype: 'Rectangular Tablecloth', color: 'Natural Spring',
        size: '70X108', qty: 30, deliveries: [
          { qty: 19, date: '05/09/2026', by: 'p9929932527@vendors-tfr.app', at: '2026-09-05T05:00:00Z' },
          { qty: 5, date: '05/09/2026', by: 'p9929932527@vendors-tfr.app', at: '2026-09-05T06:00:00Z' }] }] },
  ], busy: false, err: '', at: '', shown: [] });
  const clear = () => ['vlVendor', 'vlType', 'vlFrom', 'vlTo', 'vlQ', 'vlState'].forEach(i => { els[i].value = ''; });

  mk(); ME.admin = true; A.VL_PICKED().clear(); clear(); A.renderVlog();
  const rows = A.VLOG().rows;
  ok('both deliveries are waiting to start with', rows.length === 2 && rows.every(r => !r.ok));
  ok('the screen says so', /waiting for somebody to confirm/.test(els.vlMsg.textContent), els.vlMsg.textContent);
  ok('and the row offers Accept', /data-vl-ok=/.test(els.vlTable.innerHTML));

  /* UNTIL SOMEBODY ACCEPTS, THE PRINTER'S OWN FIGURE STANDS. 177 deliveries are already on record
   * with none accepted — demanding acceptance first would show every order as nothing-received. */
  const line = A.voLines(A.VO().rows[0])[0];
  ok('nothing accepted yet still counts as delivered', A.voDone(line) === 24, String(A.voDone(line)));

  /* Accepting exactly what was claimed changes the count not at all. */
  NET.on = true; NET.calls = [];
  ok('accepting as claimed goes through',
    (await A.vlAcceptWrite([rows[0]], (r, d) => parseFloat(d.qty) || 0, 'challan 1201')) === '');
  A.renderVlog();
  ok('the total is unchanged', A.voDone(A.voLines(A.VO().rows[0])[0]) === 24,
    String(A.voDone(A.voLines(A.VO().rows[0])[0])));
  ok('but it is now marked accepted', A.VLOG().rows[0].ok && A.VLOG().rows[0].ok.qty === 19,
    JSON.stringify(A.VLOG().rows[0].ok));
  ok('with who accepted it', A.VLOG().rows[0].ok.by === ME.email);
  ok('and the challan number kept', A.VLOG().rows[0].ok.note === 'challan 1201');

  /* A SHORT DELIVERY is the reason the count is editable. Five were claimed, three arrived. */
  ok('accepting fewer than claimed goes through',
    (await A.vlAcceptWrite([A.VLOG().rows[1]], () => 3, 'two short')) === '');
  A.renderVlog();
  const l2 = A.voLines(A.VO().rows[0])[0];
  ok('the ACCEPTED figure is what counts now', A.voDone(l2) === 22, String(A.voDone(l2)));
  ok('the printer sees the same answer, not a different one', A.vpDone(l2) === 22, String(A.vpDone(l2)));
  /* The claim is never overwritten — a shortfall has to stay visible months later. */
  const short = A.VLOG().rows.find(r => r.ok && r.ok.qty === 3);
  ok('what the printer said is kept beside it', short.qty === 5, String(short.qty));
  ok('and the screen shows how many were short', /2 short/.test(els.vlTable.innerHTML),
    (els.vlTable.innerHTML.match(/\d+ short/) || ['(none)'])[0]);

  /* The cached totals the other screens read are rewritten from the deliveries, never added to. */
  ok('the stored figure agrees with the deliveries', A.voLines(A.VO().rows[0])[0].vendorQty === 22,
    String(A.voLines(A.VO().rows[0])[0].vendorQty));
  NET.on = false;
}

console.log('\n== who may accept, and what the filters show ==');
{
  const clear = () => ['vlVendor', 'vlType', 'vlFrom', 'vlTo', 'vlQ', 'vlState'].forEach(i => { els[i].value = ''; });
  clear();
  els.vlState.value = 'pending'; A.renderVlog();
  ok('"waiting" shows only what nobody has confirmed', A.VLOG().rows.every(r => !r.ok));
  els.vlState.value = 'accepted'; A.renderVlog();
  ok('"accepted" shows only what somebody has', A.VLOG().rows.every(r => !!r.ok) && A.VLOG().rows.length === 2,
    String(A.VLOG().rows.length));
  els.vlState.value = 'short'; A.renderVlog();
  ok('"accepted short" finds the one that came up short',
    A.VLOG().rows.length === 1 && A.VLOG().rows[0].ok.qty === 3, String(A.VLOG().rows.length));
  clear(); A.renderVlog();

  /* THE RIGHT IS ITS OWN GRANT NOW. It used to come with the History section — anybody who could
   * LOOK at what printers had sent could accept it, and an acceptance creates the fabric stock and
   * settles what that printer is paid. Ravi, 18 Sep: "jo bhi access jo dene chahiye but abhi nahi h." */
  const wasVlVP = A.VP();
  A.setVP(Object.assign({}, wasVlVP, { code: '' }));
  ME.admin = false; ME.tabs = ['vlog']; ME.vlogAccept = false;
  ok('the History section alone no longer lets somebody accept', A.vlCanAccept() === false);
  ME.vlogAccept = true;
  ok('…the grant does', A.vlCanAccept() === true);
  ME.vlogAccept = false; ME.tabs = ['vord'];
  ok('somebody without it may not', A.vlCanAccept() === false);
  /* Caught: with the gate gone this reaches the database and throws, and a throw would take the
   * suite with it instead of failing this line. */
  let vlTried;
  try { vlTried = await A.vlAcceptWrite([A.VLOG().rows[0]], () => 1, ''); }
  catch (e) { vlTried = 'threw: ' + (e.message || e); }
  ok('and the attempt is refused, not ignored',
    /Can accept printer deliveries/.test(String(vlTried)), String(vlTried));
  ok('the Accept button is not even drawn for them',
    (A.renderVlog(), !/data-vl-ok=/.test(els.vlTable.innerHTML)));
  A.setVP(wasVlVP);
  ME.admin = true; ME.tabs = []; ME.vlogAccept = false;
}


console.log('\n== last week, and how it compares ==');
{
  /* Weeks run Sunday to Saturday. 30 Aug 2026 is a Sunday, so that week is 30 Aug – 5 Sep and the
   * one before it is 23 – 29 Aug. */
  ok('a week starts on its Sunday',
    A.repWkIso(A.repWeekStart(new Date(2026, 8, 2).getTime())) === '2026-08-30',
    A.repWkIso(A.repWeekStart(new Date(2026, 8, 2).getTime())));
  ok('a Sunday is its own week start',
    A.repWkIso(A.repWeekStart(new Date(2026, 7, 30).getTime())) === '2026-08-30');
  ok('the week before is seven days back', A.repWkShift('2026-08-30', -1) === '2026-08-23');
  ok('and it crosses a month end without help', A.repWkShift('2026-09-06', -1) === '2026-08-30');
  ok('the range reads the way somebody says it', A.repWkRange('2026-08-30') === '30 Aug – 5 Sep',
    A.repWkRange('2026-08-30'));

  const recv = (date, sku, at, pcs) => ({ id: 'b' + Math.random(), receivingDate: date, sku,
    articleType: at, issuePieces: pcs, receivedPieces: pcs, rejectionPieces: 0, pendingPieces: 0 });
  A.setPTG(Object.assign(A.PTG(), {
    mdb: [{ sku: 'A1', articleType: 'Napkin', packOf: '4', brand: 'SP' },
          { sku: 'B1', articleType: 'Tablecloth', packOf: '', brand: 'SP' },
          { sku: 'C1', articleType: 'Quilt', packOf: '', brand: 'SP' }],
    press: [] }));
  A.setPT(Object.assign(A.PT(), { base: [
      /* week of 23 Aug */
      recv('24/08/2026', 'A1', 'Napkin', 400),
      recv('25/08/2026', 'B1', 'Tablecloth', 100),
      recv('26/08/2026', 'C1', 'Quilt', 50),
      /* week of 30 Aug — napkins up, tablecloths down, quilts stopped, a new article appears */
      recv('31/08/2026', 'A1', 'Napkin', 600),
      recv('01/09/2026', 'B1', 'Tablecloth', 80),
    ] }));
  els.repBrand.value = '';
  const w = A.repWow('2026-08-30', '', false);
  ok('it compares against the week before', w.prevWeek === '2026-08-23', w.prevWeek);

  const by = {}; w.rows.forEach(r => { by[r.art] = r; });
  ok('an article that went up says so', by.Napkin.prod === 600 && by.Napkin.prevProd === 400
    && Math.round(by.Napkin.pct) === 50, JSON.stringify(by.Napkin));
  ok('customer-facing divides by the pack size', Math.round(by.Napkin.cust) === 150,
    String(Math.round(by.Napkin.cust)));
  ok('an article that went down says so', by.Tablecloth.delta === -20
    && Math.round(by.Tablecloth.pct) === -20, JSON.stringify(by.Tablecloth));
  /* An article that STOPPED is -100%, and it must still be listed — a row that vanishes is the one
   * nobody notices has stopped. */
  ok('an article that stopped is still listed', !!by.Quilt, Object.keys(by).join(', '));
  ok('and reads as down the whole way', by.Quilt.prod === 0 && Math.round(by.Quilt.pct) === -100,
    JSON.stringify(by.Quilt));
  ok('the biggest is first', w.rows[0].art === 'Napkin', w.rows.map(r => r.art).join(', '));
}

console.log('\n== a percentage needs something to be a percentage of ==');
{
  /* THE ONE THAT WOULD HAVE PRINTED ∞%. An article made for the first time has no previous week to
   * be a percentage of; both 100% and infinity would be inventions. */
  const recv = (date, sku, at, pcs) => ({ id: 'b' + Math.random(), receivingDate: date, sku,
    articleType: at, issuePieces: pcs, receivedPieces: pcs, rejectionPieces: 0, pendingPieces: 0 });
  A.setPTG(Object.assign(A.PTG(), {
    mdb: [{ sku: 'N1', articleType: 'Runner', packOf: '', brand: 'SP' }],
    press: [] }));
  A.setPT(Object.assign(A.PT(), { base: [recv('31/08/2026', 'N1', 'Runner', 320)],
  }));
  const w = A.repWow('2026-08-30', '', false);
  ok('a brand-new article is listed', w.rows.length === 1 && w.rows[0].art === 'Runner');
  ok('its percentage is not a number at all', w.rows[0].pct === null, String(w.rows[0].pct));
  ok('and the cell says "new" rather than a made-up figure',
    /new/.test(A.repPctCell(w.rows[0])) && !/Infinity|NaN|%/.test(A.repPctCell(w.rows[0])),
    A.repPctCell(w.rows[0]));

  /* And on screen, the whole report must not carry an Infinity anywhere. */
  els.repView.value = 'wow'; els.repBrand.value = '';
  A.renderRep();
  const h = els.repTable.innerHTML + els.repKpis.innerHTML;
  ok('nothing on the screen says Infinity or NaN', !/Infinity|NaN/.test(h), h.slice(0, 200));
  ok('the week picker offers finished weeks only, newest first',
    els.repWk.innerHTML.indexOf('option') >= 0, els.repWk.innerHTML.slice(0, 80));
  ok('the totals row is there', /All articles/.test(els.repTable.innerHTML));
  /* Counted off the RENDERED table. A header that disagrees with its cells by one puts every
   * column after it over the wrong data, and the totals row has to line up as well. */
  {
    const t = els.repTable.innerHTML;
    /* '<th' also matches '<thead>' — count the two real openings instead, which is why this
     * check said 7 headers against 6 cells when the table was right all along. */
    const count = (txt, tag) => (txt.split(tag + ' ').length - 1) + (txt.split(tag + '>').length - 1);
    const th = count(t, '<th');
    const body = t.slice(t.indexOf('<tbody>'), t.indexOf('</tbody>'));
    const firstRow = body.slice(body.indexOf('<tr>'), body.indexOf('</tr>'));
    const td = count(firstRow, '<td');
    const foot = t.slice(t.indexOf('<tfoot>'), t.indexOf('</tfoot>'));
    const ftd = count(foot, '<td');
    ok('every header has one cell under it', th > 0 && th === td, th + ' headers vs ' + td + ' cells');
    ok('and the totals row lines up too', th === ftd, th + ' headers vs ' + ftd + ' total cells');
  }
}

