console.log('\n== the report counts receipts, not press ==');
{
  /* The two registers disagree, and that is the whole reason for the change. Press only began on
   * 31 August; Base Data goes back three weeks. If the report ever drifts back onto press entries,
   * this is what catches it. */
  const recv = (date, sku, at, pcs) => ({ id: 'b' + Math.random(), receivingDate: date, sku,
    articleType: at, issuePieces: pcs, receivedPieces: pcs, rejectionPieces: 0, pendingPieces: 0 });
  A.setPTG(Object.assign(A.PTG(), {
    mdb: [{ sku: 'A1', articleType: 'Napkin', packOf: '4', brand: 'SP' }],
    /* A press entry that must NOT appear: it is in the week being asked about. */
    press: [{ id: 'px', entryDate: '31/08/2026', sku: 'A1', articleType: 'Napkin', pieces: 9999 }],
  }));
  A.setPT(Object.assign(A.PT(), { base: [recv('31/08/2026', 'A1', 'Napkin', 400)] }));
  const w = A.repWow('2026-08-30', '', false);
  ok('the figure is what came back, not what went through the press',
    w.rows.length === 1 && w.rows[0].prod === 400, JSON.stringify(w.rows.map(r => r.prod)));
  ok('the press entry is nowhere in it', !w.rows.some(r => r.prod === 9999));

  /* Issued but not returned is not production received. */
  A.setPT(Object.assign(A.PT(), { base: [
    recv('31/08/2026', 'A1', 'Napkin', 400),
    { id: 'b2', sku: 'A1', articleType: 'Napkin', issuePieces: 300, receivedPieces: 0, pendingPieces: 300 },
  ] }));
  ok('work still out with a worker is not counted', A.repWow('2026-08-30', '', false).rows[0].prod === 400,
    String(A.repWow('2026-08-30', '', false).rows[0].prod));

  /* Rejected is its own column — pendingPieces is issued − received − rejected — so it is already
   * out of receivedPieces and must not be subtracted a second time. */
  A.setPT(Object.assign(A.PT(), { base: [
    { id: 'b3', receivingDate: '31/08/2026', sku: 'A1', articleType: 'Napkin',
      issuePieces: 100, receivedPieces: 90, rejectionPieces: 10, pendingPieces: 0 },
  ] }));
  ok('rejected pieces are not deducted twice', A.repWow('2026-08-30', '', false).rows[0].prod === 90,
    String(A.repWow('2026-08-30', '', false).rows[0].prod));

  /* A part-received row has no receiving date yet — it cannot be put in a week, and saying so beats
   * dropping it. */
  A.setPT(Object.assign(A.PT(), { base: [
    recv('31/08/2026', 'A1', 'Napkin', 400),
    { id: 'b4', sku: 'A1', articleType: 'Napkin', issuePieces: 50, receivedPieces: 20, pendingPieces: 30 },
  ] }));
  els.repView.value = 'wow'; els.repWk.value = '2026-08-30'; els.repBrand.value = '';
  A.renderRep();
  ok('a part-received row is not silently swallowed',
    /20 piece\(s\) have come back but carry no receiving date/.test(els.repMsg.textContent),
    els.repMsg.textContent);
  ok('and it is not counted in a week it cannot be dated into',
    A.repWow('2026-08-30', '', false).rows[0].prod === 400);

  /* ================= THE CHARTS =================
   *
   * Every figure on a chart is in the table below it, and none of these is allowed to be the only
   * place a number can be read. What they add is the shape. */
  {
    /* ---- the arithmetic under the axis ---- */
    ok('an axis stops at a number a person would say',
       [A.repNice(4513), A.repNice(870), A.repNice(120), A.repNice(0)].join(',') === '5000,1000,200,1',
       [A.repNice(4513), A.repNice(870), A.repNice(120), A.repNice(0)].join(','));

    const weeks = ['2026-08-09', '2026-08-16', '2026-08-23', '2026-08-30'];
    const labels = ['9 Aug', '16 Aug', '23 Aug', '30 Aug'];
    const svg = A.repTrendSvg(weeks, [1532, 3928, 2775, 4513], labels);
    ok('the weeks are drawn as columns', /<svg/.test(svg) && (svg.match(/<rect/g) || []).length === 4,
       String((svg.match(/<rect/g) || []).length));
    /* THE EMPHASIS FORM. The whole report is one week against the ones before it, so that week is the
     * only one in the accent and the rest are the grey it is measured against. Eight colours for one
     * number is the commonest way a chart misses its own point. */
    ok('…the week being reported on is the only one in the accent',
       (svg.match(/#4f46e5/g) || []).length === 1 && (svg.match(/#94a3b8/g) || []).length >= 3,
       'accent ' + (svg.match(/#4f46e5/g) || []).length + ' dim ' + (svg.match(/#94a3b8/g) || []).length);
    /* LABEL SELECTIVELY. A number on every mark goes unread. */
    ok('…only that one carries its figure', (svg.match(/font-weight="700"/g) || []).length === 2,
       String((svg.match(/font-weight="700"/g) || []).length));
    ok('…and every column says what it is on hover',
       (svg.match(/<title>/g) || []).length === 4, String((svg.match(/<title>/g) || []).length));
    ok('…with a gridline that is solid, not dashed', /<line[^>]*stroke-width="1"/.test(svg) && !/stroke-dasharray/.test(svg));
    ok('a week with nothing in it still draws', /<svg/.test(A.repTrendSvg(weeks, [0, 0, 0, 0], labels)));
    ok('…and no weeks at all draws nothing', A.repTrendSvg([], [], []) === '');

    /* ---- the articles ---- */
    const many = Array.from({ length: 12 }, (_, i) => ({ art: 'Article ' + (i + 1), prod: 100 - i * 5 }));
    const bars = A.repShareSvg(many);
    /* PAST ABOUT SEVEN CLASSES A CHART STOPS BEING READ, and the table below carries them all. */
    ok('the articles are the top eight and one Other', /Other/.test(bars)
       && (bars.match(/<rect/g) || []).length === 9, String((bars.match(/<rect/g) || []).length));
    /* SAME COLOUR ON EVERY BAR. Shading them by length says the length twice and burns the only free
     * channel on something the bar already shows. */
    ok('…every article bar the same colour', (bars.match(/fill="#4f46e5"/g) || []).length === 8,
       String((bars.match(/fill="#4f46e5"/g) || []).length));
    ok('…and the tail told apart from them by its mark, not by its label',
       (bars.match(/rx="4" fill="#94a3b8"/g) || []).length === 1,
       String((bars.match(/rx="4" fill="#94a3b8"/g) || []).length));
    ok('…with the value outside the bar, where its own mark cannot clip it',
       /<rect[^>]*\/><text|<\/rect><text/.test(bars) || /<text[^>]*font-weight="600"/.test(bars), bars.slice(0, 200));
    ok('nothing to show draws nothing', A.repShareSvg([]) === '' && A.repShareSvg([{ art: 'x', prod: 0 }]) === '');

    /* ---- the sparkline ---- */
    const sp = A.repSparkSvg([10, 20, 5, 40], labels);
    ok('a row carries the shape of its weeks', (sp.match(/<rect/g) || []).length === 4,
       String((sp.match(/<rect/g) || []).length));
    ok('…with the last week in the accent and the rest not',
       (sp.match(/#4f46e5/g) || []).length === 1 && (sp.match(/#94a3b8/g) || []).length === 3);
    ok('…and no axis or labels on it, because the figures are beside it', !/<text/.test(sp));
    ok('…a week of nothing draws no bar', (A.repSparkSvg([0, 0, 5], labels).match(/<rect/g) || []).length === 1);
    ok('…and no weeks draws nothing', A.repSparkSvg([]) === '');

    /* ---- on the screen ---- */
    els.repView.value = 'wow'; els.repWk.value = '2026-08-30'; els.repBrand.value = '';
    A.renderRep();
    ok('the report draws both panels', (els.repCharts.innerHTML.match(/<svg/g) || []).length === 2,
       String((els.repCharts.innerHTML.match(/<svg/g) || []).length));
    ok('…each one saying what it plots', /Pieces received each week/.test(els.repCharts.innerHTML)
       && /What came back last week/.test(els.repCharts.innerHTML));
    ok('…and the table carries a trend column', /<th>Trend<\/th>/.test(els.repTable.innerHTML),
       els.repTable.innerHTML.slice(0, 300));
    /* A CHART FROM ONE VIEW MUST NOT SIT ABOVE ANOTHER VIEW'S TABLE. */
    els.repView.value = 'wpr'; A.renderRep();
    ok('another view clears them rather than leaving last week above it',
       els.repCharts.innerHTML === '' && els.repCharts.classList.contains('hide'),
       els.repCharts.className + ' / ' + els.repCharts.innerHTML.slice(0, 80));
  }
  els.repView.value = 'wpr';
}


console.log('\n== the indexes must never answer with stale data ==');
{
  /* The whole speed-up rests on caching, and a cache that goes stale is worse than the scan it
   * replaced: it answers confidently with yesterday's row. Every place the app changes these lists
   * replaces the array, so identity-and-length is the signal — these prove it holds for each shape
   * of change the app actually makes. */
  A.setPTG(Object.assign(A.PTG(), { mdb: [
    { _key: 'k1', sku: 'IX1', articleType: 'Napkin', packOf: '4', brand: 'SP' },
    { _key: 'k2', sku: 'IX2', articleType: 'Quilt', packOf: '', brand: 'CPC' },
  ] }));
  ok('a lookup finds its row', A.repAt('IX1', '') === 'Napkin', String(A.repAt('IX1', '')));
  ok('and a SKU that is not there is not invented', A.repAt('NOPE', 'fallback') === 'fallback');

  /* EDIT — the app rebuilds with .map */
  A.setPTG(Object.assign(A.PTG(), { mdb: A.PTG().mdb.map(x =>
    (x._key === 'k1' ? Object.assign({}, x, { articleType: 'Tablecloth' }) : x)) }));
  ok('an edited row is seen, not the cached one', A.repAt('IX1', '') === 'Tablecloth',
    String(A.repAt('IX1', '')));

  /* ADD — .concat */
  A.setPTG(Object.assign(A.PTG(), { mdb: A.PTG().mdb.concat([{ _key: 'k3', sku: 'IX3', articleType: 'Runner', packOf: '' }]) }));
  ok('a newly added SKU is found', A.repAt('IX3', '') === 'Runner', String(A.repAt('IX3', '')));

  /* DELETE — .filter */
  A.setPTG(Object.assign(A.PTG(), { mdb: A.PTG().mdb.filter(x => x.sku !== 'IX3') }));
  ok('a deleted SKU stops being found', A.repAt('IX3', 'gone') === 'gone', String(A.repAt('IX3', 'gone')));

  /* A RELOAD — a whole new list, same length */
  A.setPTG(Object.assign(A.PTG(), { mdb: [
    { _key: 'k1', sku: 'IX1', articleType: 'Curtain', packOf: '2', brand: 'SP' },
    { _key: 'k2', sku: 'IX2', articleType: 'Quilt', packOf: '', brand: 'CPC' },
  ] }));
  ok('a reload of the same size is still seen', A.repAt('IX1', '') === 'Curtain', String(A.repAt('IX1', '')));
  ok('and the pack size comes from the new list too', A.repPack('IX1') === 2, String(A.repPack('IX1')));
  ok('as does the brand', A.repBrand('IX1') === 'SP', String(A.repBrand('IX1')));
}

console.log('\n== and neither may the order-line cache ==');
{
  const ob = (no, sku, qty) => ({ id: 'o_' + no + '_' + sku, orderNo: no, sku, qty, orderDate: '25/08/2026',
    articleType: 'Napkin', articleSubtype: '', color: '', size: '' });
  A.setPTG(Object.assign(A.PTG(), { ob: [ob('AMZ-1', 'IX1', 10)], press: [] }));
  A.setPT(Object.assign(A.PT(), { base: [], cut: [] }));
  ok('the line is there', A.ordLines().length === 1 && A.ordLines()[0].qty === 10,
    JSON.stringify(A.ordLines().map(l => l.qty)));

  /* More pressed against it — the cache is built on PTG.press too, so it must notice. */
  A.setPTG(Object.assign(A.PTG(), { press: [{ id: 'p1', orderNo: 'AMZ-1', sku: 'IX1', pieces: 4 }] }));
  ok('pressing against a line is seen at once', A.ordLines()[0].pressed === 4,
    String(A.ordLines()[0].pressed));
  /* Pressing no longer moves "still to make": made is what came BACK, and nothing has. What press
   * still decides is whether the line is finished. */
  ok('but what is still to make does not follow it — made is what came back',
    A.ordLines()[0].pendingMake === 10, String(A.ordLines()[0].pendingMake));
  ok('…though pressing everything does finish the line',
    (() => { A.setPTG(Object.assign(A.PTG(), { press: [{ id: 'p1', orderNo: 'AMZ-1', sku: 'IX1', pieces: 10 }] }));
      const done = A.ordLines()[0].open === false;
      A.setPTG(Object.assign(A.PTG(), { press: [{ id: 'p1', orderNo: 'AMZ-1', sku: 'IX1', pieces: 4 }] }));
      return done; })());

  /* Issued and received come from Base Data — a different list, same rule. */
  A.setPT(Object.assign(A.PT(), { base: [{ id: 'b1', orderNo: 'AMZ-1', sku: 'IX1', issuePieces: 8, receivedPieces: 3 }] }));
  ok('an issue recorded afterwards is seen', A.ordLines()[0].issued === 8, String(A.ordLines()[0].issued));
  ok('and what came back with it', A.ordLines()[0].received === 3, String(A.ordLines()[0].received));

  /* Cutting is the third. */
  A.setPT(Object.assign(A.PT(), { cut: [{ id: 'c1', orderNo: 'AMZ-1', sku: 'IX1', pieces: 7 }] }));
  ok('cutting recorded afterwards is seen', A.ordLines()[0].cut === 7, String(A.ordLines()[0].cut));
  /* A rejected cut is not cut — the index has to keep that rule, not just the sum. */
  A.setPT(Object.assign(A.PT(), { cut: [{ id: 'c1', orderNo: 'AMZ-1', sku: 'IX1', pieces: 7 },
    { id: 'c2', orderNo: 'AMZ-1', sku: 'IX1', pieces: 5, rejected: true, rejPieces: 5 }] }));
  ok('a rejected cut is taken back off, as it always was', A.ordLines()[0].cut === 7,
    String(A.ordLines()[0].cut));
  /* And the excluding form — the row being edited — still walks and still agrees. */
  ok('excluding a row gives the same answer as before', A.obCutQty('AMZ-1', 'IX1', 'c1') === 0,
    String(A.obCutQty('AMZ-1', 'IX1', 'c1')));

  A.setPTG(Object.assign(A.PTG(), { ob: [ob('AMZ-1', 'IX1', 10), ob('AMZ-1', 'IX2', 5)] }));
  ok('a new order line appears', A.ordLines().length === 2, String(A.ordLines().length));
}


console.log('\n== the order-book lookups must not go stale either ==');
{
  /* Same risk as the other indexes: these decide how much of an order is still open, and a stale
   * answer would let somebody issue against an order that is already full. */
  const ob = (no, sku, qty) => ({ id: 'ob_' + no + '_' + sku, orderNo: no, sku, qty,
    orderDate: '25/08/2026', articleType: 'Napkin', articleSubtype: '', color: '', size: '' });
  A.setPTG(Object.assign(A.PTG(), { ob: [ob('AMZ-9', 'SK1', 100)], press: [] }));
  A.setPT(Object.assign(A.PT(), { base: [], cut: [] }));

  ok('the order asks for what it asks for', A.obOrderedQty('AMZ-9', 'SK1') === 100,
    String(A.obOrderedQty('AMZ-9', 'SK1')));
  ok('a SKU not on the order asks for nothing', A.obOrderedQty('AMZ-9', 'SK2') === 0);
  ok('and it is case-blind, as it always was', A.obOrderedQty('amz-9', 'sk1') === 100,
    String(A.obOrderedQty('amz-9', 'sk1')));
  ok('nothing issued yet', A.obIssueUsed('AMZ-9', 'SK1') === 0, String(A.obIssueUsed('AMZ-9', 'SK1')));

  /* A second order-book row for the same pair adds to it — the index sums, it does not overwrite. */
  A.setPTG(Object.assign(A.PTG(), { ob: [ob('AMZ-9', 'SK1', 100), Object.assign(ob('AMZ-9', 'SK1', 50), { id: 'ob2' })] }));
  ok('two rows for one order and SKU add up', A.obOrderedQty('AMZ-9', 'SK1') === 150,
    String(A.obOrderedQty('AMZ-9', 'SK1')));

  /* Issuing against it must be seen at once — this is what stops a double issue. */
  A.setPT(Object.assign(A.PT(), { base: [{ id: 'b1', orderNo: 'AMZ-9', sku: 'SK1', issuePieces: 40, receivedPieces: 0 }] }));
  ok('an issue is seen straight away', A.obIssueUsed('AMZ-9', 'SK1') === 40,
    String(A.obIssueUsed('AMZ-9', 'SK1')));
  /* What came back is no longer "used" — it is on the shelf. */
  A.setPT(Object.assign(A.PT(), { base: [{ id: 'b1', orderNo: 'AMZ-9', sku: 'SK1', issuePieces: 40, receivedPieces: 15 }] }));
  ok('what came back stops counting as out', A.obIssueUsed('AMZ-9', 'SK1') === 25,
    String(A.obIssueUsed('AMZ-9', 'SK1')));
  /* Pressed pieces count as used too — that rule is unchanged. */
  A.setPTG(Object.assign(A.PTG(), { press: [{ id: 'p1', orderNo: 'AMZ-9', sku: 'SK1', pieces: 10 }] }));
  ok('pressed pieces still count as used', A.obIssueUsed('AMZ-9', 'SK1') === 35,
    String(A.obIssueUsed('AMZ-9', 'SK1')));
  /* And the excluding form — the row being edited — still agrees. */
  ok('excluding the row being edited gives the same answer as before',
    A.obIssueUsed('AMZ-9', 'SK1', 'b1') === 10, String(A.obIssueUsed('AMZ-9', 'SK1', 'b1')));

  /* The open-orders list is what the dropdown is built from. */
  const open = A.bdOpenOrders();
  ok('the order shows as open with the right balance',
    open.length === 1 && open[0].orderNo === 'AMZ-9' && open[0].bal === 115,
    JSON.stringify(open.map(o => o.orderNo + ':' + o.bal)));

  /* Fill it completely and it must drop off the list, not linger. */
  A.setPT(Object.assign(A.PT(), { base: [{ id: 'b1', orderNo: 'AMZ-9', sku: 'SK1', issuePieces: 140, receivedPieces: 0 }] }));
  A.setPTG(Object.assign(A.PTG(), { press: [{ id: 'p1', orderNo: 'AMZ-9', sku: 'SK1', pieces: 10 }] }));
  ok('an order with nothing left open drops off the list', A.bdOpenOrders().length === 0,
    JSON.stringify(A.bdOpenOrders().map(o => o.orderNo + ':' + o.bal)));
}

console.log('\n== editing an entry is a permission, entering one is not ==');
{
  /* Ravi: entering is everybody's job, correcting is his to hand out. So the default — an account
   * with no prodEdit right — must be able to add and NOT to change. */
  const wasAdmin = ME.admin, wasEdit = ME.prodEdit;
  A.setPTG(Object.assign(A.PTG(), {
    mdb: [{ sku: 'PERM-1', articleType: 'Pillow Cover', subtype: 'Piping', color: 'Blue', size: '18x18', cuttingRequired: false }],
    ob: [{ orderNo: 'P-1', sku: 'PERM-1', qty: 100 }],
    press: [{ id: 'pp1', orderNo: 'P-1', sku: 'PERM-1', pieces: 5, entryDate: '01/09/2026, 10:00' }],
  }));
  const baseRow = { id: 'perm_b', sku: 'PERM-1', empName: 'Lokesh Mahawar', empType: 'Company Contractor',
    articleType: 'Pillow Cover', articleSubtype: 'Piping', color: 'Blue', size: '18x18', orderNo: 'P-1',
    issuePieces: 10, receivedPieces: 0, rejectionPieces: 0, pendingPieces: 10,
    issueDate: '01/09/2026, 10:00', receivingDate: '', frozen: false };
  const cutRow = { id: 'perm_c', orderNo: 'P-1', sku: 'PERM-1', pieces: 10, fabricWidth: '44',
    cutDate: '01/09/2026, 10:00', articleType: 'Pillow Cover', articleSubtype: 'Piping', color: 'Blue', size: '18x18' };
  A.setPT(Object.assign(A.PT(), { base: [baseRow], cut: [cutRow] }));

  /* ---- an ordinary account ---- */
  ME.admin = false; ME.prodEdit = false;
  ok('without the right, this account may not edit', A.ptCanEdit() === false);

  A.renderPbase(); A.renderPcut(); A.renderPpress();
  ok('Base Data offers no Edit button', !/data-bd-edit/.test(els.pbTable.innerHTML));
  ok('Cutting offers no Edit button', !/data-cut-edit/.test(els.pcTable.innerHTML));
  ok('Press offers no Edit button', !/data-press-edit/.test(els.ppTable.innerHTML));
  /* The row is still THERE — this is about changing it, not seeing it. */
  ok('…but the entries are still all readable', /PERM-1/.test(els.pbTable.innerHTML)
    && /PERM-1/.test(els.pcTable.innerHTML) && /PERM-1/.test(els.ppTable.innerHTML));
  /* And the receipt boxes stay: taking in what came back is entry, not editing. */
  ok('…and what came back can still be taken in', /data-bd-recv=/.test(els.pbTable.innerHTML));

  /* THE BUTTON IS NOT THE LOCK. A page left open when the right is withdrawn still has it drawn. */
  els.bdModal._hidden = true;
  A.bdEdit('perm_b');
  ok('calling the editor directly is refused, not obeyed', els.bdModal._hidden === true);
  ok('…and it says what is missing', /needs permission/.test(els.pbMsg.textContent), els.pbMsg.textContent);

  els.ptDlg._hidden = true;
  A.cutEdit('perm_c');
  ok('the cutting editor is refused too', els.ptDlg._hidden === true);
  ok('…and says so', /needs permission/.test(els.pcMsg.textContent), els.pcMsg.textContent);

  els.ptDlg._hidden = true;
  A.pressEdit_('pp1');
  ok('and the press editor', els.ptDlg._hidden === true);
  ok('…and says so', /needs permission/.test(els.ppMsg.textContent), els.ppMsg.textContent);

  ok('the refusal points at the fix, and says entering still works',
    /Can edit production entries/.test(A.PT_NO_EDIT) && /still add new entries/.test(A.PT_NO_EDIT), A.PT_NO_EDIT);

  /* ---- the same account, once Ravi grants it ---- */
  ME.prodEdit = true;
  ok('granted, the account may edit', A.ptCanEdit() === true);
  A.renderPbase(); A.renderPcut(); A.renderPpress();
  ok('the Edit button comes back on Base Data', /data-bd-edit/.test(els.pbTable.innerHTML));
  ok('…on Cutting', /data-cut-edit/.test(els.pcTable.innerHTML));
  ok('…and on Press', /data-press-edit/.test(els.ppTable.innerHTML));
  els.bdModal._hidden = true;
  A.bdEdit('perm_b');
  ok('and the editor opens', els.bdModal._hidden === false);

  /* ---- deleting is NOT what was granted: it stays admin-only, as it already was ---- */
  ok('a granted editor still gets no Delete in the row dialog',
    (() => { els.ptDlg._hidden = true; A.cutEdit('perm_c'); return els.ptDlgDelete._hidden === true; })(),
    String(els.ptDlgDelete._hidden));
  ME.admin = true;
  els.ptDlg._hidden = true; A.cutEdit('perm_c');
  ok('an admin does', els.ptDlgDelete._hidden === false, String(els.ptDlgDelete._hidden));

  /* ---- a frozen row is still frozen, granted or not ---- */
  ME.admin = false; ME.prodEdit = true;
  A.setPT(Object.assign(A.PT(), { base: [Object.assign({}, baseRow, { frozen: true })] }));
  A.renderPbase();
  ok('a frozen row offers no Edit even to someone who may edit', !/data-bd-edit/.test(els.pbTable.innerHTML));

  ME.admin = wasAdmin; ME.prodEdit = wasEdit;
  A.setPTG(Object.assign(A.PTG(), { ob: A.ptList(db.pt_orderBook), mdb, press: A.ptList(db.pt_pressInventory) }));
  A.setPT(Object.assign(A.PT(), { base, cut }));
}

console.log("\n== WhatsApp: the production tracker's flow, rule for rule ==");
{
  const wasWA = A.WA(), wasAdmin = ME.admin;
  A.setWA({ cutoff: '2026-06-01', tpl: null, loaded: true });
  A.setPTE(Object.assign(A.PTE(), { emp: [
    ['Company Contractor', 'Lokesh Mahawar', 'Stitching', '+919829675604'],
    ['Company Contractor', 'Sangeeta Devi', 'Embroidery', '9982028893'],   // stored bare — 3 really are
    ['Company Contractor', 'Gazala Bano', 'Thread Cutting', ''],           // 81 of 121 have none
  ] }));

  /* ---- the number ---- */
  ok('a +91 number is passed through', A.waNum('+919829675604') === '919829675604', A.waNum('+919829675604'));
  /* The ONE thing not copied: the old normaliser hands bare ten-digit numbers to wa.me with no
   * country code, and those reach nobody at all. */
  ok('a bare ten-digit number gets its country code', A.waNum('9982028893') === '919982028893', A.waNum('9982028893'));
  ok('spacing and dashes do not matter', A.waNum(' +91 98296-75604 ') === '919829675604', A.waNum(' +91 98296-75604 '));
  ok('nothing on file is nothing, not a broken link', A.waNum('') === '' && A.waNum(null) === '');

  /* ---- the tracker's own message, word for word ---- */
  const row = o => Object.assign({ id: 'wa1', empName: 'Lokesh Mahawar', sku: 'WA-1',
    articleType: 'Pillow Cover', articleSubtype: 'Piping', color: 'Blue', size: '18x18',
    issuePieces: 12, receivedPieces: 0, rejectionPieces: 0, pendingPieces: 12,
    issueDate: '05/09/2026, 10:00', receivingDate: '' }, o);

  ok('the issue template is the tracker\'s, unchanged',
     A.WA_TPL_DEFAULT.issue === 'Hello {empName}, you have been issued {issuePieces} pieces of {articleType} ({subtype}) — {color} {size} on {issueDate}. SKU: {sku}. — {ridhi}',
     A.WA_TPL_DEFAULT.issue);
  const m = A.waMsg(row({}), 'issue');
  ok('and it fills in exactly what the tracker fills in',
     m === 'Hello Lokesh Mahawar, you have been issued 12 pieces of Pillow Cover (Piping) — Blue 18x18 on 05/09/2026. SKU: WA-1. — Ridhi Block Print', m);
  /* The tracker cuts the timestamp to ten characters, so the time never appears in the message. */
  ok('the date is cut to the day, as it is there', !/10:00/.test(m), m);
  const rm = A.waMsg(row({ receivedPieces: 9, rejectionPieces: 2, receivingDate: '06/09/2026, 11:00' }), 'receive');
  ok('the receive message is the tracker\'s too',
     rm === 'Hello Lokesh Mahawar, we have received 9 pieces of Pillow Cover (Piping) — Blue 18x18 from you on 06/09/2026. Thank you! — Ridhi Block Print', rm);
  /* pt_waTemplates is unset today, but the tracker lets a Super Admin change it — and then BOTH
   * tools have to say the new thing, not just the old one. */
  A.setWA(Object.assign(A.WA(), { tpl: { issue: 'Ji {empName}, {issuePieces} pcs {sku} — {ridhi}' } }));
  ok('a template stored in the shared node wins over the built-in one',
     A.waMsg(row({}), 'issue') === 'Ji Lokesh Mahawar, 12 pcs WA-1 — Ridhi Block Print', A.waMsg(row({}), 'issue'));
  ok('…and the other kind still falls back to the tracker\'s default',
     /we have received/.test(A.waMsg(row({ receivedPieces: 5, receivingDate: '06/09/2026, 11:00' }), 'receive')));
  A.setWA(Object.assign(A.WA(), { tpl: null }));

  /* ---- who may be messaged, and why not ---- */
  ME.admin = false;
  ok('a fresh issue may be messaged', A.waWhyBlocked(row({}), 'issue') === '', A.waWhyBlocked(row({}), 'issue'));
  ok('no number means the button says so, not nothing',
     /No WhatsApp number/.test(A.waWhyBlocked(row({ empName: 'Gazala Bano' }), 'issue')),
     A.waWhyBlocked(row({ empName: 'Gazala Bano' }), 'issue'));
  ok('a row before the cutoff names the cutoff',
     /before the WhatsApp cutoff \(2026-06-01\)/.test(A.waWhyBlocked(row({ issueDate: '05/03/2026, 10:00' }), 'issue')),
     A.waWhyBlocked(row({ issueDate: '05/03/2026, 10:00' }), 'issue'));
  ok('nothing received yet cannot be thanked for',
     /Nothing received/.test(A.waWhyBlocked(row({ receivingDate: '06/09/2026, 10:00' }), 'receive')));
  /* THE ONE-SHOT RULE — the tracker's, kept exactly. */
  ok('a row already messaged is spent for an ordinary user',
     /Already sent/.test(A.waWhyBlocked(row({ waIssueSentAt: '2026-09-05T10:00:00Z' }), 'issue')));
  ME.admin = true;
  ok('…but an admin may send it again', A.waWhyBlocked(row({ waIssueSentAt: '2026-09-05T10:00:00Z' }), 'issue') === '');
  ME.admin = false;

  /* ---- the buttons on the row ---- */
  const cell = A.waCell(row({}));
  ok('the row offers an Issue button', /data-wa-row="wa1\|issue"/.test(cell), cell);
  ok('…and a Recv one that is greyed until something comes back',
     !/data-wa-row="wa1\|receive"/.test(cell) && /Nothing received/.test(cell), cell);
  const spent = A.waCell(row({ waIssueSentAt: '2026-09-05T10:00:00Z' }));
  ok('a spent row shows no live Issue button to an ordinary user', !/data-wa-row="wa1\|issue"/.test(spent), spent);
  ME.admin = true;
  ok('…and shows an admin a re-send instead', /↻ Issue/.test(A.waCell(row({ waIssueSentAt: '2026-09-05T10:00:00Z' }))),
     A.waCell(row({ waIssueSentAt: '2026-09-05T10:00:00Z' })));
  ME.admin = false;

  /* ---- rows that came back, and whether their button is live ---- */
  const day = n => { const d = new Date(Date.now() - n * 86400000);
    return String(d.getDate()).padStart(2, '0') + '/' + String(d.getMonth() + 1).padStart(2, '0') + '/' + d.getFullYear() + ', 10:00'; };
  A.setPT(Object.assign(A.PT(), { cut: [], base: [
    { id: 'p1', empName: 'Lokesh Mahawar', sku: 'A', receivedPieces: 5, rejectionPieces: 0, receivingDate: day(1) },
    { id: 'p2', empName: 'Lokesh Mahawar', sku: 'B', receivedPieces: 5, rejectionPieces: 0, receivingDate: day(9) },
    { id: 'p3', empName: 'Gazala Bano', sku: 'C', receivedPieces: 5, rejectionPieces: 0, receivingDate: day(1) },
    { id: 'p4', empName: 'Sangeeta Devi', sku: 'D', receivedPieces: 0, rejectionPieces: 0, receivingDate: day(1) },
    { id: 'p5', empName: 'Sangeeta Devi', sku: 'E', receivedPieces: 5, rejectionPieces: 0, receivingDate: day(2), waRecvSentAt: '2026-09-07T10:00:00Z' },
  ] }));
  /* The bulk panel was removed at Ravi's request; the row buttons are the whole flow now, and the
   * rules they enforce are checked above and below. */

  /* ---- opening WhatsApp ---- */
  WINOPEN.length = 0;
  NET.on = true;
  await A.waSendRow('p1', 'receive');
  ok('one wa.me window is opened', WINOPEN.length === 1, JSON.stringify(WINOPEN));
  ok('…at the right number, with the country code', /^https:\/\/wa\.me\/919829675604\?text=/.test(WINOPEN[0].url), WINOPEN[0].url);
  ok('…carrying the tracker\'s message', /we\+have\+received|we%20have%20received/.test(WINOPEN[0].url), WINOPEN[0].url.slice(0, 160));
  /* One named tab, reused — a morning of sends must not leave a dozen windows open. */
  ok('…in the one reused tab', WINOPEN[0].name === 'erpWhatsApp', WINOPEN[0].name);
  ok('and the row is marked, so the tracker will not message it again',
     !!(A.PT().base.find(r => r.id === 'p1') || {}).waRecvSentAt);
  /* Once marked, the row's own button is spent for anyone who is not an admin — the one-shot rule
   * the panel used to enforce by hiding the row now shows on the row itself. */
  ok('…so its button is spent for an ordinary user',
     /Already sent/.test(A.waWhyBlocked(A.PT().base.find(r => r.id === 'p1'), 'receive')),
     A.waWhyBlocked(A.PT().base.find(r => r.id === 'p1'), 'receive'));

  /* A BLOCKED POP-UP MARKS NOTHING. Counting a row as done when no message was ever composed is
   * how somebody quietly stops being told about their work. */
  WINOPEN.length = 0; WINOPEN.blocked = true;
  const before = (A.PT().base.find(r => r.id === 'p2') || {}).waRecvSentAt;
  A.setWA(Object.assign(A.WA(), { cutoff: '2020-01-01' }));      // let p2 through the cutoff
  await A.waSendRow('p2', 'receive');
  ok('a blocked pop-up marks nothing',
     (A.PT().base.find(r => r.id === 'p2') || {}).waRecvSentAt === before);
  ok('…and says why', /blocked the WhatsApp window/.test(els.pbMsg.textContent), els.pbMsg.textContent);
  WINOPEN.blocked = false;
  NET.on = false;

  ME.admin = wasAdmin;
  A.setWA(wasWA);
  A.setPTG(Object.assign(A.PTG(), { ob: A.ptList(db.pt_orderBook), mdb, press: A.ptList(db.pt_pressInventory) }));
  A.setPT(Object.assign(A.PT(), { base, cut }));
}

console.log('\n== Reserve: what printing owes that no printer has been given ==');
{
  const wasSOX = A.SOX(), wasVO = A.VO();
  /* TC- is a tablecloth, which a printer CAN be handed as cut pieces. PC- is a pillow cover, which
   * is printed as running fabric in metres and has no per-SKU order at all. That distinction is the
   * whole reason this screen is split — on the live data it is 134 SKUs against 783. */
  A.setPTG(Object.assign(A.PTG(), { mdb: [
    { sku: 'TC-A', articleType: 'Tablecloth', subtype: 'Round Tablecloth', color: 'Emerald Green', size: '60' },
    { sku: 'TC-B', articleType: 'Tablecloth', subtype: 'Square Tablecloth', color: 'Cosmos Red', size: '60x60' },
    { sku: 'TR-C', articleType: 'Table Runner', subtype: 'Plain Runner', color: 'Blue', size: '14x72' },
    { sku: 'PC-D', articleType: 'Pillow Cover', subtype: 'Piping', color: 'White', size: '18x18' },
  ] }));
  A.setSOX(Object.assign(A.SOX(), { rows: [
    { _id: 'AMZ-01092026-01', status: 'approved', lines: [
      { sku: 'TC-A', qty: 100 }, { sku: 'TC-B', qty: 50 }, { sku: 'TR-C', qty: 30 },
      { sku: 'PC-D', qty: 900 }, { sku: 'GHOST-1', qty: 7 } ] },
    /* SHP- is the order raised automatically from a Shopify order that needs production. 642 of the
     * 649 live sales orders are these — they have always been part of Needed. */
    { _id: 'SHP-3175', status: 'approved', lines: [{ sku: 'TC-A', qty: 20 }] },
    { _id: 'SHP-3268', status: 'approved', lines: [{ sku: 'TR-C', qty: 6 }] },
    /* A draft is not a promise. Only approved orders are demand — the cap check reads it that way
     * too, and reserve must not disagree with the cap. */
    { _id: 'so2', status: 'draft', lines: [{ sku: 'TC-A', qty: 5000 }] },
  ] }));
  A.setVO(Object.assign(A.VO(), {
    map: { VND001: { name: 'Choudhary Hand Block' }, VND002: { name: 'RBP-Bagru' } },
    rows: [
      { id: 'v1', vendorCode: 'VND001', status: 'Partially Dispatched', lines: [
        { kind: 'cut', sku: 'TC-A', qty: 40 },
        { kind: 'cut', sku: 'TC-B', qty: 50 },            // fully covered — must drop off
        { kind: 'cut', sku: 'TR-C', qty: 10, cancelled: true } ] },
      { id: 'v2', vendorCode: 'VND002', status: 'Cancelled', lines: [{ kind: 'cut', sku: 'TC-A', qty: 999 }] },
      { id: 'v3', vendorCode: 'VND002', status: 'Placed', lines: [{ kind: 'running', fabricType: 'Cotton', meters: 500 }] },
    ],
  }));

  const rows = A.resRows();
  const by = {}; rows.forEach(r => { by[r.sku] = r; });
  ok('a SKU nobody has been given is in reserve', !!by['TR-C'], Object.keys(by).join(','));
  /* 100 from Amazon + 20 from Shopify, less the 40 already on order. Shopify is not an addition to
   * Needed — it was always in there. */
  ok('a SKU only PARTLY on order is in reserve for the remainder',
     by['TC-A'] && by['TC-A'].left === 80, JSON.stringify(by['TC-A'] && { need: by['TC-A'].need, on: by['TC-A'].on, left: by['TC-A'].left }));
  ok('…and a Shopify order counts towards Needed like any other', by['TC-A'].need === 120, String(by['TC-A'].need));
  ok('a SKU fully on order is not in reserve at all', !by['TC-B'], Object.keys(by).join(','));
  /* A cancelled ORDER and a cancelled LINE both count for nothing — otherwise reserve would think
   * work was placed that nobody is doing. */
  ok('a cancelled order does not count as placed', by['TC-A'].on === 40, String(by['TC-A'].on));
  ok('a cancelled line does not either', by['TR-C'].on === 0 && by['TR-C'].left === 36,
     JSON.stringify({ on: by['TR-C'].on, left: by['TR-C'].left }));
  ok('a draft sales order is not demand — Shopify or otherwise', by['TC-A'].need === 120, String(by['TC-A'].need));
  /* A running-fabric order is metres of cloth, not pieces of a SKU. Counting it against a SKU would
   * silently make reserve look smaller than it is. */
  ok('a running-metres order does not cover a SKU', !!by['TR-C']);

  /* ---- the three piles ---- */
  ok('a tablecloth can be handed to a printer', by['TC-A'].group === 'ready', by['TC-A'].group);
  ok('a table runner can too', by['TR-C'].group === 'ready', by['TR-C'].group);
  /* THE FINDING THIS SCREEN EXISTS FOR: on the live data 783 SKUs and 122,774 pieces land here. A
   * single list would offer all of them as if a printer could be given them. */
  ok('a pillow cover cannot — it is printed as metres, not as a SKU',
     by['PC-D'].group === 'metres', by['PC-D'].group);
  ok('a SKU nothing knows about is called out, not silently dropped',
     by['GHOST-1'] && by['GHOST-1'].group === 'unknown', JSON.stringify(by['GHOST-1']));

  ok('the biggest shortfall is at the top', rows[0].sku === 'PC-D', rows.map(r => r.sku).join(','));

  /* ---- where the need came from ---- */
  const src = A.resSourceMap();
  ok('a SKU wanted by both channels shows both',
     A.resSrcText(src.get('TC-A')) === 'Amazon 100 · Shopify 20', A.resSrcText(src.get('TC-A')));
  ok('…biggest first, so the main source reads first',
     A.resSrcText(src.get('TR-C')) === 'Amazon 30 · Shopify 6', A.resSrcText(src.get('TR-C')));
  ok('a SKU only Amazon wants says only Amazon',
     A.resSrcText(src.get('PC-D')) === 'Amazon 900', A.resSrcText(src.get('PC-D')));
  /* The channel comes off the order NUMBER, which is how the app builds it — not off a field that
   * might be missing on the orders raised automatically. */
  ok('the channel is read from the order number, and named',
     A.soChannels().some(c => c.code === 'AMZ'), JSON.stringify(A.soChannels().map(c => c.code)));

  /* The header split is apportioned by what is STILL to place, so it adds up to the total printed
   * beside it rather than being a second, different number. */
  const tot = A.resTotals(rows);
  const shown = [...tot.values()].reduce((a, b) => a + b, 0);
  const left = Math.round(rows.reduce((a, r) => a + r.left, 0));
  ok('the header split adds up to the total beside it', Math.abs(shown - left) <= 1,
     'split ' + shown + ' vs total ' + left);
  ok('…and Shopify is named in it', /Shopify/.test(A.resSrcText(tot)), A.resSrcText(tot));
  /* The fixture's login cache says one thing and its master another; the master wins, which is the
   * whole point of the change. */
  ok('who already holds it is named from the master, not the login cache',
     A.resWho('TC-A').join(',') === 'RBP-Bagru', A.resWho('TC-A').join(','));
  ok('…and nobody holding it says nobody', A.resWho('TR-C').length === 0);

  /* ---- the hand-off to the order form ---- */
  els.ptDlg._hidden = true;
  A.RES_PICK().clear(); A.RES_PICK().add('TC-A'); A.RES_PICK().add('TR-C');
  await A.resSend();
  const lines = A.VOF().lines;
  ok('only the picked SKUs are carried over', lines.length === 2, JSON.stringify(lines.map(l => l.sku)));
  ok('…as cut lines, which is the only kind a SKU can be', lines.every(l => l.kind === 'cut'));
  ok('…at the outstanding quantity, not the whole demand',
     (lines.find(l => l.sku === 'TC-A') || {}).qty === 80, JSON.stringify(lines.map(l => l.sku + ':' + l.qty)));
  ok('…carrying what the item is, so the order reads properly',
     (lines.find(l => l.sku === 'TC-A') || {}).color === 'Emerald Green');
  ok('the order form is the one that opens — this screen does not place anything itself',
     els.ptDlgTitle.textContent === 'New vendor order', els.ptDlgTitle.textContent);
  ok('and the picks are cleared, so a second visit does not re-add them', A.RES_PICK().size === 0);

  A.setSOX(wasSOX); A.setVO(wasVO);
  A.setPTG(Object.assign(A.PTG(), { ob: A.ptList(db.pt_orderBook), mdb, press: A.ptList(db.pt_pressInventory) }));
  A.setPT(Object.assign(A.PT(), { base, cut }));
}

console.log('\n== the week we are in ==');
{
  const wasBase = A.PT().base;
  /* Dates are built relative to now, so this holds whatever day the suite is run on. */
  const start = A.repLiveStart();
  const dmy = ms => { const d = new Date(ms);
    return String(d.getDate()).padStart(2, '0') + '/' + String(d.getMonth() + 1).padStart(2, '0')
      + '/' + d.getFullYear() + ', ' + String(d.getHours()).padStart(2, '0') + ':00'; };
  const H = 3600000, DAY = 86400000;
  const rows = [
    /* In the running week — AT ITS VERY START, which is inside the week at every moment of it. "Ten hours
     * in" and "an hour ago" were both outside the week for its first hours: the suite crashed at 00:00:38 on
     * a Sunday (2026-09-20) because the week it was testing was 38 seconds old and held nothing yet. */
    { id: 'lw1', sku: 'TC-A', articleType: 'Tablecloth', receivedPieces: 100, receivingDate: dmy(start) },
    { id: 'lw2', sku: 'TC-A', articleType: 'Tablecloth', receivedPieces: 50, receivingDate: dmy(Math.max(start, Date.now() - H)) },
    /* The SAME stretch of last week — these are what the comparison is against. */
    { id: 'lw3', sku: 'TC-A', articleType: 'Tablecloth', receivedPieces: 60, receivingDate: dmy(start - 7 * DAY) },
    /* Last week, but LATER than we have reached this week. Counting this would be the whole mistake:
     * it belongs to a stretch of the week that has not happened yet.
     *
     * PLACED INSIDE LAST WEEK ON PURPOSE. Written as "now minus seven days plus two hours" it sat in
     * last week on a Tuesday and in THIS week late on a Saturday — two hours past the end of a week
     * that is nearly over is the next week — and the suite failed on the day of the week rather than
     * on anything the app did. */
    { id: 'lw4', sku: 'TC-A', articleType: 'Tablecloth', receivedPieces: 900,
      /* THE LAST HOUR OF LAST WEEK — as late in it as a row can be written, since a row carries its hour and no
       * finer. It is later than "as far as this week has got" at every moment EXCEPT the last hour of the
       * week, when no later hour exists to put it in; LATE_FITS below says which, and the expectations
       * follow it. Written as a fixed offset from now, this failed on the clock every Saturday night
       * (seen 2026-09-19 23:02) with nothing in the app changed. */
      receivingDate: dmy(start - H) },
    /* Issued, nothing back — never counted. */
    { id: 'lw5', sku: 'TC-A', articleType: 'Tablecloth', receivedPieces: 0, receivingDate: dmy(start + H) },
    /* Back, but no receiving date: a row is only stamped when it is FULLY received, so this sits in
     * no week at all. The running week carries most of that lag. */
    { id: 'lw6', sku: 'TC-A', articleType: 'Tablecloth', receivedPieces: 400, receivingDate: '' },
  ];
  A.setPT(Object.assign(A.PT(), { base: rows }));

  const lateSlot = new Date(start - H); lateSlot.setMinutes(0, 0, 0);
  const LATE_FITS = lateSlot.getTime() > Date.now() - 7 * DAY;     // false only in the last hour of the week
  const L = A.repLive('', false);
  ok('the running week counts what came back in it', Math.round(L.rows.reduce((s, r) => s + r.prod, 0)) === 150,
     JSON.stringify(L.rows.map(r => r.art + ':' + r.prod)));
  /* THE POINT OF THIS VIEW. Three days against a finished seven-day week reads as a collapse that
   * never happened — today that would have printed -63.7% instead of -27.5%. */
  ok('it compares against the SAME stretch of last week, not the whole of it',
     Math.round(L.rows.reduce((s, r) => s + r.prevProd, 0)) === (LATE_FITS ? 60 : 960),
     JSON.stringify(L.rows.map(r => r.art + ':' + r.prevProd)));
  ok('…so later-in-the-week work from last week is left out of the comparison',
     !LATE_FITS || L.rows.reduce((s, r) => s + r.prevProd, 0) < 900);
  ok('…but the whole of last week is still shown, as context', Math.round(L.fullPrevProd) === 960,
     String(L.fullPrevProd));
  ok('a row with nothing back is not counted', Math.round(L.rows.reduce((s, r) => s + r.prod, 0)) !== 550);
  ok('an undated row sits in no week, including this one',
     Math.round(L.rows.reduce((s, r) => s + r.prod, 0)) !== 550);
  ok('the day count is Sunday-based and at least one', L.days >= 1 && L.days <= 7, String(L.days));
  ok('and the percentage is worked from the like-for-like pair',
     Math.abs(L.rows[0].pct - ((150 - (LATE_FITS ? 60 : 960)) / (LATE_FITS ? 60 : 960)) * 100) < 0.01, String(L.rows[0].pct));

  /* THE TWO WAYS OF COUNTING A WEEK MUST AGREE. repByWindow is used by the running week and
   * repByWeek by the trend; if they ever drift, one report quietly disagrees with the one beside it. */
  const prevIso = A.repWkShift(A.repWkIso(A.repWeekStart(Date.now())), -1);
  const p = prevIso.split('-').map(Number);
  const prevStart = new Date(p[0], p[1] - 1, p[2]).getTime();
  const byWindow = A.repByWindow('', false, prevStart, prevStart + 7 * DAY);
  const byWeek = A.repByWeek('', false)[prevIso] || {};
  const flat = o => Object.keys(o).sort().map(k => k + ':' + Math.round(o[k].prod)).join(',');
  ok('a whole week through repByWindow equals repByWeek\'s bucket for it',
     flat(byWindow) === flat(byWeek), flat(byWindow) + '  vs  ' + flat(byWeek));

  /* The screen itself, rendered from the real function. */
  A.repRenderLive();
  ok('the screen names the number of days it is talking about',
     new RegExp('\\b' + L.days + '\\b').test(els.repMsg.innerHTML), els.repMsg.innerHTML.slice(0, 120));
  ok('…and says the comparison is the same days, not the whole week',
     /SAME/.test(els.repMsg.innerHTML) && /whole of it/.test(els.repMsg.innerHTML), els.repMsg.innerHTML.slice(0, 200));
  ok('the table has a row per article type', /Tablecloth/.test(els.repTable.innerHTML));
  /* The header promises six columns; a body row that gives five slides every figure one place left. */
  const th = (els.repTable.innerHTML.match(/<th[ >]/g) || []).length;
  const td = (els.repTable.innerHTML.match(/<td[ >]/g) || []).length;
  ok('…and every row has as many cells as the header has columns', th === 6 && td === 6,
     th + ' headings vs ' + td + ' cells');

  A.setPT(Object.assign(A.PT(), { base: wasBase }));
}

console.log('\n== a thumbnail asks for a thumbnail ==');
{
  /* Measured on the pictures actually stored: 530 KB and 1.21 MB, both painted into a 38px box.
   * The rewritten addresses come back at 8 KB and 6 KB. */
  const shop = 'https://ridhiblockprint.com/cdn/shop/files/Untitleddesign_61.jpg?v=1784481167&width=1296';
  const out = A.ptImgSrc(shop, 38);
  ok('a width already on the address is replaced, not added to', (out.match(/width=/g) || []).length === 1, out);
  ok('…and it asks for the size it will be drawn at', /width=114/.test(out), out);
  ok('…keeping the version stamp, or the CDN serves a different picture', /v=1784481167/.test(out), out);

  /* A shop's own domain serves the same /cdn/shop/ paths as the shared CDN — matching only on
   * cdn.shopify.com would have missed three of the four pictures on file. */
  ok('the shared Shopify CDN is handled too',
     /width=114/.test(A.ptImgSrc('https://cdn.shopify.com/s/files/1/0659/8505/2833/files/IMG_7084.webp?v=1774251897', 38)),
     A.ptImgSrc('https://cdn.shopify.com/s/files/1/0659/8505/2833/files/IMG_7084.webp?v=1774251897', 38));
  /* A height left beside a new width would crop the picture instead of scaling it. */
  ok('a stale height is dropped', !/height=/.test(A.ptImgSrc(shop + '&height=900', 38)), A.ptImgSrc(shop + '&height=900', 38));

  /* Amazon takes the size in the filename. */
  ok('an Amazon address gets a size modifier',
     A.ptImgSrc('https://m.media-amazon.com/images/I/51sx3A0mf1L.jpg', 38) === 'https://m.media-amazon.com/images/I/51sx3A0mf1L._SL114_.jpg',
     A.ptImgSrc('https://m.media-amazon.com/images/I/51sx3A0mf1L.jpg', 38));
  /* An address that already carries modifiers was built by somebody who meant them. */
  ok('…but one that already has modifiers is left as it is',
     A.ptImgSrc('https://m.media-amazon.com/images/I/51sx3A0mf1L._AC_SL1500_.jpg', 38)
       === 'https://m.media-amazon.com/images/I/51sx3A0mf1L._AC_SL1500_.jpg');

  /* GUESSING A PARAMETER THAT DOES NOT EXIST turns a slow picture into a missing one. */
  ok('a host with no known resize is left untouched',
     A.ptImgSrc('https://example.com/pic.jpg', 38) === 'https://example.com/pic.jpg');
  ok('something that is not a URL is handed back, not thrown over',
     A.ptImgSrc('not a url at all', 38) === 'not a url at all');
  ok('and nothing stays nothing', A.ptImgSrc('', 38) === '' && A.ptImgSrc(null, 38) === '');

  /* The bigger cell asks for more, and neither runs away. */
  ok('a 44px cell asks for more than a 38px one', /width=132/.test(A.ptImgSrc(shop, 44)), A.ptImgSrc(shop, 44));
  ok('the request never drops below a usable size', /width=80/.test(A.ptImgSrc(shop, 4)), A.ptImgSrc(shop, 4));
  ok('…and never runs away either', /width=400/.test(A.ptImgSrc(shop, 5000)), A.ptImgSrc(shop, 5000));

  /* THE STORED URL IS NOT TOUCHED. Only the <img> asks for a thumbnail — an export still carries the
   * full picture, and so does anything that ever wants to show one. */
  A.setPTG(Object.assign(A.PTG(), { mdb: [{ sku: 'IMG-1', imageUrl: shop }] }));
  A.setPTIMG({ loaded: true, map: {}, dirty: {} });
  const cell = A.ptImgInner('IMG-1', 38);
  ok('the drawn picture is the small one', /width=114/.test(cell), cell.slice(0, 160));
  ok('…and the master row still holds the original', A.PTG().mdb[0].imageUrl === shop);
  ok('…and it is still lazy, so nothing off screen is fetched at all', /loading="lazy"/.test(cell));

  A.setPTG(Object.assign(A.PTG(), { mdb }));
}

console.log('\n== renaming SKUs from a file ==');
{
  const wasMdb = A.PTG().mdb;
  A.setPTG(Object.assign(A.PTG(), { mdb: [
    { _key: 'k1', sku: 'OLD-1', articleType: 'Tablecloth' },
    { _key: 'k2', sku: 'OLD-2', articleType: 'Tablecloth' },
    { _key: 'k3', sku: 'OLD-3', articleType: 'Napkin' },
    { _key: 'k4', sku: 'TAKEN', articleType: 'Napkin' },
  ] }));

  /* ---- reading the file ---- */
  const parsed = A.mdbRenameFromRows([['Old SKU', 'New SKU'], ['OLD-1', 'NEW-1'], ['', ''], ['OLD-2', 'NEW-2']]);
  ok('two columns come off the template', parsed.rows && parsed.rows.length === 2,
     JSON.stringify(parsed.rows || parsed.err));
  ok('…and a blank row is not an error', !parsed.err);
  ok('a file with no Old SKU column is refused by name',
     /no "Old SKU" column/.test(A.mdbRenameFromRows([['sku', 'thing'], ['a', 'b']]).err || ''),
     A.mdbRenameFromRows([['sku', 'thing'], ['a', 'b']]).err);
  ok('a header lower down the sheet is still found',
     (A.mdbRenameFromRows([['Ridhi Block Print'], [], ['old sku', 'new sku'], ['OLD-1', 'NEW-1']]).rows || []).length === 1);

  /* ---- the rules, each refusing the whole file ---- */
  const errs = p => A.mdbRenamePlan(p).errs;
  ok('a clean file plans cleanly', errs([{ from: 'OLD-1', to: 'NEW-1' }, { from: 'OLD-2', to: 'NEW-2' }]).length === 0,
     JSON.stringify(errs([{ from: 'OLD-1', to: 'NEW-1' }, { from: 'OLD-2', to: 'NEW-2' }])));
  ok('a SKU that is not in the master database is named',
     /GHOST is not in the master database/.test(errs([{ from: 'GHOST', to: 'X' }]).join(' ')),
     errs([{ from: 'GHOST', to: 'X' }]).join(' '));
  /* Which row wins would be an accident of order. */
  ok('the same code renamed twice is refused, naming both rows',
     /renamed twice/.test(errs([{ from: 'OLD-1', to: 'A' }, { from: 'OLD-1', to: 'B' }]).join(' ')),
     errs([{ from: 'OLD-1', to: 'A' }, { from: 'OLD-1', to: 'B' }]).join(' '));
  /* Two products collapsing into one code is a MERGE — two histories added together — and doing
   * that by accident cannot be undone. */
  ok('two SKUs pointed at one new code is refused as a merge',
     /that is a merge, not a rename/.test(errs([{ from: 'OLD-1', to: 'SAME' }, { from: 'OLD-2', to: 'SAME' }]).join(' ')),
     errs([{ from: 'OLD-1', to: 'SAME' }, { from: 'OLD-2', to: 'SAME' }]).join(' '));
  /* Top-down OLD-1 becomes OLD-3's new code; bottom-up it stays OLD-2. Neither reading is obviously
   * the one that was meant, so neither is chosen. */
  ok('a chain is refused rather than resolved by row order',
     /is itself being renamed in this file/.test(errs([{ from: 'OLD-1', to: 'OLD-2' }, { from: 'OLD-2', to: 'NEW-2' }]).join(' ')),
     errs([{ from: 'OLD-1', to: 'OLD-2' }, { from: 'OLD-2', to: 'NEW-2' }]).join(' '));
  ok('and so is a swap', errs([{ from: 'OLD-1', to: 'OLD-2' }, { from: 'OLD-2', to: 'OLD-1' }]).length > 0);
  ok('a new code that already belongs to something else is refused',
     /TAKEN already exists/.test(errs([{ from: 'OLD-1', to: 'TAKEN' }]).join(' ')),
     errs([{ from: 'OLD-1', to: 'TAKEN' }]).join(' '));
  /* …unless that something is moving out of the way in the same file, which frees the code before
   * the write lands. */
  ok('…unless the thing holding it is moving away in the same file',
     errs([{ from: 'TAKEN', to: 'FREED' }, { from: 'OLD-1', to: 'TAKEN' }])
       .filter(e => /already exists/.test(e)).length === 0,
     errs([{ from: 'TAKEN', to: 'FREED' }, { from: 'OLD-1', to: 'TAKEN' }]).join(' '));
  ok('renaming a code to itself is refused', /the two codes are the same/.test(errs([{ from: 'OLD-1', to: 'OLD-1' }]).join(' ')));
  ok('every problem is reported, not just the first',
     errs([{ from: 'GHOST', to: 'X' }, { from: 'OLD-1', to: 'TAKEN' }]).length === 2,
     JSON.stringify(errs([{ from: 'GHOST', to: 'X' }, { from: 'OLD-1', to: 'TAKEN' }])));
  ok('lower case in the file is still matched', errs([{ from: 'old-1', to: 'new-1' }]).length === 0,
     errs([{ from: 'old-1', to: 'new-1' }]).join(' '));

  /* ---- and the write ---- */
  A.setPT(Object.assign(A.PT(), {
    base: [{ id: 'b1', sku: 'OLD-1' }, { id: 'b2', sku: 'OLD-2' }, { id: 'b3', sku: 'OLD-3' }], cut: [] }));
  A.setPTG(Object.assign(A.PTG(), { press: [], ob: [{ id: 'o1', sku: 'OLD-1' }] }));
  A.setQC(Object.assign(A.QC(), { checks: [], issue: [] }));
  A.setFGI(Object.assign(A.FGI(), { rows: [{ _id: 'f1', sku: 'OLD-2', txnType: 'OPENING', qty: 4 }] }));
  A.setSOX(Object.assign(A.SOX(), { rows: [{ _id: 'S1', status: 'approved', lines: [{ sku: 'OLD-1', qty: 1 }] }] }));
  A.setVO(Object.assign(A.VO(), { rows: [] }));
  A.setPTE(Object.assign(A.PTE(), { custom: [], priority: { 'OLD-1': 'P1' } }));
  A.setACC(Object.assign(A.ACC(), { ledger: [] }));

  NET.on = true; NET.calls = [];
  const plan = A.mdbRenamePlan([{ from: 'OLD-1', to: 'NEW-1' }, { from: 'OLD-2', to: 'NEW-2' }]);
  await A.mdbRenameRun(plan.pairs);
  const patches = NET.calls.filter(c => c.method === 'PATCH');
  /* THE WHOLE FILE OR NONE OF IT. A half-applied rename leaves one product counted under two codes
   * with nothing on either to say so. */
  ok('the whole file goes up as ONE write', patches.length === 1, String(patches.length));
  const p = patches[0].body;
  ok('both master rows move', p['pt_masterDB/k1/sku'] === 'NEW-1' && p['pt_masterDB/k2/sku'] === 'NEW-2');
  ok('base data moves for both', p['pt_baseData/b1/sku'] === 'NEW-1' && p['pt_baseData/b2/sku'] === 'NEW-2');
  ok('a SKU the file did not mention is left alone', p['pt_baseData/b3/sku'] === undefined);
  ok('the order book moves', p['pt_orderBook/o1/sku'] === 'NEW-1');
  ok('finished goods moves', p['pt_fgiLedger/f1/sku'] === 'NEW-2');
  ok('sales-order lines move, addressed by index', p['pt_salesOrders/S1/lines/0/sku'] === 'NEW-1');
  ok('the priority list gains the new key and loses the old',
     p['pt_skuPriority/NEW-1'] === 'P1' && p['pt_skuPriority/OLD-1'] === null);
  ok('and each rename is stamped with where it came from', p['pt_masterDB/k1/renamedFrom'] === 'OLD-1');
  ok('the screen no longer holds the old codes',
     !A.PTG().mdb.some(r => /^OLD-[12]$/.test(A.obUC(r.sku))) && A.PT().base.some(r => r.sku === 'NEW-1'),
     A.PTG().mdb.map(r => r.sku).join(','));
  NET.on = false;

  A.setPTG(Object.assign(A.PTG(), { mdb: wasMdb, ob: A.ptList(db.pt_orderBook), press: A.ptList(db.pt_pressInventory) }));
  A.setPT(Object.assign(A.PT(), { base, cut }));
}

console.log('\n== made, pressed, and what is actually left ==');
{
  const line = (qty, cut, issued, received, pressed) => {
    A.setPTG(Object.assign(A.PTG(), {
      ob: [{ id: 'm1', orderNo: 'M-1', sku: 'M-SKU', qty, orderDate: '2026-09-01', articleType: 'Napkin' }],
      press: pressed ? [{ id: 'mp', orderNo: 'M-1', sku: 'M-SKU', pieces: pressed }] : [],
      mdb: [{ sku: 'M-SKU', articleType: 'Napkin', subtype: 'Border Napkin', color: 'Red', size: '20x20', cuttingRequired: true }],
    }));
    A.setPT(Object.assign(A.PT(), {
      base: issued ? [{ id: 'mb', orderNo: 'M-1', sku: 'M-SKU', issuePieces: issued, receivedPieces: received }] : [],
      cut: cut ? [{ id: 'mc', orderNo: 'M-1', sku: 'M-SKU', pieces: cut }] : [],
    }));
    A.setORD({ req: {}, busy: false, at: '', rows: [] });
    return A.ordLines()[0];
  };

  /* THE ROW RAVI POINTED AT: 149 ordered, cut, issued and received back — nothing pressed. It read
   * "149 to make" while every piece was sitting made, waiting only for the press. */
  const r = line(149, 149, 149, 149, 0);
  ok('a line fully received has nothing left to make', r.pendingMake === 0, String(r.pendingMake));
  ok('…and says what it IS waiting for instead', r.madeToPress === 149, String(r.madeToPress));
  ok('…but is not called Complete, because pressing has not happened', r.open === true);

  /* MADE IS WHAT CAME BACK — Ravi's rule, chosen knowing what it costs. Work that reached the press
   * with no Base Data receipt behind it does NOT count as made: that is a hole in the register, not a
   * piece that made itself, and counting it as made would hide the hole. 97 lines live are like this,
   * carrying 1,934 pressed pieces that now read as still to make. */
  const p = line(100, 100, 0, 0, 60);
  ok('pressed work with nothing in Base Data is NOT counted as made', p.made === 0 && p.pendingMake === 100,
     JSON.stringify({ made: p.made, make: p.pendingMake }));
  ok('…and press is not quietly added to received either', p.made !== 60);

  /* Pressing running ahead of receiving — 97 such lines live. */
  const ahead = line(105, 105, 105, 92, 105);
  ok('when pressing runs ahead of receiving, only what came back counts as made', ahead.made === 92, JSON.stringify({ made: ahead.made }));
  ok('…but it is still Complete, because everything has been pressed', ahead.open === false);
  /* RAVI, 2026-09-24: "jo item handed over ya complete ho gya ho wo to make me nahi aana chahiye". A
   * Complete line owes nothing; the missing receipt is carried as "never recorded" instead. */
  ok('…and a Complete line has nothing left to make — the 13 missing receipts are "never recorded"',
     ahead.pendingMake === 0 && ahead.pendingCut === 0 && ahead.unrecorded === 13, JSON.stringify({ make: ahead.pendingMake, unrec: ahead.unrecorded }));

  /* Both stages present: adding them would claim 132 of 120 pieces were made. */
  const both = line(120, 120, 80, 72, 60);
  ok('the two stages are never added together', both.made === 72, String(both.made));
  ok('…so what is made can never exceed what was ordered', both.made <= both.qty);

  /* Nothing has happened yet. */
  const none = line(50, 0, 0, 0, 0);
  /* AND NOTHING OF IT IS 'MADE, TO PRESS'. This is the case that made the total nonsense: an
   * untouched line used to contribute its whole quantity to a figure labelled made. */
  ok('an untouched line is all still to make', none.pendingMake === 50 && none.madeToPress === 0,
     JSON.stringify({ make: none.pendingMake, toPress: none.madeToPress }));

  /* THE SEVENTY-FOUR THAT WOULD NOT ADD UP. Still to make is floored at zero per line, so extra
   * pieces on one SKU cannot fill a shortfall on another — and the panel therefore does not equal
   * Ordered - Received. Naming that difference is what lets the arithmetic close on screen. */
  const over = line(110, 110, 139, 139, 0);
  ok('more back than ordered leaves nothing to make', over.pendingMake === 0, String(over.pendingMake));
  ok('…and the excess is counted, not swallowed', over.overRecv === 29, String(over.overRecv));
  ok('…so ordered - received + over-received closes',
     (over.qty - over.received) + over.overRecv === over.pendingMake,
     JSON.stringify({ q: over.qty, r: over.received, over: over.overRecv, make: over.pendingMake }));
  ok('a line received exactly to order has no excess', line(50, 50, 50, 50, 0).overRecv === 0);
  ok('…and a line that is fully pressed has nothing waiting either',
     line(50, 50, 50, 50, 50).madeToPress === 0);

  A.setPTG(Object.assign(A.PTG(), { ob: A.ptList(db.pt_orderBook), mdb, press: A.ptList(db.pt_pressInventory) }));
  A.setPT(Object.assign(A.PT(), { base, cut }));
}

console.log('\n== a new article can be given a rate ==');
{
  const wasHR = A.HR(), wasMdb = A.PTG().mdb;
  A.setPTG(Object.assign(A.PTG(), {
    masters: Object.assign({}, A.PTG().masters, {
      articleType: [{ code: 'TC', desc: 'Tablecloth', active: true },
                    { code: 'QL', desc: 'Quilt', active: true },
                    { code: 'OLD', desc: 'Retired Thing', active: false }],
      articleSubtype: [{ code: 'RT', desc: 'Round Tablecloth', active: true }],
    }),
    mdb: [{ sku: 'X-1', articleType: 'Pillow Cover', subtype: 'Piping', color: 'Blue', size: '18x18' }],
  }));
  A.setHR(Object.assign(A.HR(), { rate: [['Curtain', 'Plain Curtain', '52X104', 'Company Contractor', 32, 'NA']] }));

  /* THE CLOSED CIRCLE. The pickers used to be built from HR.rate alone, so the only article types on
   * offer were the ones that already had a rate — and a new article could never get its first. */
  const at = A.hrRateKnown('at');
  ok('an article type from the Masters list is offered', at.includes('Tablecloth'), at.join(','));
  ok('…one the master database uses is too, even with no master row', at.includes('Pillow Cover'), at.join(','));
  ok('…and one only an old rate names is not dropped', at.includes('Curtain'), at.join(','));
  ok('an inactive master is not offered', !at.includes('Retired Thing'), at.join(','));
  ok('the subtypes come from the same three places',
     A.hrRateKnown('sub').includes('Round Tablecloth') && A.hrRateKnown('sub').includes('Piping')
     && A.hrRateKnown('sub').includes('Plain Curtain'), A.hrRateKnown('sub').join(','));

  /* Suggested, not required. */
  const f = A.hrRateFields(null);
  const fld = k => f.find(x => x.key === k);
  ok('the article type is a text box, not a picker', !fld('at').type && !!fld('at').list, JSON.stringify(fld('at').type));
  ok('…and so is the subtype', !fld('sub').type && !!fld('sub').list);
  ok('the size keeps suggestions too', !!fld('size').list);
  ok('editing an existing rate still shows its own values',
     A.hrRateFields(['Curtain', 'Plain Curtain', '52X104', 'External Contractor', 30, '11'])
       .find(x => x.key === 'at').value === 'Curtain');

  /* A NAME NOTHING HAS EVER SEEN must save. That is the whole point. */
  const brandNew = { at: 'Bean Bag', sub: 'Round Bean Bag', size: '30x30', for: 'Company Contractor', rate: '55', comm: '' };
  ok('a brand-new article name is accepted', A.hrRateCheck(brandNew, -1) === '', A.hrRateCheck(brandNew, -1));
  const rec = A.hrRateRec(brandNew);
  ok('…and is stored as typed', rec[0] === 'Bean Bag' && rec[1] === 'Round Bean Bag' && rec[4] === 55,
     JSON.stringify(rec));
  ok('…with no commission written as NA, the way the old tool does', rec[5] === 'NA', rec[5]);

  /* The guards that were there before are untouched. */
  ok('a blank article type is still refused',
     /Select the article type/.test(A.hrRateCheck(Object.assign({}, brandNew, { at: '' }), -1)));
  ok('a zero rate is still refused', /more than zero/.test(A.hrRateCheck(Object.assign({}, brandNew, { rate: '0' }), -1)));
  ok('and a duplicate combination is still refused',
     /already exists/.test(A.hrRateCheck({ at: 'Curtain', sub: 'Plain Curtain', size: '52X104',
       for: 'Company Contractor', rate: '40', comm: '' }, -1)));

  /* The dialog renders it as an input with a datalist behind it — a select could not take a new name. */
  A.ptOpenDialog({ title: 'New rate', fields: A.hrRateFields(null), onSave: () => '' });
  const html = els.ptDlgBody.innerHTML;
  ok('the article type renders as an input, not a select',
     /<input id="ptf_at"[^>]*list="ptf_at_dl"/.test(html), html.slice(0, 200));
  ok('…with a datalist of the known names behind it',
     /<datalist id="ptf_at_dl">[\s\S]*Tablecloth/.test(html));
  ok('…and a plain field is left exactly as it was', /<input id="ptf_rate" type="number"/.test(html)
     && !/id="ptf_rate"[^>]*list=/.test(html));

  A.setHR(wasHR);
  A.setPTG(Object.assign(A.PTG(), { mdb: wasMdb }));
}

console.log("\n== the vendor order, as the production tracker shows it ==");
{
  const wasAdmin = ME.admin;
  ME.admin = true;
  const o = { vendorCode: 'VND005', id: 'p1', orderNo: 'VPO-P1', orderType: 'cut', status: 'Partially Dispatched',
    lines: [
      /* Claimed 60 across two rounds, none of it accepted yet. */
      { sku: 'A-1', articleType: 'Tablecloth', articleSubtype: 'Round', color: 'Red', size: '60', qty: 100, priority: 'P1',
        deliveries: [{ qty: 40, date: '01/09/2026' }, { qty: 20, date: '03/09/2026' }] },
      /* Claimed 30, we accepted 25 — the tracker's Δ case. */
      { sku: 'A-2', articleType: 'Napkin', articleSubtype: 'Border', color: 'Blue', size: '20x20', qty: 30, priority: 'P3',
        deliveries: [{ qty: 30, date: '02/09/2026', ok: { qty: 25, by: 'ravi@x', at: '2026-09-03T00:00:00Z' } }] },
      /* Cancelled. */
      { sku: 'A-3', articleType: 'Quilt', qty: 5, priority: '', cancelled: true, deliveries: [] },
    ] };
  A.setVOE({ key: 'VND005/p1', lines: null, cancel: new Set([2]) });

  /* WHAT THE PRINTER CLAIMED, across its rounds — before anybody accepted any of it. */
  ok('the claimed quantity is the sum of the rounds', A.voClaimed(o.lines[0]) === 60, String(A.voClaimed(o.lines[0])));
  /* Nothing accepted yet: the tracker's own confirmedQty is unset too, so there is no figure to show. */
  ok('nothing accepted reads as nothing, not as zero', A.voConfirmed(o.lines[0]) === null,
     JSON.stringify(A.voConfirmed(o.lines[0])));
  ok('an accepted round is what Inwards Conf. shows', A.voConfirmed(o.lines[1]) === 25, String(A.voConfirmed(o.lines[1])));
  /* The old tool writes a line-level confirmedQty; both tools point at the same database, so a
   * delivery accepted in either has to show here. */
  ok('a confirmedQty written by the old tracker is read too',
     A.voConfirmed({ qty: 10, confirmedQty: 7, deliveries: [{ qty: 10 }] }) === 7,
     String(A.voConfirmed({ qty: 10, confirmedQty: 7, deliveries: [{ qty: 10 }] })));

  const row0 = A.voEditRow(o, o.lines[0], 0, true);
  ok('the priority is a badge, as it is there', /P1<\/span>/.test(row0), row0.slice(0, 400));
  ok('the ordered quantity is editable', /data-voe="0"/.test(row0));
  ok('the rounds are counted underneath the claim', /2 round\(s\)/.test(row0), row0);
  /* Balance is ordered less what the printer says it sent — 100 − 60. */
  ok('the balance is what is still owed', />40<\/span>/.test(row0.replace(/\s+/g, '')), row0);
  ok('a live line offers Cancel', /✕ Cancel/.test(row0) && /data-voetog="0"/.test(row0));

  const row1 = A.voEditRow(o, o.lines[1], 1, true);
  /* Claimed 30, accepted 25 — the gap is the whole reason this column exists. */
  ok('the gap between claimed and accepted is shown, signed', /\+5</.test(row1), row1);
  const agree = A.voEditRow(o, { qty: 30, priority: 'P2',
    deliveries: [{ qty: 30, ok: { qty: 30 } }] }, 9, true);
  ok('…and when the two agree it is a tick, not a zero', /✓/.test(agree), agree);

  /* A cancelled line: no balance figure, a CANCELLED pill, and the way back. */
  const row2 = A.voEditRow(o, o.lines[2], 2, true);
  ok('a cancelled line says so instead of a balance', /CANCELLED/.test(row2), row2);
  ok('…and offers Restore rather than Cancel', /↺ Restore/.test(row2) && !/✕ Cancel/.test(row2), row2);
  ok('…and its quantity is not editable while it is cancelled', !/data-voe="2"/.test(row2), row2);

  /* Read-only for anyone who cannot edit: no inputs, no line actions. */
  const ro = A.voEditRow(o, o.lines[0], 0, false);
  ok('without the right to edit there are no inputs', !/data-voe=/.test(ro) && !/data-voetog=/.test(ro), ro);
  ok('…but every figure is still there', /2 round\(s\)/.test(ro) && /P1<\/span>/.test(ro));

  /* A running order leads with fabric, colour and print — the tracker's other shape. */
  const ro2 = { vendorCode: 'V', id: 'r1', orderType: 'running',
    lines: [{ fabricType: 'Voil 112', color: 'Queen Blue', printDirection: 'Horizontal', meters: 25, priority: 'P1', deliveries: [] }] };
  A.setVOE({ key: 'V/r1', lines: null, cancel: new Set() });
  const rr = A.voEditRow(ro2, ro2.lines[0], 0, true);
  ok('a running line leads with fabric, colour and print',
     /Voil 112/.test(rr) && /Queen Blue/.test(rr) && /Horizontal/.test(rr), rr.slice(0, 300));
  ok('…and carries no SKU column', !/ui-monospace/.test(rr), rr.slice(0, 200));

  ME.admin = wasAdmin;
}

console.log('\n== current orders, laid out the way the tracker lays them out ==');
{
  const wasVO = A.VO(), wasAdmin = ME.admin;
  ME.admin = true;
  const mk = (id, no, type, status, lines) => ({ vendorCode: 'VND001', id, orderNo: no, orderType: type,
    orderDate: '02/09/2026', status, lines });
  A.setVO({ busy: false, err: '', at: '', shown: [], map: { VND001: { name: 'RBP-Bagru' } }, rows: [
    mk('c1', 'VPO-C1', 'running', 'Partially Dispatched', [
      { fabricType: 'Voil 112', color: 'Mughal Buta Blue', printDirection: 'Horizontal', meters: 60, priority: 'P1',
        deliveries: [{ qty: 40, date: '03/09/2026' }, { qty: 20, date: '04/09/2026' }] },
      { fabricType: 'Voil 112', color: 'Queen Blue', printDirection: 'Horizontal', meters: 25, priority: 'P3', deliveries: [] },
    ]),
    mk('c2', 'VPO-C2', 'cut', 'Placed', [
      { sku: 'RTC-1', articleType: 'Tablecloth', articleSubtype: 'Round', color: 'Red', size: '60', qty: 40, priority: 'P2', deliveries: [] },
      { sku: 'NAP-1', articleType: 'Napkin', articleSubtype: 'Border', color: 'Blue', size: '20x20', qty: 10, priority: 'P4', deliveries: [] },
    ]),
  ] });
  ['voVendor', 'voStatus', 'voType', 'voQ', 'voAt', 'voSub', 'voCol', 'voSz', 'voPri'].forEach(i => { els[i].value = ''; });

  /* The list stays the list until the view is switched. */
  els.voView.value = 'list';
  A.renderVo();
  ok('the one-row-per-order list is still there', /VPO-C1/.test(els.voTable.innerHTML) && els.voCards._hidden === true,
     String(els.voCards._hidden));
  ok('…and the line filters are out of the way', els.voAttrRow._hidden === true);

  els.voView.value = 'cards';
  A.renderVo();
  const h = els.voCards.innerHTML;
  ok('the cards take over', els.voTableWrap._hidden === true && els.voCards._hidden === false);
  ok('…and the line filters appear with them', els.voAttrRow._hidden === false);
  /* The tracker's card head: order number, what kind it is, the printer, the status. */
  ok('each order is a card with its number', /VPO-C1/.test(h) && /VPO-C2/.test(h));
  ok('…saying which kind it is', /Running fabric/.test(h) && /Cut fabric/.test(h), h.slice(0, 400));
  ok('…and who it is with', /RBP-Bagru/.test(h));
  ok('…and the sub-line the tracker writes', /Placed 02\/09\/2026/.test(h), h.slice(0, 900));
  /* The lines are ON the card, not behind a dialog — that is the whole ask. */
  ok('the lines are on the card', /Mughal Buta Blue/.test(h) && /Queen Blue/.test(h), h.slice(0, 1400));
  ok('…with the tracker\'s own columns', /Vendor Qty/.test(h) && /Inwards Conf\./.test(h) && /Balance/.test(h));
  ok('…and the rounds counted under the claim', /2 round\(s\)/.test(h));
  /* THE CARD IS THE WORKING SURFACE NOW. "ye pop up nahi chahiye … same data aata h bas cancel main
   * screen me nahi h" — so the two things that needed the dialog are here, and the dialog's own
   * inputs are not. */
  ok('a card carries no dialog inputs', !/data-voe=/.test(h) && !/data-voetog=/.test(h));
  ok('…it carries its own: a tick box and a quantity on every line',
     /data-vopick=/.test(h) && /data-voqty=/.test(h), h.slice(0, 400));
  ok('…and the buttons for the whole order', /data-voqtysave=/.test(h) && /data-vo-cxl=/.test(h));
  /* THE TICK COLUMN SLID OFF THE LEFT EDGE. It is the first column of a table wider than the screen,
   * so a feature that was right there stopped existing as far as anybody could tell. */
  ok('the tick column is pinned, so it cannot scroll out of sight',
     /<th class="frz"[^>]*><input type="checkbox" data-vopickall/.test(h)
     && /<td class="frz"><input type="checkbox" data-vopick=/.test(h), h.slice(0, 400));
  /* And the buttons that act on the ticks came AFTER 113 rows of them. */
  ok('…and the buttons come before the lines, not after 113 of them',
     h.indexOf('data-voqtysave=') < h.indexOf('<table'), h.indexOf('data-voqtysave=') + ' vs ' + h.indexOf('<table'));
  ok('…and the card says what the ticks are for before any is ticked',
     /Tick line\(s\) on the left/.test(h), h.slice(0, 700));
  ok('…so there is no longer a popup to open from it', !/data-vo-open=/.test(h));

  /* Somebody who may not change an order gets the card without any of it, and the one way to read
   * the detail — a button that does nothing would read as a broken app. */
  {
    const wasAdmin = ME.admin;
    ME.admin = false;
    A.renderVo();
    const ro = els.voCards.innerHTML;
    ok('a reader gets no tick boxes and no inputs',
       !/data-vopick=/.test(ro) && !/data-voqty=/.test(ro) && !/data-voqtysave=/.test(ro), ro.slice(0, 300));
    ok('…and is offered the read-only way in instead', /data-vo-open=/.test(ro));
    ME.admin = wasAdmin;
    A.renderVo();
  }

  /* The order's chip is the most urgent priority any live line carries. */
  ok('the card takes the most urgent priority on the order', A.voOrderPri(A.VO().rows[0]) === 'P1',
     A.voOrderPri(A.VO().rows[0]));
  ok('…ignoring cancelled lines', A.voOrderPri({ vendorCode: 'V', id: 'x',
     lines: [{ priority: 'P1', cancelled: true }, { priority: 'P3' }] }) === 'P3');

  /* ---- the second filter row narrows LINES, not orders ---- */
  els.voCol.value = 'Queen Blue';
  A.renderVo();
  const q = els.voCards.innerHTML;
  ok('a colour filter keeps only the lines that match', /Queen Blue/.test(q) && !/Mughal Buta Blue/.test(q), q.slice(0, 900));
  ok('…and drops an order with nothing matching', !/VPO-C2/.test(q), q.slice(0, 300));
  ok('…and says how many of the order it hid', /filtered out/.test(q), q);
  els.voAttrClear.onclick();
  ok('Clear filters puts everything back', /Mughal Buta Blue/.test(els.voCards.innerHTML) && /VPO-C2/.test(els.voCards.innerHTML));

  ok('a priority filter matches case-insensitively',
     A.voLineMatches({ priority: 'p1' }, { pri: 'P1' }) === true);
  ok('a running line is not matched by an article filter',
     A.voLineMatches({ fabricType: 'Voil 112' }, { at: 'Tablecloth' }) === false);
  ok('no filters set means no filtering', A.voAttrOn({ at: '', sub: '', col: '', sz: '', pri: '' }) === false);

  /* ---- all vendors: job work goes out on these orders too, so the picker is not printers only ---- */
  ok('the vendor picker offers every vendor, not just one',
     /All vendors/.test(els.voVendor.innerHTML), els.voVendor.innerHTML.slice(0, 160));
  els.voVendor.value = 'VND001';
  A.renderVo();
  ok('…and picking one narrows to it', /VPO-C1/.test(els.voCards.innerHTML));
  els.voVendor.value = '';

  /* ---- the bug the card view exposed ---- */
  /* VOE holds what the DIALOG has marked, for the one order it is open on. Without the key check the
   * second order's line at the same index would have been drawn as cancelled. */
  A.setVOE({ key: 'VND001/c1', lines: null, cancel: new Set([0]) });
  const other = A.voEditRow(A.VO().rows[1], A.VO().rows[1].lines[0], 0, false);
  ok('another order does not inherit the dialog\'s cancelled rows', !/CANCELLED/.test(other), other);
  const own = A.voEditRow(A.VO().rows[0], A.VO().rows[0].lines[0], 0, false);
  ok('…while the order the dialog IS on still shows them', /CANCELLED/.test(own), own);
  A.setVOE({ key: null, lines: null, cancel: null });

  els.voView.value = 'list';
  ME.admin = wasAdmin;
  A.setVO(wasVO);
}

console.log('\n== what came back, and what went back ==');
{
  const wasVO = A.VO();
  ME.admin = true;
  const mkDel = () => { els.vlState.value = ''; return A.setVO({ busy: false, err: '', at: '', shown: [], map: { VND001: { name: 'RBP-Bagru' } }, rows: [
    { vendorCode: 'VND001', id: 'r1', orderNo: 'VPO-R1', orderType: 'cut', orderDate: '01/09/2026', status: 'Placed',
      lines: [{ sku: 'RTC-9', articleType: 'Tablecloth', articleSubtype: 'Round', color: 'Olive Green', size: '132',
        qty: 100, deliveries: [{ qty: 13, date: '10/09/2026', by: 'p7976723933@vendors-tfr.app', at: '2026-09-10T04:00:00Z' }] }] },
  ] }); };
  mkDel();
  ['vlVendor', 'vlType', 'vlFrom', 'vlTo', 'vlQ', 'vlState'].forEach(i => { els[i].value = ''; });
  A.renderVlog();
  const row = A.VLOG().rows[0];
  ok('the delivery is waiting to be accepted', !!row && !row.ok, JSON.stringify(row && row.qty));

  /* RETURNED IS NOT SHORT. Short means the pieces never arrived; returned means they did, were looked
   * at, and were sent back. Ten kept, two returned, one that never turned up — three facts. */
  NET.on = true;
  await A.vlAcceptWrite([row], () => 10, 'challan 88', () => 2);
  const mkDelCheck = A.VO().rows[0].lines[0].deliveries[0];
  ok('what was kept is recorded', mkDelCheck.ok.qty === 10, JSON.stringify(mkDelCheck.ok));
  ok('…and what was sent back, separately', mkDelCheck.ok.rej === 2, JSON.stringify(mkDelCheck.ok));
  ok('…with the note and who did it', mkDelCheck.ok.note === 'challan 88' && !!mkDelCheck.ok.by);
  /* The printer is credited with the good pieces alone, so a returned piece stays owed and has to be
   * made again. That is the whole reason the two are not added together. */
  ok('the printer is credited with the kept pieces only',
     A.VO().rows[0].lines[0].vendorQty === 10, String(A.VO().rows[0].lines[0].vendorQty));
  ok('…so the order still owes what was returned',
     A.voDone(A.VO().rows[0].lines[0]) === 10, String(A.voDone(A.VO().rows[0].lines[0])));

  A.renderVlog();
  const h = els.vlTable.innerHTML;
  ok('the log has a Returned column', /Returned/.test(h), h.slice(0, 400));
  ok('…showing what went back', />2<\/span>/.test(h.replace(/\s+/g, '')), h);
  /* 13 sent, 10 kept, 2 returned — one never arrived, and that is short. */
  ok('…and short is what is left after BOTH', /1 short/.test(h), h);
  ok('the total says how much went back', /Returned to printers/.test(els.vlKpis.innerHTML), els.vlKpis.innerHTML);

  /* Nothing returned should not print a zero — an empty cell is the honest reading. */
  mkDel();
  A.renderVlog();
  await A.vlAcceptWrite([A.VLOG().rows[0]], () => 13, '', () => 0);
  ok('a clean delivery stores no return at all',
     A.VO().rows[0].lines[0].deliveries[0].ok.rej === undefined,
     JSON.stringify(A.VO().rows[0].lines[0].deliveries[0].ok));
  A.renderVlog();
  ok('…and the total drops the metric rather than showing nought',
     !/Returned to printers/.test(els.vlKpis.innerHTML), els.vlKpis.innerHTML);

  /* The filter finds them. */
  mkDel(); A.renderVlog();
  await A.vlAcceptWrite([A.VLOG().rows[0]], () => 10, '', () => 2);
  els.vlState.value = 'returned';
  A.renderVlog();
  ok('the returned filter finds a delivery with a return', A.VLOG().rows.length === 1, String(A.VLOG().rows.length));
  mkDel(); A.renderVlog();
  await A.vlAcceptWrite([A.VLOG().rows[0]], () => 13, '', () => 0);
  els.vlState.value = 'returned';
  A.renderVlog();
  ok('…and passes over one with none', A.VLOG().rows.length === 0, String(A.VLOG().rows.length));
  els.vlState.value = '';

  /* The bulk accept takes the challan at face value — no return, nothing short. */
  mkDel(); A.renderVlog();
  await A.vlAcceptWrite(A.VLOG().rows, (r, d) => parseFloat(d.qty) || 0, '');
  ok('a bulk accept records no return', A.VO().rows[0].lines[0].deliveries[0].ok.rej === undefined);
  ok('…and credits the printer with everything it sent', A.VO().rows[0].lines[0].vendorQty === 13,
     String(A.VO().rows[0].lines[0].vendorQty));
  NET.on = false;

  /* The block above switched the network off; these writes need it back on. */
  NET.on = true;

  /* ---- A REJECT FOUND AFTERWARDS ----
   * Thirteen taken in this morning, three found to be misprints this afternoon. The row was a dash
   * and there was no way to say so. */
  mkDel(); A.renderVlog();
  await A.vlAcceptWrite([A.VLOG().rows[0]], () => 13, 'all good', () => 0);
  A.renderVlog();
  ok('an accepted row still offers a way back in',
     /data-vl-ok=/.test(els.vlTable.innerHTML) && /Change<\/button>/.test(els.vlTable.innerHTML),
     els.vlTable.innerHTML.slice(-700));

  const before = A.VO().rows[0].lines[0].vendorQty;
  ok('…and the printer was credited with everything, for now', before === 13, String(before));

  await A.vlAcceptWrite([A.VLOG().rows[0]], () => 10, 'three misprints', () => 3);
  const ok2 = A.VO().rows[0].lines[0].deliveries[0].ok;
  ok('the correction is what stands now', ok2.qty === 10 && ok2.rej === 3, JSON.stringify(ok2));
  /* THE POINT OF RECORDING IT: three pieces go back onto what the printer still owes. */
  ok('…and the three go back onto what the printer owes',
     A.VO().rows[0].lines[0].vendorQty === 10, String(A.VO().rows[0].lines[0].vendorQty));
  /* WHAT WAS SAID BEFORE IS NOT ERASED. This figure decides what a printer is paid, so a quiet
   * correction with nothing behind it is the kind nobody can settle later. */
  ok('what it said before is kept', Array.isArray(ok2.was) && ok2.was.length === 1, JSON.stringify(ok2.was));
  ok('…with the figures and who gave them',
     ok2.was[0].qty === 13 && ok2.was[0].rej === 0 && !!ok2.was[0].by, JSON.stringify(ok2.was[0]));
  A.renderVlog();
  ok('and the log says the row was changed', /changed 1/.test(els.vlTable.innerHTML), els.vlTable.innerHTML.slice(-900));

  /* Changed twice: both earlier answers are there, oldest first. */
  await A.vlAcceptWrite([A.VLOG().rows[0]], () => 9, '', () => 4);
  const ok3 = A.VO().rows[0].lines[0].deliveries[0].ok;
  ok('a second change keeps both earlier answers', ok3.was.length === 2, JSON.stringify(ok3.was));
  ok('…oldest first', ok3.was[0].qty === 13 && ok3.was[1].qty === 10, JSON.stringify(ok3.was.map(w => w.qty)));

  /* An accepted row cannot be swept up by the bulk accept — that takes the challan at face value. */
  ok('an accepted row is not offered to the bulk accept',
     !new RegExp('data-vl-pick').test(els.vlTable.innerHTML), els.vlTable.innerHTML.slice(-500));
  NET.on = false;

  A.setVO(wasVO);
}

console.log('\n== how much fabric was in those pieces ==');
{
  const wasMdb = A.PTG().mdb, wasVO = A.VO();
  A.setPTG(Object.assign(A.PTG(), { mdb: [
    /* The 80x120 on Sheeting 82 that was checked against the finished piece: 3.1 m of 82-inch cloth
     * is 6.46 m², against a 6.19 m² tablecloth — 4% for hems and cutting. */
    { sku: 'RTC95-80120', articleType: 'Tablecloth', subtype: 'Rectangular Tablecloth', size: '80X120',
      fabric: 'Sheeting 82', consumption: 3.1 },
    /* Cambric carries no width in its name — 914 master rows are like this. */
    { sku: 'NO-WIDTH', articleType: 'Napkin', size: '20x20', fabric: 'Cambric', consumption: 0.5 },
    /* No consumption figure — 640 rows are like this. */
    { sku: 'NO-CONS', articleType: 'Napkin', size: '20x20', fabric: 'Sheeting 62' },
  ] }));

  /* The width is only ever written into the fabric's own NAME. The fabricType master carries a code
   * and a description and no width at all. */
  ok('a width is read out of the fabric name', Math.abs(A.voFabWidthM('Sheeting 82') - 82 * 0.0254) < 1e-9,
     String(A.voFabWidthM('Sheeting 82')));
  ok('…and a three-digit one too', Math.abs(A.voFabWidthM('Voil 112') - 112 * 0.0254) < 1e-9);
  ok('a fabric with no number in its name has no width', A.voFabWidthM('Cambric') === 0);
  ok('…and neither does nothing at all', A.voFabWidthM('') === 0 && A.voFabWidthM(null) === 0);

  const cut = { run: false, sku: 'RTC95-80120', qty: 10 };
  ok('a cut delivery is pieces x consumption x width',
     Math.abs(A.voSqm(cut, 10) - 10 * 3.1 * 82 * 0.0254) < 1e-9, String(A.voSqm(cut, 10)));
  ok('…which for these ten comes to about 64.6 m²', Math.round(A.voSqm(cut, 10) * 10) / 10 === 64.6,
     String(A.voSqm(cut, 10)));
  /* A running order is already metres of cloth — no consumption figure involved. */
  ok('a running delivery is metres x width',
     Math.abs(A.voSqm({ run: true, fabric: 'Voil 112' }, 100) - 100 * 112 * 0.0254) < 1e-9,
     String(A.voSqm({ run: true, fabric: 'Voil 112' }, 100)));

  /* WHAT IT CANNOT WORK OUT IT DOES NOT GUESS. A zero here would be read as "no fabric", which is a
   * different claim from "nobody has recorded enough to say". */
  ok('a fabric with no width gives nothing, not nought',
     A.voSqm({ run: false, sku: 'NO-WIDTH', qty: 5 }, 5) === null);
  ok('a SKU with no consumption gives nothing either',
     A.voSqm({ run: false, sku: 'NO-CONS', qty: 5 }, 5) === null);
  ok('a SKU nothing knows about gives nothing',
     A.voSqm({ run: false, sku: 'GHOST', qty: 5 }, 5) === null);
  ok('and no pieces is nothing, not zero m²', A.voSqm(cut, 0) === null);

  /* IN HAND: what was kept once accepted, what the printer says until then — one definition, so the
   * column and its totals cannot disagree. */
  ok('until it is accepted, in hand is what the printer says',
     A.vlInHand({ qty: 13, ok: null }) === 13);
  ok('…and after, it is what was kept', A.vlInHand({ qty: 13, ok: { qty: 10, rej: 3 } }) === 10);

  /* On the screen. */
  A.setVO({ busy: false, err: '', at: '', shown: [], map: { VND001: { name: 'RBP-Bagru' } }, rows: [
    { vendorCode: 'VND001', id: 's1', orderNo: 'VPO-S1', orderType: 'cut', orderDate: '01/09/2026', status: 'Placed',
      lines: [
        { sku: 'RTC95-80120', qty: 100, articleType: 'Tablecloth', size: '80X120',
          deliveries: [{ qty: 10, date: '10/09/2026', by: 'p@x', at: '2026-09-10T04:00:00Z' }] },
        { sku: 'NO-WIDTH', qty: 50, articleType: 'Napkin', size: '20x20',
          deliveries: [{ qty: 5, date: '10/09/2026', by: 'p@x', at: '2026-09-10T05:00:00Z' }] },
      ] },
  ] });
  ['vlVendor', 'vlType', 'vlFrom', 'vlTo', 'vlQ', 'vlState'].forEach(i => { els[i].value = ''; });
  A.renderVlog();
  const h = els.vlTable.innerHTML;
  ok('the log has a Fabric m² column', /Fabric m/.test(h), h.slice(0, 500));
  ok('…with the figure on the row it can work out', /64\.57/.test(h), h.slice(0, 600));
  ok('…and a dash on the one it cannot', /—/.test(h));
  ok('the panel totals the cloth', /Fabric received/.test(els.vlKpis.innerHTML), els.vlKpis.innerHTML);
  /* One of the two rows could not be worked out, and the panel says so rather than quietly
   * totalling the other. */
  ok('…and says how many it could not do', /1 unknown/.test(els.vlKpis.innerHTML), els.vlKpis.innerHTML);

  /* Accepting less moves the cloth figure with it — it follows the pieces in hand, not the claim. */
  NET.on = true;
  await A.vlAcceptWrite([A.VLOG().rows.find(r => r.sku === 'RTC95-80120')], () => 6, '', () => 4);
  A.renderVlog();
  /* Six kept of ten: 6 × 3.1 m of 82-inch cloth = 38.74 m². The cloth follows the pieces in hand,
   * not what the printer claimed — so the 64.57 that was there a moment ago must be gone. */
  ok('accepting fewer pieces lowers the cloth with them',
     /38\.74/.test(els.vlTable.innerHTML) && !/64\.57/.test(els.vlTable.innerHTML),
     els.vlTable.innerHTML.slice(0, 600));
  NET.on = false;

  A.setPTG(Object.assign(A.PTG(), { mdb: wasMdb }));
  A.setVO(wasVO);
}

console.log('\n== Order Console: what the vendors hold, order by order ==');
{
  /* THE PRINTING COLUMN KNEW ONLY A PRINTER PUT ON A LINE FROM THAT SCREEN. 489 live vendor-order lines
   * were invisible to it, so it said "not printed" on cloth that had been at the printer for a week. A
   * vendor line names a SKU and never a sales order — 0 of 489 do — so the link is by SKU, and where
   * several orders want the SKU the printer's pieces are dealt out between them ONCE. */
  /* COPIES. setPTG(Object.assign(A.PTG(), …)) changes the object in place, so a reference kept here would be
   * changed with it and "putting it back" would put back the fixture. */
  const wasPTG = Object.assign({}, A.PTG()), wasPT = Object.assign({}, A.PT()), wasVO = Object.assign({}, A.VO()), wasORD = Object.assign({}, A.ORD()), wasAdmin = ME.admin;
  ME.admin = true;
  const day = (qty, okq) => Object.assign({ qty, date: '10/09/2026', by: 'p@x', at: '2026-09-10T04:00:00Z' },
    okq == null ? {} : { ok: { qty: okq, by: 'me@x', at: '2026-09-10T05:00:00Z' } });
  const book = extra => A.setPTG(Object.assign(A.PTG(), {
    ob: [{ id: 'a1', orderNo: 'O-1', sku: 'S-A', qty: 30, orderDate: '2026-09-01', articleType: 'Tablecloth', articleSubtype: 'Square Tablecloth', color: 'Blue', size: '60X60' },
         { id: 'a2', orderNo: 'O-2', sku: 'S-A', qty: 30, orderDate: '2026-09-05', articleType: 'Tablecloth', articleSubtype: 'Square Tablecloth', color: 'Blue', size: '60X60' },
         { id: 'b1', orderNo: 'O-3', sku: 'S-B', qty: 10, orderDate: '2026-09-02' },
         { id: 'c1', orderNo: 'O-4', sku: 'S-C', qty: 5, orderDate: '2026-09-03' }],
    press: (extra && extra.press) || [],
    mdb: ['S-A', 'S-B', 'S-C'].map(sku => ({ sku, articleType: 'Tablecloth', subtype: 'Square Tablecloth', size: '60X60', cuttingRequired: true })),
    masters: Object.assign({}, A.PTG().masters, { vendor: [
      { code: 'VND001', desc: 'RBP-Bagru', category: 'Printer', active: true },
      { code: 'VND002', desc: 'Choudhary Hand Block', category: 'Printer', active: true }] }) }));
  book();
  A.setPT(Object.assign(A.PT(), { base: [], cut: [] }));
  A.setORD({ req: {}, busy: false, at: '', rows: [] });
  const orders = () => [
    { vendorCode: 'VND001', id: 'v1', orderNo: 'VPO-1', orderType: 'cut', orderDate: '02/09/2026', status: 'Placed',
      lines: [{ kind: 'cut', sku: 'S-A', qty: 40, vendorDate: '22/09/2026', deliveries: [day(10, 10)] },
              { kind: 'cut', sku: 'S-A', qty: 500, cancelled: true },                                   // a cancelled line holds nothing
              { kind: 'cut', sku: 'S-A', qty: 50, shopKey: 'O-9|S-A', shopOrderNo: '#9' },             // put on a line from the console: not in the pile
              { kind: 'running', fabricType: 'Voil 92', meters: 900 }] },                              // metres are nobody's pieces
    { vendorCode: 'VND002', id: 'v2', orderNo: 'VPO-2', orderType: 'cut', orderDate: '03/09/2026', status: 'Placed',
      lines: [{ kind: 'cut', sku: 'S-B', qty: 10, deliveries: [day(4)] }] },                          // claimed, not accepted: not back
    { vendorCode: 'VND002', id: 'v3', orderNo: 'VPO-3', orderType: 'cut', orderDate: '01/09/2026', status: 'Cancelled',
      lines: [{ kind: 'cut', sku: 'S-A', qty: 999 }] }];
  A.setVO({ busy: false, err: '', at: '', shown: [], map: {}, rows: orders() });

  const of = (no, sku) => A.ordVendorOf(no, sku) || { given: 0, back: 0, parts: [], shared: false, none: true };
  ok('an order that alone wants a SKU holds all the vendor has of it', of('O-3', 'S-B').given === 10 && of('O-3', 'S-B').shared === false, JSON.stringify(of('O-3', 'S-B')));
  ok('…and a delivery nobody has accepted is not back yet', of('O-3', 'S-B').back === 0);
  ok('an order no vendor holds anything for says so', !!of('O-4', 'S-C').none);

  /* DEALT OUT ONCE. 40 pieces, two orders of 30: the older takes its 30, the newer the 10 that are left.
   * Judging each against the whole pile would say 30 and 30 — 60 pieces at a printer holding 40. */
  ok('two orders wanting one SKU share the vendor\'s pieces, oldest first',
     of('O-1', 'S-A').given === 30 && of('O-2', 'S-A').given === 10, of('O-1', 'S-A').given + ' / ' + of('O-2', 'S-A').given);
  ok('…so that what they hold adds up to what the vendor holds, never more',
     of('O-1', 'S-A').given + of('O-2', 'S-A').given === 40);
  ok('…and both are marked as sharing', of('O-1', 'S-A').shared === true && of('O-2', 'S-A').shared === true);
  ok('what came back goes to the order served first', of('O-1', 'S-A').back === 10 && of('O-2', 'S-A').back === 0);
  ok('a cancelled line, a cancelled order, a console-assigned line and metres are not in the pile',
     of('O-1', 'S-A').given + of('O-2', 'S-A').given === 40);
  ok('each share names the vendor order and the date the vendor promised',
     of('O-1', 'S-A').parts[0].vpo === 'VPO-1' && of('O-1', 'S-A').parts[0].due === '22/09/2026', JSON.stringify(of('O-1', 'S-A').parts));

  /* OPEN ORDERS FIRST. The older order is finished; the cloth at the printer is for the one that is not. */
  book({ press: [{ id: 'p1', orderNo: 'O-1', sku: 'S-A', pieces: 30 }] });
  ok('a finished order does not swallow cloth an open one is waiting for',
     of('O-2', 'S-A').given === 30 && of('O-1', 'S-A').given === 10, of('O-2', 'S-A').given + ' / ' + of('O-1', 'S-A').given);
  book();

  /* ---- where a line is waiting ---- */
  const row = (no, sku) => A.ordLines().find(r => r.orderNo === no && r.sku === sku);
  ok('a line whose cloth is still at the printer is waiting on the vendor', /^Vendor/.test(A.ordWaitingAt(row('O-1', 'S-A'))), A.ordWaitingAt(row('O-1', 'S-A')));
  ok('…and one nobody has given out is waiting to be cut', /^Cutting/.test(A.ordWaitingAt(row('O-4', 'S-C'))), A.ordWaitingAt(row('O-4', 'S-C')));
  book({ press: [{ id: 'p1', orderNo: 'O-4', sku: 'S-C', pieces: 5 }] });
  ok('…and a finished one is complete', A.ordWaitingAt(row('O-4', 'S-C')) === 'Complete');
  book();

  /* ---- the screen ---- */
  ['odOrd', 'odArt', 'odSub', 'odCol', 'odSz', 'odStatus', 'odQ'].forEach(i => { els[i].value = ''; });
  A.renderOrd();
  const h = els.odTable.innerHTML;
  ok('the Printing cell says what the vendor holds, not "not printed"', /back of 30 given/.test(h) && !/not printed/.test(h), h.slice(0, 900));
  ok('…and who holds it', /RBP-Bagru/.test(h));
  ok('…and how much of the line nobody has given out', /20 not given/.test(h), (h.match(/\d+ not given/g) || []).join(','));
  ok('…and says so when nothing is with any vendor', /not given to a vendor/.test(h));
  ok('…and that a share is shared', /shared/.test(h));
  ok('every order number opens that order', (h.match(/data-ordj="O-1"/g) || []).length === 1 && /data-ordj="O-4"/.test(h));

  /* ---- one order, start to finish ---- */
  A.ptOpenDialog({ title: 'cleared', html: '', note: '' });
  try { A.ordJourney('O-1'); } catch (e) { /* the empty dialog fails the lines below */ }
  const d = A.PTD_() || {};
  ok('an order opens start to finish', /O-1/.test(d.title || '') && /start to finish/.test(d.title || ''), d.title);
  ok('…with every stage across the top', ['Ordered', 'With vendor', 'Back from vendor', 'Cut', 'Issued', 'Received', 'QC passed', 'Pressed', 'In store']
     .every(x => (d.html || '').indexOf(x) >= 0), String(d.html).slice(0, 300));
  ok('…and the vendor order behind each line, with its promise', /VPO-1/.test(d.html || '') && /promised 22\/09\/2026/.test(d.html || ''), String(d.html).slice(0, 1200));
  ok('…and where the line is waiting', /Vendor —/.test(d.html || ''));
  ok('…and says the share is shared, and how', /shared with other orders/.test(d.html || '') && /open orders first/.test(d.note || ''));
  A.ptOpenDialog({ title: 'cleared', html: '', note: '' });
  let threw = '';
  try { A.ordJourney('NO-SUCH-ORDER'); } catch (e) { threw = e.message || String(e); }
  ok('an order that is not in the book opens nothing, and does not throw', threw === '' && (A.PTD_() || {}).title === 'cleared', threw);

  /* THE CLICK ITSELF. The table is written with innerHTML, so the link only works through the delegated
   * listener — a test that called ordJourney directly would pass with the link dead. */
  A.ptOpenDialog({ title: 'cleared', html: '', note: '' });
  for (const fn of (els.odTable._listeners.click || [])) {
    try { await fn({ preventDefault() {}, target: { closest: sel => (sel === '[data-ordj]' ? { getAttribute: () => 'O-3' } : null) } }); } catch (e) { /* fails below */ }
  }
  ok('clicking an order number opens that order', /O-3/.test((A.PTD_() || {}).title || ''), String((A.PTD_() || {}).title));

  /* ---- the console reads the vendor orders when it opens ---- */
  {
    const keepStore = NET.store, keepNet = NET.on; NET.on = true;
    NET.store = { pt_vendorOrders: { VND001: { v9: { id: 'v9', orderNo: 'VPO-9', orderType: 'cut', status: 'Placed', lines: [{ kind: 'cut', sku: 'S-C', qty: 5 }] } } } };
    A.setVO({ rows: null, map: null, err: '', busy: false, at: '', shown: [], pick: {} });
    try { await A.ensureOrd(); } catch (e) { /* fails below */ }
    ok('opening the console reads the vendor orders', (A.VO().rows || []).some(o => o.id === 'v9'), JSON.stringify((A.VO().rows || []).map(o => o.id)));
    ok('…and the line nobody held a moment ago now shows its vendor', (A.ordVendorOf('O-4', 'S-C') || {}).given === 5);
    NET.store = keepStore; NET.on = keepNet;
  }

  /* ================= A NEW VENDOR LINE SAYS WHICH ORDERS IT IS FOR =================
   *
   * The 489 lines already placed name no sales order, so their link is worked out. From now on it is
   * written down as the order is placed, and a written link is not moved by any rule. */
  book(); A.setPT(Object.assign(A.PT(), { base: [], cut: [] }));
  const vo = rows => A.setVO({ busy: false, err: '', at: '', shown: [], map: {}, rows });
  const stamp = lines => A.voStampOrders(lines).map(l => (l.forOrders || []).map(f => f.orderNo + ':' + f.qty).join(' '));

  vo([]);
  ok('a new line is stamped with the open orders wanting it, oldest first',
     stamp([{ kind: 'cut', sku: 'S-A', qty: 40 }])[0] === 'O-1:30 O-2:10', stamp([{ kind: 'cut', sku: 'S-A', qty: 40 }])[0]);
  ok('two lines of one SKU in the same order do not stamp the same order twice',
     stamp([{ kind: 'cut', sku: 'S-A', qty: 30 }, { kind: 'cut', sku: 'S-A', qty: 30 }]).join(' | ') === 'O-1:30 | O-2:30',
     stamp([{ kind: 'cut', sku: 'S-A', qty: 30 }, { kind: 'cut', sku: 'S-A', qty: 30 }]).join(' | '));
  ok('pieces no open order wants are left unstamped, not invented an order for',
     stamp([{ kind: 'cut', sku: 'S-B', qty: 25 }])[0] === 'O-3:10', stamp([{ kind: 'cut', sku: 'S-B', qty: 25 }])[0]);
  ok('…and a SKU nobody ordered gets no stamp at all', !('forOrders' in A.voStampOrders([{ kind: 'cut', sku: 'S-NOBODY', qty: 5 }])[0]));
  ok('metres, a cancelled line and a console-assigned line are left as they are',
     A.voStampOrders([{ kind: 'running', fabricType: 'Voil 92', meters: 50 }, { kind: 'cut', sku: 'S-A', qty: 9, cancelled: true },
       { kind: 'cut', sku: 'S-A', qty: 9, shopKey: 'O-1|S-A' }]).every(l => !('forOrders' in l)));
  ok('a line already stamped is not stamped again',
     stamp([{ kind: 'cut', sku: 'S-A', qty: 40, forOrders: [{ orderNo: 'O-2', qty: 40 }] }])[0] === 'O-2:40');
  /* WHAT VENDORS ALREADY HOLD COMES OFF THE NEED FIRST — a second order for the SKU stamps the NEXT order. */
  vo([{ vendorCode: 'VND001', id: 'w1', orderNo: 'VPO-W1', orderType: 'cut', orderDate: '02/09/2026', status: 'Placed', lines: [{ kind: 'cut', sku: 'S-A', qty: 40 }] }]);
  ok('a second order for the SKU stamps what the first left uncovered',
     stamp([{ kind: 'cut', sku: 'S-A', qty: 25 }])[0] === 'O-2:20', stamp([{ kind: 'cut', sku: 'S-A', qty: 25 }])[0]);

  /* ---- and the allocation honours what was written ---- */
  vo([{ vendorCode: 'VND001', id: 'w2', orderNo: 'VPO-W2', orderType: 'cut', orderDate: '02/09/2026', status: 'Placed',
    lines: [{ kind: 'cut', sku: 'S-A', qty: 20, forOrders: [{ orderNo: 'O-2', qty: 20 }], deliveries: [day(5, 5)] }] }]);
  ok('a stamp beats the sharing rule: the older order gets nothing of a line placed for the newer',
     of('O-2', 'S-A').given === 20 && !!of('O-1', 'S-A').none, JSON.stringify([of('O-2', 'S-A').given, of('O-1', 'S-A').given]));
  ok('…and what came back on it is that order\'s', of('O-2', 'S-A').back === 5);
  ok('…and it is not called shared, because nothing about it was worked out',
     of('O-2', 'S-A').shared === false && (of('O-2', 'S-A').parts[0] || {}).stamped === true);
  /* A STAMP AND THE DEALING TOGETHER NEVER GIVE AN ORDER MORE THAN IT ORDERED. 20 placed for the newer order,
   * 60 more unstamped: the older takes its 30, and the newer is owed only the 10 its stamp left uncovered. */
  vo([{ vendorCode: 'VND001', id: 'w2b', orderNo: 'VPO-W2B', orderType: 'cut', orderDate: '02/09/2026', status: 'Placed',
    lines: [{ kind: 'cut', sku: 'S-A', qty: 20, forOrders: [{ orderNo: 'O-2', qty: 20 }] }, { kind: 'cut', sku: 'S-A', qty: 60 }] }]);
  ok('a stamped order is dealt only what its stamp left uncovered',
     of('O-2', 'S-A').given === 30 && of('O-1', 'S-A').given === 30, of('O-1', 'S-A').given + ' / ' + of('O-2', 'S-A').given);
  ok('…and part of it is then shared, which the row says', of('O-2', 'S-A').shared === true);
  vo([{ vendorCode: 'VND001', id: 'w2', orderNo: 'VPO-W2', orderType: 'cut', orderDate: '02/09/2026', status: 'Placed',
    lines: [{ kind: 'cut', sku: 'S-A', qty: 20, forOrders: [{ orderNo: 'O-2', qty: 20 }], deliveries: [day(5, 5)] }] }]);
  A.renderOrd();
  ok('the screen says it was placed for this order', /for this order/.test(els.odTable.innerHTML));
  vo([{ vendorCode: 'VND001', id: 'w3', orderNo: 'VPO-W3', orderType: 'cut', orderDate: '02/09/2026', status: 'Placed',
    lines: [{ kind: 'cut', sku: 'S-A', qty: 20, forOrders: [{ orderNo: 'GONE-FROM-THE-BOOK', qty: 20 }] }] }]);
  ok('a stamp for an order that has left the book goes back to be shared, not lost',
     of('O-1', 'S-A').given === 20, String(of('O-1', 'S-A').given));
  vo([{ vendorCode: 'VND001', id: 'w4', orderNo: 'VPO-W4', orderType: 'cut', orderDate: '02/09/2026', status: 'Placed',
    lines: [{ kind: 'cut', sku: 'S-A', qty: 8, forOrders: [{ orderNo: 'O-2', qty: 500 }] }] }]);
  ok('a stamp can never give out more than the line holds', of('O-2', 'S-A').given === 8, String(of('O-2', 'S-A').given));

  /* ---- placing an order writes the stamp ---- */
  {
    const keepNet = NET.on, keepStore = NET.store, keepSOX = Object.assign({}, A.SOX()); NET.on = true; NET.store = {};
    A.setSOX(Object.assign({}, A.SOX(), { rows: [{ id: 'so1', status: 'approved', lines: [{ sku: 'S-A', qty: 100 }] }] }));
    vo([]);
    await A.voFormOpen();
    els.vof_service.value = 'Block print'; A.voOnServicePick();
    els.vof_vendor.value = 'VND001';
    A.setVOF(Object.assign(A.VOF(), { kind: 'cut', service: 'Block print', lines: [{ kind: 'cut', sku: 'S-A', qty: 40 }] }));
    let said = ''; try { said = String(await A.voPlace() || ''); } catch (e) { said = 'threw: ' + (e.message || e); }
    ok('the order is placed', said === '', said);
    const put = NET.calls.filter(c => c.method === 'PUT' && /pt_vendorOrders\/VND001\//.test(c.url)).pop();
    ok('…and each line is written with the orders it is for',
       !!put && JSON.stringify((put.body.lines[0] || {}).forOrders) === JSON.stringify([{ orderNo: 'O-1', qty: 30 }, { orderNo: 'O-2', qty: 10 }]),
       JSON.stringify(put && put.body.lines[0]));
    A.setVOF({ kind: 'running', lines: [] }); A.setSOX(keepSOX); NET.on = keepNet; NET.store = keepStore;
  }

  /* ================= QC NAMES ITS ORDER, AND THE CONSOLE CAN SHOW QC AT ALL =================
   *
   * The check form's Order box was optional, and in 245 live checks nobody filled it once — so the Order
   * Console, which looks QC up by order + SKU, showed a dash on every line it has ever drawn. */
  {
    const keepQC = Object.assign({}, A.QC()), keepNet = NET.on, keepStore = NET.store;
    vo([]); book();
    A.setPT(Object.assign(A.PT(), { cut: [], base: [
      { id: 'q1', orderNo: 'O-1', sku: 'S-A', issuePieces: 25, receivedPieces: 20 },
      { id: 'q2', orderNo: 'O-2', sku: 'S-A', issuePieces: 5, receivedPieces: 5 },
      { id: 'q3', orderNo: 'O-3', sku: 'S-B', issuePieces: 10, receivedPieces: 10 }] }));
    const checks = list => A.setQC(Object.assign({}, A.QC(), { checks: list, issue: [], ret: [] }));
    const qc = (no, sku) => A.ordQcOf(no, sku) || { checked: 0, ok: 0, rej: 0, alt: 0, worked: 0, none: true };

    /* ---- history: checks that named no order ---- */
    checks([{ id: 'c1', sku: 'S-A', checked: 22, ok: 20, rejected: 2, forAlteration: 0 }]);
    ok('a check that named no order is shared between the orders of its SKU',
       qc('O-1', 'S-A').checked === 20 && qc('O-2', 'S-A').checked === 2, qc('O-1', 'S-A').checked + ' / ' + qc('O-2', 'S-A').checked);
    ok('…once: the shares add up to what was checked, never more', qc('O-1', 'S-A').checked + qc('O-2', 'S-A').checked === 22);
    ok('…never beyond what an order received — nothing is inspected that did not come back', qc('O-1', 'S-A').checked <= 20);
    ok('…the older order first', qc('O-1', 'S-A').checked > qc('O-2', 'S-A').checked);
    ok('…with passed and rejected going with the pieces', qc('O-1', 'S-A').ok === 18 && qc('O-1', 'S-A').rej === 2, JSON.stringify(qc('O-1', 'S-A')));
    ok('…and marked as worked out, because nobody wrote it down', qc('O-1', 'S-A').worked === 20);
    /* A CHECK THAT NAMED ITS ORDER IS THAT ORDER'S, and comes off the room before anything is shared in. */
    checks([{ id: 'c2', sku: 'S-B', orderNo: 'O-3', checked: 4, ok: 4 }, { id: 'c3', sku: 'S-B', checked: 100, ok: 100 }]);
    ok('a check that named its order is that order\'s', qc('O-3', 'S-B').checked >= 4);
    ok('…and unnamed checks only fill what is left of what the order received',
       qc('O-3', 'S-B').checked === 10 && qc('O-3', 'S-B').worked === 6, JSON.stringify(qc('O-3', 'S-B')));
    checks([{ id: 'c4', sku: 'S-C', checked: 9, ok: 9 }]);
    ok('an order that received nothing is given no QC, whatever was checked', !!qc('O-4', 'S-C').none);
    checks([{ id: 'c1', sku: 'S-A', checked: 22, ok: 20, rejected: 2, forAlteration: 0 }]);
    ['odOrd', 'odArt', 'odSub', 'odCol', 'odSz', 'odStatus', 'odQ'].forEach(i => { els[i].value = ''; });
    A.renderOrd();
    ok('the console\'s QC column is no longer a dash', />18</.test(els.odTable.innerHTML), (els.odTable.innerHTML.match(/shared out by SKU/g) || []).length + ' notes');
    /* BOTH WORDINGS. A line with rejects says it inside the longer note and a clean one says it on its own;
     * matching the three words they share passed with either one gone. */
    ok('…and says these were shared out, not recorded — on a line with rejects', /named no order and are shared out by SKU/.test(els.odTable.innerHTML));
    ok('…and on a clean one', /named no order, so they are shared out by SKU/.test(els.odTable.innerHTML));

    /* ---- from now on: the form asks ---- */
    ok('the form offers the orders a SKU is on, the one with pieces back first',
       A.qcOrdersFor('S-A').map(o => o.orderNo).join(',') === 'O-1,O-2' && A.qcOrdersFor('S-A')[0].received === 20, JSON.stringify(A.qcOrdersFor('S-A')));
    checks([]); NET.on = true; NET.store = {};
    const fill = (sku, ord, n) => { els.qcwSrc.value = ''; els.qcwSku.value = sku; els.qcwSku.dataset = els.qcwSku.dataset || {}; els.qcwSku.dataset.typed = '1';
      els.qcwBy.value = 'Anita'; els.qcwOrd.value = ord; els.qcwChecked.value = String(n); els.qcwAlt.value = ''; els.qcwRej.value = ''; els.qcwRemarks.value = ''; };
    const save = async () => { const at = NET.calls.length; try { await els.qcwSave.onclick(); } catch (e) { return { threw: e.message || String(e), puts: [] }; }
      return { msg: els.qcwMsg.textContent, puts: NET.calls.slice(at).filter(c => c.method === 'PUT' && /pt_qcChecks/.test(c.url)) }; };
    fill('S-A', '', 3);
    let r = await save();
    ok('a check on a SKU that is on orders is refused without one', r.puts.length === 0 && /pick which one/.test(r.msg || ''), JSON.stringify(r));
    fill('S-A', 'O-3', 3);
    r = await save();
    ok('…and with an order that SKU is not on', r.puts.length === 0 && /has no line for/.test(r.msg || ''), JSON.stringify(r));
    fill('S-A', 'o-2', 3);
    r = await save();
    ok('…and saved with the order it names, however it was typed', r.puts.length === 1 && r.puts[0].body.orderNo === 'O-2', JSON.stringify(r.puts[0] && r.puts[0].body));
    ok('…so the console shows it against that order by name', qc('O-2', 'S-A').checked === 3 && qc('O-2', 'S-A').worked === 0, JSON.stringify(qc('O-2', 'S-A')));
    /* ONE ORDER, ONE ANSWER — the box fills itself in. */
    els.qcwSku.value = 'S-B'; els.qcwSku.dataset.typed = '1'; els.qcwOrd.value = '';
    try { A.renderQcCheckForm(); } catch (e) { /* fails below */ }
    ok('a SKU on exactly one order fills the box in by itself', els.qcwOrd.value === 'O-3', els.qcwOrd.value);
    ok('…and the box says it is required', /\*/.test(els.qcwOrd.placeholder || ''), els.qcwOrd.placeholder);
    NET.on = keepNet; NET.store = keepStore; A.setQC(keepQC);
  }

  /* ---- THE SAME ISSUE, SAVED TWICE ---- eleven pairs in the live register, 0 to 47 seconds apart. */
  {
    const keepBase = A.PT().base, iso = ms => new Date(Date.now() - ms).toISOString();
    const e = { empName: 'Anita', sku: 'S-A', orderNo: 'O-1', issuePieces: 5 };
    A.setPT(Object.assign(A.PT(), { base: [Object.assign({ id: 't1', addedAt: iso(20000) }, e)] }));
    ok('an identical issue saved twenty seconds ago is noticed', !!A.bdTwinOf(e));
    ok('…but not a different number of pieces', !A.bdTwinOf(Object.assign({}, e, { issuePieces: 6 })));
    ok('…nor another karigar, SKU or order', !A.bdTwinOf(Object.assign({}, e, { empName: 'Soniya' })) && !A.bdTwinOf(Object.assign({}, e, { sku: 'S-B' })) && !A.bdTwinOf(Object.assign({}, e, { orderNo: 'O-2' })));
    A.setPT(Object.assign(A.PT(), { base: [Object.assign({ id: 't1', addedAt: iso(10 * 60000) }, e)] }));
    ok('…nor the same issue ten minutes later, which is simply a second issue', !A.bdTwinOf(e));
    A.setPT(Object.assign(A.PT(), { base: [Object.assign({ id: 't1', addedAt: iso(5000) }, e, { orderNo: '' })] }));
    ok('a custom order, which names no order, is caught the same way', !!A.bdTwinOf(Object.assign({}, e, { orderNo: '' })));
    A.setPT(Object.assign(A.PT(), { base: keepBase }));
  }

  /* ---- the export carries what the screen shows ---- */
  vo(orders());
  {
    const csv = A.ordBookCsv(A.ordLines()), head = csv[0].split(',');
    const col = n => head.indexOf(n), rowOf = no => (csv.find(x => x.indexOf(no + ',') === 0) || '').split(',');
    ok('the export has the vendor columns', ['Vendor', 'Given to vendor', 'Back from vendor', 'Not given', 'Vendor orders', 'Promised', 'How linked', 'Waiting at']
       .every(n => col(n) >= 0), csv[0]);
    ok('…with the same figures the screen shows', rowOf('O-1')[col('Given to vendor')] === '30' && rowOf('O-1')[col('Back from vendor')] === '10'
       && rowOf('O-2')[col('Not given')] === '20', JSON.stringify([rowOf('O-1')[col('Given to vendor')], rowOf('O-2')[col('Not given')]]));
    ok('…and how each was linked', rowOf('O-1')[col('How linked')] === 'shared by SKU' && rowOf('O-3')[col('How linked')] === 'only order for this SKU',
       rowOf('O-1')[col('How linked')] + ' / ' + rowOf('O-3')[col('How linked')]);
    ok('…and where each is waiting', /^Vendor/.test(rowOf('O-1')[col('Waiting at')]), rowOf('O-1')[col('Waiting at')]);
    ok('…and a header and a row that are the same length', csv.every(x => x.split(',').length === head.length),
       csv.map(x => x.split(',').length).join(' '));
  }

  ME.admin = wasAdmin; A.setVO(wasVO); A.setPTG(wasPTG); A.setPT(wasPT); A.setORD(wasORD);
}

console.log('\n== what each printer charges ==');
{
  const wasHR = A.HR(), wasVO = A.VO(), wasMdb = A.PTG().mdb, wasAdmin = ME.admin;
  ME.admin = true;
  A.setPTG(Object.assign(A.PTG(), {
    mdb: [{ sku: 'RTC-6060', articleType: 'Tablecloth', subtype: 'Square Tablecloth', size: '60X60', fabric: 'Sheeting 82', consumption: 2 }],
    masters: Object.assign({}, A.PTG().masters, { vendor: [
      { code: 'VND001', desc: 'RBP-Bagru', category: 'Printer', active: true },
      { code: 'VND002', desc: 'Choudhary Hand Block', category: 'Printer', active: true }] }),
  }));
  A.setVO({ busy: false, err: '', at: '', shown: [], map: { VND001: { name: 'RBP-Bagru' }, VND002: { name: 'Choudhary Hand Block' } }, rows: [
    { vendorCode: 'VND001', id: 'q1', orderNo: 'VPO-Q1', orderType: 'running', status: 'Placed',
      lines: [{ kind: 'running', fabricType: 'Voil 92', color: 'Blue', printDirection: 'Vertical', meters: 100 }] },
    { vendorCode: 'VND002', id: 'q2', orderNo: 'VPO-Q2', orderType: 'cut', status: 'Placed',
      lines: [{ kind: 'cut', sku: 'RTC-6060', qty: 40 }] },
  ] });
  A.setHR(Object.assign(A.HR(), { prate: [] }));

  /* Running work is priced by the METRE and varies by fabric and print direction; cut work by the
   * PIECE and varies by article, subtype and size. That is the shape the live orders take. */
  const run = { vendor: 'VND001', service: 'Block print', kind: 'running', fabric: 'Voil 92', print: 'Vertical', rate: '14' };
  const cut = { vendor: 'VND002', service: 'Block print', at: 'Tablecloth', sub: 'Square Tablecloth', size: '60X60', rate: '22' };
  ok('a printing rate is accepted', A.prCheck(run, -1) === '', A.prCheck(run, -1));
  ok('a piecework rate is accepted', A.prCheck(cut, -1) === '', A.prCheck(cut, -1));
  ok('a rate with no work named is refused',
     /not a kind of work|Pick what the work is/.test(A.prCheck(Object.assign({}, cut, { service: '' }), -1)),
     A.prCheck(Object.assign({}, cut, { service: '' }), -1));
  ok('…and it is stored by the metre or the piece',
     A.prUnit(A.prRec(run)) === 'per m' && A.prUnit(A.prRec(cut)) === 'per pc',
     A.prUnit(A.prRec(run)) + ' / ' + A.prUnit(A.prRec(cut)));
  /* THE SAME PRINTING, BOUGHT BOTH WAYS — running fabric by the metre and cut pieces by the piece.
   * Tying one unit to each service made most of the existing rate card impossible to write. */
  ok('printing is bought both ways, and the two are different rates',
     A.prKey(A.prRec(run)) !== A.prKey(A.prRec(cut)));
  /* A service with only one unit settles it itself — nobody is asked a question with one answer. */
  ok('a service with one unit needs no answer',
     A.prUnit(A.prRec({ vendor: 'VND001', service: 'Stitching', at: 'Napkin', sub: 'Border Napkin',
       size: '20x20', rate: '6' })) === 'per pc');
  /* The boxes for the OTHER kind are ignored rather than stored, so a rate never carries a fabric
   * and a size at the same time and leaves nobody guessing which one was meant. */
  const mixed = A.prRec(Object.assign({}, cut, { fabric: 'Voil 92', print: 'Vertical' }));
  ok('the boxes for the other kind are dropped, not stored', !mixed.fabric && !mixed.print, JSON.stringify(mixed));

  ok('a rate with no vendor is refused', /Pick the vendor/.test(A.prCheck(Object.assign({}, cut, { vendor: '' }), -1)));
  ok('printing with no fabric is refused', /priced by fabric/.test(A.prCheck(Object.assign({}, run, { fabric: '' }), -1)));
  /* A size is not optional: a printer's price for a 60X60 is not their price for a 70X108. */
  ok('piecework with no size is refused', /60X60 rate is not a 70X108/.test(A.prCheck(Object.assign({}, cut, { size: '' }), -1)),
     A.prCheck(Object.assign({}, cut, { size: '' }), -1));
  ok('a zero rate is refused', /more than zero/.test(A.prCheck(Object.assign({}, cut, { rate: '0' }), -1)));
  /* PROPOSING IS OPEN, APPROVING IS NOT. It was the other way round — only an admin could write a
   * rate at all — which left everybody else with nothing to do but ask somebody to type it. */
  ME.admin = false;
  ok('somebody who cannot approve may still propose a rate', A.prCheck(cut, -1) === '', A.prCheck(cut, -1));
  ok('…and what they propose is only a proposal', A.prStatus(A.prRec(cut)) === 'Pending');
  ok('…which prices nothing', A.prApproved(A.prRec(cut)) === false);
  ME.admin = true;
  ok('an approver\u2019s own rate is approved as it is written', A.prStatus(A.prRec(cut)) === 'Approved');
  ok('…and stamped with their name', A.prRec(cut).approvedBy === ME.email);

  /* ---- ONE FIRM, TWO SERVICES. The fabricator cuts embroidery napkins AND stitches pieces, so the
   * service belongs to the work and not to the vendor. Keying off the vendor's category would have
   * made this impossible to price. ---- */
  const fabCut = { vendor: 'VND001', service: 'Cutting', at: 'Napkin', sub: 'Border Napkin', size: '20x20', rate: '4' };
  const fabStitch = Object.assign({}, fabCut, { service: 'Stitching', rate: '6' });
  ok('one vendor can be paid for two different services',
     A.prCheck(fabCut, -1) === '' && A.prKey(A.prRec(fabCut)) !== A.prKey(A.prRec(fabStitch)),
     A.prKey(A.prRec(fabCut)) + '  vs  ' + A.prKey(A.prRec(fabStitch)));
  ok('…and neither is priced by the metre',
     A.prUnit(A.prRec(fabCut)) === 'per pc' && A.prUnit(A.prRec(fabStitch)) === 'per pc');

  /* ---- FILLING. Ravi's own sheet prices the same quilt twice: Rs.550 on surgical cotton and Rs.450
   * on cotton. Without the filler in the key the second is a duplicate of the first, and the wrong
   * one of the two would price every quilt. ---- */
  const q1 = { vendor: 'VND001', service: 'Filling', at: 'Quilt', sub: 'Twin Quilt', size: '60x90',
    filler: 'Surgical Cotton', weight: '1', rate: '550' };
  const q2 = Object.assign({}, q1, { filler: 'Cotton', rate: '450' });
  ok('a filling rate is accepted', A.prCheck(q1, -1) === '', A.prCheck(q1, -1));
  ok('…and the same quilt in a different filler is a DIFFERENT rate',
     A.prKey(A.prRec(q1)) !== A.prKey(A.prRec(q2)), A.prKey(A.prRec(q1)));
  ok('…as is the same filler at a different weight',
     A.prKey(A.prRec(q1)) !== A.prKey(A.prRec(Object.assign({}, q1, { weight: '1.75' }))));
  ok('filling with no filler named is refused',
     /name the filler material/i.test(A.prCheck(Object.assign({}, q1, { filler: '' }), -1)),
     A.prCheck(Object.assign({}, q1, { filler: '' }), -1));
  ok('…and with no weight', /weight in kg/i.test(A.prCheck(Object.assign({}, q1, { weight: '' }), -1)),
     A.prCheck(Object.assign({}, q1, { weight: '' }), -1));
  ok('the filler and the weight are part of what the rate is called',
     /Surgical Cotton/.test(A.prWhat(A.prRec(q1))) && /1 kg/.test(A.prWhat(A.prRec(q1))),
     A.prWhat(A.prRec(q1)));
  /* Nothing else is priced on what is inside it, so nothing else carries them. */
  ok('a stitching rate carries no filler at all',
     !A.prRec(fabStitch).filler && !A.prRec(fabStitch).weight, JSON.stringify(A.prRec(fabStitch)));
  ok('…and prIsFill knows which is which',
     A.prIsFill({ service: 'Filling' }) === true && A.prIsFill({ service: 'Cutting' }) === false);

  /* Seat Pad — his answer, and what the master calls it on all 13 of those SKUs. */
  ok('a seat pad filling rate is accepted',
     A.prCheck({ vendor: 'VND001', service: 'Filling', at: 'Seat Pad', sub: 'Seat Pad', size: '16x16',
       filler: 'Recron', weight: '0.65', rate: '80' }, -1) === '');

  A.setHR(Object.assign(A.HR(), { prate: [A.prRec(run), A.prRec(cut)] }));
  /* A second rate for the same combination is never reached, so it would sit there looking
   * authoritative and pricing nothing. */
  ok('a second rate for the same combination is refused',
     /already has an approved rate for/.test(A.prCheck(Object.assign({}, cut, { rate: '25' }), -1)),
     A.prCheck(Object.assign({}, cut, { rate: '25' }), -1));
  ok('…but the same work for a DIFFERENT printer is fine',
     A.prCheck(Object.assign({}, cut, { vendor: 'VND001' }), -1) === '');
  ok('…and editing that very rate is not a duplicate of itself',
     A.prCheck(Object.assign({}, cut, { rate: '25' }), 1) === '');

  /* Which rate a line is priced at. An order line is block printing — the only kind this app raises. */
  const vo = A.VO().rows;
  ok('a running line finds its printer\'s metre rate',
     A.prRateFor('VND001', vo[0], vo[0].lines[0]) === 14, String(A.prRateFor('VND001', vo[0], vo[0].lines[0])));
  ok('a cut line finds its printer\'s piece rate',
     A.prRateFor('VND002', vo[1], vo[1].lines[0]) === 22, String(A.prRateFor('VND002', vo[1], vo[1].lines[0])));
  /* A filling or stitching rate is never reached from an order line — nothing has ordered that work. */
  ok('a filling rate is not reached by an order line', (() => {
    const was = A.HR().prate;
    A.setHR(Object.assign(A.HR(), { prate: [A.prRec(Object.assign({}, q1, { vendor: 'VND002',
      at: 'Tablecloth', sub: 'Square Tablecloth', size: '60X60' }))] }));
    const got = A.prRateFor('VND002', vo[1], vo[1].lines[0]);
    A.setHR(Object.assign(A.HR(), { prate: was }));
    return got === null; })());
  /* THE CUT LINE CARRIES NO ARTICLE OR SIZE OF ITS OWN — they come off the master row, the way every
   * other screen here reads a SKU. */
  ok('…reading the article and size off the master row', !vo[1].lines[0].articleType);
  /* NO FALLBACK LADDER, unlike the employee rates. A wrong rate on a purchase order is money. */
  ok('another printer\'s rate is not borrowed', A.prRateFor('VND001', vo[1], vo[1].lines[0]) === null);
  ok('and a rate that does not match exactly is not used',
     A.prRateFor('VND002', vo[1], { kind: 'cut', sku: 'RTC-6060', size: '70X108',
       articleType: 'Tablecloth', articleSubtype: 'Square Tablecloth' }) === null);

  /* A rate nothing matches is not wrong, but it will never be reached — and the number itself gives
   * no hint of that. */
  ok('a rate that prices a live line says so', A.prUsage(A.HR().prate[1]) === 1, String(A.prUsage(A.HR().prate[1])));
  ok('…and one that matches nothing says none',
     A.prUsage(A.prRec(Object.assign({}, cut, { size: '99X99' }))) === 0);
  /* A cancelled order is not live work. */
  A.setVO(Object.assign(A.VO(), { rows: [Object.assign({}, vo[1], { status: 'Cancelled' })] }));
  ok('a cancelled order does not count as a match', A.prUsage(A.HR().prate[1]) === 0);
  A.setVO(Object.assign(A.VO(), { rows: vo }));

  /* The screen, vendor by vendor — which is how Ravi asked for it. */
  els.hrView.value = 'prate'; els.hrQ.value = '';
  A.renderHr();
  const h = els.hrTable.innerHTML;
  ok('each printer heads its own block', /RBP-Bagru/.test(h) && /Choudhary Hand Block/.test(h), h.slice(0, 700));
  ok('…with what it charges and for what', /Rs\.14/.test(h) && /Voil 92 · Vertical/.test(h), h);
  ok('…and what the work is', /Block print/.test(h), h.slice(0, 600));
  ok('…and whether the rate is by the metre or the piece', /per m</.test(h) && /per pc</.test(h), h);
  ok('…and how many live lines it would price', /On live orders/.test(h));
  ok('the panel counts the vendors', /Vendors/.test(els.hrKpis.innerHTML), els.hrKpis.innerHTML);
  ok('an empty list says how to start', (() => {
    A.setHR(Object.assign(A.HR(), { prate: [] })); A.renderHr();
    return /New rate/.test(els.hrTable.innerHTML); })(), els.hrTable.innerHTML);
  /* And explains the model, because filling is the one nobody would guess. */
  ok('…and explains that filling carries a filler and a weight',
     /filler and its weight/.test(els.hrMsg.textContent), els.hrMsg.textContent);

  /* ================= WHEN A RATE REACHES A LINE =================
   *
   * The column said "none" on 112 of Ravi's 116 rates, and only one of the four reasons was a rate
   * genuinely pricing no work. Each block below is one of the other three, with the live row that
   * showed it. */
  A.setHR(Object.assign(A.HR(), { prate: [] }));

  /* ---- A SIZE IS THE SAME SIZE WRITTEN EITHER WAY ROUND ----
   *
   * Sixteen of his rates say 90x60 where the order book says 60X90. It is one rectangular cloth. */
  ok('a size written back to front is the same size',
     A.prSizeKey('90x60') === A.prSizeKey('60X90'), A.prSizeKey('90x60') + ' vs ' + A.prSizeKey('60X90'));
  ok('…and the inch mark is not part of it', A.prSizeKey('72"') === A.prSizeKey('72'));
  ok('…nor which times sign was typed',
     A.prSizeKey('16' + String.fromCharCode(0x00D7) + '90') === A.prSizeKey('16x90'));
  /* AND TWO DIFFERENT SIZES STAY DIFFERENT — that is the whole risk of folding them at all. */
  ok('…but 60x60 and 60x90 are still two sizes', A.prSizeKey('60x60') !== A.prSizeKey('60x90'));
  ok('…and a round cloth is not a square one', A.prSizeKey('60 Round') !== A.prSizeKey('60x60'));

  /* ---- A ROUND CLOTH SAYS THE WORD TWICE ----
   *
   * Seventeen round rates across three printers say "90 Round" where the order book says "90", and
   * the subtype has already said Round Tablecloth on both. */
  ok('a round size is the same with the word and without it',
     A.prSizeKey('90 Round') === A.prSizeKey('90'), A.prSizeKey('90 Round') + ' vs ' + A.prSizeKey('90'));
  ok('…and 90 round is still not 110 round', A.prSizeKey('90 Round') !== A.prSizeKey('110 Round'));
  /* A MISSPELLING IS NOT FOLDED. Teaching the app to read noise is how noise gets in; that row says
   * none until somebody corrects it, which is the truth about it. */
  ok('…and a misspelt one is not quietly accepted',
     A.prSizeKey('72 Roundd') !== A.prSizeKey('72'), A.prSizeKey('72 Roundd'));
  {
    const wasMdb4 = A.PTG().mdb;
    A.setPTG(Object.assign(A.PTG(), { mdb: (wasMdb4 || []).concat([
      { sku: 'RTC-R90', articleType: 'Tablecloth', subtype: 'Round Tablecloth', size: '90' }]) }));
    const o = { vendorCode: 'VND002', id: 'q12', orderType: 'cut', status: 'Placed',
      lines: [{ kind: 'cut', sku: 'RTC-R90', qty: 6 }] };
    const rate = A.prRec({ vendor: 'VND002', service: 'Block print', kind: 'cut',
      at: 'Tablecloth', sub: 'Round Tablecloth', size: '90 Round', rate: '44' });
    ok('…so a "90 Round" rate reaches the round line the book calls 90',
       A.prLineMatches(rate, o, o.lines[0]) === true);
    /* AND A SQUARE CLOTH OF THE SAME NUMBER IS NOT REACHED, because the subtype is what keeps the
     * two apart once the word is gone from the size. */
    A.setPTG(Object.assign(A.PTG(), { mdb: (wasMdb4 || []).concat([
      { sku: 'RTC-S90', articleType: 'Tablecloth', subtype: 'Square Tablecloth', size: '90' }]) }));
    const sq = { vendorCode: 'VND002', id: 'q13', orderType: 'cut', status: 'Placed',
      lines: [{ kind: 'cut', sku: 'RTC-S90', qty: 6 }] };
    ok('…but the square cloth of the same number is not',
       A.prLineMatches(rate, sq, sq.lines[0]) === false);
    A.setPTG(Object.assign(A.PTG(), { mdb: wasMdb4 }));
  }

  /* ---- RECTANGLE AND RECTANGULAR ----
   *
   * His rate list says one, his master database says the other, about the same cloth. */
  ok('rectangle and rectangular are one word',
     A.prNameKey('Rectangle Tablecloth') === A.prNameKey('Rectangular Tablecloth'));
  ok('…and it is a named pair, not a guess at English',
     Array.isArray(A.PR_SPELL) && A.PR_SPELL.length >= 1 && A.PR_SPELL[0].length === 2,
     JSON.stringify(A.PR_SPELL));
  ok('…while a square tablecloth is still a different thing',
     A.prNameKey('Square Tablecloth') !== A.prNameKey('Rectangle Tablecloth'));

  /* ---- AND THE TWO TOGETHER REACH THE LINE ----
   *
   * VND004's sixteen rectangle rates, in the shape they are stored in today. */
  {
    const wasMdb2 = A.PTG().mdb;
    A.setPTG(Object.assign(A.PTG(), { mdb: (wasMdb2 || []).concat([
      { sku: 'RTC-6090', articleType: 'Tablecloth', subtype: 'Rectangular Tablecloth', size: '60X90' }]) }));
    const o = { vendorCode: 'VND002', id: 'q3', orderType: 'cut', status: 'Placed',
      lines: [{ kind: 'cut', sku: 'RTC-6090', qty: 12 }] };
    const rate = A.prRec({ vendor: 'VND002', service: 'Block print', kind: 'cut',
      at: 'Tablecloth', sub: 'Rectangle Tablecloth', size: '90x60', rate: '31' });
    ok('a rectangle rate reaches the rectangular line it was written for',
       A.prLineMatches(rate, o, o.lines[0]) === true);
    A.setVO(Object.assign(A.VO(), { rows: (A.VO().rows || []).concat([o]) }));
    ok('…so the column counts it instead of saying none', A.prUsage(rate) === 1, String(A.prUsage(rate)));
    /* AND THE MONEY AGREES WITH THE COLUMN, because both go through the same function. A count that
     * says one and a price that says nothing is the state this screen was already in. */
    A.setHR(Object.assign(A.HR(), { prate: [rate] }));
    ok('…and the same line is actually priced at it',
       A.prRateFor('VND002', o, o.lines[0]) === 31, String(A.prRateFor('VND002', o, o.lines[0])));
    A.setHR(Object.assign(A.HR(), { prate: [] }));
    A.setVO(Object.assign(A.VO(), { rows: (A.VO().rows || []).filter(x => x.id !== 'q3') }));
    A.setPTG(Object.assign(A.PTG(), { mdb: wasMdb2 }));
  }

  /* ---- WHAT WORK A LINE IS, READ FROM THE FIRM IT WAS PLACED WITH ----
   *
   * VND007 is a filling firm with fifteen live quilt lines and six quilt rates, and the column threw
   * every one of them out on a comment of mine saying an order line is only ever block printing. */
  {
    const wasMasters = A.PTG().masters, wasMdb3 = A.PTG().mdb;
    A.setPTG(Object.assign(A.PTG(), {
      mdb: (wasMdb3 || []).concat([{ sku: 'RQL14-Q', articleType: 'Quilt', subtype: 'Queen Quilt', size: '90x96' }]),
      masters: Object.assign({}, wasMasters, { vendor: (wasMasters.vendor || []).concat([
        { code: 'VND007', desc: 'Alisha Garments', category: 'Filling', active: true },
        { code: 'VND013', desc: 'Jatin Singh', category: 'Fabricator', active: true },
        { code: 'VND099', desc: 'Nothing written down', active: true }]) }) }));
    const o = { vendorCode: 'VND007', id: 'q7', orderType: 'cut', status: 'Placed',
      lines: [{ kind: 'cut', sku: 'RQL14-Q', qty: 5 }] };
    const fill = A.prRec({ vendor: 'VND007', service: 'Filling', kind: 'cut', at: 'Quilt',
      sub: 'Queen Quilt', size: '90X96', filler: 'Surgical Cotton', weight: '1', rate: '220' });
    ok('a filling firm\'s quilt rate reaches its quilt line',
       A.prLineMatches(fill, o, o.lines[0]) === true);
    /* AND THE GATE STILL SHUTS THE OTHER WAY. Printing work is not what this firm was given. */
    const print = A.prRec({ vendor: 'VND007', service: 'Block print', kind: 'cut', at: 'Quilt',
      sub: 'Queen Quilt', size: '90X96', rate: '220' });
    ok('…but a printing rate on that same firm reaches nothing',
       A.prLineMatches(print, o, o.lines[0]) === false);
    ok('the firm\'s kind is what decides',
       A.prLineServices('VND007').join(',') === 'Filling', A.prLineServices('VND007').join(','));
    /* A FABRICATOR BOTH CUTS AND STITCHES at two different rates, so both are reachable and the rate
     * that exists decides which. Guessing one would file a price where nobody would look for it. */
    ok('a fabricator can be reached by either of its two jobs',
       A.prLineServices('VND013').join(',') === 'Cutting,Stitching', A.prLineServices('VND013').join(','));
    /* AND A FIRM WITH NO KIND WRITTEN DOWN GATES NOTHING. A guard that cannot see its data and
     * answers no is the same mistake as the one this replaced, pointing the other way. */
    ok('a firm with no kind recorded is not gated on work at all',
       A.prLineServices('VND099').length === A.PR_SERVICES.length, A.prLineServices('VND099').join(','));
    A.setPTG(Object.assign(A.PTG(), { masters: wasMasters, mdb: wasMdb3 }));
  }

  /* ---- METRES AND PIECES ARE NOT INTERCHANGEABLE ----
   *
   * THE EMPTY-AGAINST-EMPTY CASE. A cut line reads its article, subtype and size off the master row,
   * and a SKU the master does not have leaves all three blank. A running rate carries those three
   * blank too, always — so without the unit test, a line nobody could identify would match every
   * metre rate the printer has and be paid by the metre. */
  {
    const o = { vendorCode: 'VND001', id: 'q8', orderType: 'cut', status: 'Placed',
      lines: [{ kind: 'cut', sku: 'SKU-NOBODY-HAS', qty: 9 }] };
    const metres = A.prRec({ vendor: 'VND001', service: 'Block print', kind: 'running',
      fabric: 'Voil 92', print: 'Vertical', rate: '14' });
    ok('a piece line is never priced by a metre rate, even when nothing is known about it',
       A.prLineMatches(metres, o, o.lines[0]) === false);
    const pieces = A.prRec({ vendor: 'VND001', service: 'Block print', kind: 'cut',
      at: 'Tablecloth', sub: 'Square Tablecloth', size: '60X60', rate: '22' });
    const run = { vendorCode: 'VND001', id: 'q9', orderType: 'running', status: 'Placed',
      lines: [{ kind: 'running', fabricType: 'Voil 92', printDirection: 'Vertical', meters: 50 }] };
    ok('…and a metre line is never priced by a piece rate',
       A.prLineMatches(pieces, run, run.lines[0]) === false);

    /* ---- THE SAME CLOTH PRINTED THE OTHER WAY IS ANOTHER PRICE ----
     *
     * VND001 has Sheeting 82 running both ways on live orders today, and they are two rates. */
    const vert = A.prRec({ vendor: 'VND001', service: 'Block print', kind: 'running',
      fabric: 'Sheeting 82', print: 'Vertical', rate: '16' });
    const horiz = A.prRec({ vendor: 'VND001', service: 'Block print', kind: 'running',
      fabric: 'Sheeting 82', print: 'Horizontal', rate: '19' });
    const hLine = { vendorCode: 'VND001', id: 'q10', orderType: 'running', status: 'Placed',
      lines: [{ kind: 'running', fabricType: 'Sheeting 82', printDirection: 'Horizontal', meters: 40 }] };
    ok('the print direction picks which of the two metre rates applies',
       A.prLineMatches(horiz, hLine, hLine.lines[0]) === true
       && A.prLineMatches(vert, hLine, hLine.lines[0]) === false);
    A.setHR(Object.assign(A.HR(), { prate: [vert, horiz] }));
    ok('…and the line is paid at that one and not the other',
       A.prRateFor('VND001', hLine, hLine.lines[0]) === 19,
       String(A.prRateFor('VND001', hLine, hLine.lines[0])));
    A.setHR(Object.assign(A.HR(), { prate: [] }));

    /* ---- A CANCELLED LINE IS NOT WORK ----
     *
     * The order is live, one line on it is not. Counting it would tell Ravi a rate is reaching work
     * that nobody is doing. */
    const mixed = { vendorCode: 'VND001', id: 'q11', orderType: 'running', status: 'Placed',
      lines: [{ kind: 'running', fabricType: 'Sheeting 82', printDirection: 'Horizontal', meters: 40 },
        { kind: 'running', fabricType: 'Sheeting 82', printDirection: 'Horizontal', meters: 25, cancelled: true }] };
    A.setVO(Object.assign(A.VO(), { rows: [mixed] }));
    ok('a cancelled line on a live order is not counted',
       A.prUsage(horiz) === 1, String(A.prUsage(horiz)));
    A.setVO(Object.assign(A.VO(), { rows: vo }));
  }

  /* ---- AND THE DUPLICATE CHECK READS IT THE SAME WAY ----
   *
   * Two rates that would be reached by the same line are not two prices to choose between. */
  ok('rectangle 90x60 and rectangular 60X90 are one rate',
     A.prKey(A.prRec({ vendor: 'VND002', kind: 'cut', at: 'Tablecloth', sub: 'Rectangle Tablecloth', size: '90x60', rate: '1' }))
     === A.prKey(A.prRec({ vendor: 'VND002', kind: 'cut', at: 'Tablecloth', sub: 'Rectangular Tablecloth', size: '60X90', rate: '1' })));
  ok('…while two genuinely different sizes stay two rates',
     A.prKey(A.prRec({ vendor: 'VND002', kind: 'cut', at: 'Tablecloth', sub: 'Rectangle Tablecloth', size: '90x60', rate: '1' }))
     !== A.prKey(A.prRec({ vendor: 'VND002', kind: 'cut', at: 'Tablecloth', sub: 'Rectangle Tablecloth', size: '90x70', rate: '1' })));

  ME.admin = wasAdmin;
  A.setHR(wasHR); A.setVO(wasVO);
  A.setPTG(Object.assign(A.PTG(), { mdb: wasMdb }));
}

console.log('\n== what each vendor is owed ==');
{
  const wasHR = A.HR(), wasVO = A.VO(), wasMdb = A.PTG().mdb, wasMasters = A.PTG().masters, wasAdmin = ME.admin;
  ME.admin = true;
  A.setPTG(Object.assign(A.PTG(), {
    mdb: [{ sku: 'RTC-6060', articleType: 'Tablecloth', subtype: 'Square Tablecloth', size: '60X60' },
      { sku: 'RTC-7010', articleType: 'Tablecloth', subtype: 'Rectangular Tablecloth', size: '70X108' }],
    masters: Object.assign({}, A.PTG().masters, { vendor: [
      { code: 'VND001', desc: 'RBP-Bagru', category: 'Printer', active: true },
      { code: 'VND002', desc: 'Choudhary Hand Block', category: 'Printer', active: true },
      { code: 'VND007', desc: 'Alisha Garments', category: 'Filling', active: true }] }) }));

  const del = (qty, day, ok) => Object.assign({ qty, date: day, by: 'p@x', at: '2026-09-20T04:00:00Z' },
    ok ? { ok: Object.assign({ by: 'me@x', at: '2026-09-20T05:00:00Z' }, ok) } : {});
  const rate = v => A.prRec(Object.assign({ service: 'Block print', kind: 'cut' }, v));

  /* One printer, one cloth, one accepted delivery, one approved rate. Everything else is a variation
   * on this row. */
  A.setHR(Object.assign(A.HR(), { prate: [
    rate({ vendor: 'VND002', at: 'Tablecloth', sub: 'Square Tablecloth', size: '60X60', rate: '22' }),
    rate({ vendor: 'VND002', service: 'Block print', kind: 'running', fabric: 'Voil 92', print: 'Vertical', rate: '14' })] }));
  A.setVO({ busy: false, err: '', at: '', shown: [], map: {}, rows: [
    { vendorCode: 'VND002', id: 'p1', orderNo: 'VPO-P1', orderType: 'cut', status: 'Placed',
      lines: [{ kind: 'cut', sku: 'RTC-6060', qty: 100,
        deliveries: [del(10, '05/09/2026', { qty: 10 })] }] }] });
  els.hrMonth.value = '2026-09'; els.hrPeriod.value = '1'; els.hrQ.value = '';

  {
    const r = A.vpayRows(2026, 9, 1);
    ok('an accepted delivery is owed at its printer\'s rate',
       r.length === 1 && r[0].qty === 10 && r[0].rate === 22 && r[0].amount === 220, JSON.stringify(r));
    ok('…and it is named by the vendor and the work',
       r[0].vendorCode === 'VND002' && /Square Tablecloth/.test(r[0].what), JSON.stringify(r[0]));
    ok('…and priced by the piece', r[0].unit === 'pcs' && r[0].run === false);
  }

  /* WHAT WAS KEPT, NOT WHAT WAS CLAIMED. The printer said twelve and eight were taken in. */
  A.VO().rows[0].lines[0].deliveries = [del(12, '05/09/2026', { qty: 8 })];
  ok('the vendor is paid for what was kept, not what the challan said',
     A.vpayRows(2026, 9, 1)[0].amount === 176, JSON.stringify(A.vpayRows(2026, 9, 1)[0]));

  /* RETURNED PIECES ARE NOT PAID. Paying for them would pay for them twice: the printer still owes
   * the work and will deliver it again. */
  A.VO().rows[0].lines[0].deliveries = [del(12, '05/09/2026', { qty: 8, rej: 4 })];
  {
    const r = A.vpayRows(2026, 9, 1)[0];
    ok('returned pieces are not paid for', r.amount === 176 && r.qty === 8, JSON.stringify(r));
    ok('…but they are shown, because the work is still owed', r.rej === 4);
  }

  /* MORE THAN THE CHALLAN IS PAID, because it was taken in — and shown apart, because it is the
   * figure somebody will query. */
  A.VO().rows[0].lines[0].deliveries = [del(10, '05/09/2026', { qty: 12, over: 2, note: 'challan 88' })];
  {
    const r = A.vpayRows(2026, 9, 1)[0];
    ok('pieces taken in over the challan are paid for', r.amount === 264 && r.qty === 12, JSON.stringify(r));
    ok('…and the excess is shown on its own', r.over === 2);
  }

  /* NOT YET ACCEPTED IS NOT YET OWED. A claim nobody has checked is not a bill. */
  A.VO().rows[0].lines[0].deliveries = [del(10, '05/09/2026', null)];
  ok('a delivery nobody has accepted is owed nothing yet', A.vpayRows(2026, 9, 1).length === 0);

  /* DATED BY THE DAY THE GOODS CAME. Delivered on the 14th, accepted on the 17th — that is the work
   * of the first fortnight, and putting it in the second would move a figure Ravi had already
   * checked. */
  A.VO().rows[0].lines[0].deliveries = [del(10, '14/09/2026', { qty: 10, at: '2026-09-17T05:00:00Z' })];
  ok('a delivery is dated by the day it came, not the day it was accepted',
     A.vpayRows(2026, 9, 1).length === 1 && A.vpayRows(2026, 9, 2).length === 0,
     A.vpayRows(2026, 9, 1).length + '/' + A.vpayRows(2026, 9, 2).length);
  ok('…and the full month holds both halves', A.vpayRows(2026, 9, 3).length === 1);
  ok('…and another month holds none of it', A.vpayRows(2026, 8, 3).length === 0);
  ok('…which is all vpayInWindow decides',
     A.vpayInWindow({ date: '14/09/2026' }, { from: '2026-09-01', to: '2026-09-15' }) === true
     && A.vpayInWindow({ date: '16/09/2026' }, { from: '2026-09-01', to: '2026-09-15' }) === false);
  ok('…and a delivery with no readable date is not owed in any period',
     A.vpayInWindow({ date: '' }, { from: '2026-09-01', to: '2026-09-15' }) === false);

  /* A CANCELLED ORDER STILL OWES WHAT WAS TAKEN IN. Thirteen accepted deliveries, 275 pieces, were
   * sitting on cancelled orders in the live book and had dropped out of every bill. Cancelling the
   * rest of an order does not un-receive the goods that came before it. */
  A.VO().rows[0].lines[0].deliveries = [del(10, '05/09/2026', { qty: 10 })];
  A.setVO(Object.assign(A.VO(), { rows: [Object.assign({}, A.VO().rows[0], { status: 'Cancelled' })] }));
  {
    const r = A.vpayRows(2026, 9, 1);
    ok('a cancelled order still owes what was accepted on it',
       r.length === 1 && r[0].amount === 220, JSON.stringify(r));
    ok('…and says so, because that is the figure somebody will query', (r[0] || {}).gone === 10, JSON.stringify(r[0]));
    els.hrView.value = 'vpay'; els.hrMonth.value = '2026-09'; els.hrPeriod.value = '1'; els.hrQ.value = '';
    A.renderHr();
    ok('…on the screen', /on a cancelled order/.test(els.hrTable.innerHTML), els.hrTable.innerHTML.slice(0, 600));
    A.ptOpenDialog({ title: 'cleared', html: '', note: '' });
    if (r[0]) A.vpayShowDrill(r[0].key);
    ok('…and in the drill-down', /cancelled/.test((A.PTD_() || {}).html || ''), String((A.PTD_() || {}).html).slice(0, 400));
  }
  A.setVO(Object.assign(A.VO(), { rows: [Object.assign({}, A.VO().rows[0], { status: 'Placed',
    lines: [Object.assign({}, A.VO().rows[0].lines[0], { cancelled: true })] })] }));
  ok('…and a cancelled line likewise', A.vpayRows(2026, 9, 1).length === 1 && (A.vpayRows(2026, 9, 1)[0] || {}).gone === 10);
  /* WHILE THE COLUMN ON THE RATE LIST STILL MEANS LIVE WORK — a cancelled order is not work a rate
   * would be reached by tomorrow. The two screens ask two different questions. */
  ok('…while the rate list still counts only live work',
     A.prUsage(A.HR().prate[0]) === 0, String(A.prUsage(A.HR().prate[0])));

  /* NO RATE IS NOT FREE WORK. The pieces arrived and are owed; what is missing is the price. */
  A.setVO({ busy: false, err: '', at: '', shown: [], map: {}, rows: [
    { vendorCode: 'VND002', id: 'p2', orderNo: 'VPO-P2', orderType: 'cut', status: 'Placed',
      lines: [{ kind: 'cut', sku: 'RTC-7010', qty: 50, deliveries: [del(6, '05/09/2026', { qty: 6 })] }] }] });
  {
    const r = A.vpayRows(2026, 9, 1);
    ok('work with no approved rate is listed, not hidden', r.length === 1 && r[0].qty === 6, JSON.stringify(r));
    ok('…with no rate rather than a rate of zero', r[0].rate === null);
    ok('…and it adds nothing to what is payable', r[0].amount === 0);
  }

  /* A DELIVERY WHERE NOTHING WAS KEPT IS NOT A LINE ON A BILL.
   *
   * Accepting zero is a real answer — everything arrived short, or everything was sent back — and it
   * would otherwise sit on the payout as a row of nothing, at a rate, for somebody to wonder about. */
  A.setVO({ busy: false, err: '', at: '', shown: [], map: {}, rows: [
    { vendorCode: 'VND002', id: 'p2b', orderNo: 'VPO-P2B', orderType: 'cut', status: 'Placed',
      lines: [{ kind: 'cut', sku: 'RTC-6060', qty: 50, deliveries: [del(6, '05/09/2026', { qty: 0, rej: 6 })] }] }] });
  ok('a delivery where nothing was kept is not a line at all', A.vpayRows(2026, 9, 1).length === 0,
     JSON.stringify(A.vpayRows(2026, 9, 1)));

  /* AND TWO FIRMS DOING THE SAME WORK ARE TWO BILLS. Merging them would hand one printer's pieces to
   * another printer's total, at another printer's rate. */
  A.setHR(Object.assign(A.HR(), { prate: [
    rate({ vendor: 'VND002', at: 'Tablecloth', sub: 'Square Tablecloth', size: '60X60', rate: '22' }),
    /* THE SAME PRICE ON BOTH, deliberately. With two different rates the rate alone would keep them
     * apart and the vendor could drop out of the key unnoticed — which is exactly how one firm's
     * pieces end up in another firm's total. */
    rate({ vendor: 'VND001', at: 'Tablecloth', sub: 'Square Tablecloth', size: '60X60', rate: '22' })] }));
  A.setVO({ busy: false, err: '', at: '', shown: [], map: {}, rows: [
    { vendorCode: 'VND002', id: 'p2c', orderNo: 'VPO-P2C', orderType: 'cut', status: 'Placed',
      lines: [{ kind: 'cut', sku: 'RTC-6060', qty: 50, deliveries: [del(10, '05/09/2026', { qty: 10 })] }] },
    { vendorCode: 'VND001', id: 'p2d', orderNo: 'VPO-P2D', orderType: 'cut', status: 'Placed',
      lines: [{ kind: 'cut', sku: 'RTC-6060', qty: 50, deliveries: [del(10, '05/09/2026', { qty: 10 })] }] }] });
  {
    const r = A.vpayRows(2026, 9, 1);
    ok('two firms doing the same work are two rows, not one',
       r.length === 2 && r.map(x => x.vendorCode).sort().join(',') === 'VND001,VND002',
       JSON.stringify(r.map(x => x.vendorCode)));
    ok('…even when both charge exactly the same',
       r.map(x => x.amount).join(',') === '220,220', JSON.stringify(r.map(x => x.amount)));
  }
  A.setHR(Object.assign(A.HR(), { prate: [
    rate({ vendor: 'VND002', at: 'Tablecloth', sub: 'Square Tablecloth', size: '60X60', rate: '22' }),
    rate({ vendor: 'VND002', service: 'Block print', kind: 'running', fabric: 'Voil 92', print: 'Vertical', rate: '14' })] }));

  /* ---- A-1: "ALL" MEANS ANY NUMBER OF COLOURS, NOT A LABEL ----
   *
   * Fifty-one of Ravi's 116 rates say "All" in the colours column. It has no digit, so it read as a
   * label — the "Gadd" mechanism — and a labelled rate is recorded, never matched. Every one of them
   * priced nothing. */
  {
    const all = A.prRec({ vendor: 'VND002', service: 'Block print', kind: 'cut',
      at: 'Tablecloth', sub: 'Square Tablecloth', size: '60X60', colours: 'All', rate: '22' });
    ok('"All" in the colours column is not a label', A.prColIsLabel(all) === false, JSON.stringify(all.colours));
    ok('…and is stored as blank, which is what it means', all.colours === '', JSON.stringify(all.colours));
    A.setHR(Object.assign(A.HR(), { prate: [] }));   // the duplicate check must see nothing
    ok('…and the form accepts it', A.prCheck({ vendor: 'VND002', service: 'Block print', kind: 'cut',
      at: 'Tablecloth', sub: 'Square Tablecloth', size: '60X60', colours: 'All', rate: '22' }, -1) === '',
      A.prCheck({ vendor: 'VND002', service: 'Block print', kind: 'cut', at: 'Tablecloth', sub: 'Square Tablecloth', size: '60X60', colours: 'All', rate: '22' }, -1));
    A.setHR(Object.assign(A.HR(), { prate: [all] }));
    A.setVO({ busy: false, err: '', at: '', shown: [], map: {}, rows: [
      { vendorCode: 'VND002', id: 'pa1', orderNo: 'VPO-A1', orderType: 'cut', status: 'Placed',
        lines: [{ kind: 'cut', sku: 'RTC-6060', qty: 20, colours: 3, deliveries: [del(10, '05/09/2026', { qty: 10 })] }] }] });
    /* AS IT IS STORED TODAY. The fifty-one live rows say "All" in the database and never pass through
     * prRec again, so nothing blanks them on the way in — prColLabel is all that rescues them. */
    const stored = Object.assign({}, all, { colours: 'All' });
    ok('a row already stored as "All" is not a label either', A.prColIsLabel(stored) === false);
    A.setHR(Object.assign(A.HR(), { prate: [stored] }));
    ok('…and prices the line without being saved again',
       A.prRateFor('VND002', A.VO().rows[0], A.VO().rows[0].lines[0]) === 22,
       String(A.prRateFor('VND002', A.VO().rows[0], A.VO().rows[0].lines[0])));
    A.setHR(Object.assign(A.HR(), { prate: [all] }));
    ok('…so a rate written "All" prices a three-colour design',
       A.prRateFor('VND002', A.VO().rows[0], A.VO().rows[0].lines[0]) === 22,
       String(A.prRateFor('VND002', A.VO().rows[0], A.VO().rows[0].lines[0])));
    ok('…and a design with no colour count written', (() => {
      const o = A.VO().rows[0]; return A.prRateFor('VND002', o, Object.assign({}, o.lines[0], { colours: '' })) === 22; })());
    ok('…and the payout pays it', A.vpayRows(2026, 9, 1)[0] && A.vpayRows(2026, 9, 1)[0].amount === 220,
       JSON.stringify(A.vpayRows(2026, 9, 1)));
    /* AND "GADD" IS STILL A LABEL. The fix is a short list of words meaning any, not a loosening. */
    ok('…while "Gadd" is still a label and still prices nothing by count',
       A.prColIsLabel({ colours: 'Gadd' }) === true);
  }

  /* ---- WHEN EVERY COLOUR BAND CHARGES THE SAME, THE COUNT DOES NOT MATTER ----
   *
   * One printer's whole card is "1-4" and "5+" at the same price, sixteen sizes out of sixteen, and
   * not one of 2,647 tablecloth SKUs carries a colour count: 516 received pieces went unpriced for
   * want of a number that could not have changed the answer. */
  {
    const band = (colours, r) => A.prRec({ vendor: 'VND002', service: 'Block print', kind: 'cut',
      at: 'Tablecloth', sub: 'Square Tablecloth', size: '60X60', colours, rate: r });
    const o = { vendorCode: 'VND002', id: 'pb', orderNo: 'VPO-B', orderType: 'cut', status: 'Placed',
      lines: [{ kind: 'cut', sku: 'RTC-6060', qty: 20, deliveries: [del(10, '05/09/2026', { qty: 10 })] }] };   // no colour count anywhere
    A.setHR(Object.assign(A.HR(), { prate: [band('1-4', '125'), band('5+', '125')] }));
    ok('two bands at one price need no colour count', A.prRateFor('VND002', o, o.lines[0]) === 125,
       String(A.prRateFor('VND002', o, o.lines[0])));
    A.setVO({ busy: false, err: '', at: '', shown: [], map: {}, rows: [o] });
    const row = A.vpayRows(2026, 9, 1)[0] || {};
    ok('…and the payout says that is why none was needed', /every colour band charges this/.test(row.rateNote || ''), row.rateNote);
    ok('…without claiming it was a 1-4 colour job', !/1-4/.test(row.rateNote || ''), row.rateNote);

    /* BUT BANDS THAT DISAGREE ARE A REAL CHOICE, and with no count there is nothing to make it with. */
    A.setHR(Object.assign(A.HR(), { prate: [band('1-4', '125'), band('5+', '180')] }));
    ok('two bands at two prices, and no count, is still no rate', A.prRateFor('VND002', o, o.lines[0]) === null);
    ok('…and the reason names both prices and where to put the count',
       /Rs\.125/.test(A.prRateWhy('VND002', o, o.lines[0])) && /Rs\.180/.test(A.prRateWhy('VND002', o, o.lines[0]))
       && /master database/.test(A.prRateWhy('VND002', o, o.lines[0])), A.prRateWhy('VND002', o, o.lines[0]));
    /* And a design that DOES say its count still gets its own band, same price or not. */
    const five = Object.assign({}, o, { lines: [Object.assign({}, o.lines[0], { colours: 6 })] });
    ok('…while a design that says six colours takes the 5+ band', A.prRateFor('VND002', five, five.lines[0]) === 180);
    /* A label is still not a band: "Gadd" at the same price does not make a labelled rate match. */
    A.setHR(Object.assign(A.HR(), { prate: [band('Gadd', '125')] }));
    ok('…and a labelled rate is still not reached this way', A.prRateFor('VND002', o, o.lines[0]) === null);
  }

  /* ---- A-2: TWO FILLERS, AND THE ORDER SAYS WHICH ----
   *
   * The filling firm prices the same quilt at Rs.550 in surgical cotton and Rs.450 in cotton, and an
   * order line said nothing about which — so both matched and [0] won. */
  {
    const fill = (filler, rate) => A.prRec({ vendor: 'VND007', service: 'Filling', kind: 'cut',
      at: 'Quilt', sub: 'Queen Quilt', size: '90X96', filler, weight: '1.5', rate });
    A.setHR(Object.assign(A.HR(), { prate: [fill('Surgical Cotton', '750'), fill('Cotton', '625')] }));
    A.setPTG(Object.assign(A.PTG(), { mdb: (A.PTG().mdb || []).concat([
      { sku: 'RQL14-Q', articleType: 'Quilt', subtype: 'Queen Quilt', size: '90x96' }]) }));
    const mk = (extra, lineExtra) => Object.assign({ vendorCode: 'VND007', id: 'pq', orderNo: 'VPO-Q', orderType: 'cut',
      status: 'Placed', service: 'Filling',
      lines: [Object.assign({ kind: 'cut', sku: 'RQL14-Q', qty: 5, deliveries: [del(5, '05/09/2026', { qty: 5 })] }, lineExtra || {})] }, extra || {});
    const mute = mk();
    ok('a quilt line that names no filler is priced by NEITHER rate',
       A.prRateFor('VND007', mute, mute.lines[0]) === null, String(A.prRateFor('VND007', mute, mute.lines[0])));
    ok('…and the reason names the two fillers',
       /Surgical Cotton/.test(A.prRateWhy('VND007', mute, mute.lines[0])) && /Cotton/.test(A.prRateWhy('VND007', mute, mute.lines[0]))
       && /which/.test(A.prRateWhy('VND007', mute, mute.lines[0])), A.prRateWhy('VND007', mute, mute.lines[0]));
    A.setVO({ busy: false, err: '', at: '', shown: [], map: {}, rows: [mute] });
    {
      const r = A.vpayRows(2026, 9, 1)[0];
      ok('…so the payout shows no rate, with that reason', r && r.rate === null && /two fillers/.test(r.why), JSON.stringify(r && r.why));
      els.hrView.value = 'vpay'; els.hrMonth.value = '2026-09'; els.hrPeriod.value = '1'; els.hrQ.value = '';
      A.renderHr();
      ok('…as the tooltip on the cell', /two fillers are priced/.test(els.hrTable.innerHTML), els.hrTable.innerHTML.slice(0, 700));
      A.ptOpenDialog({ title: 'cleared', html: '', note: '' });
      /* Guarded: a drill that throws must fail this test, not stop the run. */
      try { if (r) A.vpayShowDrill(r.key); } catch (e) { /* the empty dialog below fails it */ }
      ok('…and in the drill-down', /two fillers/.test((A.PTD_() || {}).note || ''), String((A.PTD_() || {}).note));
    }
    const cot = mk({ filler: 'Cotton' });
    ok('an order that says Cotton is priced at the cotton rate',
       A.prRateFor('VND007', cot, cot.lines[0]) === 625, String(A.prRateFor('VND007', cot, cot.lines[0])));
    const sur = mk({ filler: 'surgical cotton' });
    ok('…and Surgical Cotton at the other, however it is capitalised',
       A.prRateFor('VND007', sur, sur.lines[0]) === 750, String(A.prRateFor('VND007', sur, sur.lines[0])));
    const lineSays = mk({ filler: 'Cotton' }, { filler: 'Surgical Cotton' });
    ok('…and a line that says otherwise overrides its order',
       A.prRateFor('VND007', lineSays, lineSays.lines[0]) === 750);
    /* A filler nobody has a rate for is no rate, not the nearest one. */
    const foam = mk({ filler: 'Foam' });
    ok('a filler with no rate card is priced by nothing', A.prRateFor('VND007', foam, foam.lines[0]) === null
       && /no rate in the Vendor rate list/.test(A.prRateWhy('VND007', foam, foam.lines[0])), A.prRateWhy('VND007', foam, foam.lines[0]));
    /* THE ORDER SAYS WHAT WORK IT IS, and that outranks the firm's kind — an old order with nothing
     * written still reads from the kind, as before. */
    ok('the order\'s own service decides what work its lines are',
       A.prLineServices('VND002', { service: 'Filling' }).join(',') === 'Filling'
       && A.prLineServices('VND007', {}).join(',') === 'Filling', A.prLineServices('VND002', { service: 'Filling' }).join(','));
    /* A rate with only ONE filler still prices a line that names none — there is nothing to choose. */
    A.setHR(Object.assign(A.HR(), { prate: [fill('Cotton', '625')] }));
    ok('one filler on the rate card needs no word from the order',
       A.prRateFor('VND007', mute, mute.lines[0]) === 625);
    /* And the reasons for the other two ways a line ends up unpriced. */
    A.setHR(Object.assign(A.HR(), { prate: [Object.assign(fill('Cotton', '625'), { status: 'Pending' })] }));
    ok('a rate waiting for approval is named as such', /none is approved/.test(A.prRateWhy('VND007', mute, mute.lines[0])),
       A.prRateWhy('VND007', mute, mute.lines[0]));
    A.setHR(Object.assign(A.HR(), { prate: [A.prRec({ vendor: 'VND002', service: 'Block print', kind: 'cut',
      at: 'Tablecloth', sub: 'Square Tablecloth', size: '60X60', colours: '1-4', rate: '22' })] }));
    const seven = { vendorCode: 'VND002', id: 'p7', orderType: 'cut', status: 'Placed', lines: [{ kind: 'cut', sku: 'RTC-6060', qty: 1, colours: 7 }] };
    ok('…and a colour count no rate covers is named with its number',
       /7 colours/.test(A.prRateWhy('VND002', seven, seven.lines[0])), A.prRateWhy('VND002', seven, seven.lines[0]));
  }

  /* ---- AND AN ORDER ALREADY PLACED CAN BE TOLD ITS FILLER ----
   *
   * Five live filling orders, fifty lines, were raised before the form asked. The rule that prices
   * nothing without a filler was sound; having no screen on which to supply one was not. */
  {
    const fill = (filler, rate) => A.prRec({ vendor: 'VND007', service: 'Filling', kind: 'cut',
      at: 'Quilt', sub: 'Queen Quilt', size: '90X96', filler, weight: '1.5', rate });
    A.setHR(Object.assign(A.HR(), { prate: [fill('Surgical Cotton', '750'), fill('Cotton', '625')] }));
    const old = { vendorCode: 'VND007', id: 'pf1', orderNo: 'VPO-F1', orderType: 'cut', status: 'Placed',
      lines: [{ kind: 'cut', sku: 'RQL14-Q', qty: 5, deliveries: [] }] };          // no service, no filler: as they are stored
    const printing = { vendorCode: 'VND002', id: 'pf2', orderNo: 'VPO-F2', orderType: 'cut', status: 'Placed',
      lines: [{ kind: 'cut', sku: 'RTC-6060', qty: 5, deliveries: [] }] };
    A.setVO({ busy: false, err: '', at: '', shown: [], map: {}, rows: [old, printing] });
    ok('an order with a filling firm is filling work, though it never said so', A.voIsFilling(old) === true);
    ok('…and a printing order is not', A.voIsFilling(printing) === false);

    const wasAdminF = ME.admin; ME.admin = true;
    A.voOpen('VND007/pf1');
    const f = (A.PTD_().fields || []).find(x => x.key === 'filler');
    ok('the order dialog offers a filler on a filling order', !!f, JSON.stringify((A.PTD_().fields || []).map(x => x.key)));
    ok('…and says plainly that none is set', !!f && /NOT SET/.test(f.label), f && f.label);
    ok('…offering the fillers the rate list knows', !!f && (f.list || []).indexOf('Cotton') >= 0, JSON.stringify(f && f.list));
    A.voOpen('VND002/pf2');
    ok('…and not on a printing order', !(A.PTD_().fields || []).some(x => x.key === 'filler'));

    ok('before it is set the line is priced by nothing', A.prRateFor('VND007', old, old.lines[0]) === null);
    ok('…and the reason says where to go and fix it', /Open the order/.test(A.prRateWhy('VND007', old, old.lines[0])),
       A.prRateWhy('VND007', old, old.lines[0]));

    A.voOpen('VND007/pf1');
    Object.keys(QS).forEach(k => delete QS[k]);
    QS['[data-voe="0"]'] = { value: '5', disabled: false };
    els.ptf_notes = els.ptf_notes || {}; els.ptf_notes.value = '';
    els.ptf_filler.value = 'Cotton';
    NET.on = true; const at = NET.calls.length;
    let said = ''; try { said = String(await A.voEditSave() || ''); } catch (e) { said = 'threw: ' + (e.message || e); }
    ok('saving the dialog sets it', said === '', said);
    const wrote = NET.calls.slice(at).find(c => c.method === 'PUT' && /pt_vendorOrders/.test(c.url));
    ok('…on the order itself, in the database', !!wrote && wrote.body.filler === 'Cotton', JSON.stringify(wrote && wrote.body && wrote.body.filler));
    const now = (A.VO().rows || []).find(x => x.id === 'pf1') || {};
    ok('…and the line is priced at that filler\'s rate from then on',
       A.prRateFor('VND007', now, (now.lines || [])[0] || {}) === 625, String(A.prRateFor('VND007', now, (now.lines || [])[0] || {})));

    /* CLEARING THE BOX CLEARS IT. An order naming the wrong filler is paid at the wrong card without a
     * word; one naming none says so. */
    A.voOpen('VND007/pf1');
    els.ptf_filler.value = '  ';
    try { await A.voEditSave(); } catch (e) { /* the next line fails it */ }
    ok('clearing the box clears the filler', !('filler' in ((A.VO().rows || []).find(x => x.id === 'pf1') || { filler: 1 })));

    /* And a printing order never picks one up, whatever is left in the box. */
    A.voOpen('VND002/pf2');
    els.ptf_filler.value = 'Cotton';
    try { await A.voEditSave(); } catch (e) { /* the next line fails it */ }
    ok('a printing order never gains a filler', !('filler' in ((A.VO().rows || []).find(x => x.id === 'pf2') || { filler: 1 })));
    els.ptf_filler.value = ''; NET.on = false; ME.admin = wasAdminF;
  }

  /* ---- A-2, the form: a filling order has to say its filler ---- */
  {
    await A.voFormOpen();
    els.vof_service.value = 'Filling'; A.voOnServicePick();
    ok('picking Filling shows the filler box', !els.vof_fillerWrap.classList.contains('hide'));
    els.vof_service.value = 'Block print'; A.voOnServicePick();
    ok('…and printing hides it again', els.vof_fillerWrap.classList.contains('hide'));
    els.vof_service.value = 'Filling'; A.voOnServicePick();
    els.vof_vendor.value = 'VND007';
    A.setVOF(Object.assign(A.VOF(), { kind: 'cut', service: 'Filling', lines: [{ kind: 'cut', sku: 'RQL14-Q', qty: 5 }] }));
    els.vof_filler.value = '';
    /* The network is ON for the refusal too: with the guard gone the order would simply be placed,
     * and that has to read as a failed test, not as a crash on a write that had nowhere to go. */
    NET.on = true;
    let refused = '';
    try { refused = String(await A.voPlace() || ''); } catch (e) { refused = 'threw: ' + (e.message || e); }
    ok('a filling order with no filler is refused', /which filler/.test(refused), refused);
    A.setVOF(Object.assign(A.VOF(), { kind: 'cut', service: 'Filling', lines: [{ kind: 'cut', sku: 'RQL14-Q', qty: 5 }] }));
    els.vof_filler.value = 'Cotton';
    const err = await A.voPlace();
    NET.on = false;
    ok('…and with one it is placed', err === '' || err == null, String(err));
    const placed = (A.VO().rows || []).find(o => o.vendorCode === 'VND007' && o.filler);
    ok('…carrying the filler on the order', !!placed && placed.filler === 'Cotton' && placed.service === 'Filling',
       JSON.stringify(placed && { filler: placed.filler, service: placed.service }));
    A.setVOF({ kind: 'running', lines: [] });
  }
  /* Back to the two rates the block opened with, for the tests that follow. */
  A.setHR(Object.assign(A.HR(), { prate: [
    rate({ vendor: 'VND002', at: 'Tablecloth', sub: 'Square Tablecloth', size: '60X60', rate: '22' }),
    rate({ vendor: 'VND002', service: 'Block print', kind: 'running', fabric: 'Voil 92', print: 'Vertical', rate: '14' })] }));

  /* RUNNING WORK IS PAID BY THE METRE. */
  A.setVO({ busy: false, err: '', at: '', shown: [], map: {}, rows: [
    { vendorCode: 'VND002', id: 'p3', orderNo: 'VPO-P3', orderType: 'running', status: 'Placed',
      lines: [{ kind: 'running', fabricType: 'Voil 92', printDirection: 'Vertical', meters: 200,
        deliveries: [del(60, '05/09/2026', { qty: 55.5 })] }] }] });
  {
    const r = A.vpayRows(2026, 9, 1)[0];
    ok('running work is paid by the metre', r.unit === 'm' && r.run === true && r.rate === 14, JSON.stringify(r));
    ok('…and metres keep their fraction', r.qty === 55.5 && r.amount === 777, String(r.amount));
  }

  /* TWO COLOUR COUNTS OF THE SAME CLOTH ARE TWO PRICES, so they may not merge into one figure at a
   * rate that priced neither. */
  A.setHR(Object.assign(A.HR(), { prate: [
    rate({ vendor: 'VND002', at: 'Tablecloth', sub: 'Square Tablecloth', size: '60X60', colours: '1 to 4', rate: '22' }),
    rate({ vendor: 'VND002', at: 'Tablecloth', sub: 'Square Tablecloth', size: '60X60', colours: '5 or more', rate: '30' })] }));
  A.setVO({ busy: false, err: '', at: '', shown: [], map: {}, rows: [
    { vendorCode: 'VND002', id: 'p4', orderNo: 'VPO-P4', orderType: 'cut', status: 'Placed',
      lines: [{ kind: 'cut', sku: 'RTC-6060', qty: 20, colours: 2, deliveries: [del(10, '05/09/2026', { qty: 10 })] },
        { kind: 'cut', sku: 'RTC-6060', qty: 20, colours: 6, deliveries: [del(10, '05/09/2026', { qty: 10 })] }] }] });
  {
    const r = A.vpayRows(2026, 9, 1);
    ok('the same cloth at two colour counts stays two rows',
       r.length === 2 && r.map(x => x.rate).sort((a, b) => a - b).join(',') === '22,30', JSON.stringify(r.map(x => x.rate)));
    ok('…and the total is the two of them, not either one twice',
       r.reduce((t, x) => t + x.amount, 0) === 520, String(r.reduce((t, x) => t + x.amount, 0)));
  }

  /* ---- the screen ---- */
  A.setHR(Object.assign(A.HR(), { prate: [
    rate({ vendor: 'VND002', at: 'Tablecloth', sub: 'Square Tablecloth', size: '60X60', rate: '22' })] }));
  A.setVO({ busy: false, err: '', at: '', shown: [], map: {}, rows: [
    { vendorCode: 'VND002', id: 'p5', orderNo: 'VPO-P5', orderType: 'cut', status: 'Placed',
      lines: [{ kind: 'cut', sku: 'RTC-6060', qty: 100, deliveries: [del(10, '05/09/2026', { qty: 10 })] },
        { kind: 'cut', sku: 'RTC-7010', qty: 50, deliveries: [del(6, '06/09/2026', { qty: 6 })] }] }] });
  els.hrView.value = 'vpay'; els.hrMonth.value = '2026-09'; els.hrPeriod.value = '1'; els.hrQ.value = '';
  A.renderHr();
  {
    const h = els.hrTable.innerHTML;
    ok('the screen heads each vendor with its own name', /Choudhary Hand Block/.test(h), h.slice(0, 500));
    ok('…and says what the work was', /Square Tablecloth/.test(h) && /Rectangular Tablecloth/.test(h), h);
    ok('…and what it is worth', /Rs\.220/.test(h), h);
    /* A rate nobody has written says so in words, because a 0 in a money column reads as free. */
    ok('…and says "no rate" where there is none, not zero', /no rate/.test(h), h);
    ok('the panel totals what is payable', /Payable/.test(els.hrKpis.innerHTML), els.hrKpis.innerHTML);
    ok('…and warns about the lines that are priced by nothing',
       /no rate/i.test(els.hrKpis.innerHTML), els.hrKpis.innerHTML);
    /* NOTHING HERE IS SETTLED, and the screen has to say so — a total that looks final is how a
     * live figure gets paid as if it were agreed. The PANEL has to say it, beside the total itself:
     * a line of small print under the table is not where somebody reading a figure is looking. */
    ok('the panel itself says nothing on it is settled',
       /not settled|nothing on this screen is settled/i.test(els.hrKpis.innerHTML), els.hrKpis.innerHTML);
    ok('…and so does the line under the table',
       /not frozen, so a rate change will still move/i.test(els.hrMsg.textContent), els.hrMsg.textContent);
    ok('…and says what it counts and how it dates it',
       /KEPT/.test(els.hrMsg.textContent) && /day the goods came/.test(els.hrMsg.textContent),
       els.hrMsg.textContent);
    ok('the period picker is offered on this view', !els.hrPeriod.classList.contains('hide'));
    /* THE FREEZE IS OFFERED NOW. It was held back while there was nothing behind it — a button that
     * locked nothing would have said there was — and it names the fortnight it would lock. */
    ok('…and a Freeze button that names the fortnight',
       !els.hrFreeze.classList.contains('hide') && /Freeze 1st/.test(els.hrFreeze.textContent), els.hrFreeze.textContent);
    els.hrPeriod.value = '3'; A.renderHr();
    ok('…which is switched off on the whole month, because the halves are settled apart', els.hrFreeze.disabled === true);
    els.hrPeriod.value = '1'; A.renderHr();
  }

  /* ---- taking one figure apart, which is the whole point ---- */
  {
    /* The dialog is cleared first, so that a drill which opens NOTHING fails on an empty box rather
     * than passing on whatever the last dialog left behind. */
    const r = A.vpayRows(2026, 9, 1).find(x => x.rate === 22);
    A.ptOpenDialog({ title: 'cleared', html: '', note: '' });
    if (r) A.vpayShowDrill(r.key);
    const d = A.PTD_() || {};
    ok('a figure can be taken apart into its deliveries', /VPO-P5/.test(d.html || ''), String(d.html).slice(0, 400));
    ok('…showing what the challan said beside what was kept',
       /Challan said/.test(d.html || '') && /Kept/.test(d.html || ''), String(d.html).slice(0, 300));
    ok('…and the arithmetic that made the figure',
       /10 pcs/.test(d.note || '') && /Rs\.220/.test(d.note || ''), String(d.note));
    /* THE RATE ROW, NOT A BARE NUMBER. "Block print" alone is printed by the fallback even when the
     * row has been thrown away, so the approver is what proves a real rate was looked up. */
    ok('…and which rate it used, so a bill can be argued with',
       /Block print/.test(d.note || '') && /approved by/.test(d.note || ''), String(d.note));
  }
  {
    /* And the same for work nobody has priced: it says the rate is missing, not the work. */
    const r = A.vpayRows(2026, 9, 1).find(x => x.rate === null);
    A.ptOpenDialog({ title: 'cleared', html: '', note: '' });
    if (r) A.vpayShowDrill(r.key);
    ok('an unpriced figure says the rate is what is missing',
       /NO APPROVED RATE/.test((A.PTD_() || {}).note || ''), String((A.PTD_() || {}).note));
  }

  /* ================= FREEZING A FORTNIGHT =================
   *
   * Until this, every figure was today's data at today's rate: change a rate and last month moved. */
  {
    const wasFreezes = A.HR().freezes, wasConfirm = CONFIRM; CONFIRM = true; NET.on = true;
    const freezeKey = A.payFreezeKey(A.VPAY_TYPE, 2026, 9);
    els.hrView.value = 'vpay'; els.hrMonth.value = '2026-09'; els.hrPeriod.value = '1'; els.hrQ.value = '';
    A.setHR(Object.assign(A.HR(), { freezes: {} }));

    /* WORK WITH NO RATE CANNOT BE FROZEN. It would be settled at nothing, where no later rate could
     * reach it. The fixture has one such line on purpose. */
    let at = NET.calls.length;
    await A.vpaySetFreeze(true);
    ok('a fortnight holding unpriced work refuses to freeze',
       /NO approved rate/.test(els.hrMsg.textContent) && /Rectangular/.test(els.hrMsg.textContent), els.hrMsg.textContent);
    ok('…and nothing is written', !NET.calls.slice(at).some(c => c.method === 'PUT'));

    /* Price it, and it freezes. */
    A.setHR(Object.assign(A.HR(), { prate: A.HR().prate.concat([
      rate({ vendor: 'VND002', at: 'Tablecloth', sub: 'Rectangular Tablecloth', size: '70X108', rate: '50' })]) }));
    const liveBefore = A.vpayRows(2026, 9, 1), sumBefore = liveBefore.reduce((x, r) => x + r.amount, 0);
    ME.admin = false;
    await A.vpaySetFreeze(true);
    ok('only an admin freezes', /Only an admin/.test(els.hrMsg.textContent), els.hrMsg.textContent);
    ME.admin = true;
    at = NET.calls.length;
    await A.vpaySetFreeze(true);
    const put = NET.calls.slice(at).find(c => c.method === 'PUT' && /pt_payoutFreezes/.test(c.url));
    ok('freezing writes the fortnight under the vendor type', !!put && /Vendor/.test(decodeURIComponent(put.url)), put && put.url);
    ok('…with every row, its rate, and the deliveries behind it',
       !!put && put.body.periods[1].length === liveBefore.length && put.body.periods[1].every(r => r.rate != null && (r.dels || []).length),
       JSON.stringify(put && put.body.periods[1].map(r => [r.rate, (r.dels || []).length])));
    ok('…and who froze it, and when', !!put && put.body.meta[1].by === ME.email && !!put.body.meta[1].at);
    ok('the panel now says the figures are settled', /frozen — settled/.test(els.hrKpis.innerHTML), els.hrKpis.innerHTML.slice(0, 300));
    ok('…and the button offers to re-open', /Re-open/.test(els.hrFreeze.textContent), els.hrFreeze.textContent);

    /* THE POINT OF IT: a rate change no longer reaches this fortnight. */
    A.setHR(Object.assign(A.HR(), { prate: A.HR().prate.map(r => Object.assign({}, r, { rate: 999 })) }));
    const after = A.vpayRows(2026, 9, 1);
    ok('a rate changed afterwards does not move a frozen fortnight',
       after.reduce((x, r) => x + r.amount, 0) === sumBefore, after.reduce((x, r) => x + r.amount, 0) + ' vs ' + sumBefore);
    ok('…while the live calculation beside it has moved', A.vpayLive(2026, 9, 1).reduce((x, r) => x + r.amount, 0) !== sumBefore);
    /* A frozen row can still say which rate it was paid at — the words were frozen with it. */
    A.ptOpenDialog({ title: 'cleared', html: '', note: '' });
    try { A.vpayShowDrill(after[0].key); } catch (e) { /* the empty dialog fails the next line */ }
    ok('a frozen figure still names its rate, and says it is frozen',
       /FROZEN/.test((A.PTD_() || {}).note || '') && /Block print/.test((A.PTD_() || {}).note || ''), String((A.PTD_() || {}).note));

    /* THE MONTH IS THE TWO HALVES, EACH AS IT STANDS — amounts added, never re-multiplied. */
    const second = { vendorCode: 'VND002', id: 'p6', orderNo: 'VPO-P6', orderType: 'cut', status: 'Placed',
      lines: [{ kind: 'cut', sku: 'RTC-6060', qty: 100, deliveries: [del(10, '20/09/2026', { qty: 10 })] }] };
    A.setVO(Object.assign(A.VO(), { rows: A.VO().rows.concat([second]) }));
    /* Two rows, not one: the rate is part of what a row IS, and the frozen half was paid at 22 while
     * the live half stands at 999. Merging them would show one quantity at a rate that priced neither. */
    const month = A.vpayRows(2026, 9, 3).filter(r => /Square/.test(r.what));
    const sq = { qty: month.reduce((x, r) => x + r.qty, 0), amount: month.reduce((x, r) => x + r.amount, 0), rows: month.length };
    ok('the month adds the frozen half to the live one',
       sq.rows === 2 && sq.qty === 20 && sq.amount === 220 + 10 * 999, JSON.stringify(sq));

    /* Re-opening puts it back to live. */
    await A.vpaySetFreeze(false);
    ok('re-opening makes the fortnight live again',
       A.vpayRows(2026, 9, 1).reduce((x, r) => x + r.amount, 0) !== sumBefore && !/frozen — settled/.test(els.hrKpis.innerHTML));
    A.setVO(Object.assign(A.VO(), { rows: A.VO().rows.filter(o => o.id !== 'p6') }));
    A.setHR(Object.assign(A.HR(), { freezes: wasFreezes, prate: [
      rate({ vendor: 'VND002', at: 'Tablecloth', sub: 'Square Tablecloth', size: '60X60', rate: '22' })] }));
    CONFIRM = wasConfirm; NET.on = false;
  }

  /* ---- THE SAME WORK IN BOTH HALVES IS ONE ROW FOR THE MONTH, its amounts ADDED ----
   *
   * Same vendor, same cloth, same rate: one key, so the month merges them. The amount is the sum of the
   * two halves' amounts and is never worked out again from the merged quantity — that would pay a
   * frozen half at whatever the rate is today. */
  {
    const keepRows = A.VO().rows;
    A.setVO(Object.assign(A.VO(), { rows: [{ vendorCode: 'VND002', id: 'p9', orderNo: 'VPO-P9', orderType: 'cut', status: 'Placed',
      lines: [{ kind: 'cut', sku: 'RTC-6060', qty: 100,
        deliveries: [del(10, '05/09/2026', { qty: 10 }), del(7, '20/09/2026', { qty: 7 })] }] }] }));
    const m = A.vpayRows(2026, 9, 3);
    ok('the same work in both halves is one row for the month', m.length === 1 && m[0].qty === 17, JSON.stringify(m.map(r => r.qty)));
    ok('…worth the two halves added together', !!m[0] && m[0].amount === 17 * 22, String(m[0] && m[0].amount));
    ok('…with the deliveries of both behind it', !!m[0] && (m[0].dels || []).length === 2);
    A.setVO(Object.assign(A.VO(), { rows: keepRows }));
  }

  /* ---- A CORRECTED RECEIPT SHOWS WHAT IT SAID BEFORE ---- */
  {
    const keepRows = A.VO().rows;
    A.setVO(Object.assign(A.VO(), { rows: [{ vendorCode: 'VND002', id: 'p7', orderNo: 'VPO-P7', orderType: 'cut', status: 'Placed',
      lines: [{ kind: 'cut', sku: 'RTC-6060', qty: 100,
        deliveries: [del(12, '05/09/2026', { qty: 8, was: [{ qty: 12, by: 'a@x', at: '2026-09-05T00:00:00Z' }] })] }] }] }));
    const r = A.vpayRows(2026, 9, 1)[0];
    A.ptOpenDialog({ title: 'cleared', html: '', note: '' });
    try { if (r) A.vpayShowDrill(r.key); } catch (e) { /* fails below */ }
    ok('a receipt corrected from 12 to 8 says so where the 8 is shown',
       /was 12/.test((A.PTD_() || {}).html || ''), String((A.PTD_() || {}).html).slice(0, 500));
    A.setVO(Object.assign(A.VO(), { rows: keepRows }));
  }

  /* ---- REFRESH READS THE VENDOR ORDERS TOO ---- */
  {
    /* A COPY — setVO(Object.assign(A.VO(), …)) changes the object in place, and the one kept here would be
     * changed with it. */
    const keepVO = Object.assign({}, A.VO()), keepStore = NET.store; NET.on = true;
    NET.store = { pt_vendorOrders: { VND002: { p8: { id: 'p8', orderNo: 'VPO-P8', orderType: 'cut', status: 'Placed',
      lines: [{ kind: 'cut', sku: 'RTC-6060', qty: 5, deliveries: [del(5, '06/09/2026', { qty: 5 })] }] } } } };
    await els.hrGo.onclick();
    ok('Refresh brings in a delivery accepted since the page was opened',
       (A.VO().rows || []).some(o => o.id === 'p8'), JSON.stringify((A.VO().rows || []).map(o => o.id)));
    /* AND A FAILED READ IS NOT AN EMPTY MONTH. */
    A.setVO(Object.assign({}, A.VO(), { rows: [], err: 'the line went down' }));
    els.hrView.value = 'vpay'; A.renderHr();
    ok('a failed read of the orders says so, instead of showing nothing owed',
       /could not be read/.test(els.hrMsg.textContent) && /line went down/.test(els.hrMsg.textContent), els.hrMsg.textContent);
    NET.store = keepStore; NET.on = false; A.setVO(keepVO);
  }

  /* Searching narrows it, the way every other view here does. */
  els.hrQ.value = 'rectangular'; A.renderHr();
  ok('the search box narrows the payout too',
     !/Square Tablecloth/.test(els.hrTable.innerHTML) && /Rectangular/.test(els.hrTable.innerHTML),
     els.hrTable.innerHTML.slice(0, 400));
  els.hrQ.value = '';

  /* A period with nothing accepted in it says so, rather than showing an empty table. */
  els.hrMonth.value = '2026-07'; A.renderHr();
  ok('a period with nothing accepted explains itself',
     /Nothing was accepted/.test(els.hrTable.innerHTML), els.hrTable.innerHTML.slice(0, 300));

  els.hrView.value = 'emp'; els.hrQ.value = '';
  ME.admin = wasAdmin;
  A.setHR(wasHR); A.setVO(wasVO);
  A.setPTG(Object.assign(A.PTG(), { mdb: wasMdb, masters: wasMasters }));
}

console.log('\n== a delivery that never arrived ==');
{
  const wasVO = A.VO(), wasAdmin = ME.admin;
  ME.admin = true;
  const mk = () => { els.vlState.value = ''; return A.setVO({ busy: false, err: '', at: '', shown: [],
    map: { VND002: { name: 'Choudhary Hand Block' } }, rows: [
      { vendorCode: 'VND002', id: 'n1', orderNo: 'VPO-N1', orderType: 'cut', orderDate: '25/08/2026', status: 'Placed',
        lines: [{ sku: 'CPC002-12R', qty: 26, articleType: 'Tablecloth', size: '132',
          deliveries: [{ qty: 13, date: '10/09/2026', by: 'p7976723933@vendors-tfr.app', at: '2026-09-10T10:58:46.462Z' }] }] },
    ] }); };
  mk();
  ['vlVendor', 'vlType', 'vlFrom', 'vlTo', 'vlQ'].forEach(i => { els[i].value = ''; });
  A.renderVlog();

  /* THE STATE RAVI IS LOOKING AT. The printer's own portal login recorded 13 pieces today, and until
   * somebody says otherwise the app counts them — vlQtyOf falls back to the claim. */
  ok('an unaccepted claim counts at the printer\'s own figure',
     A.vlQtyOf(A.VO().rows[0].lines[0].deliveries[0]) === 13,
     String(A.vlQtyOf(A.VO().rows[0].lines[0].deliveries[0])));
  ok('…and the order reads as part-delivered on it alone',
     A.voDone(A.VO().rows[0].lines[0]) === 13, String(A.voDone(A.VO().rows[0].lines[0])));
  ok('the row offers the other answer, not only Accept',
     /data-vl-no=/.test(els.vlTable.innerHTML) && /Didn&#039;t arrive|Didn't arrive/.test(els.vlTable.innerHTML),
     els.vlTable.innerHTML.slice(-600));

  NET.on = true;
  const err = await A.vlNoWrite(A.VLOG().rows[0], 'nothing came, asked on the phone', false);
  ok('marking it as never arrived is written', err === '', err);
  const d = A.VO().rows[0].lines[0].deliveries[0];
  ok('…with who said so and when', !!d.no && !!d.no.by && !!d.no.at, JSON.stringify(d.no));
  ok('…and the note', d.no.note === 'nothing came, asked on the phone', JSON.stringify(d.no));
  /* IT COUNTS FOR NOTHING, which is the whole point — the order goes back to owing those pieces. */
  ok('it is worth nothing now', A.vlQtyOf(d) === 0, String(A.vlQtyOf(d)));
  ok('…so the order owes them again', A.voDone(A.VO().rows[0].lines[0]) === 0,
     String(A.voDone(A.VO().rows[0].lines[0])));
  ok('…and the cached total on the line follows', A.VO().rows[0].lines[0].vendorQty === 0,
     String(A.VO().rows[0].lines[0].vendorQty));

  A.renderVlog();
  const h = els.vlTable.innerHTML;
  ok('the row says it did not arrive', /did not arrive/.test(h), h.slice(0, 1600));
  /* Not "accepted nought", which would say the goods came and none were kept — a different and
   * false statement about what happened. */
  ok('…and is not dressed up as an acceptance', !/pill-ok/.test(h));
  ok('the panel counts it separately', /Never arrived/.test(els.vlKpis.innerHTML), els.vlKpis.innerHTML);
  /* Nobody is waiting for it, so it comes out of that count rather than sitting in it forever. */
  ok('…and stops calling it waiting', />0<\/div><div class="l">Waiting to be accepted/.test(els.vlKpis.innerHTML)
     || !/1<\/div><div class="l">Waiting to be accepted/.test(els.vlKpis.innerHTML), els.vlKpis.innerHTML);
  ok('it cannot be ticked into a bulk accept', !/data-vl-pick/.test(h), h.slice(0, 900));

  els.vlState.value = 'never';
  A.renderVlog();
  ok('the filter finds it', A.VLOG().rows.length === 1, String(A.VLOG().rows.length));
  els.vlState.value = 'pending';
  A.renderVlog();
  ok('…and "waiting" passes over it', A.VLOG().rows.length === 0, String(A.VLOG().rows.length));
  els.vlState.value = '';
  A.renderVlog();

  /* NOT A VERDICT — a statement about today. The day the goods turn up it goes back. */
  ok('it can be taken back when the goods turn up',
     (await A.vlNoWrite(A.VLOG().rows[0], '', true)) === '');
  ok('…and counts again at the printer\'s figure',
     A.vlQtyOf(A.VO().rows[0].lines[0].deliveries[0]) === 13);
  ok('…with the mark gone', !A.VO().rows[0].lines[0].deliveries[0].no);

  /* An acceptance and a did-not-arrive cannot both stand. */
  await A.vlAcceptWrite([A.VLOG().rows[0]], () => 13, '', () => 0);
  ok('a delivery can be accepted first', !!A.VO().rows[0].lines[0].deliveries[0].ok);
  await A.vlNoWrite(A.VLOG().rows[0], '', false);
  ok('…and saying it never came undoes that acceptance',
     !A.VO().rows[0].lines[0].deliveries[0].ok && !!A.VO().rows[0].lines[0].deliveries[0].no,
     JSON.stringify(A.VO().rows[0].lines[0].deliveries[0]));

  /* Only somebody who may confirm deliveries may say this. */
  ME.admin = false;
  const savedTabs = ME.tabs; ME.tabs = [];
  mk(); A.renderVlog();
  ok('a reader cannot mark a delivery as never arrived',
     /Can accept printer deliveries/.test(await A.vlNoWrite(A.VLOG().rows[0], '', false)));
  ME.tabs = savedTabs; ME.admin = wasAdmin;
  NET.on = false;
  A.setVO(wasVO);
}

console.log('\n== a rate card, by name and by the fileful ==');
{
  const wasHR = A.HR(), wasVO = A.VO(), wasMdb = A.PTG().mdb, wasAdmin = ME.admin;
  ME.admin = true;
  A.setPTG(Object.assign(A.PTG(), {
    mdb: [{ sku: 'RTC-6060', articleType: 'Tablecloth', subtype: 'Square Tablecloth', size: '60X60' }],
    masters: Object.assign({}, A.PTG().masters, { vendor: [
      { code: 'VND001', desc: 'RBP-Bagru', category: 'Printer', active: true },
      { code: 'VND002', desc: 'Choudhary Hand Block', category: 'Printer', active: true }] }),
  }));
  A.setVO({ busy: false, err: '', at: '', shown: [], rows: [],
    map: { VND001: { name: 'RBP-Bagru' }, VND002: { name: 'Choudhary Hand Block' } } });
  A.setHR(Object.assign(A.HR(), { prate: [] }));

  /* THE PICKER. Nobody at this factory says "VND002" out loud. */
  const vf = A.prFields(null).find(f => f.key === 'vendor');
  ok('the printer picker offers pairs, not bare codes', Array.isArray(vf.options[1]), JSON.stringify(vf.options[1]));
  ok('…with the code stored and the name shown',
     vf.options.some(o => o[0] === 'VND002' && o[1] === 'Choudhary Hand Block'), JSON.stringify(vf.options));
  /* EDITING is one printer's rate, so it keeps the labelled select. */
  const ef = A.prFields({ vendor: 'VND002', kind: 'cut', articleType: 'Tablecloth',
    subtype: 'Square Tablecloth', size: '60X60', rate: 22 }).find(f => f.key === 'vendor');
  ok('editing a rate picks one printer', ef.type === 'select', ef.type);
  A.ptOpenDialog({ title: 'Edit printer rate', fields: A.prFields({ vendor: 'VND002', kind: 'cut',
    articleType: 'Tablecloth', subtype: 'Square Tablecloth', size: '60X60', rate: 22 }), onSave: () => '' });
  ok('…and the dialog renders the name against the code',
     /<option value="VND002"[^>]*>Choudhary Hand Block<\/option>/.test(els.ptDlgBody.innerHTML),
     els.ptDlgBody.innerHTML.slice(0, 400));

  /* A NEW rate may be for several at once — the same quilt price across four printers is one
   * decision, not four. */
  ok('a new rate takes several printers', vf.type === 'multi', vf.type);
  A.ptOpenDialog({ title: 'New printer rate', fields: A.prFields(null), onSave: () => '' });
  const mh = els.ptDlgBody.innerHTML;
  ok('…rendered as a tick per printer',
     /data-multi="vendor"[^>]*value="VND001"/.test(mh) && /data-multi="vendor"[^>]*value="VND002"/.test(mh),
     mh.slice(0, 500));
  ok('…each labelled by name', /Choudhary Hand Block/.test(mh) && /RBP-Bagru/.test(mh));

  /* A FILE names the printer the way a person would. */
  ok('a printer is found by name', A.prVendorCode('Choudhary Hand Block') === 'VND002');
  ok('…however it is cased or spaced', A.prVendorCode('  choudhary hand block ') === 'VND002');
  /* A code is accepted too — an export writes one, and a code is unambiguous. */
  ok('…and by code, because an export writes one', A.prVendorCode('VND001') === 'VND001');
  ok('a printer nobody knows is nobody', A.prVendorCode('Some Other Firm') === '');

  /* Vendor · Work · Fabric · Print · Article · Subtype · Size · Filler · Weight · Rate · Notes.
   * The middle two rows are written the OLD way — "cut" and "running" in the Work column — because a
   * rate card written last week still has to upload. */
  const file = [
    A.PR_COLS,
    ['Choudhary Hand Block', 'cut', '', '', 'Tablecloth', 'Square Tablecloth', '60X60', '', '', '', '22', 'monsoon rate'],
    ['RBP-Bagru', 'running', 'Voil 92', 'Vertical', '', '', '', '', '', '', '14', ''],
    ['', '', '', '', '', '', '', '', '', '', '', ''],
  ];
  const got = A.prFromRows(file);
  ok('two rates come off the template', got.rows && got.rows.length === 2, JSON.stringify(got.err || got.rows.length));
  ok('…and a blank row is not an error', !got.err);
  ok('the unit is read from the words a person writes',
     got.rows[0].kind === 'cut' && got.rows[1].kind === 'running', JSON.stringify(got.rows.map(r => r.kind)));
  ok('…and an old file\'s "cut" and "running" still mean block printing',
     got.rows.every(r => r.service === 'Block print'), JSON.stringify(got.rows.map(r => r.service)));
  ok('a file with no Vendor column is refused by name',
     /no "Vendor" column/.test(A.prFromRows([['sku', 'rate'], ['a', '1']]).err || ''),
     A.prFromRows([['sku', 'rate'], ['a', '1']]).err);
  /* Ravi's own sheet has a vendor name on a row with nothing else — a heading for the rows under it.
   * Refusing the whole file over that would be pedantry. */
  ok('a vendor heading with no rate is skipped, not refused', (() => {
    const g = A.prFromRows([A.PR_COLS,
      ['Alisha Garmnets', 'Filling', '', '', 'Quilt', 'Twin Quilt', '60x90', '', 'Cotton', '1', '450', ''],
      ['Shama Cotton Udhyog', '', '', '', '', '', '', '', '', '', '']]);
    return !g.err && g.rows.length === 1; })());

  const plan = A.prPlan(got.rows);
  ok('a clean file plans cleanly', plan.errs.length === 0 && plan.rows.length === 2, JSON.stringify(plan.errs));

  /* ONE BAD ROW REFUSES THE FILE. Half a rate card prices some work and silently prices none of the
   * rest, with no way to tell which by looking. */
  const bad = A.prFromRows([A.PR_COLS,
    ['Nobody Printers', 'cut', '', '', 'Tablecloth', 'Square Tablecloth', '60X60', '', '', '', '22', ''],
    ['RBP-Bagru', 'cut', '', '', 'Tablecloth', '', '60X60', '', '', '', '10', ''],
    ['RBP-Bagru', 'running', 'Voil 92', 'Vertical', '', '', '', '', '', '', '0', ''],
  ]).rows;
  const badPlan = A.prPlan(bad);
  ok('a vendor nobody knows is named in the refusal',
     /"Nobody Printers" is not in the vendor master/.test(badPlan.errs.join(' ')), badPlan.errs.join(' '));
  ok('a missing subtype is refused', /subtype/i.test(badPlan.errs.join(' ')), badPlan.errs.join(' '));
  ok('a zero rate is refused', /more than zero/.test(badPlan.errs.join(' ')));
  ok('every problem is reported, not just the first', badPlan.errs.length === 3, JSON.stringify(badPlan.errs));
  ok('…and nothing survives to be written', badPlan.rows.length === 0);

  /* TWO PRICES FOR ONE THING, in one file. Which row wins would be an accident of order, and the
   * answer is what a printer gets paid — so it is refused, with both figures named. */
  const twice = A.prPlan(A.prFromRows([A.PR_COLS,
    ['RBP-Bagru', 'cut', '', '', 'Tablecloth', 'Square Tablecloth', '60X60', '', '', '', '20', ''],
    ['RBP-Bagru', 'cut', '', '', 'Tablecloth', 'Square Tablecloth', '60X60', '', '', '', '25', ''],
  ]).rows);
  ok('two different rates for one thing are refused, naming both rows and both figures',
     /same rate as row 2/.test(twice.errs.join(' ')) && /20/.test(twice.errs.join(' '))
     && /25/.test(twice.errs.join(' ')), twice.errs.join(' '));
  /* THE SAME rate twice is a repetition — a sheet grouped by vendor, or a line pasted again. Ravi,
   * 18 Sep: "rate same ho to upload me issue na ho, bas pop-up aa jay." */
  const twiceSame = A.prPlan(A.prFromRows([A.PR_COLS,
    ['RBP-Bagru', 'cut', '', '', 'Tablecloth', 'Square Tablecloth', '60X60', '', '', '', '20', ''],
    ['RBP-Bagru', 'cut', '', '', 'Tablecloth', 'Square Tablecloth', '60X60', '', '', '', '20', ''],
  ]).rows);
  ok('the SAME rate twice loads instead, taken once',
     twiceSame.errs.length === 0 && twiceSame.rows.length === 1, JSON.stringify(twiceSame.errs));
  ok('…and is reported as a repetition rather than hidden',
     twiceSame.warns.length === 1 && /repeats row 2/.test(twiceSame.warns[0]), JSON.stringify(twiceSame.warns));

  /* And against what is already there. */
  A.setHR(Object.assign(A.HR(), { prate: [A.prRec({ vendor: 'VND002', kind: 'cut',
    at: 'Tablecloth', sub: 'Square Tablecloth', size: '60X60', rate: '22' })] }));
  const clash = A.prPlan(A.prFromRows([A.PR_COLS,
    ['Choudhary Hand Block', 'cut', '', '', 'Tablecloth', 'Square Tablecloth', '60X60', '', '', '', '30', ''],
  ]).rows);
  ok('a rate the list already has is refused', /already has an approved rate for/.test(clash.errs.join(' ')),
     clash.errs.join(' '));

  /* RAVI'S OWN QUILT SHEET, as a file. The two Twin Quilt rows differ only by the filler and the
   * price — without the filler in the key the second is a duplicate of the first, and the wrong one
   * of the two would price every quilt. */
  A.setPTG(Object.assign(A.PTG(), { masters: Object.assign({}, A.PTG().masters, { vendor: [
    { code: 'VND001', desc: 'RBP-Bagru', category: 'Printer', active: true },
    { code: 'VND002', desc: 'Choudhary Hand Block', category: 'Printer', active: true },
    { code: 'VND007', desc: 'Alisha Garmnets', category: 'Filling', active: true },
    { code: 'VND008', desc: 'Yakum Ansari', category: 'Filling', active: true }] }) }));
  A.setHR(Object.assign(A.HR(), { prate: [] }));
  const quilt = A.prFromRows([A.PR_COLS,
    ['Alisha Garmnets', 'Filling', '', '', 'Quilt', 'Twin Quilt', '60x90', '', 'Surgical Cotton', '1', '550', ''],
    ['Alisha Garmnets', 'Filling', '', '', 'Quilt', 'Twin Quilt', '60x90', '', 'Cotton', '1', '450', ''],
    ['Alisha Garmnets', 'Filling', '', '', 'Quilt', 'King Quilt', '96x106', '', 'Surgical Cotton', '1.75', '800', ''],
    ['Yakum Ansari', 'Filling', '', '', 'Seat Pad', 'Seat Pad', '16x16', '', 'Recron', '0.65', '80', ''],
  ]);
  ok('the quilt sheet reads', quilt.rows && quilt.rows.length === 4, JSON.stringify(quilt.err || quilt.rows.length));
  const qp = A.prPlan(quilt.rows);
  ok('…and plans cleanly, both fillers and all', qp.errs.length === 0 && qp.rows.length === 4,
     JSON.stringify(qp.errs));
  ok('…because the filler is what tells the two Twin Quilt rates apart',
     A.prKey(A.prRec(qp.rows[0])) !== A.prKey(A.prRec(qp.rows[1])));
  ok('…and a filling vendor is found by name like any other', qp.rows[3].vendor === 'VND008',
     qp.rows[3].vendor);

  /* ---- QUILTS: the case that showed the pickers were looking in the wrong place ----
   * prKnown was built from vendor ORDER lines alone. No vendor order has ever carried a quilt, so
   * every quilt word was missing from a list that had no business excluding it — and a rate typed
   * blind and spelled slightly differently matches nothing, silently. */
  A.setPTG(Object.assign(A.PTG(), { mdb: [
    { sku: 'RQL-K', articleType: 'Quilt', subtype: 'King Quilt', size: '96X106' },
    { sku: 'RQL-Q', articleType: 'Quilt', subtype: 'Queen Quilt', size: '90x96' },
    { sku: 'RTC-6060', articleType: 'Tablecloth', subtype: 'Square Tablecloth', size: '60X60' },
  ] }));
  A.setVO(Object.assign(A.VO(), { rows: [] }));
  ok('an article nobody has ordered from a printer is still offered',
     A.prKnown('articleType').includes('Quilt'), A.prKnown('articleType').join(','));
  ok('…with its subtypes', A.prKnown('subtype').includes('King Quilt') && A.prKnown('subtype').includes('Queen Quilt'),
     A.prKnown('subtype').join(','));
  ok('…and its sizes', A.prKnown('size').includes('96X106'), A.prKnown('size').join(','));

  /* The quilt sizes are written both ways in the master — 90X96 and 90x96, and four more pairs.
   * prKey lower-cases every part, so one rate covers both spellings. */
  ok('one rate covers both spellings of a size',
     A.prKey(A.prRec({ vendor: 'VND001', kind: 'cut', at: 'Quilt', sub: 'Queen Quilt', size: '90X96', rate: '1' }))
     === A.prKey(A.prRec({ vendor: 'VND001', kind: 'cut', at: 'Quilt', sub: 'Queen Quilt', size: '90x96', rate: '1' })));

  /* ---- one rate, four printers ---- */
  A.setHR(Object.assign(A.HR(), { prate: [] }));
  ok('a tick list with nothing ticked is refused',
     /at least one vendor/.test(A.prCheck({ vendor: [], service: 'Filling', at: 'Quilt', sub: 'King Quilt',
       size: '96X106', filler: 'Cotton', weight: '1.75', rate: '85' }, -1)));
  ok('…and with one ticked it is fine',
     A.prCheck({ vendor: ['VND001'], service: 'Filling', at: 'Quilt', sub: 'King Quilt',
       size: '96X106', filler: 'Cotton', weight: '1.75', rate: '85' }, -1) === '');

  NET.on = true;
  QS['[data-multi="vendor"]'] = [
    { checked: true, value: 'VND001' }, { checked: true, value: 'VND002' }, { checked: false, value: 'VND003' }];
  A.ptOpenDialog({ title: 'New printer rate', fields: A.prFields(null), onSave: () => '' });
  const vals = A.ptDlgValues();
  ok('the ticked printers are read as a list',
     Array.isArray(vals.vendor) && vals.vendor.join(',') === 'VND001,VND002', JSON.stringify(vals.vendor));
  Object.keys(QS).forEach(k => delete QS[k]);
  NET.on = false;

  ME.admin = wasAdmin;
  A.setHR(wasHR); A.setVO(wasVO);
  A.setPTG(Object.assign(A.PTG(), { mdb: wasMdb }));
}

console.log('\n== what a vendor is shown, and what they can narrow it to ==');
{
  const wasVP = A.VP();
  const line = (sku, ex) => Object.assign({ sku, qty: 10, articleType: 'Tablecloth',
    articleSubtype: 'Square Tablecloth', color: 'Taupe', size: '60X60', priority: 'P1' }, ex || {});
  const ord = (id, ex) => Object.assign({ vendorCode: 'VND002', id, orderNo: 'VPO-' + id,
    orderType: 'cut', status: 'Placed', createdAt: '2026-09-0' + id, lines: [line('A' + id)] }, ex || {});

  /* A CANCELLED ORDER IS NOT WORK. It was showing with a red pill on it, which is an invitation to
   * read it and wonder what to do about it. The vendor has nothing to do with it and never will. */
  const set = [ord(1), ord(2, { status: 'Cancelled' }), ord(3, { status: 'Pending Approval' }),
    ord(4, { status: 'Dispatched' })];
  const seen = A.vpVisible(set);
  ok('a cancelled order is never shown to the vendor',
     !seen.some(o => o.status === 'Cancelled'), seen.map(o => o.status).join());
  ok('…nor one that is still waiting for approval, because it is not an order yet',
     !seen.some(o => o.status === 'Pending Approval'));
  ok('…and everything else is', seen.length === 2, String(seen.length));

  /* A cancelled LINE on a live order is a different thing and stays, struck through: a line that
   * simply vanished would leave a printer making it from memory. */
  const withDeadLine = A.vpVisible([ord(9, { lines: [line('A9'), line('B9', { cancelled: true })] })]);
  ok('but a cancelled LINE stays on a live order, so they know to stop making it',
     A.voLines(withDeadLine[0]).length === 2);

  /* ONE ORDER, ONE ROW. Cut and running together in one list, unique by order number — two rows
   * carrying the same number is a puzzle nobody can solve from the portal. */
  const dup = A.vpVisible([
    Object.assign(ord(5), { orderNo: 'VPO-SAME', createdAt: '2026-09-01' }),
    Object.assign(ord(6), { orderNo: 'VPO-SAME', createdAt: '2026-09-09' }),
    Object.assign(ord(7), { orderNo: 'VPO-RUN', orderType: 'running' }),
  ]);
  ok('an order number appears once, however many rows carry it', dup.length === 2, String(dup.length));
  ok('…and the newest of them is the one kept',
     String(dup.find(o => o.orderNo === 'VPO-SAME').id) === '6',
     String(dup.find(o => o.orderNo === 'VPO-SAME').id));
  ok('cut and running sit in the same list', dup.some(o => o.orderType === 'running') && dup.some(o => o.orderType === 'cut'));

  /* The filters. */
  A.setVP(Object.assign({}, wasVP, { code: 'VND002', name: 'Choudhary Hand Block', rows: [
    ord('a', { orderNo: 'VPO-AAA', lines: [line('SKU-A', { color: 'Taupe', articleType: 'Tablecloth' })] }),
    ord('b', { orderNo: 'VPO-BBB', status: 'Dispatched',
      lines: [line('SKU-B', { color: 'Indigo Floral', articleType: 'Runner' })] }),
    ord('c', { orderNo: 'VPO-CCC', orderType: 'running',
      lines: [{ fabricType: 'Voil 112', color: 'Queen Blue', printDirection: 'Horizontal', meters: 25 }] }),
  ], err: '', busy: false, at: '' }));
  A.renderVp();

  ok('the pickers are filled from this vendor\u2019s own orders, not the whole factory',
     /Indigo Floral/.test(els.vpCol.innerHTML) && /Taupe/.test(els.vpCol.innerHTML)
     && !/Mughal/.test(els.vpCol.innerHTML), els.vpCol.innerHTML);
  ok('…and the statuses too', /Dispatched/.test(els.vpStatus.innerHTML) && /Placed/.test(els.vpStatus.innerHTML));
  ok('all three orders are drawn to begin with',
     (els.vpBody.innerHTML.match(/data-vporder=/g) || []).length === 3);

  els.vpStatus.value = 'Dispatched'; A.renderVp();
  ok('a status filter narrows it', (els.vpBody.innerHTML.match(/data-vporder=/g) || []).length === 1
     && /VPO-BBB/.test(els.vpBody.innerHTML));
  ok('…and the count says so, not just the list', /1 of 3 order\(s\)/.test(els.vpMsg.textContent), els.vpMsg.textContent);
  els.vpStatus.value = '';

  els.vpType.value = 'running'; A.renderVp();
  ok('metres and pieces can be told apart when asked',
     /VPO-CCC/.test(els.vpBody.innerHTML) && !/VPO-AAA/.test(els.vpBody.innerHTML));
  els.vpType.value = ''; A.renderVp();
  ok('…but they sit together by default',
     /VPO-CCC/.test(els.vpBody.innerHTML) && /VPO-AAA/.test(els.vpBody.innerHTML));

  els.vpQ.value = 'sku-b'; A.renderVp();
  ok('search reaches inside the lines, not just the order number',
     /VPO-BBB/.test(els.vpBody.innerHTML) && !/VPO-AAA/.test(els.vpBody.innerHTML));
  els.vpQ.value = '';

  els.vpCol.value = 'Indigo Floral'; A.renderVp();
  ok('a colour filter leaves only the orders that have it',
     /VPO-BBB/.test(els.vpBody.innerHTML) && !/VPO-AAA/.test(els.vpBody.innerHTML));
  ok('…and an order with nothing left is not drawn empty',
     (els.vpBody.innerHTML.match(/data-vporder=/g) || []).length === 1);

  els.vpCol.value = ''; A.renderVp();
  ok('clearing puts them all back', (els.vpBody.innerHTML.match(/data-vporder=/g) || []).length === 3);

  /* ---- ONE TABLE, NOT A CARD EACH. "abhi bhi 2 order show ho rhe h … mujhe aisa view chahiye jisme
   * vendor ek sath me bina roll kiye 10 order line dekh sake." Every order got its own card, and
   * every card put its lines in a box capped at 40vh with its own scrollbar — four lines at a time,
   * through two little windows. ---- */
  {
    /* A fourth order, mid-production — the only state in which a quantity may be typed. The other
     * three are Placed (not acknowledged yet) and Dispatched (already finished). */
    const was3 = A.VP().rows;
    A.setVP(Object.assign(A.VP(), { rows: was3.concat([
      ord('d', { orderNo: 'VPO-DDD', status: 'In Production' })]) }));
    els.vpView.value = 'lines'; A.renderVp();
    const html = els.vpBody.innerHTML;
    ok('all four orders are in ONE table', (html.match(/<table/g) || []).length === 1,
       String((html.match(/<table/g) || []).length));
    ok('…with nothing to scroll inside it', !/max-height/.test(html));
    ok('…and every order still on the screen',
       /VPO-AAA/.test(html) && /VPO-BBB/.test(html) && /VPO-CCC/.test(html));
    /* Cut and running in the same table is the point — they are the same job to the person doing it. */
    ok('cut lines and running lines share the table',
       /SKU-A/.test(html) && /Voil 112/.test(html));

    /* THE BUTTONS ARE A LAYOUT AWAY, NOT A REWRITE. Every input keeps the attribute its handler
     * already looks for, so Record, Save dates, Acknowledge and the note go on working. */
    ok('each order is still one row of its own', (html.match(/data-vporder=/g) || []).length === 4);
    /* THE TWO BUTTONS THAT DO THE WORK ARE AT THE TOP NOW. Four orders meant four "Sending on"
     * dates, four Record buttons and four Save-dates buttons down one table — four copies of a
     * button that should be pressed once. */
    ok('…and no longer four copies of the Record button', !/data-vpdeliver=/.test(html));
    ok('…nor four copies of the date save', !/data-vpsaveprom=/.test(html));
    ok('…nor four one-date-for-all boxes', !/data-vpallprom=/.test(html));
    /* What is left on the bar belongs to ONE order and means nothing spread across several. */
    ok('but Acknowledge stays on the order it belongs to', /data-vpflow="a"/.test(html));
    ok('the promise boxes are still addressed by order and line',
       /data-vpprom="a" data-i="0"/.test(html), html.slice(0, 0) || 'not found');
    ok('an order in production offers the quantity box',
       /data-vpsend="d" data-i="0"/.test(html));
    /* A Placed order has to be acknowledged before anything is sent, and a Dispatched one is done. */
    ok('…one still waiting to be acknowledged does not',
       !/data-vpsend="a"/.test(html));
    ok('…and nor does one already dispatched', !/data-vpsend="b"/.test(html));
    ok('the order still offers the button that moves it on', /data-vpflow="a"/.test(html));

    /* One heading per cell, counted — the same trap that slid the buyer's columns sideways. */
    const heads = (html.match(/<th[ >]/g) || []).length;
    const rowCells = html.split(/<tr[^>]*>/).slice(1).map(r => (r.split('</tr>')[0].match(/<td[ >]/g) || []).length);
    const lineRows = rowCells.filter(n => n > 1);
    ok('one heading for every cell in a line row',
       heads === 10 && lineRows.length > 0 && lineRows.every(n => n === heads),
       heads + ' headings vs ' + [...new Set(lineRows)].join('/'));
    /* A bar and a colour heading each span the whole table, so they must name the same number. */
    ok('and every spanning row spans exactly that many',
       (html.match(/colspan="\d+"/g) || []).every(c => c === 'colspan="10"'),
       [...new Set(html.match(/colspan="\d+"/g) || [])].join(' '));

    /* The card view is still there for anybody who wants it. */
    /* What the strip counts. Two cut orders and one running: 10 + 10 pieces ordered with 4 already
   * sent on one of them, and 25 metres with 5 sent. */
  {
    const mk = (id, ex) => Object.assign({ vendorCode: 'VND002', id, orderNo: 'VPO-' + id,
      orderType: 'cut', status: 'In Production', createdAt: '2026-09-01',
      lines: [{ sku: 'S' + id, qty: 10, deliveryDate: '2026-10-01' }] }, ex || {});
    const wasRows = A.VP().rows;
    A.setVP(Object.assign(A.VP(), { rows: [
      mk('k1'),
      mk('k2', { status: 'Dispatched', lines: [{ sku: 'Sk2', qty: 10, vendorQty: 4 }] }),
      mk('k3', { orderType: 'running', lines: [{ fabricType: 'Voil', meters: 25, vendorQty: 5 }] }),
    ] }));
    A.renderVp();
    const k = els.vpKpis.innerHTML;
    ok('open counts the orders that are not finished', /<b>2<\/b> open/.test(k), k.match(/<b>\d+<\/b> open/));
    ok('…and says how many are done, out of how many', /1 done of 3/.test(k), k.slice(0, 300));
    /* 4 pieces went out (none on k1, 4 on k2) and 5 metres. Pieces and metres are never added
     * together — "9" would be a number of nothing. */
    ok('sent adds up the pieces and the metres separately, never into one figure',
       /4 pcs · 5 m/.test(k), (k.match(/Sent<\/span>[\s\S]{0,120}/) || [''])[0]);
    ok('left to send does the same',
       /16 pcs · 20 m/.test(k), (k.match(/Left to send<\/span>[\s\S]{0,120}/) || [''])[0]);
    A.setVP(Object.assign(A.VP(), { rows: wasRows }));
    A.renderVp();
  }

  /* ---- ONE COLOUR, ONE PLACE, IN PRIORITY ORDER. "item ko 3 breakup me todo article, color, size
     * and 1 color ki series 1 jagah dikhani chahiye in priority wise." A printer works a colour at a
     * time; the Item column had the same colour appearing three times with sizes scattered between
     * them, inside one long string that could not be lined up or scanned. ---- */
    {
      const L = (ex) => Object.assign({ sku: 'X', qty: 1, articleType: 'Tablecloth',
        articleSubtype: 'Round Tablecloth', color: 'Turquoise Moss Green', size: '60', priority: 'P3' }, ex);
      const mixed = [
        { l: L({ sku: 'S1', size: '110' }), i: 0 },
        { l: L({ sku: 'S2', color: 'Indigo Floral', priority: 'P1', size: '70X118' }), i: 1 },
        { l: L({ sku: 'S3', size: '60' }), i: 2 },
        { l: L({ sku: 'S4', color: 'Indigo Floral', priority: 'P1', size: '60X108' }), i: 3 },
        { l: L({ sku: 'S5', color: 'Goldenrod Yellow', priority: 'P3', size: '60X60' }), i: 4 },
        { l: L({ sku: 'S6', color: 'Late Colour', priority: '' }), i: 5 },
      ];
      const g = A.vpGroups(mixed);
      ok('P1 comes before P3', g[0].priority === 'P1', g.map(x => x.priority + ':' + x.colour).join(' | '));
      ok('…and a line with no priority at all comes last',
         g[g.length - 1].colour === 'Late Colour', g[g.length - 1].colour);
      ok('a colour appears as one group, not once per size',
         g.filter(x => x.colour === 'Turquoise Moss Green').length === 1,
         String(g.filter(x => x.colour === 'Turquoise Moss Green').length));
      ok('…with every size of it inside', g.find(x => x.colour === 'Turquoise Moss Green').items.length === 2);
      ok('…and its sizes read in number order, not as text',
         g.find(x => x.colour === 'Turquoise Moss Green').items.map(x => x.l.size).join() === '60,110',
         g.find(x => x.colour === 'Turquoise Moss Green').items.map(x => x.l.size).join());
      ok('both P1 lines are one group', g[0].items.length === 2 && g[0].colour === 'Indigo Floral');

      /* THE RISK THIS CHANGE CARRIES. Everything a vendor types is addressed by the line's index —
       * data-i. Re-ordering the rows for reading must not re-number them, or a quantity typed on the
       * row they are looking at lands on a different line entirely. */
      ok('re-ordering the rows does not re-number the lines',
         g.flatMap(x => x.items).map(x => x.i).sort((a, b) => a - b).join() === '0,1,2,3,4,5');
      ok('…and each line keeps the index it arrived with',
         g[0].items.map(x => x.l.sku + '=' + x.i).join() === 'S4=3,S2=1',
         g[0].items.map(x => x.l.sku + '=' + x.i).join());
      ok('a priority rank puts P1 first and no priority last',
         A.vpPriRank({ priority: 'P1' }) === 1 && A.vpPriRank({ priority: 'P4' }) === 4
         && A.vpPriRank({}) === 9);
    }

    /* And on the screen: the colour once, at the head of its run. */
    ok('the colour heads its group rather than repeating on every row',
       (html.match(/Turquoise Moss Green/g) || []).length <= 1
       || !/Turquoise Moss Green[\s\S]{0,400}Turquoise Moss Green/.test(html));

    /* ---- ONE PRESS, EVERY ORDER. And the trap it carries: each write re-renders the table, so a
     * loop that read as it went would wipe the boxes on the orders it had not reached yet. ---- */
    {
      const wasNet = NET.on; NET.on = true; NET.store = {};
      A.renderVp();                                   // fresh boxes for every line on screen
      Object.keys(QS).forEach(k => { if (/data-vpsend|data-vpprom/.test(k)) delete QS[k]; });

      /* Two orders in production, a quantity typed on each. Only 'd' is in a state that can take one,
       * so a second is added for this test. */
      const two = A.VP().rows.map(o => (o.id === 'b' ? Object.assign({}, o, { status: 'In Production' }) : o));
      A.setVP(Object.assign(A.VP(), { rows: two }));
      A.renderVp();
      QS['[data-vpsend="d"][data-i="0"]'] = { value: '3' };
      QS['[data-vpsend="b"][data-i="0"]'] = { value: '4' };
      els.vpSendDate.value = '2026-09-11';

      /* THE RE-RENDER. Every box goes the moment the first order is written — which is what makes
       * this test worth having: an implementation that read as it looped would find nothing for the
       * second order and silently record only the first. */
      NET.after = () => { Object.keys(QS).forEach(k => { if (/data-vpsend/.test(k)) delete QS[k]; }); };
      await A.vpRecordAll();
      NET.after = null;
      const d = (A.VP().rows || []).find(x => x.id === 'd');
      const b = (A.VP().rows || []).find(x => x.id === 'b');
      ok('one press records against every order that was typed into',
         A.vpDone(A.voLines(d)[0]) === 3 && A.vpDone(A.voLines(b)[0]) === 4,
         A.vpDone(A.voLines(d)[0]) + ' / ' + A.vpDone(A.voLines(b)[0]));
      ok('…and the second order is not lost to the first one\u2019s re-render',
         A.vpDone(A.voLines(b)[0]) === 4, String(A.vpDone(A.voLines(b)[0])));
      ok('…and it says what it did, per order',
         /VPO-DDD/.test(els.vpActMsg.textContent) && /VPO-BBB/.test(els.vpActMsg.textContent),
         els.vpActMsg.textContent);
      ok('…dated day-first, the way this database stores it',
         (A.voLines(d)[0].deliveries || []).slice(-1)[0].date === '11/09/2026',
         JSON.stringify((A.voLines(d)[0].deliveries || []).slice(-1)[0]));

      /* Nothing typed is said, not silently ignored. */
      Object.keys(QS).forEach(k => { if (/data-vpsend/.test(k)) delete QS[k]; });
      A.renderVp();
      await A.vpRecordAll();
      ok('nothing typed anywhere is refused, not silently ignored',
         /at least one line/.test(els.vpActMsg.textContent), els.vpActMsg.textContent);

      els.vpSendDate.value = '';
      await A.vpRecordAll();
      ok('and no date is refused before anything else is looked at',
         /date you are sending on/.test(els.vpActMsg.textContent), els.vpActMsg.textContent);
      els.vpSendDate.value = '2026-09-11';

      /* The same for the delivery dates: one date at the top, every order shown. */
      A.renderVp();
      els.vpPromDate.value = '2026-10-20';
      await A.vpPromiseAll();
      const d2 = (A.VP().rows || []).find(x => x.id === 'd');
      const a2 = (A.VP().rows || []).find(x => x.id === 'a');
      ok('one delivery date answers every order on the screen',
         A.voProm(A.voLines(d2)[0]) === '2026-10-20' && A.voProm(A.voLines(a2)[0]) === '2026-10-20',
         A.voProm(A.voLines(d2)[0]) + ' / ' + A.voProm(A.voLines(a2)[0]));
      ok('…and saying the same thing twice is not a promise moved',
         (await A.vpPromiseAll(), A.voMoves(A.voLines((A.VP().rows || []).find(x => x.id === 'd'))[0])) === 0);

      els.vpPromDate.value = '';
      NET.on = wasNet;
    }

    els.vpView.value = 'orders'; A.renderVp();
    ok('the by-order view still gives a card each',
       (els.vpBody.innerHTML.match(/<table/g) || []).length === 4,
       String((els.vpBody.innerHTML.match(/<table/g) || []).length));
    ok('…and it no longer traps the lines in a 40vh box', !/max-height:40vh/.test(els.vpBody.innerHTML));
    els.vpView.value = 'lines';
  }

  A.setVP(wasVP);
}

console.log('\n== what the download carries ==');
{
  /* "mujhe sku, article, color, size alag alag column me dikhne chahiye and priority bhi." Four
   * things shared one Item cell, which reads perfectly well and cannot be sorted, filtered or
   * totalled by — the whole reason for opening it in Excel. */
  const cut = { vendorCode: 'VND002', id: 'x1', orderNo: 'VPO-X1', orderType: 'cut',
    status: 'In Production', orderDate: '11/09/2026', lines: [
      { sku: 'RTC0009-60108', qty: 7, articleType: 'Tablecloth', articleSubtype: 'Rectangular Tablecloth',
        color: 'Indigo Floral', size: '60X108', priority: 'P3', deliveryDate: '2026-10-01',
        vendorDate: '2026-10-09' },
      { sku: 'RTC14', qty: 12, articleType: 'Tablecloth', articleSubtype: 'Square Tablecloth',
        color: 'Amber Marigold', size: '60X60', priority: 'P1', deliveryDate: '2026-10-01' },
    ] };
  const run = { vendorCode: 'VND002', id: 'x2', orderNo: 'VPO-X2', orderType: 'running',
    status: 'Placed', orderDate: '02/09/2026', lines: [
      { fabricType: 'Voil 112', color: 'Queen Blue', printDirection: 'Horizontal', meters: 25, priority: 'P1' },
    ] };

  const head = A.vpExportRows([cut, run], {})[0];
  ['Priority', 'SKU / fabric', 'Article', 'Colour', 'Size'].forEach(c =>
    ok('the file has a ' + c + ' column of its own', head.indexOf(c) >= 0, head.join('|')));
  ok('…and no single Item column with four things in it', head.indexOf('Item') < 0, head.join('|'));
  ok('both dates travel: what was asked for and what was promised',
     head.indexOf('Wanted by') >= 0 && head.indexOf('Your date') >= 0, head.join('|'));

  const rows = A.vpExportRows([cut, run], {});
  const col = n => head.indexOf(n);
  /* Grouped the way the screen groups them, so the file and the screen read side by side: P1 first. */
  ok('the rows come out in the order the screen shows them',
     rows[1][col('Priority')] === 'P1' && rows[1][col('SKU / fabric')] === 'RTC14',
     rows[1].join('|'));
  const r = rows.find(x => x[col('SKU / fabric')] === 'RTC0009-60108');
  ok('a cut line splits into its four parts',
     r[col('Article')] === 'Rectangular Tablecloth' && r[col('Colour')] === 'Indigo Floral'
     && r[col('Size')] === '60X108', r.join('|'));
  ok('…with its priority beside them', r[col('Priority')] === 'P3');
  ok('…and both of its dates', r[col('Wanted by')] === '2026-10-01' && r[col('Your date')] === '2026-10-09');

  /* A running line has no article or size; its fabric and print go where they belong rather than
   * being squeezed into columns meant for something else. */
  const rr = rows.find(x => x[col('SKU / fabric')] === 'Voil 112');
  ok('a running line puts its fabric and print in the right columns',
     rr[col('Article')] === 'Horizontal' && rr[col('Colour')] === 'Queen Blue' && rr[col('Size')] === '',
     rr.join('|'));
  ok('…and is measured in metres', rr[col('Unit')] === 'm' && rr[col('Ordered')] === 25);

  /* THE FILTERS COME WITH IT. Looking at one colour and downloading every colour is how somebody
   * ends up working from the wrong list. */
  const one = A.vpExportRows([cut, run], { col: 'Amber Marigold' });
  ok('a line filter narrows the download too', one.length === 2 && one[1][col('Colour')] === 'Amber Marigold',
     one.map(x => x[col('Colour')]).join('|'));
  ok('…and the heading row is still there', one[0][0] === 'Order');
}

console.log('\n== Shopify keeps its own production record ==');
{
  /* "only shopify orders ke liye open entry yahi se rakho … kya cut ho gya kya issue ho gya kya
   * receive ho gya kya press par gya … and add a option here handover to shipping team", and asked
   * whether it belongs in Base Data with everything else: "Shopify ke liye alag rakhein = yes".
   *
   * So it lives in pt_shopProd. The cost is real and was said out loud: the cutting cap, the weekly
   * report and piece-rate pay all read Base Data, and none of them sees any of this. */
  const wasOb = A.PTG().ob, wasSp = A.PTG().shopProd, wasNet = NET.on, wasAdmin = ME.admin;
  ME.admin = true; NET.on = true; NET.store = {};
  A.setPTG(Object.assign(A.PTG(), { shopProd: {}, ob: [
    { id: 'ob_shp_SHP-9001_TEST-SKU', orderNo: 'SHP-9001', sku: 'TEST-SKU', qty: 10, src: 'SHP',
      orderDate: '2026-09-01', articleType: 'Quilt', articleSubtype: 'Queen Quilt', shopOrderNo: '#9001' },
  ] }));
  const line = () => (A.ordLines() || []).find(l => l.orderNo === 'SHP-9001');

  ok('a Shopify line starts with nothing recorded against it',
     line().cut === 0 && line().received === 0 && line().pressed === 0);
  ok('…and is open, with everything still to make', line().open === true && line().pendingMake === 10);

  /* THE SEQUENCE IS THE POINT. A register that accepts "12 pressed, 0 received" is one nobody can
   * answer a question from later. */
  ok('pressed more than received is refused',
     /more than received/.test(await A.spSave('SHP-9001', 'TEST-SKU', { cut: 10, issued: 10, received: 0, pressed: 12 })));
  ok('received more than issued is refused',
     /more than issued/.test(await A.spSave('SHP-9001', 'TEST-SKU', { cut: 10, issued: 4, received: 9, pressed: 0 })));
  ok('issued more than cut is refused',
     /more than cut/.test(await A.spSave('SHP-9001', 'TEST-SKU', { cut: 4, issued: 9, received: 0, pressed: 0 })));
  /* Over-receipt is allowed and named elsewhere on this screen. A figure many times the order is a
   * typo, not a windfall. */
  ok('a wildly over-sized receipt is questioned rather than stored',
     /three times/.test(await A.spSave('SHP-9001', 'TEST-SKU', { cut: 99, issued: 99, received: 99, pressed: 0 })));
  ok('…and none of those wrote anything', !A.spOf('SHP-9001', 'TEST-SKU'));

  ok('a sensible entry saves',
     (await A.spSave('SHP-9001', 'TEST-SKU', { cut: 10, issued: 10, received: 8, pressed: 6, remarks: 'two short' })) === '');
  ok('…and the line reads its own figures, not Base Data\u2019s',
     line().cut === 10 && line().issued === 10 && line().received === 8 && line().pressed === 6,
     JSON.stringify([line().cut, line().issued, line().received, line().pressed]));
  ok('…so what is still to make is what has not come back', line().pendingMake === 2);
  ok('…and what is made and waiting on the press is the difference', line().madeToPress === 2);
  ok('the remarks are kept', line().spRemarks === 'two short');

  /* HANDOVER IS THE END, and pressed alone is not — a pressed piece on the table is not out of the
   * building. */
  ok('a line is still open even when everything received has been pressed',
     (await A.spSave('SHP-9001', 'TEST-SKU', { cut: 10, issued: 10, received: 10, pressed: 10 })) === ''
     && line().open === true);
  ok('handing over closes it', (await A.spHandover('SHP-9001', 'TEST-SKU', true)) === '' && line().open === false);
  ok('…and records who took it and when', !!line().handedAt && !!line().handedBy);
  ok('…and it can be taken back if it went too early',
     (await A.spHandover('SHP-9001', 'TEST-SKU', false)) === '' && line().open === true);

  /* NOTHING IS HANDED OVER THAT WAS NEVER MADE, or the one act that closes a line would also be the
   * way to make work vanish without doing it. */
  A.setPTG(Object.assign(A.PTG(), { shopProd: {} }));
  ok('a line with nothing received cannot be handed over',
     /nothing to hand over/.test(await A.spHandover('SHP-9001', 'TEST-SKU', true)));
  await A.spSave('SHP-9001', 'TEST-SKU', { cut: 10, issued: 10, received: 10, pressed: 4 });
  ok('…nor one with pieces still unpressed, without saying so',
     /have not been pressed yet/.test(await A.spHandover('SHP-9001', 'TEST-SKU', true)));

  /* It is addressed by order and SKU — the pair a line is keyed by anyway. The order-book row id is
   * rewritten every time the Shopify sync re-plans an order, and keying on that would throw the
   * progress away with it. */
  ok('the record is addressed by order and SKU', A.spKey('shp-9001', 'test-sku') === 'SHP-9001__TEST-SKU');
  ok('…and a key the database cannot hold is refused', A.spKeySafe('A/B') === false && A.spKeySafe('A__B') === true);

  /* Somebody who may not change a production entry may not change this one either. */
  ME.admin = false;
  const wasEdit = ME.prodEdit; ME.prodEdit = false;
  ok('and recording one needs the same right as any other production entry',
     /permission/i.test(await A.spSave('SHP-9001', 'TEST-SKU', { cut: 1 })));
  ME.prodEdit = wasEdit; ME.admin = wasAdmin;

  /* ---- THE SCREEN. A new column is where this kind of change goes wrong: one heading short and
   * every column after it sits over the wrong data, which nothing else notices. ---- */
  {
    ME.admin = true;
    await A.spSave('SHP-9001', 'TEST-SKU', { cut: 10, issued: 10, received: 8, pressed: 6 });
    els.odView.value = 'shopprod';
    A.renderOrdShopify(false);
    const h = els.odTable.innerHTML;
    const heads = (h.match(/<th\b/g) || []).length;
    const firstRow = (h.match(/<tbody><tr[\s\S]*?<\/tr>/) || [''])[0];
    const cells = (firstRow.match(/<td\b/g) || []).length;
    ok('every heading on the Shopify table has a cell under it',
       heads > 0 && heads === cells, heads + ' headings vs ' + cells + ' cells');
    ok('…and the Entry button is on the row, under the last, unnamed column',
       /data-sp="[^"]+"[^>]*>Entry</.test(h), h.slice(0, 200));
    ok('the row offers the way to record it', /data-sp="SHP-9001\|TEST-SKU"/.test(h), h.slice(0, 300));
    ok('…and the way to hand it over', /data-sphand=/.test(h));

    /* Once handed over it says so by name — "Complete" on its own left you wondering whether the
     * goods had actually gone anywhere. */
    await A.spSave('SHP-9001', 'TEST-SKU', { cut: 10, issued: 10, received: 10, pressed: 10 });
    await A.spHandover('SHP-9001', 'TEST-SKU', true);
    A.renderOrdShopify(false);
    ok('a handed-over line leaves the pending window', !/SHP-9001/.test(els.odTable.innerHTML));
    A.renderOrdShopify(false, true);
    const h2 = els.odTable.innerHTML;
    ok('a handed-over line says so, rather than just "Complete"', /Handed over/.test(h2), h2.slice(0, 400));
    ok('…and offers the way back', /data-spback=/.test(h2) && !/data-sphand=/.test(h2));

    /* Everything received and pressed, but nobody has taken it yet. */
    await A.spHandover('SHP-9001', 'TEST-SKU', false);
    A.renderOrdShopify(false);
    ok('and a line waiting to be collected says that, not "to press"',
       /ready to hand over/.test(els.odTable.innerHTML), els.odTable.innerHTML.slice(0, 400));

    /* ---- TICK MANY, HAND THEM OVER ONCE. "1 click me select kiye hue orders ko ek sath handover
     * kar sake." ---- */
    {
      /* Two more lines, so there is something to tick together. */
      A.setPTG(Object.assign(A.PTG(), { ob: [
        { id: 'a', orderNo: 'SHP-9001', sku: 'TEST-SKU', qty: 10, src: 'SHP', orderDate: '2026-09-01', shopOrderNo: '#9001', articleType: 'Quilt' },
        { id: 'b', orderNo: 'SHP-9002', sku: 'SKU-B', qty: 5, src: 'SHP', orderDate: '2026-09-02', shopOrderNo: '#9002', articleType: 'Quilt' },
        { id: 'c', orderNo: 'SHP-9003', sku: 'SKU-C', qty: 5, src: 'SHP', orderDate: '2026-09-03', shopOrderNo: '#9003', articleType: 'Quilt' },
      ] }));
      A.setPTG(Object.assign(A.PTG(), { shopProd: {} }));
      await A.spSave('SHP-9001', 'TEST-SKU', { cut: 10, issued: 10, received: 10, pressed: 10 });
      await A.spSave('SHP-9002', 'SKU-B', { cut: 5, issued: 5, received: 5, pressed: 5 });
      /* This one is only half pressed: it is not ready, and it is the point of the test. */
      await A.spSave('SHP-9003', 'SKU-C', { cut: 5, issued: 5, received: 5, pressed: 2 });

      ok('nothing ticked is said, not silently ignored',
         /Tick the line/.test(await A.spHandoverPicked()));

      A.ORD().pick = new Set(['SHP-9001|TEST-SKU', 'SHP-9002|SKU-B']);
      ok('two ticked lines go over in one press', (await A.spHandoverPicked()) === '');
      const ln = k => (A.ordLines() || []).find(l => l.orderNo === k);
      ok('…and both of them are handed over',
         !!ln('SHP-9001').handedAt && !!ln('SHP-9002').handedAt);
      ok('…and the ticks are cleared once they have gone', A.ORD().pick.size === 0);

      /* PARTLY APPLIED ON PURPOSE. Cancelling twenty lines where two are wrong is stopped outright;
       * handing over the eighteen that are ready IS the work, and refusing the lot would mean doing
       * those eighteen one at a time. Each one left behind is named, and each can be undone. */
      await A.spHandover('SHP-9001', 'TEST-SKU', false);
      A.ORD().pick = new Set(['SHP-9001|TEST-SKU', 'SHP-9003|SKU-C']);
      ok('a mixed selection hands over the ones that are ready', (await A.spHandoverPicked()) === '');
      ok('…the ready one went', !!ln('SHP-9001').handedAt);
      ok('…the one still being pressed did not', !ln('SHP-9003').handedAt);
      ok('…and the screen says how many were left behind and why',
         /1 line\(s\) handed/.test(els.odMsg.textContent) && /1 left behind/.test(els.odMsg.textContent)
         && /pressed/.test(els.odMsg.textContent), els.odMsg.textContent);
      ok('…and the one left behind is still ticked, so it is not forgotten',
         A.ORD().pick.has('SHP-9003|SKU-C') && !A.ORD().pick.has('SHP-9001|TEST-SKU'));

      /* When not one of them can go, that is a refusal rather than a report of nothing happening. */
      A.ORD().pick = new Set(['SHP-9003|SKU-C']);
      ok('a selection where nothing is ready is refused outright',
         /pressed/.test(await A.spHandoverPicked()));

      A.ORD().pick = new Set();
      A.renderOrdShopify(false);
      const h3 = els.odTable.innerHTML;
      ok('the pending window holds only the line still open', (h3.match(/data-sppick=/g) || []).length === 1 && /SHP-9003/.test(h3), (h3.match(/data-sppick="[^"]+"/g) || []).join());
      A.renderOrdShopify(false, true);
      ok('…and the two handed over are in the complete window, each with its tick box',
         (els.odTable.innerHTML.match(/data-sppick=/g) || []).length === 2 && !/SHP-9003/.test(els.odTable.innerHTML));
      A.renderOrdShopify(false);
      /* The same trap as the vendor card: the first column of a table wider than the screen is the
       * first thing to slide off it. */
      ok('…and the tick column is pinned so it cannot scroll away',
         /<td class="frz"><input type="checkbox" data-sppick=/.test(h3), h3.slice(0, 300));
      ok('…with one heading for it', /<th class="frz"[^>]*><input type="checkbox" id="spPickAll"/.test(h3));
      ok('before anything is ticked the bar says nothing and is not there',
         els.odPickBar.innerHTML === '' && els.odPickBar._hidden === true, els.odPickBar.innerHTML);
      A.ORD().pick = new Set(['SHP-9002|SKU-B']);
      A.renderOrdShopify(false);
      ok('…and once one is, it offers the single press',
         /Hand 1 over to shipping/.test(els.odPickBar.innerHTML), els.odPickBar.innerHTML);
      A.ORD().pick = new Set();
    }

    /* Somebody who may not record production gets neither button — one that refuses when pressed
     * reads as a broken app, not as a permission nobody gave them. */
    const wasEdit2 = ME.prodEdit; ME.admin = false; ME.prodEdit = false;
    A.renderOrdShopify(false);
    ok('a reader is offered no buttons at all',
       !/data-sp=/.test(els.odTable.innerHTML) && !/data-sphand=/.test(els.odTable.innerHTML));
    ME.admin = wasAdmin; ME.prodEdit = wasEdit2;
  }

  A.setPTG(Object.assign(A.PTG(), { ob: wasOb, shopProd: wasSp }));
  NET.on = wasNet;
}

console.log('\n== asking for a deletion, and answering it ==');
{
  /* The one thing Vimal's tool has that this one did not. Of 34 nodes holding data this app already
   * read 23; ten of the other eleven are the old tool's own housekeeping. pt_approvals was the
   * eleventh, with EIGHT requests waiting, the oldest from 4 September and none ever answered.
   *
   * Vikas may correct a Base Data row and not delete one — deleting moves the order balance, the
   * cutting cap, the weekly report and somebody's pay at once. In the old tool he could ASK. */
  const wasBase = A.PT().base, wasApv = A.APV(), wasNet = NET.on, wasAdmin = ME.admin, wasEdit = ME.prodEdit;
  NET.on = true; NET.store = {};
  const row = { id: 'bd_x1', sku: 'TC-A', empName: 'Vikram Mahawar', empType: 'Company Contractor',
    issuePieces: 20, receivedPieces: 0, issueDate: '08/09/2026, 12:09', orderNo: 'AMZ-1' };
  A.setPT(Object.assign(A.PT(), { base: [row] }));
  A.setAPV([]);

  /* An admin has nobody to ask. */
  ME.admin = true; ME.prodEdit = true;
  ok('an admin is told to just delete it', /delete it yourself/.test(await A.apvAsk(row, 'wrong entry')));

  ME.admin = false;
  ok('somebody who may correct but not delete can ask', (await A.apvAsk(row, 'wrong size entered')) === '');
  ok('…and the request names the entry', A.apvOpen().length === 1 && A.apvOpen()[0].id === 'bd_x1');
  ok('…and carries the reason, so whoever answers knows what happened',
     A.apvOpen()[0].why === 'wrong size entered');
  /* THE ROW TRAVELS WITH IT. A week later the answerer needs to see what the asker saw. */
  ok('…and what the entry said at the time',
     (A.apvOpen()[0].data || {}).empName === 'Vikram Mahawar' && (A.apvOpen()[0].data || {}).issuePieces === 20);
  ok('asking twice is not two requests', /already asked/.test(await A.apvAsk(row, 'again')));

  /* Answering is the admin's. */
  ok('a non-admin cannot answer their own request', /Only an admin/.test(await A.apvAnswer('bd_x1', true)));

  ME.admin = true;
  ok('keeping it closes the request and leaves the entry alone',
     (await A.apvAnswer('bd_x1', false)) === ''
     && A.apvOpen().length === 0 && (A.PT().base || []).length === 1);

  ME.admin = false;
  await A.apvAsk(row, 'really wrong');
  ME.admin = true;
  ok('approving deletes the entry', (await A.apvAnswer('bd_x1', true)) === '');
  ok('…and it is gone from the register', (A.PT().base || []).length === 0);
  ok('…and the request is gone with it, because it has been answered', A.apvOpen().length === 0);
  ok('answering one that is no longer waiting says so',
     /no longer waiting/.test(await A.apvAnswer('bd_x1', true)));

  /* THE SNAPSHOT IS NOT WHAT GETS DELETED. A week is long enough for somebody to have corrected the
   * row instead, and deleting what the snapshot said would throw away work nobody asked to lose. */
  A.setPT(Object.assign(A.PT(), { base: [] }));
  A.setAPV([{ id: 'bd_gone', type: 'del_entry', at: '2026-09-04T05:59:59.221Z', by: 'v@x',
    label: 'Delete Base Data entry', data: { sku: 'TC-B', empName: 'Somebody', issuePieces: 5 } }]);
  ok('a request whose entry has already gone is cleared, not acted on',
     /already gone/.test(await A.apvAnswer('bd_gone', true)) && A.apvOpen().length === 0);

  /* AND THE SCREEN SAYS SO. A queue somebody has to remember to open is a queue that fills up —
   * eight sat unanswered for a week in the tool this replaces, with nothing anywhere saying so. */
  A.setAPV([{ id: 'a1', type: 'del_entry', at: 'x', data: {} }, { id: 'a2', type: 'del_entry', at: 'y', data: {} }]);
  ME.admin = true; A.renderPbase();
  ok('the register says how many are waiting', /2 deletion requests/.test(els.pbApv.textContent), els.pbApv.textContent);
  ok('…and the button is there to press', els.pbApv._hidden !== true);
  A.setAPV([]); A.renderPbase();
  ok('…and it goes away when nothing is waiting', els.pbApv._hidden === true);
  ME.admin = false; A.setAPV([{ id: 'a1', type: 'del_entry', at: 'x', data: {} }]); A.renderPbase();
  ok('…and somebody who cannot answer is not shown a queue', els.pbApv._hidden === true);
  ME.admin = true;

  /* The eight that are already waiting are read exactly as the old tool left them. */
  NET.store['pt_approvals'] = {
    'bd_1788501581181_9bc6hk': { id: 'bd_1788501581181_9bc6hk', type: 'del_entry',
      at: '2026-09-04T05:59:59.221Z', by: 'vikas.mahawar@thefabricrush.com',
      label: 'Delete Base Data entry — Vikas Mahawar / TC-CUST-260904-37',
      data: { sku: 'TC-CUST-260904-37', empName: 'Vikas Mahawar', issuePieces: 5 } },
  };
  /* ONE OF THE EIGHT IS NOT FILED UNDER ITS ROW. The old tool met a second request for a row
   * somebody had already asked about and parked it beside the first, under "…_dup1". */
  NET.store['pt_approvals']['bd_1788612687566_zp7gue'] = { id: 'bd_1788612687566_zp7gue',
    type: 'del_entry', at: '2026-09-06T04:10:00.000Z', by: 'vikas.mahawar@thefabricrush.com',
    data: { sku: 'CPCCRU052-18', empName: 'Vikas Mahawar', issuePieces: 18 } };
  NET.store['pt_approvals']['bd_1788612687566_zp7gue_dup1'] = { id: 'bd_1788612687566_zp7gue',
    type: 'del_entry', at: '2026-09-08T04:10:00.000Z', by: 'vikas.mahawar@thefabricrush.com',
    data: { sku: 'CPCCRU052-18', empName: 'Vikas Mahawar', issuePieces: 18 } };
  A.setPT(Object.assign(A.PT(), { base: [{ id: 'bd_1788612687566_zp7gue', sku: 'CPCCRU052-18' }] }));
  A.setAPV(null);
  await A.apvLoad(true);
  ok('both requests for the same row are read, not one', A.apvOpen().length === 3);
  ME.admin = true;
  ok('keeping the dup answers the dup', (await A.apvAnswer('bd_1788612687566_zp7gue_dup1', false)) === '');
  ok('…and the one it was parked beside is still waiting',
     A.apvOpen().some(x => (x._key || x.id) === 'bd_1788612687566_zp7gue'),
     JSON.stringify(A.apvOpen().map(x => x._key || x.id)));
  ok('…and it is the dup that is gone from the database',
     NET.store['pt_approvals']['bd_1788612687566_zp7gue_dup1'] === undefined
     && !!NET.store['pt_approvals']['bd_1788612687566_zp7gue']);
  NET.calls.length = 0;
  ok('and answering the other one deletes the row it names, not the key it sits under',
     (await A.apvAnswer('bd_1788612687566_zp7gue', true)) === ''
     && (A.PT().base || []).length === 0
     && NET.calls.some(c => c.method === 'DELETE' && /pt_baseData\/bd_1788612687566_zp7gue$/.test(netPath(c.url))),
     JSON.stringify(NET.calls.filter(c => c.method === 'DELETE').map(c => netPath(c.url))));

  NET.store['pt_approvals'] = {
    'bd_1788501581181_9bc6hk': { id: 'bd_1788501581181_9bc6hk', type: 'del_entry',
      at: '2026-09-04T05:59:59.221Z', by: 'vikas.mahawar@thefabricrush.com',
      label: 'Delete Base Data entry — Vikas Mahawar / TC-CUST-260904-37',
      data: { sku: 'TC-CUST-260904-37', empName: 'Vikas Mahawar', issuePieces: 5 } },
  };
  A.setAPV(null);
  await A.apvLoad(true);
  ok('the requests already waiting in the old tool are read as they stand',
     A.apvOpen().length === 1 && A.apvOpen()[0].by === 'vikas.mahawar@thefabricrush.com',
     JSON.stringify(A.apvOpen().map(x => x.id)));
  ok('…with the entry the old tool recorded against them',
     (A.apvOpen()[0].data || {}).sku === 'TC-CUST-260904-37');

  A.setPT(Object.assign(A.PT(), { base: wasBase })); A.setAPV(wasApv);
  NET.on = wasNet; ME.admin = wasAdmin; ME.prodEdit = wasEdit;
}

console.log('\n== printing, and whose line it is ==');
{
  /* "iska access edit access me sirf printer ko dunga and jis printer ko assign karunga only bahi
   * printer us order ko dekh payega or koi nhi." Three different things: assigning is Ravi's,
   * recording the printing is the printer's, and seeing it is the printer's own line only. */
  const wasOb = A.PTG().ob, wasSp = A.PTG().shopProd, wasVP = A.VP(), wasNet = NET.on, wasAdmin = ME.admin;
  ME.admin = true; NET.on = true; NET.store = {};
  A.setPTG(Object.assign(A.PTG(), { shopProd: {}, ob: [
    { id: 'p1', orderNo: 'SHP-7001', sku: 'PRINT-A', qty: 10, src: 'SHP', orderDate: '2026-09-01', articleType: 'Quilt' },
    { id: 'p2', orderNo: 'SHP-7002', sku: 'PRINT-B', qty: 4, src: 'SHP', orderDate: '2026-09-02', articleType: 'Quilt' },
  ] }));
  A.setVP(Object.assign({}, wasVP, { code: null }));
  const ln = no => (A.ordLines() || []).find(l => l.orderNo === no);

  ok('a line starts with no printer on it', A.spPrinter('SHP-7001', 'PRINT-A') === '');
  ok('…and nobody can record printing on it', A.spCanPrint('SHP-7001', 'PRINT-A') === false);
  ok('…which it says, rather than failing silently',
     /Nobody has been given this line/.test(await A.spPrint('SHP-7001', 'PRINT-A', 5)));
  ok('a line nobody prints is not behind on printing', ln('SHP-7001').pendingPrint === 0);

  ok('a printer nothing knows is refused', /not in the vendor master/.test(await A.spAssign('SHP-7001', 'PRINT-A', 'VND999')));
  ok('assigning a real printer works', (await A.spAssign('SHP-7001', 'PRINT-A', 'VND001')) === '');
  ok('…and the line says who has it', ln('SHP-7001').printer === 'VND001');
  ok('…and is now waiting on printing', ln('SHP-7001').pendingPrint === 10);

  /* ASSIGNING IS RAVI'S. A printer who could assign could take somebody else's work. */
  ME.admin = false;
  A.setVP(Object.assign({}, A.VP(), { code: 'VND001' }));
  /* The refusal now names the permission rather than the role — handing work out stopped being
   * admin-only and became a grant of its own. A printer never has it either way. */
  ok('a printer cannot give themselves a line', /needs permission/.test(await A.spAssign('SHP-7002', 'PRINT-B', 'VND001')),
     await A.spAssign('SHP-7002', 'PRINT-B', 'VND001'));

  /* RECORDING IS THE PRINTER'S, and only the one the line was given to. */
  ok('the printer it was given to may record the printing', A.spCanPrint('SHP-7001', 'PRINT-A') === true);
  ok('recording it works', (await A.spPrint('SHP-7001', 'PRINT-A', 6)) === '');
  ok('…and the line carries the figure', ln('SHP-7001').printed === 6 && ln('SHP-7001').pendingPrint === 4);

  A.setVP(Object.assign({}, A.VP(), { code: 'VND002' }));
  ok('another printer may not', A.spCanPrint('SHP-7001', 'PRINT-A') === false);
  ok('…and is told whose line it is', /Only RBP-Bagru records/.test(await A.spPrint('SHP-7001', 'PRINT-A', 9)),
     await A.spPrint('SHP-7001', 'PRINT-A', 9));

  /* SEEING IT. A printer sees the lines given to them and no others — not another printer's, and not
   * the ones nobody has been given. */
  A.setVP(Object.assign({}, A.VP(), { code: 'VND001' }));
  ok('this account counts as a vendor', A.spIsVendor() === true);
  ok('a printer sees their own line', A.spCanSee('SHP-7001', 'PRINT-A') === true);
  ok('…and not one nobody has been given', A.spCanSee('SHP-7002', 'PRINT-B') === false);
  ok('…and the screen shows them only theirs',
     A.shppLines().length === 1 && A.shppLines()[0].orderNo === 'SHP-7001',
     A.shppLines().map(l => l.orderNo).join());

  /* THE TRAP THIS ALMOST WALKED INTO. VP.code is filled the moment the Vendor Portal looks an account
   * up, which an ADMIN may do — and asking "is VP.code set" made every line vanish for Ravi the first
   * time he had visited that screen. */
  ME.admin = true;
  ok('an admin who has opened the portal is still not a vendor', A.spIsVendor() === false);
  ok('…and still sees every line', A.shppLines().length === 2, String(A.shppLines().length));
  ok('…and may record the printing when a printer cannot', A.spCanPrint('SHP-7001', 'PRINT-A') === true);

  /* NOTHING IS CUT THAT WAS NOT PRINTED, once a line has a printer. */
  const over = await A.spSave('SHP-7001', 'PRINT-A', { cut: 9, issued: 0, received: 0, pressed: 0 });
  ok('cutting more than was printed is refused', /only 6 printed/.test(over), over);
  ok('…and it names who has to print it first', /RBP-Bagru/.test(over), over);
  ok('cutting what was printed is fine',
     (await A.spSave('SHP-7001', 'PRINT-A', { cut: 6, issued: 0, received: 0, pressed: 0 })) === '');
  /* And a line with no printer is bounded by nothing new — not every SKU is block printed. */
  ok('a line nobody prints can still be cut',
     (await A.spSave('SHP-7002', 'PRINT-B', { cut: 4, issued: 0, received: 0, pressed: 0 })) === '');

  /* The printing figure is the printer's. Saving the rest of the line must never take it back to nil. */
  ok('saving the other figures leaves the printing alone', ln('SHP-7001').printed === 6);
  /* Nor can printing be taken below what has already been cut from it. */
  ok('printing cannot go below what has been cut out of it',
     /already been cut/.test(await A.spPrint('SHP-7001', 'PRINT-A', 2)));

  /* Taking a printer off a line they have printed loses the only record of who did it. */
  ok('a printer cannot simply be removed once they have printed',
     /Change the printer instead/.test(await A.spAssign('SHP-7001', 'PRINT-A', '')));
  ok('…but can be changed to another', (await A.spAssign('SHP-7001', 'PRINT-A', 'VND002')) === '');

  A.setPTG(Object.assign(A.PTG(), { ob: wasOb, shopProd: wasSp }));
  A.setVP(wasVP); NET.on = wasNet; ME.admin = wasAdmin;
}

console.log('\n== a piece takes its zipper and its ruffle with it ==');
{
  /* "ruffle tablecloth and ruffle pillow cover me zipper and ruffle fabric lagta h but jab hum base
   * data me entry krte to koi record mainten nhi krte h."
   *
   * Measured on the live data: the zipper deduction existed and had never deducted one zipper — there
   * was no accessories master to find the zipper in, so all 576 zip SKUs came back "not in the
   * accessories master". Ruffle fabric had no deduction at all, on 818 ruffle SKUs. */
  const wasPTG = A.PTG(), wasPTE = A.PTE(), wasNet = NET.on, wasEdit = ME.prodEdit, wasAdmin = ME.admin;
  const wasMdb = A.PTG().mdb, wasMasters = A.PTG().masters, wasAcc = A.PTE().acc, wasLed = A.PTE().accLedger;
  ME.admin = true; ME.prodEdit = true; NET.on = true; NET.store = {};

  const zipRow = { sku: 'RPCRU-ZIP-1', articleType: 'Pillow Cover', subtype: 'Ruffle Pillow Cover', size: '20x20',
    color: 'Sea Green', isZip: true, chainLength: '20', isRuffle: false, packOf: '1' };
  const tcRow = { sku: 'RTCRU-1', articleType: 'Tablecloth', subtype: 'Ruffle Tablecloth', size: '70x118',
    color: 'Indigo', isZip: false, isRuffle: false, packOf: '1' };
  const tcRow2 = Object.assign({}, tcRow, { sku: 'RTCRU-2', color: 'Rust' });   // same size, another colour
  const quilt = { sku: 'RQL41-T', articleType: 'Quilt', subtype: 'Twin Quilt', size: '60x90',
    isRuffle: true, ruffleFabric: 'Cambric', ruffleMeters: 0.75, isZip: false, packOf: '1' };
  A.setPTG(Object.assign(A.PTG(), { mdb: [zipRow, tcRow, tcRow2, quilt],
    masters: Object.assign({}, wasMasters, {
      fabricType: [{ code: 'CAMBRIC', desc: 'Cambric', active: true }, { code: 'VOIL 92', desc: 'Voil 92', active: true }],
      ruffleRule: [] }) }));
  A.setPTE(Object.assign(A.PTE(), { acc: [], accLedger: [] }));
  /* The list is cleared EVERYWHERE, because the gate asks every copy — leaving the real masters in
   * place would find code 20 there and test a different branch than the one meant. */
  A.setPTG(Object.assign(A.PTG(), { masters: Object.assign({}, A.PTG().masters, { accessories: [] }) }));
  const wasACCz = A.ACC();
  /* null, not [] — that is the app's real "not loaded yet" state, and it matters: the deduction
   * copies ACC.ledger over PTE.accLedger whenever ACC.ledger is truthy, and an empty ARRAY is
   * truthy. A fixture using [] quietly wiped the opening stock it had just set. */
  A.setACC(Object.assign({}, wasACCz, { items: null, ledger: null }));

  /* 1. ZIPPERS.
   *
   * A LENGTH NOBODY HAS STOCKED IS REFUSED. It used to be added automatically and the issue let
   * through, which is how Zipper 30 reached −150: nine issues went out before anybody typed an
   * opening figure, and the row that was added was a name, never a quantity. */
  let noStock = '';
  try { await A.ptConsumeZippers({ id: 'bd_z0', sku: 'RPCRU-ZIP-1', issuePieces: 12, issueDate: '2026-09-13', empName: 'Ramesh' }); }
  catch (e) { noStock = e.message || String(e); }
  ok('a zipper nobody listed cannot be issued', /not on the accessories list/.test(noStock), noStock);
  ok('…and nothing is written behind anybody\'s back',
    !Object.keys(NET.store).some(p => /pt_masters\/accessories|pt_accLedger/.test(p)),
    Object.keys(NET.store).join(' '));

  /* So the store lists it and says what is on the shelf, which is what a store does. */
  A.setPTE(Object.assign(A.PTE(), {
    acc: [{ code: '20', name: 'Zipper 20 inch', unit: 'pcs' }],
    accLedger: [{ _id: 'z_open', itemCode: '20', txnType: 'OPENING', qty: 100, date: '2026-09-01' }] }));
  A.setPTG(Object.assign(A.PTG(), { masters: Object.assign({}, A.PTG().masters, { accessories: A.PTE().acc }) }));

  const e1 = { id: 'bd_z1', sku: 'RPCRU-ZIP-1', issuePieces: 12, issueDate: '2026-09-13', empName: 'Ramesh' };
  /* Caught: break the shelf reader and this refuses, and a throw would take the suite with it
   * instead of failing this line. */
  let note1 = '';
  try { note1 = await A.ptConsumeZippers(e1); } catch (e) { note1 = 'threw: ' + (e.message || e); }
  ok('a stocked zipper is deducted without comment', note1 === '', note1);
  ok('…and the zippers are deducted', NET.store['pt_accLedger/acc_auto_bd_z1']
     && NET.store['pt_accLedger/acc_auto_bd_z1'].qty === 12 && NET.store['pt_accLedger/acc_auto_bd_z1'].txnType === 'OUT',
     JSON.stringify(NET.store['pt_accLedger/acc_auto_bd_z1']));
  /* THE NAME, as a field. "Who has what" reads the field, not the sentence in remarks — an
   * automatic zipper issue is an issue to a person like any other. */
  ok('…in the karigar’s name, not only in the remarks',
    (NET.store['pt_accLedger/acc_auto_bd_z1'] || {}).issuedTo === 'Ramesh',
    JSON.stringify(NET.store['pt_accLedger/acc_auto_bd_z1']));
  ok('…so it shows up under who has what', (() => {
    const was = A.ACC();
    A.setACC({ items: A.PTE().acc || [], ledger: A.PTE().accLedger || [] });
    const hit = A.accOutWith().some(e => e.who === 'Ramesh' && e.held > 0);
    A.setACC(was); return hit;
  })());
  /* The second time it simply deducts again, and the list is not touched. */
  /* Caught for the same reason as the first: break the shelf reader and this refuses instead of
   * deducting, and a throw would take the suite with it. */
  let note2 = '';
  try { note2 = await A.ptConsumeZippers({ id: 'bd_z2', sku: 'RPCRU-ZIP-1', issuePieces: 3, issueDate: '2026-09-13' }); }
  catch (e) { note2 = 'threw: ' + (e.message || e); }
  ok('the next issue just deducts, and the list is left alone',
     note2 === '' && A.PTE().acc.filter(it => it.code === '20').length === 1, note2);
  /* AND THE SHELF IS THE LIMIT. 100 on the shelf, 15 gone; an issue of 90 is 5 more than there are. */
  /* The two deductions above are already on the ledger — the consumption put them there. Adding
   * them again by hand counted the same zippers twice. */
  let over = '';
  try { await A.ptConsumeZippers({ id: 'bd_z3', sku: 'RPCRU-ZIP-1', issuePieces: 90, issueDate: '2026-09-13' }); }
  catch (e) { over = e.message || String(e); }
  ok('…and an issue beyond what is left is refused', /has 85 in stock/.test(over), over);
  ok('…without writing the deduction', !NET.store['pt_accLedger/acc_auto_bd_z3']);
  /* The screen copy goes back only once this section is done with it — accLedgerNow prefers it,
   * so restoring it early makes every figure here read off the wrong ledger. */
  /* SAVED TWICE, DEDUCTED ONCE — the posting is keyed on the Base Data row. Still inside this
   * section's own shelf, and caught, so a break in the shelf reader fails rather than throws. */
  try { await A.ptConsumeZippers(e1); } catch (e) { /* the count below is what this asks about */ }
  A.setACC(wasACCz);
  ok('the same issue saved again does not deduct twice',
     (A.PTE().accLedger || []).filter(r => r._id === 'acc_auto_bd_z1').length === 1);

  /* 2. RUFFLE — a rule per subtype and size covers every colour. */
  ok('a ruffle product is known by its subtype, not only by the flag',
     A.ptIsRuffle(tcRow) && A.ptIsRuffle(zipRow) && A.ptIsRuffle(quilt));
  const noRule = await A.ptConsumeRuffle({ id: 'bd_r0', sku: 'RTCRU-1', issuePieces: 5, issueDate: '2026-09-13', empName: 'Sita' });
  ok('with no rule, nothing is deducted — and it says so', /NOT deducted/.test(noRule) && /Ruffle Tablecloth 70x118/.test(noRule), noRule);
  ok('…and nothing is written', !NET.store['pt_fabInvLedger/fab_ruf_bd_r0']);

  ok('a rule can be set', (await A.ruffleRuleSave('Ruffle Tablecloth', '70x118', 'Voil 92', '1.2')) === '');
  ok('…but not with a fabric the master does not have',
     /not in the Fabric Type master/.test(await A.ruffleRuleSave('Ruffle Tablecloth', '70x118', 'Silk', '1')));
  ok('…nor with no metres at all', /more than nothing/.test(await A.ruffleRuleSave('Ruffle Tablecloth', '70x118', 'Voil 92', '0')));

  ok('one rule covers both colours of that size',
     A.ptRuffleOf(tcRow).meters === 1.2 && A.ptRuffleOf(tcRow2).meters === 1.2 && A.ptRuffleOf(tcRow2).fabric === 'Voil 92');
  ok('a SKU that carries its own ruffle figures keeps them', A.ptRuffleOf(quilt).from === 'sku'
     && A.ptRuffleOf(quilt).meters === 0.75);

  const e3 = { id: 'bd_r1', sku: 'RTCRU-2', issuePieces: 10, issueDate: '2026-09-13', empName: 'Sita', orderNo: 'AMZ-1' };
  ok('issuing a ruffle piece deducts the ruffle', (await A.ptConsumeRuffle(e3)) === '');
  const fr = NET.store['pt_fabInvLedger/fab_ruf_bd_r1'];
  ok('…metres times pieces, of the rule\'s fabric', fr && fr.qty === 12 && fr.fabricType === 'Voil 92', JSON.stringify(fr));
  ok('…as cloth issued to the stitchers', fr && fr.txnType === 'ISSUE_TO_STITCHERS');

  /* DELETING THE ISSUE GIVES THE MATERIAL BACK. */
  NET.calls.length = 0;
  await A.ptUnconsumeRuffle('bd_r1');
  await A.ptUnconsumeZippers('bd_z1');
  ok('deleting the issue takes the ruffle deduction back',
     NET.calls.some(c => c.method === 'DELETE' && /fab_ruf_bd_r1/.test(c.url)));
  ok('…and the zipper one', NET.calls.some(c => c.method === 'DELETE' && /acc_auto_bd_z1/.test(c.url)));

  /* 3. THE SCREEN — every ruffle size the catalogue has, set or blank. */
  const combos = A.ruffleCombos();
  ok('every ruffle subtype and size is on the list', combos.length === 3,
     JSON.stringify(combos.map(c => c.subtype + ' ' + c.size + ' ' + c.skus)));
  ok('…with how many SKUs each one covers',
     combos.find(c => c.subtype === 'Ruffle Tablecloth').skus === 2);
  ok('…and whether it has been set',
     combos.find(c => c.subtype === 'Ruffle Tablecloth').fabric === 'Voil 92'
     && !combos.find(c => c.subtype === 'Ruffle Pillow Cover').fabric);
  els.mstPick.value = 'ruffleRule'; els.mstQ.value = '';
  A.setMST_ && 0;
  A.renderMst();
  ok('the Masters screen draws the rules', /Metres per piece/.test(els.mstTable.innerHTML)
     && /Ruffle Tablecloth/.test(els.mstTable.innerHTML), els.mstTable.innerHTML.slice(0, 120));
  ok('…and says what is still blank', /still have no ruffle fabric/.test(els.mstMsg.textContent), els.mstMsg.textContent);

  A.setPTG(Object.assign(A.PTG(), { mdb: wasMdb, masters: wasMasters }));
  A.setPTE(Object.assign(A.PTE(), { acc: wasAcc, accLedger: wasLed }));
  NET.on = wasNet; ME.prodEdit = wasEdit; ME.admin = wasAdmin;
  els.mstPick.value = '';
}

console.log('\n== the fabric on a cutting entry is picked from the master ==');
{
  /* "I need dropdown in fabric like production tracker app in cutting data." The tracker filled it from
   * the Fabric Type master — active only, by description, case-insensitive duplicates folded. A typed
   * fabric is how one cloth lands on the register as three spellings. */
  const wasMasters = A.PTG().masters;
  A.setPTG(Object.assign(A.PTG(), { masters: Object.assign({}, wasMasters, { fabricType: [
    { code: 'CAMBRIC', desc: 'Cambric', active: true },
    { code: 'SHEETING 82', desc: 'Sheeting 82', active: true },
    { code: 'sheeting 82', desc: 'sheeting 82', active: true },     // the same cloth, typed again
    { code: 'OLD VOIL', desc: 'Old Voil', active: false },          // retired
    { code: '400 TC', desc: '', active: true },                     // no description: the code stands in
  ] }) }));

  /* ================= THE CLOTH IS PICKED FROM THE MASTER, NOT TYPED =================
   *
   * One live SKU says "Sheeitng 112" — a fabric with no master row, no width and no ledger. Cutting
   * has always refused a spelling the master does not have; the master database was where one could
   * still be invented. */
  {
    const wasM = A.PTG().masters;
    A.setPTG(Object.assign({}, A.PTG(), { masters: Object.assign({}, wasM, {
      fabricType: { a: { code: 'SHEETING 62', desc: 'Sheeting 62', active: true },
        b: { code: 'CAMBRIC', desc: 'Cambric', active: true, widthIn: 42 },
        c: { code: 'RETIRED', desc: 'Retired cloth', active: false } } }) }));
    const fieldOf = (rec, key) => (A.mdbFields(rec) || []).find(f => f.key === key) || {};
    const blank = fieldOf(null, 'fabric');
    ok('a new SKU picks its fabric from a list, it does not type one',
       blank.type === 'select', String(blank.type));
    ok('…and the list is the Fabric Type master',
       (blank.options || []).indexOf('Sheeting 62') > 0 && (blank.options || []).indexOf('Cambric') > 0,
       (blank.options || []).join(','));
    ok('…without the ones somebody switched off',
       (blank.options || []).indexOf('Retired cloth') < 0, (blank.options || []).join(','));
    ok('…and it starts blank rather than on whichever cloth happens to sort first',
       (blank.options || [])[0] === '' && !blank.value, JSON.stringify([blank.options && blank.options[0], blank.value]));
    /* WHAT THE ROW ALREADY SAYS IS NEVER TAKEN AWAY FROM IT. A bad spelling must stay visible and
     * fixable — silently swapping it for a valid one would change what a SKU is made of. */
    const bad = fieldOf({ sku: 'X-1', fabric: 'Sheeitng 112' }, 'fabric');
    ok('a SKU whose spelling is not in the master keeps it',
       bad.value === 'Sheeitng 112' && (bad.options || []).indexOf('Sheeitng 112') >= 0, (bad.options || []).join(','));
    ok('…and the real fabrics are still offered beside it',
       (bad.options || []).indexOf('Sheeting 62') >= 0, (bad.options || []).join(','));
    ok('…and it is not offered twice',
       (A.fabListOr('Sheeting 62') || []).filter(x => x === 'Sheeting 62').length === 1,
       A.fabListOr('Sheeting 62').join(','));
    /* The ruffle cloth is written straight onto the fabric ledger, so it is picked too. */
    const ruf = fieldOf({ sku: 'X-1', ruffleFabric: 'Cambric' }, 'ruffleFabric');
    ok('the ruffle cloth is picked from the same master', ruf.type === 'select' && ruf.value === 'Cambric',
       String(ruf.type) + ' ' + String(ruf.value));
    /* AND THE COLOUR-BEARING FIELDS ARE UNTOUCHED — this changed two fields, not the form. */
    ok('the rest of the form is as it was',
       fieldOf(null, 'consumption').type === 'number' && fieldOf(null, 'cuttingRequired').type === 'select'
       && (A.mdbFields(null) || []).length === 22, String((A.mdbFields(null) || []).length) + ' fields');   // + piping dori, its metres (2026-09-22)
    A.setPTG(Object.assign({}, A.PTG(), { masters: wasM }));
  }

  /* ================= WHAT IS BEING MADE, READ OFF THE ORDER CONSOLE =================
   *
   * The In Production column used to be a workbook uploaded by hand; the live one was 22 days old
   * and every one of its dates was being thrown away. The whole replenishment plan rests on this
   * figure: too low and somebody starts a second run of goods already on a machine. */
  {
    /* ---- THE DATE READER. "29-09-2026" is a date. new Date('29-09-2026T00:00:00') is not, and that
     * one line marked 234,847 live units "no date" while every row had one. ---- */
    ok('a date written the Indian way is read', A.pdIso('29-09-2026') === '2026-09-29', A.pdIso('29-09-2026'));
    ok('…with slashes too', A.pdIso('9/3/2026') === '2026-03-09', A.pdIso('9/3/2026'));
    ok('…and a single-digit day and month are padded', A.pdIso('5-7-2026') === '2026-07-05', A.pdIso('5-7-2026'));
    ok('an ISO date is left as it is', A.pdIso('2026-09-29') === '2026-09-29', A.pdIso('2026-09-29'));
    ok('…even with a time on the end', A.pdIso('2026-09-29T11:00:00Z') === '2026-09-29', A.pdIso('2026-09-29T11:00:00Z'));
    ok('a blank is a blank, not today', A.pdIso('') === '' && A.pdIso(null) === '' && A.pdIso(undefined) === '');
    ok('and something that is not a date at all is refused', A.pdIso('soon') === '' && A.pdIso('29-09') === '',
       JSON.stringify([A.pdIso('soon'), A.pdIso('29-09')]));

    const wasOb = A.PTG().ob, wasPress = A.PTG().press, wasSP2 = A.PTG().shopProd, wasSox = A.SOX();
    const wasBase2 = A.PT().base, wasCut2 = A.PT().cut, wasMdb = A.PTG().mdb;
    A.setPTG(Object.assign({}, A.PTG(), { mdb: [{ sku: 'IP-A', articleType: 'Quilt', subtype: 'Queen Quilt',
      size: '90X96', color: 'Blue', packOf: 1, cuttingRequired: true },
      /* Not a quilt: a Shopify quilt keeps counters of its own, so the press register decides nothing
       * for one. The two cases below need the register to be what counts. */
      { sku: 'IP-B', articleType: 'Tablecloth', subtype: 'Square Tablecloth',
        size: '60x60', color: 'Blue', packOf: 1, cuttingRequired: true }] }));
    A.setPT(Object.assign({}, A.PT(), { base: [], cut: [] }));
    A.setPTG(Object.assign({}, A.PTG(), { press: [], shopProd: {},
      ob: [{ orderNo: 'AMZ-9001', sku: 'IP-A', qty: 100, orderDate: '2026-09-01', src: 'SO' }] }));
    A.setSOX_(Object.assign({}, A.SOX(), { rows: [{ _id: 'AMZ-9001', deliveryDate: '',
      lines: [{ sku: 'IP-A', qty: 100, deliveryDate: '2026-10-15' }] }] }));
    A.setORD({ req: {}, busy: false, at: '', rows: [], pick: new Set() });

    /* ---- THE PROMISE COMES OFF THE SALES ORDER ---- */
    ok('the delivery date the order promised is found', A.ordDueIndex().get('AMZ-9001|IP-A') === '2026-10-15',
       String(A.ordDueIndex().get('AMZ-9001|IP-A')));

    let rows = A.ordProdRows();
    ok('an open line is being made', rows.length === 1 && rows[0].sku === 'IP-A', JSON.stringify(rows));
    ok('…for every piece nobody has pressed', rows[0].qty === 100, String(rows[0].qty));
    ok('…ready when the order said', rows[0].ready === '2026-10-15', rows[0].ready);
    ok('…against the order it is on', rows[0].supplier === 'AMZ-9001' && rows[0].orderNo === 'AMZ-9001', rows[0].supplier);
    ok('…and it says which stage it is at', rows[0].stage === 'to cut', rows[0].stage);

    /* ---- PRESSED PIECES ARE NOT IN PRODUCTION. They are finished; counting them would tell the
     * plan that goods already made are still to come. ---- */
    A.setPTG(Object.assign({}, A.PTG(), { press: [{ id: 'ip1', orderNo: 'AMZ-9001', sku: 'IP-A', pieces: 40 }] }));
    A.setORD({ req: {}, busy: false, at: '', rows: [], pick: new Set() });
    rows = A.ordProdRows();
    ok('what has been through the press stops counting as in production', rows[0].qty === 60, String(rows[0].qty));
    /* ---- AND A FINISHED LINE DROPS OUT ALTOGETHER ---- */
    A.setPTG(Object.assign({}, A.PTG(), { press: [{ id: 'ip1', orderNo: 'AMZ-9001', sku: 'IP-A', pieces: 100 }] }));
    A.setORD({ req: {}, busy: false, at: '', rows: [], pick: new Set() });
    ok('a line that is fully pressed is not being made at all', A.ordProdRows().length === 0,
       JSON.stringify(A.ordProdRows()));
    /* …AND OVER-PRESSING CANNOT TURN IT NEGATIVE. Only a Shopify line can reach this: everything else
     * closes the moment pressed reaches ordered, so the subtraction never sees a bigger number. A
     * Shopify line stays open until shipping takes it, and 9 live lines have more pressed than
     * ordered - 3 of them still open. One negative row would quietly eat another SKU's production
     * out of the total. */
    const shopOpen = pressed => ({
      press: [{ id: 'ip2', orderNo: 'SHP-9002', sku: 'IP-B', pieces: pressed }],
      /* A RECORD WITH NO handedAt: that is what keeps a Shopify line open however much is pressed. */
      shopProd: { 'SHP-9002__IP-B': { orderNo: 'SHP-9002', sku: 'IP-B' } },
      ob: [{ orderNo: 'SHP-9002', sku: 'IP-B', qty: 4, pcs: 4, orderDate: '2026-09-02', src: 'SHP',
        articleType: 'Tablecloth', articleSubtype: 'Square Tablecloth' }] });
    A.setPTG(Object.assign({}, A.PTG(), shopOpen(6)));
    A.setORD({ req: {}, busy: false, at: '', rows: [], pick: new Set() });
    ok('…and more pressed than ordered never makes a negative figure', A.ordProdRows().length === 0,
       JSON.stringify(A.ordProdRows()));
    /* AND AN OPEN LINE WITH NOTHING LEFT DROPS OUT rather than sitting in the list as a zero. It is
     * waiting for shipping to take it, not waiting to be made. */
    A.setPTG(Object.assign({}, A.PTG(), shopOpen(4)));
    A.setORD({ req: {}, busy: false, at: '', rows: [], pick: new Set() });
    ok('…and an open line with nothing left to make is not listed at all', A.ordProdRows().length === 0,
       JSON.stringify(A.ordProdRows()));
    /* …while one with a piece still to go IS. */
    A.setPTG(Object.assign({}, A.PTG(), shopOpen(3)));
    A.setORD({ req: {}, busy: false, at: '', rows: [], pick: new Set() });
    ok('…but one with a piece still to make is', A.ordProdRows().length === 1 && A.ordProdRows()[0].qty === 1,
       JSON.stringify(A.ordProdRows()));
    A.setPTG(Object.assign({}, A.PTG(), { press: [], shopProd: {},
      ob: [{ orderNo: 'AMZ-9001', sku: 'IP-A', qty: 100, orderDate: '2026-09-01', src: 'SO' }] }));

    /* ---- AN ORDER THAT PROMISED NOTHING IS SHOWN AS UNDATED, NOT GUESSED HERE ---- */
    A.setPTG(Object.assign({}, A.PTG(), { press: [] }));
    A.setSOX_(Object.assign({}, A.SOX(), { rows: [{ _id: 'AMZ-9001', deliveryDate: '',
      lines: [{ sku: 'IP-A', qty: 100, deliveryDate: '' }] }] }));
    A.setORD({ req: {}, busy: false, at: '', rows: [], pick: new Set() });
    ok('a line whose order promised no date carries no date', A.ordProdRows()[0].ready === '',
       JSON.stringify(A.ordProdRows()[0]));
    /* …and the order's own date stands in for a line that has none. */
    A.setSOX_(Object.assign({}, A.SOX(), { rows: [{ _id: 'AMZ-9001', deliveryDate: '30-11-2026',
      lines: [{ sku: 'IP-A', qty: 100, deliveryDate: '' }] }] }));
    ok('…unless the order itself named one', A.ordDueIndex().get('AMZ-9001|IP-A') === '2026-11-30',
       String(A.ordDueIndex().get('AMZ-9001|IP-A')));
    /* …and where BOTH are set the LINE's own date is the one that counts. The order header is only a
     * fallback: an order-wide date must not override what a particular line promised. */
    A.setSOX_(Object.assign({}, A.SOX(), { rows: [{ _id: 'AMZ-9001', deliveryDate: '2026-12-31',
      lines: [{ sku: 'IP-A', qty: 100, deliveryDate: '2026-10-15' }] }] }));
    ok('…and where both are set the line beats the order header',
       A.ordDueIndex().get('AMZ-9001|IP-A') === '2026-10-15', String(A.ordDueIndex().get('AMZ-9001|IP-A')));
    /* …and the EARLIEST promise wins when an order names two for the same SKU. The earlier one is
     * listed FIRST on purpose: if the last one simply overwrote, this would pass either way. */
    A.setSOX_(Object.assign({}, A.SOX(), { rows: [{ _id: 'AMZ-9001', deliveryDate: '',
      lines: [{ sku: 'IP-A', qty: 40, deliveryDate: '2026-09-25' }, { sku: 'IP-A', qty: 60, deliveryDate: '2026-10-15' }] }] }));
    ok('…and the earliest of two promises is the one that counts',
       A.ordDueIndex().get('AMZ-9001|IP-A') === '2026-09-25', String(A.ordDueIndex().get('AMZ-9001|IP-A')));

    /* ---- A SHOPIFY LINE THE SHIPPING TEAM HAS TAKEN IS NOT IN PRODUCTION ---- */
    A.setPTG(Object.assign({}, A.PTG(), {
      ob: [{ orderNo: 'SHP-9001', sku: 'IP-A', qty: 4, pcs: 4, orderDate: '2026-09-02', src: 'SHP' }],
      shopProd: { 'SHP-9001__IP-A': { orderNo: 'SHP-9001', sku: 'IP-A', handedAt: '2026-09-12T05:00:00Z' } } }));
    A.setORD({ req: {}, busy: false, at: '', rows: [], pick: new Set() });
    ok('a Shopify line already handed to shipping is not being made', A.ordProdRows().length === 0,
       JSON.stringify(A.ordProdRows()));
    /* A NEW ob ARRAY WITH IT. ordLines caches on the identity of the lists it reads, and shopProd
     * is not one of them - so without this the second call hands back the first call's answer. */
    A.setPTG(Object.assign({}, A.PTG(), { shopProd: {},
      ob: [{ orderNo: 'SHP-9001', sku: 'IP-A', qty: 4, pcs: 4, orderDate: '2026-09-02', src: 'SHP' }] }));
    A.setORD({ req: {}, busy: false, at: '', rows: [], pick: new Set() });
    ok('…but one nobody has taken still is', A.ordProdRows().length === 1 && A.ordProdRows()[0].qty === 4,
       JSON.stringify(A.ordProdRows()));

    A.setPTG(Object.assign({}, A.PTG(), { ob: wasOb, press: wasPress, shopProd: wasSP2, mdb: wasMdb }));
    A.setPT(Object.assign({}, A.PT(), { base: wasBase2, cut: wasCut2 }));
    A.setSOX_(wasSox);
    A.setORD({ req: {}, busy: false, at: '', rows: [], pick: new Set() });
  }

  /* ================= THE CLOTH IS PART OF THE RECIPE =================
   *
   * 212 of 321 combinations use one fabric across every colour, and those were being retyped for each
   * new colour. 46 use two or more — those must not be guessed at, and are not. */
  {
    const wasM2 = A.PTG().masters, wasMdb2 = A.PTG().mdb;
    const masters = f => Object.assign({}, wasM2, {
      fabricType: { a: { code: 'SHEETING 62', desc: 'Sheeting 62', active: true },
        b: { code: 'SHEETING 82', desc: 'Sheeting 82', active: true },
        c: { code: 'CHAMBRAY', desc: 'Chambray', active: true } },
      recipe: f });
    /* One combination, two colours, ONE cloth — the 212 case. */
    const SK = [
      { sku: 'RF-1', articleType: 'Tablecloth', subtype: 'Square Tablecloth', size: '60x60', color: 'Blue',
        fabric: 'Sheeting 62', packOf: 1, consumption: 1.6, cuttingRequired: true },
      { sku: 'RF-2', articleType: 'Tablecloth', subtype: 'Square Tablecloth', size: '60x60', color: 'Red',
        fabric: 'Sheeting 62', packOf: 1, consumption: 1.6, cuttingRequired: true },
    ];
    A.setPTG(Object.assign({}, A.PTG(), { mdb: SK, masters: masters({}) }));

    ok('Fabric is one of the fields a recipe holds',
       A.RECIPE_FIELDS.some(f => f[0] === 'fabric'), A.RECIPE_FIELDS.map(f => f[0]).join(','));
    ok('…and it is a picked one, not a typed one', A.RECIPE_FAB.indexOf('fabric') >= 0, A.RECIPE_FAB.join(','));
    ok('…and the ruffle cloth is picked the same way', A.RECIPE_FAB.indexOf('ruffleFabric') >= 0, A.RECIPE_FAB.join(','));
    ok('…and the template has a column for it', A.recipeSheetHead().indexOf('Fabric') >= 0,
       A.recipeSheetHead().slice(0, 8).join(' | '));
    ok('…with its read-only twin beside the rest',
       A.recipeSheetHead().indexOf('SKUs say: Fabric') > A.recipeSheetHead().indexOf('Fabric'),
       A.recipeSheetHead().join(' | ').slice(0, 200));

    /* ---- SEEDING: agreement is filled, disagreement is a question ---- */
    let plan = A.recipeSeedPlan();
    ok('a combination whose colours all use one cloth is filled in from them',
       (plan.rows[0] || {}).rec.fabric === 'Sheeting 62', JSON.stringify((plan.rows[0] || {}).rec));
    ok('…and nothing about it is skipped',
       !plan.skipped.some(x => x.field === 'fabric'), JSON.stringify(plan.skipped));

    /* THE 46 CASE. Piping pillow covers 20x20 are Chambray on some colours and Sheeting 82 on others.
     * Forty-two against one is not a majority to this — it is a question for Ravi. */
    A.setPTG(Object.assign({}, A.PTG(), { mdb: [
      Object.assign({}, SK[0], { sku: 'RF-3', fabric: 'Chambray' }),
      Object.assign({}, SK[1], { sku: 'RF-4', fabric: 'Sheeting 82' }),
      Object.assign({}, SK[1], { sku: 'RF-5', color: 'Green', fabric: 'Sheeting 82' })] }));
    plan = A.recipeSeedPlan();
    ok('a combination whose colours use different cloth is NOT decided for you',
       !plan.rows.some(r => r.rec.fabric), JSON.stringify(plan.rows.map(r => r.rec.fabric)));
    ok('…it is put on the list of things to answer',
       plan.skipped.some(x => x.field === 'fabric'), JSON.stringify(plan.skipped.map(x => x.field)));
    ok('…with both spellings and how many SKUs say each',
       (plan.skipped.find(x => x.field === 'fabric') || { values: [] }).values.map(v => v.value).sort().join(',')
         === 'Chambray,Sheeting 82',
       JSON.stringify((plan.skipped.find(x => x.field === 'fabric') || {}).values));

    /* ---- A RECIPE IS A DEFAULT, NEVER AN OVERRIDE ---- */
    A.setPTG(Object.assign({}, A.PTG(), { mdb: SK, masters: masters({
      r1: { articleType: 'Tablecloth', subtype: 'Square Tablecloth', size: '60x60', fabric: 'Sheeting 62' } }) }));
    ok('a new colour of that combination inherits the cloth',
       A.recipeFill({ sku: 'RF-9', articleType: 'Tablecloth', subtype: 'Square Tablecloth', size: '60x60',
         color: 'Green' }).rec.fabric === 'Sheeting 62',
       JSON.stringify(A.recipeFill({ sku: 'RF-9', articleType: 'Tablecloth', subtype: 'Square Tablecloth', size: '60x60' }).rec));
    ok('…and the screen says the cloth came from the recipe',
       A.recipeFill({ sku: 'RF-9', articleType: 'Tablecloth', subtype: 'Square Tablecloth', size: '60x60' }).from.indexOf('fabric') >= 0,
       A.recipeFill({ sku: 'RF-9', articleType: 'Tablecloth', subtype: 'Square Tablecloth', size: '60x60' }).from.join(','));
    /* THIS IS THE ONE THAT MATTERS for the 46: somebody who names the cloth keeps it. */
    ok('but a SKU that names its own cloth keeps it',
       A.recipeFill({ sku: 'RF-9', articleType: 'Tablecloth', subtype: 'Square Tablecloth', size: '60x60',
         fabric: 'Chambray' }).rec.fabric === 'Chambray',
       A.recipeFill({ sku: 'RF-9', articleType: 'Tablecloth', subtype: 'Square Tablecloth', size: '60x60', fabric: 'Chambray' }).rec.fabric);
    ok('…and recipeValue answers with the SKU, not the recipe',
       A.recipeValue({ articleType: 'Tablecloth', subtype: 'Square Tablecloth', size: '60x60', fabric: 'Chambray' }, 'fabric') === 'Chambray'
       && A.recipeValue({ articleType: 'Tablecloth', subtype: 'Square Tablecloth', size: '60x60' }, 'fabric') === 'Sheeting 62');

    /* ---- AND NOTHING CAN INVENT A FABRIC THROUGH THE SHEET ---- */
    /* A THROW IS CAUGHT AND REPORTED AS AN EMPTY PLAN, so taking Fabric out of RECIPE_FIELDS shows
     * up as a broken guard rather than a crash - a crash names nothing. */
    const up = v => { try {
      return A.recipeUploadPlan([{ articleType: 'Tablecloth', subtype: 'Square Tablecloth',
        size: '60x60', row: 2, vals: { fabric: v } }]);
    } catch (e) { return { set: [], change: [], skip: [], threw: e.message || String(e) }; } };
    ok('a spelling the Fabric Type master does not have is refused',
       up('Sheeitng 112').skip.length === 1 && /not in the Fabric Type master/.test(up('Sheeitng 112').skip[0].why),
       JSON.stringify(up('Sheeitng 112').skip));
    ok('…and nothing is written for that row',
       !up('Sheeitng 112').set.length && !up('Sheeitng 112').change.length);
    ok('a fabric the master does have is accepted',
       up('Chambray').change.length === 1 && up('Chambray').change[0].to === 'Chambray',
       JSON.stringify(up('Chambray')));
    /* …AND THE MASTER'S OWN SPELLING IS WHAT LANDS, not whatever case the sheet was typed in. */
    ok('…in the master\u2019s spelling, whatever case the sheet used',
       up('chambray').change.length === 1 && up('chambray').change[0].to === 'Chambray',
       JSON.stringify(up('chambray').change));

    /* THE WORKBOOK ITSELF IS NOT REACHABLE FROM HERE. recipeXlsx leans on soColName and soZip, which
     * live outside the block this harness cuts out of the page - so the .xlsx writing (the Fabrics
     * dropdown, the hidden Lists sheet) is covered by the head and column tests above and by opening
     * the file, not by this suite. Saying so beats a test that quietly proves nothing. */

    A.setPTG(Object.assign({}, A.PTG(), { masters: wasM2, mdb: wasMdb2 }));
  }

  const list = A.cutFabrics();
  ok('the list is the Fabric Type master', list.indexOf('Cambric') >= 0 && list.indexOf('Sheeting 82') >= 0,
     JSON.stringify(list));
  ok('…by description, the way the tracker named them', list.indexOf('CAMBRIC') < 0);
  ok('…with a spelling that differs only in case folded into the first one',
     list.filter(x => x.toLowerCase() === 'sheeting 82').length === 1, JSON.stringify(list));
  ok('…leaving a retired fabric out', list.indexOf('Old Voil') < 0);
  ok('…and using the code where there is no description', list.indexOf('400 TC') >= 0);

  A.cutFillFabrics();
  ok('the dropdown is filled from it', /<option value="Cambric">/.test(els.cwFabric.innerHTML)
     && !/Old Voil/.test(els.cwFabric.innerHTML), els.cwFabric.innerHTML.slice(0, 120));

  A.setPTG(Object.assign(A.PTG(), { masters: wasMasters }));
}

console.log('\n== a cutting entry can be made without knowing the SKU ==');
{
  /* "article color name select kru to auto sku bhi match ho, jisase jisko sku nhi pta wo bese entry
   * kar sake." */
  const wasPTG = A.PTG();
  const row = (sku, at, sub, col, sz) => ({ sku, articleType: at, subtype: sub, color: col, size: sz, packOf: '1' });
  A.setPTG(Object.assign({}, wasPTG, {
    mdb: [
      row('RTC23-6060', 'Tablecloth', 'Square Tablecloth', 'Indigo', '60x60'),
      row('RTC23-6090', 'Tablecloth', 'Rectangle Tablecloth', 'Indigo', '60x90'),
      row('RTC24-6090', 'Tablecloth', 'Rectangle Tablecloth', 'Rust', '60x90'),
      row('RPC9-1616', 'Pillow Cover', 'Piping Pillow Cover', 'Rust', '16x16'),
      row('RPC9B-1616', 'Pillow Cover', 'Piping Pillow Cover', 'Rust', '16x16'),   // same description, two SKUs
      row('RNOORDER-1', 'Tablecloth', 'Round Tablecloth', 'Rust', '90'),           // on no order
    ],
    ob: [
      { orderNo: 'AMZ-1', sku: 'RTC23-6060', qty: 10 }, { orderNo: 'AMZ-1', sku: 'RTC23-6090', qty: 10 },
      { orderNo: 'AMZ-1', sku: 'RTC24-6090', qty: 5 }, { orderNo: 'AMZ-2', sku: 'RPC9-1616', qty: 5 },
      { orderNo: 'AMZ-2', sku: 'RPC9B-1616', qty: 5 },
    ],
  }));
  const reset = () => { ['cwAt', 'cwSub', 'cwCol', 'cwSz', 'cwSku'].forEach(i => { els[i].value = ''; }); els.cwSku.dataset.typed = ''; };
  const pick = (id, v) => { els[id].value = v; (els[id]._listeners.change || []).forEach(fn => fn({})); };
  reset(); A.renderCutPick();
  ok('the article list is what is on an order', /Tablecloth/.test(els.cwAt.innerHTML) && /Pillow Cover/.test(els.cwAt.innerHTML));
  pick('cwAt', 'Tablecloth');
  ok('…and a SKU on no order is not offered', !/Round Tablecloth/.test(els.cwSub.innerHTML), els.cwSub.innerHTML);
  pick('cwSub', 'Rectangle Tablecloth');
  ok('the colours are the ones that subtype comes in', /Indigo/.test(els.cwCol.innerHTML) && /Rust/.test(els.cwCol.innerHTML));
  ok('…and nothing is guessed while the item is not named', els.cwSku.value === '');
  pick('cwCol', 'Rust');
  ok('a box with only one possible answer picks it', els.cwSz.value === '60x90', els.cwSz.value);
  ok('…and the SKU fills in', els.cwSku.value === 'RTC24-6090', els.cwSku.value);
  ok('…and the form reads it like a typed one', /Rectangle Tablecloth/.test(els.cwWho.textContent)
     && /AMZ-1/.test(els.cwOrd.innerHTML), els.cwWho.textContent);
  pick('cwCol', 'Indigo');
  ok('changing the colour changes the SKU', els.cwSku.value === 'RTC23-6090', els.cwSku.value);

  reset(); A.renderCutPick();
  pick('cwAt', 'Pillow Cover');
  ok('two SKUs with one description are not guessed between', els.cwSku.value === ''
     && /2 SKUs share this description/.test(els.cwSkuNote.textContent), els.cwSkuNote.textContent);

  reset();
  els.cwSku.value = 'RTC23-6060';
  (els.cwSku._listeners.input || []).forEach(fn => fn({}));
  ok('a typed SKU fills the four boxes back', els.cwAt.value === 'Tablecloth' && els.cwSub.value === 'Square Tablecloth'
     && els.cwCol.value === 'Indigo' && els.cwSz.value === '60x60',
     JSON.stringify([els.cwAt.value, els.cwSub.value, els.cwCol.value, els.cwSz.value]));
  ok('…and stays what was typed', els.cwSku.value === 'RTC23-6060');

  reset(); A.setPTG(wasPTG);
}

console.log('\n== a colour count on a rate is a range ==');
{
  /* Ravi uploaded "1 to 4" and "5 or more" and the list showed 1 and 5: parseInt takes the first
   * number it sees and throws the rest away. That is not a misprint in his file — it is how the rate
   * is agreed: one price up to four colours, another once there are five. */
  const spec = v => { const s = A.prColSpec(v); return s ? s.from + '..' + (s.to === Infinity ? 'up' : s.to) : 'none'; };

  ok('"1 to 4" is one to four', spec('1 to 4') === '1..4', spec('1 to 4'));
  ok('…however it is written', spec('1-4') === '1..4' && spec('1 \u2013 4') === '1..4' && spec('1 4') === '1..4');
  ok('"5 or more" is five and upwards', spec('5 or more') === '5..up', spec('5 or more'));
  ok('…and so are "5+", "5 and above", "5 up"',
     spec('5+') === '5..up' && spec('5 and above') === '5..up' && spec('5 up') === '5..up',
     [spec('5+'), spec('5 and above'), spec('5 up')].join(' '));
  ok('a single number is itself', spec('3') === '3..3');
  ok('blank is any number at all', spec('') === 'none' && spec(null) === 'none');
  /* AND SOMETHING THAT IS NOT A COLOUR COUNT IS NOT SILENTLY ROUNDED to the first digit in it. */
  ok('words nobody can read are refused, not guessed', spec('a few') === 'none' && spec('4 to 1') === 'none',
     spec('a few') + ' ' + spec('4 to 1'));

  /* THE LIST SHOWS THE RANGE THE WAY IT WAS MEANT. */
  ok('the range is shown as a range', A.prCols({ colours: '1 to 4' }) === '1-4'
     && A.prCols({ colours: '5 or more' }) === '5+' && A.prCols({ colours: '3' }) === '3',
     [A.prCols({ colours: '1 to 4' }), A.prCols({ colours: '5 or more' }), A.prCols({ colours: '3' })].join(' '));

  /* WHICH RANGE ANSWERS A DESIGN. */
  ok('four colours fall inside 1-4', A.prColCovers({ colours: '1-4' }, 4));
  ok('…five do not', !A.prColCovers({ colours: '1-4' }, 5));
  ok('…and five fall inside 5+', A.prColCovers({ colours: '5+' }, 5) && A.prColCovers({ colours: '5+' }, 12));
  ok('a rate with no range covers anything', A.prColCovers({ colours: '' }, 9));

  const wasHR = A.HR();
  const rate = (colours, rs) => ({ vendor: 'VND004', service: 'Block print', kind: 'cut',
    articleType: 'Tablecloth', subtype: 'Square Tablecloth', size: '60x60',
    colours, rate: rs, ok: true, okBy: 'ravi@x', okAt: '2026-09-01T00:00:00.000Z' });
  const order = { id: 'o1', vendorCode: 'VND004', orderType: 'cut', service: 'Block print', lines: [] };
  const line = c => ({ lineId: 'l1', sku: 'TC-60', kind: 'cut', qty: 10, articleType: 'Tablecloth',
    articleSubtype: 'Square Tablecloth', size: '60x60', colours: c });

  /* RAVI'S OWN TWO ROWS: 1 to 4 at 125, 5 or more at 125 for this size — priced by the range. */
  A.setHR(Object.assign({}, wasHR, { prate: [rate('1 to 4', 125), rate('5 or more', 180)] }));
  ok('a two-colour design takes the 1-4 rate', A.prRateFor('VND004', order, line(2)) === 125,
     String(A.prRateFor('VND004', order, line(2))));
  ok('…a four-colour one as well', A.prRateFor('VND004', order, line(4)) === 125);
  ok('…and a five-colour one crosses to the other rate',
     A.prRateFor('VND004', order, line(5)) === 180, String(A.prRateFor('VND004', order, line(5))));
  ok('…as does a nine-colour one', A.prRateFor('VND004', order, line(9)) === 180);

  /* THE NARROWEST RANGE WINS: somebody who wrote an exact rule meant it. */
  A.setHR(Object.assign({}, A.HR(), { prate: [rate('1-4', 125), rate('3', 150)] }));
  ok('an exact three beats the range that contains it',
     A.prRateFor('VND004', order, line(3)) === 150, String(A.prRateFor('VND004', order, line(3))));
  ok('…while two still takes the range', A.prRateFor('VND004', order, line(2)) === 125);

  /* AND A LINE THAT SAYS NOTHING TAKES THE RATE THAT NAMES NO RANGE — never a range by accident. */
  A.setHR(Object.assign({}, A.HR(), { prate: [rate('1-4', 125), rate('', 99)] }));
  ok('a line with no colour count takes the rate with no range',
     A.prRateFor('VND004', order, line(undefined)) === 99, String(A.prRateFor('VND004', order, line(undefined))));

  /* TWO RANGES THAT BOTH ANSWER THE SAME DESIGN ARE A CLASH. */
  ok('1-4 and 3-6 overlap', A.prColOverlap({ colours: '1-4' }, { colours: '3-6' }));
  ok('…1-4 and 5+ do not', !A.prColOverlap({ colours: '1-4' }, { colours: '5+' }));
  A.setHR(Object.assign({}, A.HR(), { prate: [rate('1-4', 125)] }));
  ok('a rate whose range overlaps one already there is refused',
     /already has/.test(A.prCheck({ vendor: 'VND004', service: 'Block print', kind: 'cut',
       at: 'Tablecloth', sub: 'Square Tablecloth', size: '60x60', colours: '3-6', rate: '140' })),
     A.prCheck({ vendor: 'VND004', service: 'Block print', kind: 'cut', at: 'Tablecloth',
       sub: 'Square Tablecloth', size: '60x60', colours: '3-6', rate: '140' }));
  ok('…and one that does not overlap is allowed',
     A.prCheck({ vendor: 'VND004', service: 'Block print', kind: 'cut', at: 'Tablecloth',
       sub: 'Square Tablecloth', size: '60x60', colours: '5+', rate: '180' }) === '');
  /* A COUNT WRITTEN WRONG IS STILL REFUSED. It has a digit in it, so somebody was writing a number,
   * and reading "3 colors" as anything other than an error is how a four-colour tablecloth gets a
   * one-colour price. */
  ok('a colour count nobody can read is refused by name',
     /is not a number of colours/.test(A.prCheck({ vendor: 'VND004', service: 'Block print', kind: 'cut',
       at: 'Tablecloth', sub: 'Square Tablecloth', size: '70x70', colours: '3 colors', rate: '140' })));
  /* A NAME WITH NO DIGITS IS NOT A COUNT AT ALL, and is now allowed — it is how two rates for the
   * same cloth are told apart. */
  ok('…but a name with no digits in it is a label, and passes',
     A.prCheck({ vendor: 'VND004', service: 'Block print', kind: 'cut',
       at: 'Tablecloth', sub: 'Square Tablecloth', size: '70x70', colours: 'Gadd', rate: '140' }) === '');

  /* THE FILE HE ACTUALLY UPLOADED. */
  A.setHR(Object.assign({}, A.HR(), { prate: [] }));
  const up = A.prFromRows([A.PR_COLS,
    ['A R Textile Printer', 'Block print', '', '', 'Tablecloth', 'Square Tablecloth', '60x60', '1 to 4', '', '', '125', ''],
    ['A R Textile Printer', 'Block print', '', '', 'Tablecloth', 'Square Tablecloth', '60x60', '5 or more', '', '', '125', '']]);
  ok('his own file reads as two ranges', (up.rows || []).length === 2
     && A.prRec(up.rows[0]).colours === '1-4' && A.prRec(up.rows[1]).colours === '5+',
     JSON.stringify(up.err || (up.rows || []).map(r => A.prRec(r).colours)));
  /* The plan is run on rows whose vendor the master knows — the name in his file is a real printer,
   * but the vendor master this suite reads is the live one and the point here is the ranges. */
  const mine = up.rows.map(r => Object.assign({}, r, { vendor: 'VND004' }));
  ok('…and they are not a clash, because they do not overlap',
     A.prPlan(mine).errs.length === 0, JSON.stringify(A.prPlan(mine).errs));

  A.setHR(wasHR);
}

console.log('\n== a printing rate is priced by how many colours are in it ==');
{
  /* "printing rate color wise set hoti h meri — 60x60 2 color 60 rs, 60x60 3 color 70 rs."
   *
   * Each colour is another block and another pass. The rate list had no way to say it, so those two
   * were the same row and one of them was always wrong. */
  const wasHR = A.HR(), wasVO = A.VO(), wasPTG = A.PTG();
  const rate = (colours, rs) => ({ vendor: 'VND002', service: 'Block print', kind: 'cut',
    articleType: 'Tablecloth', subtype: 'Square Tablecloth', size: '60X60',
    colours: colours, rate: rs, ok: true, okBy: 'ravi@x', okAt: '2026-09-01T00:00:00.000Z' });

  ok('printing is priced by colours; filling is not',
     A.prIsPrinting('Block print') && A.prIsPrinting('Screen print') && !A.prIsPrinting('Filling'));
  ok('a blank colour count means "any number"', A.prCols({ colours: '' }) === ''
     && A.prCols({ colours: 0 }) === '' && A.prCols({ colours: '3' }) === '3');

  /* TWO RATES THAT USED TO BE ONE ROW. */
  ok('two colours and three colours are different rates',
     A.prKey(rate('2', 60)) !== A.prKey(rate('3', 70)),
     A.prKey(rate('2', 60)) + '  vs  ' + A.prKey(rate('3', 70)));

  A.setHR(Object.assign({}, wasHR, { prate: [rate('2', 60), rate('3', 70)] }));
  const order = { id: 'o1', vendorCode: 'VND002', orderType: 'cut', service: 'Block print',
    lines: [{ lineId: 'l1', sku: 'TC-60', kind: 'cut', qty: 10, articleType: 'Tablecloth',
      articleSubtype: 'Square Tablecloth', size: '60X60' }] };
  const line = c => Object.assign({}, order.lines[0], c == null ? {} : { colours: c });

  ok('a two-colour design is priced at the two-colour rate',
     A.prRateFor('VND002', order, line(2)) === 60, String(A.prRateFor('VND002', order, line(2))));
  ok('…and a three-colour one at the three-colour rate',
     A.prRateFor('VND002', order, line(3)) === 70, String(A.prRateFor('VND002', order, line(3))));
  ok('a colour count nobody has priced is not guessed at',
     !A.prRateFor('VND002', order, line(5)), String(A.prRateFor('VND002', order, line(5))));

  /* THE TWENTY-ONE RATES ALREADY ON THE LIST CARRY NO COLOUR COUNT. Adding colours to the key would
   * have stopped every one of them matching, silently, on live orders — so a rate with no colour
   * count still answers for any number. */
  A.setHR(Object.assign({}, A.HR(), { prate: [rate('', 55)] }));
  ok('an old rate with no colour count still prices a line',
     A.prRateFor('VND002', order, line(3)) === 55, String(A.prRateFor('VND002', order, line(3))));
  ok('…and a line that says nothing about colours too',
     A.prRateFor('VND002', order, line(null)) === 55);

  /* AND A COLOUR-WISE RATE WINS OVER THE CATCH-ALL, which is how the list tightens as it is filled in. */
  A.setHR(Object.assign({}, A.HR(), { prate: [rate('', 55), rate('3', 70)] }));
  ok('a colour-wise rate beats the catch-all', A.prRateFor('VND002', order, line(3)) === 70,
     String(A.prRateFor('VND002', order, line(3))));
  ok('…while a colour nobody priced falls back to it', A.prRateFor('VND002', order, line(4)) === 55,
     String(A.prRateFor('VND202', order, line(4))));

  /* THE FILE CARRIES IT. The list is emptied first: an upload is checked against what is already
   * on the list, and the rates put there a moment ago would make the file look like a duplicate. */
  A.setHR(Object.assign({}, A.HR(), { prate: [] }));
  const up = A.prFromRows([A.PR_COLS,
    ['Choudhary Hand Block', 'Block print', '', '', 'Tablecloth', 'Square Tablecloth', '60X60', '2', '', '', '60', ''],
    ['Choudhary Hand Block', 'Block print', '', '', 'Tablecloth', 'Square Tablecloth', '60X60', '3', '', '', '70', '']]);
  ok('the upload reads a colours column', (up.rows || []).length === 2
     && up.rows[0].colours === '2' && up.rows[1].colours === '3',
     JSON.stringify(up.err || (up.rows || []).map(r => r.colours)));
  const plan = A.prPlan(up.rows);
  ok('…and two colour counts of the same size are not a duplicate',
     plan.errs.length === 0, JSON.stringify(plan.errs));

  /* A filling rate has no colours in it, whatever the file says. */
  const fill = A.prRec({ vendor: 'VND007', service: 'Filling', at: 'Quilt', sub: 'Twin Quilt',
    size: '60x90', filler: 'Cotton', weight: '1', colours: '3', rate: '450' });
  ok('a filling rate does not carry a colour count', fill.colours === '', JSON.stringify(fill.colours));

  A.setHR(wasHR); A.setVO(wasVO); A.setPTG(wasPTG);
}

console.log('\n== a Shopify order is worked by a karigar who gets paid for it ==');
{
  /* "base data ke jese kis karigar ko issue kar rahe h wo karo, becuase unka payment jab banega to
   * pcs count honge jinse unki salary banti h."
   *
   * The screen used to keep its own four figures and said so: "Shopify work is kept out of Base Data
   * by choice, so none of this reaches the cutting cap, the weekly report or piece-rate pay." A
   * tailor who sews a Shopify order is paid by the piece like any other, so that had to change. */
  const wasBase = A.PT().base, wasCut = A.PT().cut, wasOb = A.PTG().ob, wasPress = A.PTG().press,
    wasEmp = A.PTE().emp, wasNet = NET.on, wasEdit = ME.prodEdit, wasAdmin = ME.admin;
  ME.admin = true; ME.prodEdit = true; NET.on = true; NET.store = {};
  A.setPTE(Object.assign(A.PTE(), { emp: [['Company Contractor', 'Ramesh Kumar', 'Stitching', '']] }));
  A.setPT(Object.assign(A.PT(), { base: [], cut: [] }));
  A.setPTG(Object.assign(A.PTG(), { press: [], ob: [
    { id: 'ob1', orderNo: 'SHP-9501', sku: 'KAR-A', qty: 10, src: 'SHP', orderDate: '2026-09-12',
      shopOrderNo: '#9501', articleType: 'Pillow Cover', articleSubtype: 'Ruffle Pillow Cover',
      color: 'Sea Green', size: '18x18' }] }));

  /* NOTHING CAN BE ISSUED THAT HAS NOT BEEN CUT — the same cap as any other order. */
  const early = await A.spIssueReal('SHP-9501', 'KAR-A', 'Company Contractor', 'Ramesh Kumar', 5, '2026-09-12');
  ok('a line nobody has cut cannot be issued', /cut piece/.test(early), early);

  ok('cutting is recorded', (await A.spCutReal('SHP-9501', 'KAR-A', 20, '2026-09-12', 'CAMBRIC', '')) === '');
  ok('…in the cutting register itself, not a counter',
     Object.keys(NET.store).some(k => /^pt_cuttingData\//.test(k)), Object.keys(NET.store).join(', '));

  /* THE ISSUE NAMES THE KARIGAR, and lands in Base Data where pay is counted. */
  ok('an issue with no karigar is refused',
     /Which karigar/.test(await A.spIssueReal('SHP-9501', 'KAR-A', 'Company Contractor', '', 5, '2026-09-12')));
  ok('…and somebody not on that list is refused by name',
     /not on the Company Contractor list/.test(
       await A.spIssueReal('SHP-9501', 'KAR-A', 'Company Contractor', 'Nobody At All', 5, '2026-09-12')));
  ok('issuing to a karigar works',
     (await A.spIssueReal('SHP-9501', 'KAR-A', 'Company Contractor', 'Ramesh Kumar', 12, '2026-09-12')) === '');

  const bdKey = Object.keys(NET.store).find(k => /^pt_baseData\//.test(k));
  ok('…as a real Base Data row', !!bdKey, Object.keys(NET.store).join(', '));
  const row = NET.store[bdKey];
  ok('…naming who has the pieces', row.empName === 'Ramesh Kumar' && row.empType === 'Company Contractor',
     JSON.stringify({ n: row.empName, t: row.empType }));
  ok('…against the Shopify order, with the article on it',
     row.orderNo === 'SHP-9501' && row.sku === 'KAR-A' && row.articleSubtype === 'Ruffle Pillow Cover');
  /* THIS IS THE WHOLE POINT: payroll reads Base Data, so the pieces are now countable. */
  ok('…and the pieces are the ones pay is worked out from',
     row.issuePieces === 12 && row.pendingPieces === 12 && row.receivedPieces === 0);

  /* THE ORDER'S OWN CAP STILL HOLDS. */
  const over = await A.spIssueReal('SHP-9501', 'KAR-A', 'Company Contractor', 'Ramesh Kumar', 15, '2026-09-12');
  ok('more than the order asked for is refused', /at most 8 more allowed/.test(over), over);

  /* RECEIVING CLOSES THE OLDEST ISSUE FIRST. */
  ok('nothing can come back that is not out',
     /Only 12 piece/.test(await A.spReceiveReal('SHP-9501', 'KAR-A', 15, '2026-09-13')));
  ok('pieces come back', (await A.spReceiveReal('SHP-9501', 'KAR-A', 9, '2026-09-13')) === '');
  ok('…and the row says so', A.spRecvReal('SHP-9501', 'KAR-A') === 9
     && A.spIssuedReal('SHP-9501', 'KAR-A') === 12, JSON.stringify({
       issued: A.spIssuedReal('SHP-9501', 'KAR-A'), back: A.spRecvReal('SHP-9501', 'KAR-A') }));
  ok('…leaving three still with him',
     A.spBaseRows('SHP-9501', 'KAR-A').reduce((a, r) => a + A.ptNum(r.pendingPieces), 0) === 3);

  /* PRESSING, in the press register. */
  ok('pressing is recorded', (await A.spPressReal('SHP-9501', 'KAR-A', 9, '2026-09-14', '')) === '');
  ok('…in the press inventory', Object.keys(NET.store).some(k => /^pt_pressInventory\//.test(k)));

  /* And every one of them is an entry, so it needs the right to make one. */
  ME.prodEdit = false; ME.admin = false;
  ok('somebody without permission cannot issue Shopify work either',
     /permission/i.test(await A.spIssueReal('SHP-9501', 'KAR-A', 'Company Contractor', 'Ramesh Kumar', 1, '2026-09-12')));

  A.setPT(Object.assign(A.PT(), { base: wasBase, cut: wasCut }));
  A.setPTG(Object.assign(A.PTG(), { ob: wasOb, press: wasPress }));
  A.setPTE(Object.assign(A.PTE(), { emp: wasEmp }));
  NET.on = wasNet; ME.prodEdit = wasEdit; ME.admin = wasAdmin;
}

console.log('\n== production analysis: where the week went ==');
{
  /* "mujhe mera production 20000 per week par lekr jana h ... meri kami kaha h." And then: "target ke
   * base par karigars ki kam ya jyada ka anuman mat lagao — company contractor ka per day ka ave dekho
   * ki 1 karigar 1 din me kitne pcs bana sakta h, then karigar kam ya jyada decide karo." A made-up week
   * whose answers are known, so every figure on the screen can be checked by hand. */
  const wasPT = A.PT(), wasPTG = A.PTG(), wasPTE = A.PTE(), wasHR = A.HR(), wasATT = A.ATT(), wasPA = A.PA();
  const wasNet = NET.on, wasEdit = ME.prodEdit, wasAdmin = ME.admin;
  const d = (day, h) => `${String(day).padStart(2, '0')}/09/2026, ${String(h || 10).padStart(2, '0')}:00`;
  const row = (name, issueDay, pcs, recvDay, extra) => Object.assign({ id: 'bd_' + name + issueDay + pcs, empName: name, empType: 'Company Contractor',
    articleType: 'Tablecloth', articleSubtype: 'Square Tablecloth', size: '60x60', sku: 'RTC1-6060', orderNo: 'AMZ-1',
    issueDate: d(issueDay, 9), issuePieces: pcs, receivedPieces: recvDay ? pcs : 0, pendingPieces: recvDay ? 0 : pcs,
    rejectionPieces: 0, receivingDate: recvDay ? d(recvDay, 17) : '', frozen: !!recvDay }, extra || {});
  /* Mon 7 – Sun 13 Sep. Asha works every day. Bina is given work on Monday, it comes back Tuesday, and
   * she has nothing after. Chetan is a team of three, working every day. Pradeep Contractor is an
   * external team of 20, 25 from the 14th. Dev worked the week before and not this one; Esha sits on
   * last week's work; Farid is on the list and has never worked; Gopal is salaried. */
  A.setPT(Object.assign({}, wasPT, { base: [
    row('Asha', 7, 100, 7), row('Asha', 8, 100, 8), row('Asha', 9, 100, 9), row('Asha', 10, 100, 10), row('Asha', 11, 100, 11), row('Asha', 12, 100, 12),
    row('Bina', 7, 60, 8),
    row('Chetan', 7, 150, 8), row('Chetan', 9, 150, 10), row('Chetan', 11, 150, 12, { rejectionPieces: 6 }),
    row('Pradeep Contractor', 7, 1200, 12, { empType: 'External Contractor' }),
    row('Old', 1, 999, 2),                                  // the week before: not this week's
    row('Esha', 3, 40, 0),                                  // out since last week, nothing back
    row('Dev', 1, 20, 2),                                   // worked the week before, nothing this week
  ], cut: [{ id: 'c1', cutDate: d(7, 8), pieces: 500 }, { id: 'c2', cutDate: d(9, 8), pieces: 400 }] }));
  A.setPTG(Object.assign({}, wasPTG, { press: [], mdb: wasPTG.mdb || [] }));
  A.setPTE(Object.assign({}, wasPTE, { emp: [
    ['Company Contractor', 'Asha', 'Stitching', ''], ['Company Contractor', 'Bina', 'Stitching', ''],
    ['Company Contractor', 'Chetan', 'Stitching', ''], ['Company Contractor', 'Dev', 'Stitching', ''], ['Company Contractor', 'Esha', 'Stitching', ''],
    ['Company Contractor', 'Farid', 'Stitching', ''],       // on the list, never any work
    ['External Contractor', 'Pradeep Contractor', 'Stitching', ''],
    ['Company Role', 'Gopal', 'Stitching', ''],             // salaried: nothing of theirs is in the register
    ['Company Role', 'Cutter Ram', 'Cutting', ''], ['Company Role', 'Dev', 'Pressman', ''],   // Dev is on the list twice
  ] }));
  A.setHR(Object.assign({}, wasHR, { rate: [['Tablecloth', 'Square Tablecloth', '60x60', 'Company Contractor', 20, '']] }));
  A.setATT(Object.assign({}, wasATT, { rows: [
    { day: '2026-09-09', empName: 'Bina', dept: 'Stitching', status: 'P' },
    { day: '2026-09-09', empName: 'Dev', dept: 'Stitching', status: 'A' },
  ] }));
  A.setPA(Object.assign({}, wasPA, { team: {
    chetan: { name: 'Chetan', sizes: [{ n: 3, from: '2026-01-01' }] },
    'pradeep contractor': { name: 'Pradeep Contractor', sizes: [{ n: 20, from: '2026-01-01' }, { n: 25, from: '2026-09-14' }] },
  } }));

  const f = A.paWeekFacts('2026-09-07', new Date(2026, 8, 20).getTime());
  ok('made is what came back in the week', f.received === 2310, String(f.received));
  ok('…issued and cut likewise', f.issued === 2310 && f.cut === 900, JSON.stringify([f.issued, f.cut]));
  ok('…and last week\'s work is not in it', !f.people.some(p => p.name === 'Old' && p.received));
  ok('the working days are the days anything was entered', f.workDays === 6, String(f.workDays));
  ok('karigars are the piece-rate stitching list — not the cutter, not the salaried', f.karigars === 7 && f.salaried.length === 1 && f.salaried[0].name === 'Gopal', JSON.stringify([f.karigars, f.salaried.map(p => p.name)]));
  ok('a contractor with no work for a month is not "given no work" — the list needs checking', f.dormant.length === 1 && f.dormant[0].name === 'Farid');
  ok('Esha sat on last week\'s work — that is not the same as getting none', f.stuck.length === 1 && f.stuck[0].name === 'Esha' && f.stuck[0].held === 40);
  ok('Dev got nothing this week', f.idle.length === 1 && f.idle[0].name === 'Dev', JSON.stringify(f.idle.map(p => p.name)));
  ok('empty-handed days are counted per karigar', f.emptyDays === 4 && f.emptyBy[0][0] === 'Bina' && f.emptyBy[0][1] === 4, JSON.stringify(f.emptyBy));
  ok('…including the one Bina was marked present', f.presentEmpty === 1, String(f.presentEmpty));
  ok('the labour value is pieces at the rate list — the external team has no rate', f.value === 1110 * 20 && f.noRate === 1200, JSON.stringify([f.value, f.noRate]));
  ok('rejection is counted', f.rejected === 6);

  /* DAYS WITH WORK AND PEOPLE. */
  const P = n => f.people.find(w => w.name === n);
  ok('a karigar-day is a working day with work in hand: Asha 6, Bina 2', P('Asha').days === 6 && P('Bina').days === 2, JSON.stringify([P('Asha').days, P('Bina').days]));
  ok('a team counts every person: Chetan is 3 people × 6 days', P('Chetan').people === 3 && P('Chetan').personDays === 18);
  ok('the external team is 20 people this week, not the 25 from next week', P('Pradeep Contractor').people === 20);

  /* THE AVERAGE: company contractors only. 1,110 pieces ÷ (6 + 2 + 18) karigar-days. */
  ok('company contractors made 1,110 over 26 karigar-days, as 5 people', f.ccPcs === 1110 && f.ccPersonDays === 26 && f.ccPeople === 5,
     JSON.stringify([f.ccPcs, f.ccPersonDays, f.ccPeople]));
  ok('…and the external team is kept out of it', f.ext.length === 1 && f.ext[0].name === 'Pradeep Contractor');
  const base = A.paAvgBase(f, 'week');
  ok('one karigar makes 1,110 ÷ 26 pieces a day', Math.abs(base.avg - 1110 / 26) < 1e-9, String(base.avg));
  ok('…and the external team 1,200 ÷ (20 × 6) = 10 per person per day', base.extPer.get('pradeep contractor') === 10);
  const base4 = A.paAvgBase(f, '4w');
  /* The week before: Old 999 over 2 days, Dev 20 over 2 days, Esha 0 over 1 day. */
  ok('the four-week average pools the pieces and the karigar-days', base4.weeks === 2 && Math.abs(base4.avg - (1110 + 1019) / (26 + 5)) < 1e-9,
     JSON.stringify([base4.weeks, base4.pcs, base4.personDays]));

  /* THE NEED, from the average and nothing else. */
  const need = A.paNeed(f, 20000, base);
  ok('the external team is counted at next week\'s size: 25 × 10 × 6 = 1,500', need.extOut === 1500 && need.ext[0].peopleNext === 25, JSON.stringify(need.ext));
  ok('20,000 − 1,500 = 18,500 from company contractors', need.fromCC === 18500);
  ok('at 1,110 ÷ 26 × 6 a week each, that is 73 karigars', need.need === Math.ceil(18500 / (1110 / 26 * 6)) && need.need === 73, String(need.need));
  ok('5 worked, so 68 more are needed', need.have === 5 && need.diff === 68);
  ok('…or each of the 5 would need 616.7 a day', Math.abs(need.perDayToHit - 18500 / 30) < 1e-9);
  const v20 = A.paVerdict(f, need, 20000);
  ok('the verdict is the karigar count', v20.key === 'hire' && /68 more karigar\(s\) needed/.test(v20.head) && /73 of them working; 5 worked/.test(v20.why), JSON.stringify(v20));
  const v2000 = A.paVerdict(f, A.paNeed(f, 2000, base), 2000);
  ok('a target already made says by how much', v2000.key === 'reached' && /310 above target/.test(v2000.head), JSON.stringify(v2000));
  const n2500 = A.paNeed(f, 2500, base), v2500 = A.paVerdict(f, n2500, 2500);
  ok('enough karigars for 2,500 at their average — the short week is pieces a day, not heads', n2500.need === 4 && v2500.key === 'output', JSON.stringify([n2500.need, v2500]));

  /* TEAM SIZES ARE SAVED, AND APPLY FROM THEIR DATE. */
  ME.admin = true; ME.prodEdit = true; NET.on = true; NET.store = {};
  ok('a team size must be a whole number of people', /whole number/.test(await A.paTeamSave('Manish Khuswaha', '0', '2026-01-01')));
  ok('Manish Khuswaha is saved as two karigars', (await A.paTeamSave('Manish Khuswaha', '2', '2026-01-01')) === ''
     && NET.store['pt_teamSize/manish khuswaha'].sizes[0].n === 2, JSON.stringify(NET.store));
  ok('…and counts as two from then on', A.paTeamSize('manish khuswaha', new Date(2026, 8, 10).getTime()) === 2);
  ok('a team that grows keeps its old size for the weeks before', A.paTeamSize('pradeep contractor', new Date(2026, 8, 13).getTime()) === 20
     && A.paTeamSize('pradeep contractor', new Date(2026, 8, 14).getTime()) === 25);
  ok('a name with no record is one person', A.paTeamSize('asha', Date.now()) === 1);
  NET.on = wasNet; ME.prodEdit = wasEdit; ME.admin = wasAdmin;

  /* THE SCREEN. */
  els.paWk.value = '2026-09-07'; els.paTarget.value = '20000'; els.paBasis.value = 'week';
  A.renderPa();
  const h = els.paBody.innerHTML;
  ok('the screen says what was made against the target', /<b>2,310<\/b><span>of 20,000 pieces made/.test(h) && /17,690 short/.test(h), h.slice(0, 300));
  ok('…and the karigar count in one sentence', /68 more karigar\(s\) needed/.test(h));
  ok('…shows the sum: pieces per karigar per day, from pieces and karigar-days', /<b>42\.7<\/b> pieces per karigar per day \(1,110 pcs ÷ 26 karigar-days\)/.test(h), String(h.match(/pa-fx-note">[^]*?<\/div>/)));
  /* TREND FIRST (Ravi, 2026-09-24): the screen opens on the weeks against the target. */
  ok('the screen opens on the weeks against the target', h.indexOf('pa-top') >= 0 && h.indexOf('pa-top') < h.indexOf('How many karigars')
     && /Weeks against 20,000/.test(h) && /class="pa-need" style="bottom:/.test(h), h.slice(0, 200));
  ok('…one bar a week, the chosen week marked', (h.match(/class="pa-wkb/g) || []).length >= 2 && /class="pa-wkb is-on/.test(h));
  ok('…beside it the best week of those shown, as a share of the target', /best week of these \d+|this week is the best of these \d+/.test(h) && /% of the target/.test(h));
  ok('…and the usual week: the average of the full weeks before it, or nothing when there are none',
     /average of the last \d full week/.test(h) || !/<em>[^<]*·/.test(h));
  ok('the flow and the four small figures are still on the page', /pa-strip/.test(h) && /Cut<\/span>/.test(h) && /Pressed<\/span>/.test(h) && /company contractors worked/.test(h));
  ok('…and nothing below the top was lost', /Every karigar, per person per day/.test(h) && /Who made the week/.test(h) && /Look into/.test(h) && /Week on week/.test(h));
  ok('…the external team at its own pace', /Pradeep Contractor: 25 people × 10\.0 × 6/.test(h));
  ok('…and the karigars needed', /<b>73<\/b><span>karigars needed/.test(h) && /\+68/.test(h));
  ok('every karigar is listed per person per day, with a way to set a team', /data-team="chetan"[^>]*>3 people</.test(h) && /<b class="pa-dn">25\.0<\/b>/.test(h) && /<b class="pa-up">100\.0<\/b>/.test(h),
     String(h.match(/data-team="chetan"[^]*?<\/tr>/)));
  ok('…with the external team listed apart from the average', /External teams — not in the average above/.test(h));
  ok('the salaried stitchers are named as not in the figures', /1 salaried stitcher\(s\) are not in these figures/.test(h) && /Gopal/.test(h));
  ok('…and the dormant contractor is named', /have not worked for a month/.test(h) && /Farid/.test(h));
  ok('…and the idle one with their other role', /got no work this week/.test(h) && /Dev \(also Pressman\)/.test(h));
  ok('nothing is worked out from a median any more', !/median/i.test(h), String(h.match(/.{60}median.{60}/i)));

  /* KARIGAR ANALYSIS. */
  const t = A.kaTable('recv', 'karigar', 4, '', '');
  const asha = t.rows.find(r => r.name === 'Asha');
  ok('a row per karigar on the list, even one with nothing — and anybody else given job work', t.rows.length === 8 && !t.rows.some(r => r.name === 'Gopal') && t.rows.some(r => r.name === 'Old' && /not on the list/.test(r.dept)) && t.rows.some(r => r.name === 'Farid' && r.total === 0),
     JSON.stringify(t.rows.map(r => r.name)));
  ok('…a column per week', t.weeks.includes('2026-09-07') && asha.values[t.weeks.indexOf('2026-09-07')] === 600);
  const perDay = A.kaTable('perDay', 'karigar', 4, '', '').rows.find(r => r.name === 'Chetan');
  ok('pieces per person per day counts the team', perDay.total === 25, String(perDay.total));
  ok('the article study adds up to the week', A.kaTable('recv', 'article', 4, '', '').rows.find(r => r.name === 'Tablecloth').values[t.weeks.indexOf('2026-09-07')] === 2310);

  /* ---- DAY BY DAY, AND THE MONTHLY TARGET (2026-09-22) ---- */
  {
    const rng = A.kaMonthRange('2026-09');
    ok('September has 30 days, from the 1st', rng.days.length === 30 && new Date(rng.days[0]).getDate() === 1 && new Date(rng.days[29]).getDate() === 30);
    const dd = A.kaDaily('2026-09', '', '');
    const ashaD = dd.rows.find(r => r.name === 'Asha');
    /* Worked out again from the register, by hand: every piece Asha returned in September. */
    const byHand = (A.PT().base || []).filter(r => r && /^asha$/i.test(String(r.empName).trim()) && r.receivingDate)
      .map(r => ({ ms: A.ptDtMs(r.receivingDate), n: A.ptNum(r.receivedPieces) })).filter(x => x.ms >= rng.from && x.ms < rng.to && x.n > 0);
    ok('a karigar\'s month adds up to what the register says they returned',
      ashaD && ashaD.cells.reduce((a, c) => a + c.received, 0) === byHand.reduce((a, x) => a + x.n, 0),
      JSON.stringify([ashaD && ashaD.cells.reduce((a, c) => a + c.received, 0), byHand.reduce((a, x) => a + x.n, 0)]));
    if (byHand.length) {
      const d0 = byHand[0], i = rng.days.findIndex((ms, j) => d0.ms >= ms && (j === rng.days.length - 1 || d0.ms < rng.days[j + 1]));
      ok('…and each piece lands on the day it came back', ashaD.cells[i].received >= d0.n, JSON.stringify({ i, cell: ashaD.cells[i], d0 }));
    }
    ok('every piece-rate stitcher on the list has a row, even with no work', dd.rows.some(r => r.name === 'Farid'));
    ok('a salaried stitcher does not', !dd.rows.some(r => r.name === 'Gopal'));

    /* THE TARGET: ₹ a month per person; a team is that times its people; a name's own figure wins. */
    const K = A.KA(), wasT = K.targets;
    K.targets = { perPerson: 30000, by: {} };
    ok('one karigar is expected the per-person target', A.kaTargetOf('asha', rng.days[0]) === 30000);
    ok('a team is expected it times its people', A.kaTargetOf('pradeep contractor', rng.days[0]) === 30000 * A.paTeamSize('pradeep contractor', rng.days[0]),
      String(A.kaTargetOf('pradeep contractor', rng.days[0])));
    K.targets = { perPerson: 30000, by: { asha: 12000 } };
    ok('a name\'s own target wins over the per-person one', A.kaTargetOf('asha', rng.days[0]) === 12000);

    /* JUDGED ON THE PACE: by Saturday 12 Sept, 11 of September's 26 working days are gone. */
    const at12 = new Date(2026, 8, 12, 15, 0).getTime();
    const tr = A.kaTargetRows('2026-09', '', '', at12);
    ok('11 of 26 working days (Monday to Saturday) gone on the 12th', tr.gone === 11 && tr.total === 26, JSON.stringify([tr.gone, tr.total]));
    const a = tr.rows.find(r => r.name === 'Asha');
    ok('should be by today is the target × 11 ÷ 26', a && a.expected === Math.round(12000 * 11 / 26), JSON.stringify(a && a.expected));
    ok('…short by is what is missing from that, never below nothing', a && a.short === Math.max(0, a.expected - a.done));
    ok('the stage follows the pace', tr.rows.every(r => r.status === (!r.target ? 'none' : r.pace >= 1 ? 'ok' : r.pace >= 0.8 ? 'behind' : 'far')),
      JSON.stringify(tr.rows.map(r => [r.name, r.status, r.pace])));
    const rank = { far: 0, behind: 1, ok: 2, future: 3, none: 4 };
    ok('the furthest behind come first', tr.rows.every((r, i) => !i || rank[tr.rows[i - 1].status] <= rank[r.status]));
    /* 70% OF THE PACE IS FAR BEHIND, 90% IS BEHIND: a target set so Asha lands on each. */
    if (a && a.done > 0) {
      K.targets = { perPerson: 30000, by: { asha: Math.round(a.done / 0.7 * 26 / 11) } };
      const s70 = A.kaTargetRows('2026-09', '', '', at12).rows.find(r => r.name === 'Asha');
      K.targets = { perPerson: 30000, by: { asha: Math.round(a.done / 0.9 * 26 / 11) } };
      const s90 = A.kaTargetRows('2026-09', '', '', at12).rows.find(r => r.name === 'Asha');
      ok('70% of the pace is far behind, 90% is behind', s70.status === 'far' && s90.status === 'behind', JSON.stringify([s70.pace, s70.status, s90.pace, s90.status]));
      K.targets = { perPerson: 30000, by: { asha: 12000 } };
    } else ok('Asha has work in the fixture to set a pace against', false, 'no done');
    const f = A.kaTargetRows('2026-09', '', '', new Date(2026, 7, 20).getTime());
    ok('a month not started yet holds nobody behind', f.gone === 0 && f.rows.every(r => r.status === 'future' || r.status === 'none'));

    /* SAVED IN ONE RECORD, BY AN ADMIN. */
    const wasOn = NET.on, wasAd = ME.admin; NET.on = true; NET.calls.length = 0;
    ME.admin = false;
    ok('only an admin sets targets', /Only an admin/.test(await A.kaTargetsSave(30000, {})));
    ME.admin = true;
    ok('an amount that is not rupees is refused', /not an amount/.test(await A.kaTargetsSave(30000, { asha: 'lots' })));
    ok('the targets are saved in one record', (await A.kaTargetsSave('30000', { asha: '12000', farid: '' })) === ''
      && NET.calls.some(c => c.method === 'PUT' && /pt_kaTargets/.test(c.url) && c.body.perPerson === 30000 && c.body.by.asha === 12000 && !('farid' in c.body.by)),
      JSON.stringify(NET.calls.map(c => c.body)));

    /* THE SCREEN. */
    els.kaGroup.value = 'daily'; els.kaMetric.value = 'recv'; els.kaDept.value = ''; els.kaQ.value = '';
    els.kaMonth.innerHTML = ''; A.renderKa();
    els.kaMonth.value = '2026-09'; A.renderKa();
    ok('day by day draws a column per day', (A.KA().daily || {}).d && A.KA().daily.d.days.length === 30 && /ka-sun/.test(els.kaTable.innerHTML), els.kaMsg.textContent);
    els.kaGroup.value = 'target'; A.renderKa();
    ok('the target view draws every name with a target', /Month target/.test(els.kaTable.innerHTML) && /data-ka="asha"/.test(els.kaTable.innerHTML));
    ok('…and the set button is there for an admin', !els.kaTgtBtn.classList.contains('hide'));
    /* CUSTOM DATES, from the Karigar study's own period picker (2026-09-22: "still not seeing date range"). */
    const r8 = A.kaRange('2026-09-08', '2026-09-14');
    ok('a range includes both ends', r8 && r8.days.length === 7 && new Date(r8.days[6]).getDate() === 14);
    ok('…and a To before the From is no range', A.kaRange('2026-09-14', '2026-09-08') === null);
    els.kaGroup.value = 'karigar'; els.kaWeeks.value = 'custom'; els.kaD1.value = ''; els.kaD2.value = ''; A.renderKa();
    ok('picking Custom dates shows the two date boxes, filled with this month so far',
      !els.kaD1.classList.contains('hide') && !els.kaD2.classList.contains('hide') && /^\d{4}-\d{2}-01$/.test(els.kaD1.value) && els.kaD2.value === A.paDayIso(Date.now()),
      els.kaD1.value + ' ' + els.kaD2.value);
    els.kaD1.value = '2026-09-08'; els.kaD2.value = '2026-09-14'; A.renderKa();
    const cd = A.KA().daily;
    ok('…and the karigar study becomes a column per day of exactly that range', cd && cd.d.days.length === 7 && /2026-09-08_to_2026-09-14/.test(cd.d.ym),
      cd && String(cd.d.days.length));
    const ashaW = (cd.rows.find(r => r.name === 'Asha') || {}).total;
    const hand = (A.PT().base || []).filter(r => r && /^asha$/i.test(String(r.empName).trim()) && r.receivingDate)
      .map(r => ({ ms: A.ptDtMs(r.receivingDate), n: A.ptNum(r.receivedPieces) })).filter(x => x.ms >= r8.from && x.ms < r8.to && x.n > 0).reduce((a, x) => a + x.n, 0);
    ok('…adding up to what the register says for those days', ashaW === hand, JSON.stringify([ashaW, hand]));
    els.kaD1.value = '2026-01-01'; els.kaD2.value = '2026-09-14'; A.renderKa();
    ok('a range too long for day columns says so', /pick 93 or fewer/.test(els.kaMsg.textContent), els.kaMsg.textContent);
    els.kaD2.value = '2025-01-01'; A.renderKa();
    ok('…and so does a range that runs backwards', /on or after it/.test(els.kaMsg.textContent));
    els.kaGroup.value = 'target'; A.renderKa();
    ok('a target is a month, so the month list offers no custom dates there', !/value="custom"/.test(els.kaMonth.innerHTML) && els.kaD1.classList.contains('hide'));
    els.kaGroup.value = 'daily'; A.renderKa();
    ok('…but Day by day does', /value="custom"/.test(els.kaMonth.innerHTML));
    els.kaWeeks.value = '8';
    els.kaGroup.value = 'karigar'; A.renderKa();
    ok('…and back on the weeks, the month picker goes', els.kaMonth.classList.contains('hide') && !els.kaWeeks.classList.contains('hide'));
    K.targets = wasT; ME.admin = wasAd; NET.on = wasOn; NET.calls.length = 0;
  }

  els.kaMetric.value = 'recv'; els.kaGroup.value = 'karigar'; els.kaWeeks.value = '4'; els.kaDept.value = ''; els.kaQ.value = '';
  A.renderKa();
  ok('the table draws, with a People column', /ka-high/.test(els.kaTable.innerHTML) && /data-ka="asha"/.test(els.kaTable.innerHTML) && /data-team="chetan">3</.test(els.kaTable.innerHTML));
  const det = A.kaDetail('chetan', 4);
  ok('a karigar\'s detail: people, karigar-days, and per person per day', det.people === 3 && det.pd === 18 && det.made === 450, JSON.stringify([det.people, det.pd, det.made]));

  A.setPT(wasPT); A.setPTG(wasPTG); A.setPTE(wasPTE); A.setHR(wasHR); A.setATT(wasATT); A.setPA(wasPA);
}

/* AND ON THE REAL REGISTERS, when a fresh pull is on disk: the screen must agree with the numbers
 * worked out by hand — Mon 7 – Sun 13 Sep, Manish and Binod as two karigars each, Pradeep's team 20
 * this week and 25 from the 14th. */
{
  const dir = __dirname + '/pa/';
  if (fs.existsSync(dir + 'pt_baseData.json')) {
    const L = n => { const v = JSON.parse(fs.readFileSync(dir + n + '.json', 'utf8')); return Array.isArray(v) ? v.filter(Boolean) : Object.entries(v || {}).map(([k, x]) => Object.assign({ _key: k }, x)); };
    const wasPT = A.PT(), wasPTG = A.PTG(), wasPTE = A.PTE(), wasHR = A.HR(), wasATT = A.ATT(), wasPA = A.PA();
    A.setPT(Object.assign({}, wasPT, { base: L('pt_baseData'), cut: L('pt_cuttingData') }));
    A.setPTG(Object.assign({}, wasPTG, { press: L('pt_pressInventory'), mdb: L('pt_masterDB') }));
    A.setPTE(Object.assign({}, wasPTE, { emp: L('pt_empList') }));
    A.setHR(Object.assign({}, wasHR, { rate: L('pt_rateList') }));
    A.setATT(Object.assign({}, wasATT, { rows: L('pt_attend') }));
    A.setPA(Object.assign({}, wasPA, { team: {
      'manish khuswaha': { name: 'Manish Khuswaha', sizes: [{ n: 2, from: '2026-01-01' }] },
      'binod kumar': { name: 'Binod Kumar', sizes: [{ n: 2, from: '2026-01-01' }] },
      'pradeep contractor': { name: 'Pradeep Contractor', sizes: [{ n: 20, from: '2026-01-01' }, { n: 25, from: '2026-09-14' }] },
    } }));
    const live = A.paWeekFacts('2026-09-07', new Date(2026, 8, 13, 23, 59).getTime());
    ok('live: Mon 7 – Sun 13 Sep made 11,650 and cut 6,270 — the Cutting Data figure and Ravi\'s own count', live.received === 11650 && live.cut === 6270, JSON.stringify([live.received, live.cut]));
    ok('live: 40 piece-rate karigars, 10 salaried left out, 10 contractors with no work in a month', live.karigars === 40 && live.salaried.length === 10 && live.dormant.length === 10,
       JSON.stringify([live.karigars, live.salaried.length, live.dormant.length]));
    ok('live: company contractors made 7,956 over 159 karigar-days, as 30 people (Hanuman Prasad, who sat on his work, is left out)', live.ccPcs === 7956 && live.ccPersonDays === 159 && live.ccPeople === 30,
       JSON.stringify([live.ccPcs, live.ccPersonDays, live.ccPeople]));
    const lb = A.paAvgBase(live, 'week'), ln = A.paNeed(live, 20000, lb);
    ok('live: 50.0 pieces per karigar per day; Pradeep\'s team 30.5 per person per day', lb.avg.toFixed(1) === '50.0' && lb.extPer.get('pradeep contractor').toFixed(1) === '30.5',
       JSON.stringify([lb.avg, [...lb.extPer]]));
    ok('live: 20,000 needs 52 company contractors; 30 worked, so 22 more', ln.need === 52 && ln.diff === 22 && ln.extOut === 4576,
       JSON.stringify({ need: ln.need, diff: ln.diff, ext: ln.extOut, perWeek: ln.perWeek }));
    const l4 = A.paAvgBase(live, '4w');
    console.log('  info live 4-week average: ' + l4.avg.toFixed(1) + ' over ' + l4.weeks + ' week(s), need ' + A.paNeed(live, 20000, l4).need);
    if (process.env.PA_PREVIEW) { els.paWk.value = '2026-09-07'; els.paTarget.value = '20000'; els.paBasis.value = 'week'; A.renderPa(); els.kaMetric.value = 'perDay'; els.kaGroup.value = 'karigar'; els.kaWeeks.value = '4'; els.kaDept.value = ''; els.kaQ.value = ''; A.KA().pick = 'manish khuswaha'; A.renderKa(); const css = html.slice(html.indexOf('<style>') + 7, html.indexOf('</' + 'style>')); fs.writeFileSync(__dirname + '/pa/preview.html', '<!doctype html><meta charset=utf-8><style>' + css + '</style><body style="padding:20px"><div class=card style="padding:10px"><div class=muted>' + els.paMsg.textContent + '</div></div>' + els.paBody.innerHTML + '<h2>Karigar Analysis</h2><div class=muted>' + els.kaMsg.textContent + '</div><div class="card kpi" style="margin-top:12px;padding:12px 14px">' + els.kaDetail.innerHTML + '</div><div class="card xlwrap" style="margin-top:12px"><table class=xl id=kaTable>' + els.kaTable.innerHTML + '</table></div></body>'); }
    A.setPT(wasPT); A.setPTG(wasPTG); A.setPTE(wasPTE); A.setHR(wasHR); A.setATT(wasATT); A.setPA(wasPA);
  }
}

console.log('\n== B2B sales orders: the buyer\'s own columns, and new items on the Custom SKUs list ==');
{
  /* "jaha apan sales order open krte h baha apan B2B orders ke liye bhi build krna h" — Brand Name,
   * Image Link, SKU ("if not in masterdata base please create list auto in custom sku with brand name"),
   * Item Name, LABEL, Material, Size, Qty, Customization. */
  const wasNet = NET.on, wasAdmin = ME.admin;
  ME.admin = true; NET.on = true; NET.calls = []; NET.store = {};
  const known = A.obUC((A.PTG().mdb.find(r => r && /^[A-Z0-9][A-Z0-9-]*$/.test(A.obUC(r.sku)))).sku);
  A.soFormOpen(null);
  els.sof_channel.value = 'B2B'; els.sof_date.value = '2026-11-03'; els.sof_type.value = 'regular';
  els.sof_delivery.value = ''; els.sof_legacy.value = 'PO-4471';

  const sheet = [
    ['Brand Name', 'Image Link', 'SKU', 'Item Name', 'LABEL', 'Material', 'Size', 'Qty', 'Customization', 'Packaging'],
    ['Crate & Barrel', 'https://img.example/a.jpg', known, 'Known item', 'No', 'Cambric', '60x60', '40', 'No', ''],
    ['Crate & Barrel', 'https://img.example/b.jpg', 'NEWB2B-1', 'Border napkin', 'Yes - woven label', 'Linen', '20x20', '120', 'Yes - logo in corner', 'Polybag, 4 per pack'],
    ['Crate & Barrel', '', '', 'Round runner, no code yet', 'No', 'Cotton', '16x72', '30', 'No', ''],
    ['', '', '', '', '', '', '', '', '', ''],
  ];
  const got = A.soB2BRows(sheet);
  ok('the B2B sheet reads by column name', got.lines.length === 3 && got.errors.length === 0, JSON.stringify(got.errors));
  const nb = got.lines.find(l => l.sku === 'NEWB2B-1');
  ok('…keeping brand, picture, item, label, material, size and customization', nb && nb.brand === 'Crate & Barrel' && nb.img === 'https://img.example/b.jpg'
     && nb.itemName === 'Border napkin' && nb.label === 'Yes - woven label' && nb.material === 'Linen' && nb.size === '20x20' && nb.customization === 'Yes - logo in corner' && nb.qty === 120,
     JSON.stringify(nb));
  ok('…and a column it does not know is kept on the line as it came', nb && nb.extra && nb.extra.Packaging === 'Polybag, 4 per pack', JSON.stringify(nb && nb.extra));
  ok('a row with no SKU and no item, or a bad quantity, rejects the file by row',
     /Row 2: no SKU and no item name/.test(A.soB2BRows([sheet[0], ['X', '', '', '', '', '', '', '5', '', '']]).errors.join(' '))
     && /must be a whole number above 0, not "two"/.test(A.soB2BRows([sheet[0], ['X', '', 'A1', '', '', '', '', 'two', '', '']]).errors.join(' ')));
  ok('a sheet with no Qty is refused', /needs a Qty column/.test(A.soB2BRows([['SKU', 'Item Name'], ['A', 'B']]).err || ''));

  /* A NEW CODE FOR AN ITEM WITH NONE: the brand's initials. */
  ok('a blank SKU is given the brand\'s code', /^CB-CUST-\d{6}-01$/.test(A.soB2BMint('Crate & Barrel', [])), A.soB2BMint('Crate & Barrel', []));

  /* SAVING. One of the new items is already on the Custom SKUs list and must be left alone. */
  NET.store['pt_customSkus/NEWB2B-1'] = { sku: 'NEWB2B-1', articleType: 'Napkin', brand: 'Crate & Barrel' };
  A.setSOF({ id: null, page: 0, lines: got.lines });
  ok('a B2B order with codes the master does not know still saves', (await A.soFormSave(false)) === '', els.sxMsg.textContent);
  const minted = A.SOF().lines.find(l => l.itemName === 'Round runner, no code yet').sku;
  ok('the item with no code was given one, and kept it on the form', /^CB-CUST-\d{6}-\d\d$/.test(minted), minted);
  const order = A.SOX().rows.find(o => o.channel === 'B2B' && o.legacyOrderId === 'PO-4471');
  ok('the order carries every line with its detail', order && order.lines.length === 3 && order.lines.find(l => l.sku === minted).itemName === 'Round runner, no code yet'
     && order.lines.find(l => l.sku === 'NEWB2B-1').extra.Packaging === 'Polybag, 4 per pack', JSON.stringify(order && order.lines.map(l => l.sku)));
  const cpatch = NET.calls.filter(c => c.method === 'PATCH' && c.body && Object.keys(c.body).some(k => /^pt_customSkus\//.test(k)));
  const cust = Object.assign({}, ...cpatch.map(c => c.body));
  ok('the item with a new code went on the Custom SKUs list, with its brand, name and picture',
     cust['pt_customSkus/' + minted] && cust['pt_customSkus/' + minted].brand === 'Crate & Barrel' && cust['pt_customSkus/' + minted].shopName === 'Round runner, no code yet'
     && cust['pt_customSkus/' + minted].fromB2B === true && cust['pt_customSkus/' + minted].b2bOrder === order._id, JSON.stringify(cust));
  ok('…one already on the list was left as somebody completed it', !cust['pt_customSkus/NEWB2B-1']);
  ok('…and a SKU the master knows is not put on it', !cust['pt_customSkus/' + known]);
  ok('the message says where the new items went', /new item\(s\) went on the Custom SKUs list/.test(els.sxMsg.textContent), els.sxMsg.textContent);

  /* ANOTHER CHANNEL STILL REFUSES AN UNKNOWN CODE. */
  A.soFormOpen(null);
  els.sof_channel.value = 'AMZ'; els.sof_date.value = '2026-11-03';
  A.setSOF({ id: null, page: 0, lines: [{ sku: 'NEWB2B-9', qty: 5 }] });
  ok('an Amazon order with a code the master does not know is still refused', /NEWB2B-9/.test(await A.soFormSave(false)));

  /* APPROVING: the floor sees what to make. */
  els.sor_mode.value = 'complete'; els.sor_date.value = '2026-11-30'; els.sor_remarks.value = '';
  ok('the B2B order approves', (await A.soApproveRun(order._id)) === '');
  const bRow = A.PTG().ob.find(r => r.orderNo === order._id && r.sku === 'NEWB2B-1');
  ok('its order-book row carries the picture and the detail, and says the SKU needs completing',
     bRow && bRow.needsSku === true && bRow.shopImg === 'https://img.example/b.jpg' && /Label: Yes - woven label/.test(bRow.remarks)
     && /Customization: Yes - logo in corner/.test(bRow.remarks) && bRow.size === '20x20' && bRow.qty === 120, JSON.stringify(bRow));
  const kRow = A.PTG().ob.find(r => r.orderNo === order._id && r.sku === known);
  ok('…while a known SKU takes its article from the master', kRow && kRow.needsSku === false && !/Label:/.test(kRow.remarks));

  NET.on = wasNet; ME.admin = wasAdmin;
}

console.log('\n== a Shopify order is packs, the factory makes pieces ==');
{
  /* "pillow cover always pack of 2 me bante h but abhi dikha rha h 1 pcs ... napkin me sku ke peeche
   * qty likhi hoti h like RCNB374-12 to usme 12 pcs banenge." */
  const wasPTG = A.PTG(), wasBase = A.PT().base, wasCut = A.PT().cut, wasEmp = A.PTE().emp,
    wasNet = NET.on, wasEdit = ME.prodEdit, wasAdmin = ME.admin;
  ME.admin = true; ME.prodEdit = true; NET.on = true; NET.store = {};
  A.setPTE(Object.assign(A.PTE(), { emp: [['Company Contractor', 'Ramesh Kumar', 'Stitching', '']] }));
  A.setPT(Object.assign(A.PT(), { base: [], cut: [] }));
  A.setPTG(Object.assign({}, wasPTG, { press: [], shopProd: {}, mdb: [
    { sku: 'RPCRU212-2424', articleType: 'Pillow Cover', subtype: 'Ruffle Pillow Cover', size: '24X24', packOf: '2' },
    { sku: 'RPCRU204-1436', articleType: 'Pillow Cover', subtype: 'Ruffle Pillow Cover', size: '14x36', packOf: '1' },
    { sku: 'CPCCRU045-1220', articleType: 'Pillow Cover', subtype: 'Ruffle Pillow Cover', size: '12x20', packOf: '1' },
    { sku: 'RCNE502-6', articleType: 'Napkin', subtype: 'Embroidery Napkin', size: '18x18', packOf: '6' },
    { sku: 'RCNB9-20', articleType: 'Napkin', subtype: 'Border Napkin', size: '20x20', packOf: '4' },
  ], ob: [
    { id: 'p1', orderNo: 'SHP-3408', sku: 'RPCRU212-2424', qty: 1, src: 'SHP', orderDate: '2026-09-10', shopOrderNo: '#3408', articleType: 'Pillow Cover' },
    { id: 'p2', orderNo: 'SHP-3500', sku: 'RCNB374-12', qty: 2, src: 'SHP', orderDate: '2026-09-10', shopOrderNo: '#3500' },
    /* The sync's own row for a set of 8 napkins Amazon stocks in fours: qty is 2 PACKS, and it says so. */
    { id: 'p4', orderNo: 'SHP-3409', sku: 'RCNB302-8', qty: 2, pcs: 8, shopQty: 1, src: 'SHP', orderDate: '2026-08-11', shopOrderNo: '#3408' },
    { id: 'p3', orderNo: 'AMZ-01092026-01', sku: 'RPCRU212-2424', qty: 147, src: 'SO', orderDate: '2026-09-01' },
  ] }));

  ok('a pillow cover the master packs in 2 is 2 pieces a pack', A.obPcsPerPack('RPCRU212-2424') === 2);
  ok('a napkin not in the master is the number after its last dash', A.obPcsPerPack('RCNB374-12') === 12
     && A.obPcsPerPack('RTME-147-8') === 8);
  ok('…but a napkin in the master keeps its Pack of, whatever its SKU ends in', A.obPcsPerPack('RCNB9-20') === 4);
  ok('another colour of a listed product takes its pack size', A.obPcsPerPack('RPCRU34-1436') === 1
     && A.obPcsPerPack('RPCRU34-2424') === 2);
  ok('a lumbar cover nobody has listed is single, like every other cover that size',
     A.obPcsPerPack('RPCRU34-1220', 'Pillow Cover') === 1, String(A.obPcsPerPack('RPCRU34-1220', 'Pillow Cover')));
  ok('a pillow cover nobody has listed is a pack of 2',A.obPcsPerPack('RPCZZ9-1818', 'Pillow Cover') === 2);
  ok('a tablecloth is one piece', A.obPcsPerPack('RTC23-6060', 'Tablecloth') === 1);

  ok('one pack of 2 is owed as 2 pieces', A.obOrderedQty('SHP-3408', 'RPCRU212-2424') === 2);
  ok('two sets of 12 napkins are 24 pieces', A.obOrderedQty('SHP-3500', 'RCNB374-12') === 24);
  ok('an Amazon order is already in pieces and is not multiplied', A.obOrderedQty('AMZ-01092026-01', 'RPCRU212-2424') === 147);

  const pc = A.ordLines().find(l => l.orderNo === 'SHP-3408');
  ok('the Order Console line is in pieces and remembers its packs', pc.qty === 2 && pc.packs === 1 && pc.pcsPer === 2,
     JSON.stringify({ q: pc.qty, p: pc.packs, per: pc.pcsPer }));

  /* THE POINT: both pieces can be cut and issued to the karigar. */
  ok('both pieces of the pack can be cut', (await A.spCutReal('SHP-3408', 'RPCRU212-2424', 2, '2026-09-13', '', '')) === '');
  ok('…and both issued to a karigar',
     (await A.spIssueReal('SHP-3408', 'RPCRU212-2424', 'Company Contractor', 'Ramesh Kumar', 2, '2026-09-13', '')) === '');
  ok('…but not a third', /cut piece|at most/.test(
     await A.spIssueReal('SHP-3408', 'RPCRU212-2424', 'Company Contractor', 'Ramesh Kumar', 1, '2026-09-13', '')));
  ok('…nor a third cut', !!(await A.spCutReal('SHP-3408', 'RPCRU212-2424', 1, '2026-09-13', '', '')));

  A.renderOrdShopify(false);
  ok('the table shows the packs under the pieces', /1 × 2<\/div>/.test(els.odTable.innerHTML));

  /* "Order qty me 1 set h, meaning 8×1, so qty should be 8." */
  ok('a row the sync wrote in Amazon packs is owed as its own pieces: 8, not 2 × 8', A.obOrderedQty('SHP-3409', 'RCNB302-8') === 8,
     String(A.obOrderedQty('SHP-3409', 'RCNB302-8')));
  const set8 = A.ordLines().find(l => l.sku === 'RCNB302-8');
  ok('…shown as 1 set × 8', set8.qty === 8 && set8.packs === 1 && set8.pcsPer === 8, JSON.stringify({ q: set8.qty, p: set8.packs, per: set8.pcsPer }));
  ok('…and the table says 1 × 8', /1 × 8<\/div>/.test(els.odTable.innerHTML));

  A.setPTG(wasPTG); A.setPT(Object.assign(A.PT(), { base: wasBase, cut: wasCut }));
  A.setPTE(Object.assign(A.PTE(), { emp: wasEmp }));
  NET.on = wasNet; ME.prodEdit = wasEdit; ME.admin = wasAdmin;
}

console.log('\n== Shopify bulk entry: one figure per SKU, shared across its orders ==');
{
  /* "single single entry kar raha hu to bahut jyada time lag rha h ... bulk wale me hi mera banda entry
   * kare, jab wo auto particular order wise entry ho jay, or upload se bhi kar sake." */
  const wasPT = A.PT(), wasPTG = A.PTG(), wasPTE = A.PTE(), wasNet = NET.on, wasEdit = ME.prodEdit, wasAdmin = ME.admin;
  ME.admin = true; ME.prodEdit = true; NET.on = true; NET.store = {};
  A.setPTE(Object.assign({}, wasPTE, { emp: [['Company Contractor', 'Ramesh Kumar', 'Stitching', ''], ['Company Contractor', 'Suresh', 'Stitching', ''],
    ['Company Role', 'Suresh', 'Pressman', '']] }));
  A.setPT(Object.assign({}, wasPT, { base: [], cut: [] }));
  const line = (no, date, qty, sku, extra) => Object.assign({ id: 'ob_' + no + sku, orderNo: no, sku: sku || 'BLK-PC', qty, src: 'SHP', orderDate: date,
    shopOrderNo: '#' + no.slice(4), articleType: 'Tablecloth', articleSubtype: 'Square Tablecloth', color: 'Red', size: '60x60' }, extra || {});
  A.setPTG(Object.assign({}, wasPTG, { press: [], shopProd: {},
    masters: Object.assign({}, wasPTG.masters, { fabricType: [{ code: 'CAMBRIC', desc: 'Cambric', active: true }] }),
    mdb: [{ sku: 'BLK-PC', articleType: 'Tablecloth', subtype: 'Square Tablecloth', color: 'Red', size: '60x60', packOf: '1', cuttingRequired: true },
          { sku: 'BLK-Q', articleType: 'Quilt', subtype: 'Queen Quilt', color: 'Red', size: '90x96', packOf: '1' }],
    ob: [line('SHP-7102', '2026-09-02', 5), line('SHP-7101', '2026-09-01', 3), line('SHP-7103', '2026-09-03', 4),
         line('SHP-7104', '2026-09-01', 1, 'BLK-Q', { articleType: 'Quilt', articleSubtype: 'Queen Quilt' })] }));

  const st0 = A.spBulkState('BLK-PC');
  ok('the lines are the open Shopify orders, oldest first', st0.lines.map(x => x.orderNo).join() === 'SHP-7101,SHP-7102,SHP-7103', st0.lines.map(x => x.orderNo).join());
  ok('…with room to cut 12, nothing to issue yet, and 12 still to make', st0.toCut === 12 && st0.toIssue === 0 && st0.toMake === 12);

  /* CUT 10 AND ISSUE 7 IN ONE ENTRY. */
  const p1 = A.spBulkPlan([{ sku: 'blk-pc', cut: '10', fabric: 'Cambric', issue: '7', karigar: 'Ramesh Kumar · Company Contractor' }], '2026-09-14');
  const cuts = p1.ops.filter(o => o.kind === 'cut').map(o => o.orderNo.slice(-4) + ':' + o.pcs).join();
  const issues = p1.ops.filter(o => o.kind === 'issue').map(o => o.orderNo.slice(-4) + ':' + o.pcs).join();
  ok('10 cut fills the oldest order, then the next: 3, 5, 2', cuts === '7101:3,7102:5,7103:2', cuts);
  ok('…and 7 issued follows the pieces just cut: 3, 4', issues === '7101:3,7102:4', issues);
  ok('…nothing left over, nothing to report', p1.problems.length === 0 && p1.orders === 3 && p1.totals.cut === 10 && p1.totals.issue === 7, JSON.stringify(p1.problems));

  const r1 = await A.spBulkApply(p1);
  ok('saving it writes every single entry', r1.done === 5 && r1.failed.length === 0, JSON.stringify(r1));
  ok('…three cutting rows and two Job Work rows, each on its own order', A.PT().cut.length === 3 && A.PT().base.length === 2
     && A.PT().base.every(r => r.empName === 'Ramesh Kumar' && r.src === 'SHP'), JSON.stringify(A.PT().base.map(r => r.orderNo + ':' + r.issuePieces)));
  ok('…with the fabric and the date on them', A.PT().cut.every(r => r.fabricWidth === 'Cambric' && /14\/09\/2026/.test(r.cutDate)));

  /* THE CAPS STILL HOLD: 5 to Suresh, but only 1 + 2 cut pieces are free. */
  const p2 = A.spBulkPlan([{ sku: 'BLK-PC', issue: '5', karigar: 'Suresh · Company Contractor' }], '2026-09-14');
  ok('what the orders have no room for is not forced on them', p2.totals.issue === 3 && p2.problems.length === 1
     && /2 of the 5 to issue could not be placed/.test(p2.problems[0]), JSON.stringify([p2.totals, p2.problems]));
  await A.spBulkApply(p2);

  /* RECEIVING FROM ONE KARIGAR leaves the other's issue alone. */
  const p3 = A.spBulkPlan([{ sku: 'BLK-PC', recv: '4', from: 'Ramesh Kumar' }], '2026-09-15');
  ok('4 back from Ramesh: 3 on the oldest order, 1 on the next', p3.ops.map(o => o.orderNo.slice(-4) + ':' + o.pcs).join() === '7101:3,7102:1',
     p3.ops.map(o => o.orderNo + ':' + o.pcs).join());
  await A.spBulkApply(p3);
  const sur = A.PT().base.filter(r => r.empName === 'Suresh');
  ok('…and Suresh\'s pieces on the same order are still out with him', sur.length === 2 && sur.every(r => ptNumT(r.receivedPieces) === 0 && !r.frozen),
     JSON.stringify(sur.map(r => [r.orderNo, r.receivedPieces, r.frozen])));
  /* SHARPER: Suresh's piece on SHP-7102 is made the OLDER issue. Receiving from Ramesh must still take
   * Ramesh's, although oldest-first alone would take Suresh's. */
  const surRow = A.PT().base.find(r => r.empName === 'Suresh' && r.orderNo === 'SHP-7102');
  surRow.issueDate = '01/09/2026, 08:00';
  ok('receiving from a named karigar never closes somebody else\'s older issue',
     (await A.spReceiveReal('SHP-7102', 'BLK-PC', 1, '2026-09-15', 'Ramesh Kumar')) === ''
     && ptNumT(A.PT().base.find(r => r.id === surRow.id).receivedPieces) === 0,
     JSON.stringify(A.PT().base.filter(r => r.orderNo === 'SHP-7102').map(r => [r.empName, r.issueDate, r.receivedPieces])));
  ok('receiving with no karigar named, when two hold it, is refused by name',
     /which karigar returned the 2\? Held by/.test(A.spBulkPlan([{ sku: 'BLK-PC', recv: '2' }]).problems[0] || ''));

  /* PRESSING follows what has come back. 4 came back; 5 asked. */
  const p4 = A.spBulkPlan([{ sku: 'BLK-PC', press: '6' }], '2026-09-15');
  ok('press is shared over what came back (3 and 2), and the sixth is reported', p4.totals.press === 5
     && p4.ops.map(o => o.orderNo.slice(-4) + ':' + o.pcs).join() === '7101:3,7102:2'
     && /1 of the 6 to press could not be placed/.test(p4.problems[0] || ''), JSON.stringify([p4.ops.map(o => o.orderNo + ':' + o.pcs), p4.problems]));

  /* WHAT IS REFUSED, AND SAYS WHY. */
  const bad = A.spBulkPlan([{ sku: 'BLK-PC', cut: 'two' }, { sku: 'BLK-PC', cut: '1', fabric: 'Silk' }, { sku: 'BLK-Q', cut: '1' },
    { sku: 'NOPE', cut: '1' }, { sku: 'BLK-PC', issue: '1', karigar: 'Suresh' }, { sku: 'BLK-PC', issue: '1' }], '2026-09-15');
  ok('a word is not a number', /"two" is not a whole number of pieces to cut/.test(bad.problems.join('|')));
  ok('a fabric the master does not have is refused', /fabric "Silk" is not in the Fabric Type master/.test(bad.problems.join('|')));
  ok('a quilt is left to its own entry', /BLK-Q: no open Shopify order is waiting for it/.test(bad.problems.join('|')));
  ok('a SKU no Shopify order carries is named', /NOPE: no Shopify order carries this SKU/.test(bad.problems.join('|')));
  ok('a name on the list twice needs its type', /"Suresh" is on the list more than once/.test(bad.problems.join('|')));
  ok('an issue with no karigar asks who', /which karigar are the 1 going to\?/.test(bad.problems.join('|')));

  /* THE SHEET. */
  const read = A.spBulkSheetEntries([['SKU', 'Item', 'Cut pcs', 'Fabric', 'Issue pcs', 'To karigar', 'Receive pcs', 'From karigar', 'Press pcs', 'Date'],
    ['BLK-PC', 'x', '2', 'Cambric', '', '', '', '', '', '15/09/2026'], ['', '', '', '', '', '', '', '', '', '']]);
  ok('the entry sheet reads back by column name', read.entries.length === 1 && read.entries[0].cut === '2' && read.entries[0].fabric === 'Cambric');
  ok('…and its dates, typed or from Excel', A.spBulkDate('15/09/2026') === '2026-09-15' && A.spBulkDate('2026-09-15') === '2026-09-15'
     && A.spBulkDate('46280') === '2026-09-15' && A.spBulkDate('', '2026-01-01') === '2026-01-01', A.spBulkDate('46280'));
  ok('a sheet with no piece columns is refused', /no Cut pcs, Issue pcs/.test(A.spBulkSheetEntries([['SKU'], ['X']]).err));

  /* "ME YAHA ORDER SE JYADA PCS BANATA HU TO USKA PROVISION DO WITH REASON KI EXTRA KYO BANAYA." */
  const e1 = A.spBulkPlan([{ sku: 'BLK-PC', cut: '5', fabric: 'Cambric' }], '2026-09-15');
  ok('cutting more than the orders need, with no reason, cuts only what they need and asks why',
     e1.totals.cut === 2 && /3 more than the open orders need to cut — pick a reason/.test(e1.problems.join('|')), JSON.stringify([e1.totals, e1.problems]));
  const e2 = A.spBulkPlan([{ sku: 'BLK-PC', cut: '5', fabric: 'Cambric', reason: 'Wastage / rejection cover' }], '2026-09-15');
  ok('with a reason, the rest goes on the newest open order as extra',
     e2.ops.map(o => o.orderNo.slice(-4) + ':' + o.pcs + (o.extraReason ? 'x' : '')).join() === '7103:2,7103:3x' && e2.problems.length === 0 && e2.extra === 3,
     JSON.stringify(e2.ops.map(o => [o.orderNo, o.pcs, o.extraReason])));
  await A.spBulkApply(e2);
  const xc = A.PT().cut.find(r => r.extraPcs === 3);
  ok('…and the cutting row says it is extra, and why', xc && xc.extraReason === 'Wastage / rejection cover' && /^Extra: Wastage/.test(xc.remarks), JSON.stringify(xc));
  const st3 = A.spBulkState('BLK-PC');
  const e3 = A.spBulkPlan([{ sku: 'BLK-PC', issue: '50', karigar: 'Ramesh Kumar · Company Contractor' }], '2026-09-15');
  ok('issuing past the orders with no reason issues only their room and asks why',
     e3.totals.issue === st3.toIssue && e3.extra === 0 && /more than the open orders need to issue — pick a reason/.test(e3.problems.join('|')),
     JSON.stringify([st3.toIssue, e3.totals, e3.problems]));
  const e4 = A.spBulkPlan([{ sku: 'BLK-PC', issue: '50', karigar: 'Ramesh Kumar · Company Contractor', reason: 'Stock for coming orders' }], '2026-09-15');
  ok('with a reason, cut pieces beyond the orders are issued as extra — and the rest, never cut, is refused',
     e4.extra > 0 && e4.totals.issue === st3.toIssue + e4.extra && e4.ops.filter(o => o.extraReason).every(o => o.extraReason === 'Stock for coming orders')
     && /could not be placed — not enough cut pieces/.test(e4.problems.join('|')),
     JSON.stringify([e4.totals, e4.extra, e4.problems]));
  await A.spBulkApply(e4);
  ok('…and the Job Work row is marked extra with its reason', A.PT().base.some(r => r.extraPcs > 0 && r.extraReason === 'Stock for coming orders' && r.empName === 'Ramesh Kumar'));
  const cutTotal = A.PT().cut.reduce((x, r) => x + ptNumT(r.pieces), 0), openNow = A.PT().base.reduce((x, r) => x + ptNumT(r.pendingPieces), 0);
  ok('…and nothing is out with karigars that was never cut', openNow <= cutTotal, JSON.stringify({ cutTotal, openNow }));
  ok('a reason never lets a piece be issued that was not cut',
     /cut piece/.test(await A.spIssueReal('SHP-7101', 'BLK-PC', 'Company Contractor', 'Ramesh Kumar', 50, '2026-09-15', '', 'Wastage / rejection cover')));

  A.setPT(wasPT); A.setPTG(wasPTG); A.setPTE(wasPTE); NET.on = wasNet; ME.prodEdit = wasEdit; ME.admin = wasAdmin;
}

console.log('\n== a quilt stays a counter, and goes to the quilt team ==');
{
  /* "quilt order direct pahle ki tarah hi rahe — unko me kisi karigar ko issue nahi krna chahta, just
   * cut issue rece. And one new column: handover to Quilt Team." */
  const wasBase = A.PT().base, wasCut = A.PT().cut, wasOb = A.PTG().ob, wasSp = A.PTG().shopProd,
    wasPress = A.PTG().press, wasEmp = A.PTE().emp, wasNet = NET.on, wasEdit = ME.prodEdit, wasAdmin = ME.admin;
  ME.admin = true; ME.prodEdit = true; NET.on = true; NET.store = {};
  A.setPTE(Object.assign(A.PTE(), { emp: [['Company Contractor', 'Ramesh Kumar', 'Stitching', '']] }));
  A.setPT(Object.assign(A.PT(), { base: [], cut: [] }));
  A.setPTG(Object.assign(A.PTG(), { press: [], shopProd: {}, ob: [
    { id: 'q1', orderNo: 'SHP-3365', sku: 'RQL34-Q', qty: 1, src: 'SHP', orderDate: '2026-09-10',
      shopOrderNo: '#3365', articleType: 'Quilt', articleSubtype: 'Queen Quilt', size: '90X96' },
    { id: 't1', orderNo: 'SHP-3366', sku: 'TC-9', qty: 6, src: 'SHP', orderDate: '2026-09-10',
      shopOrderNo: '#3366', articleType: 'Tablecloth', articleSubtype: 'Square Tablecloth', size: '60x60' }] }));

  const quilt = A.ordLines().find(l => l.sku === 'RQL34-Q');
  const tc = A.ordLines().find(l => l.sku === 'TC-9');
  ok('a quilt is known as a quilt', A.spIsQuilt(quilt) && !A.spIsQuilt(tc));

  /* THE QUILT KEEPS ITS COUNTERS — cut, issued, received, no karigar. */
  ok('a quilt is counted, not issued to anybody',
     (await A.spSave('SHP-3365', 'RQL34-Q', { cut: 1, issued: 1, received: 1, remarks: '' })) === '');
  const q = A.ordLines().find(l => l.sku === 'RQL34-Q');
  ok('…and the line reads those counters', q.cut === 1 && q.issued === 1 && q.received === 1,
     JSON.stringify({ cut: q.cut, issued: q.issued, received: q.received }));
  ok('…and nothing went into Base Data for it', !Object.keys(NET.store).some(k => /^pt_baseData\//.test(k)));

  /* THE HANDOVER TO THE QUILT TEAM. */
  ok('a quilt can be handed to the quilt team', (await A.spQuiltHand('SHP-3365', 'RQL34-Q', true)) === '');
  const rec = NET.store['pt_shopProd/SHP-3365__RQL34-Q'];
  ok('…with who and when', rec && !!rec.quiltAt && rec.quiltBy === ME.email, JSON.stringify(rec));
  ok('…and not twice', /already with the quilt team/.test(await A.spQuiltHand('SHP-3365', 'RQL34-Q', true)));
  ok('a tablecloth has no quilt team to go to', /Only a quilt/.test(await A.spQuiltHand('SHP-3366', 'TC-9', true)));
  ok('the handover can be taken back', (await A.spQuiltHand('SHP-3365', 'RQL34-Q', false)) === ''
     && !NET.store['pt_shopProd/SHP-3365__RQL34-Q'].quiltAt);

  A.renderOrdShopify(false);
  ok('the table has a Quilt team column', /<th[^>]*>Quilt team<\/th>/.test(els.odTable.innerHTML));
  ok('…and a quilt row offers the handover', /data-spquilt="SHP-3365\|RQL34-Q"/.test(els.odTable.innerHTML));
  ok('…while a tablecloth row does not', !/data-spquilt="SHP-3366\|TC-9"/.test(els.odTable.innerHTML));

  /* CLICK A TILE, SEE THOSE LINES. "cut ya rec ya anything click karu to only bahi data mujhe dikhe." */
  const kpiClick = key => (els.odKpis._listeners.click || []).forEach(fn => fn({ type: 'click',
    target: { closest: () => ({ getAttribute: () => key }) } }));
  kpiClick('received');
  ok('clicking Received keeps only lines with pieces received', A.ORD_KPI() === 'received'
     && /RQL34-Q/.test(els.odTable.innerHTML) && !/TC-9/.test(els.odTable.innerHTML), A.ORD_KPI());
  ok('…marks the tile it is showing', /pt-kpi-on" data-odkpi="received"/.test(els.odKpis.innerHTML));
  ok('…and says so under the filters', /only lines with Received/.test(els.odMsg.textContent), els.odMsg.textContent);
  ok('…while the tiles still count every line', /<div class="v">7<\/div><div class="l">Pieces/.test(els.odKpis.innerHTML));
  kpiClick('pendingMake');
  ok('another tile swaps the filter', /TC-9/.test(els.odTable.innerHTML) && !/RQL34-Q/.test(els.odTable.innerHTML));
  kpiClick('pendingMake');
  ok('clicking it again shows everything', A.ORD_KPI() === '' && /TC-9/.test(els.odTable.innerHTML) && /RQL34-Q/.test(els.odTable.innerHTML));
  A.setORD_KPI('cut'); els.odClear.onclick();
  ok('Clear lets the tile go too', A.ORD_KPI() === '');

  /* THE BUG THIS FIXED. Assigning a printer writes the line a record of its own, and a line with a
   * record used to read counters instead of Base Data — so a karigar issue vanished from the screen the
   * moment a printer was put on it. */
  await A.spAssign('SHP-3366', 'TC-9', 'VND001');
  await A.spCutReal('SHP-3366', 'TC-9', 6, '2026-09-12', '', '');
  await A.spIssueReal('SHP-3366', 'TC-9', 'Company Contractor', 'Ramesh Kumar', 6, '2026-09-12', '');
  const t = A.ordLines().find(l => l.sku === 'TC-9');
  ok('a karigar issue still shows on a line that has a printer',
     t.issued === 6 && t.cut === 6, JSON.stringify({ cut: t.cut, issued: t.issued }));

  /* PAID THE SAME WAY EITHER WAY IT WAS ENTERED. Payroll pays a Base Data row once it carries a
   * receiving date, and Base Data stamps that only when the last piece is back. */
  await A.spReceiveReal('SHP-3366', 'TC-9', 4, '2026-09-13');
  const half = A.spBaseRows('SHP-3366', 'TC-9')[0];
  ok('a part receipt does not close the row, so it is not paid yet — as on Base Data',
     !half.receivingDate && A.ptNum(half.receivedPieces) === 4, JSON.stringify({ d: half.receivingDate, r: half.receivedPieces }));
  await A.spReceiveReal('SHP-3366', 'TC-9', 2, '2026-09-14');
  const done = A.spBaseRows('SHP-3366', 'TC-9')[0];
  ok('…and the last piece closes it, on the day the goods came in',
     !!done.receivingDate && /14\/09\/2026/.test(String(done.receivingDate)) && done.frozen === true,
     JSON.stringify({ d: done.receivingDate, f: done.frozen }));

  /* A TABLECLOTH GOES TO SHIPPING TOO. Its figures are in Base Data and the press register, not on
   * its record — and its handover is on its record, and must be read, or it comes back as open. */
  ok('a karigar-made line is checked against its real press figure',
     /have not been pressed yet/.test(await A.spHandover('SHP-3366', 'TC-9', true)));
  await A.spPressReal('SHP-3366', 'TC-9', 6, '2026-09-14', '');
  ok('…and once pressed it can be handed over', (await A.spHandover('SHP-3366', 'TC-9', true)) === '');
  const tcDone = A.ordLines().find(l => l.sku === 'TC-9');
  ok('…which closes it, although it is not a quilt', tcDone.open === false && !!tcDone.handedAt,
     JSON.stringify({ open: tcDone.open, at: tcDone.handedAt }));
  ok('…and it still shows its printer', tcDone.printer === 'VND001');

  A.setPT(Object.assign(A.PT(), { base: wasBase, cut: wasCut }));
  A.setPTG(Object.assign(A.PTG(), { ob: wasOb, shopProd: wasSp, press: wasPress }));
  A.setPTE(Object.assign(A.PTE(), { emp: wasEmp }));
  NET.on = wasNet; ME.prodEdit = wasEdit; ME.admin = wasAdmin;
}

console.log('\n== the fabric a printer is sent ==');
{
  /* Ravi's reference sheet, read as a rule: brand + (F | SF) + colour code, and for sheeting the
   * direction and the width. Cambric carries neither — there is no width to print across. */
  ok('cambric, CPC', A.fsSku('CPC', '004', 'Cambric', 'Vertical') === 'CPCF004',
     A.fsSku('CPC', '004', 'Cambric', 'Vertical'));
  ok('cambric, Ridhi', A.fsSku('RBP', '327', 'Cambric', 'Vertical') === 'RBP327',
     A.fsSku('RBP', '327', 'Cambric', 'Vertical'));
  ok('sheeting, vertical', A.fsSku('CPC', '004', 'Sheeting 72', 'Vertical') === 'CPCSF004-V-72',
     A.fsSku('CPC', '004', 'Sheeting 72', 'Vertical'));
  ok('sheeting, horizontal', A.fsSku('RBP', '327', 'Sheeting 112', 'Horizontal') === 'RBPSF327-H-112',
     A.fsSku('RBP', '327', 'Sheeting 112', 'Horizontal'));
  /* THE WIDTH IS THE CLOTH'S OWN. Ravi's sheet has "Sheeting 72, Horizontal" written as -H-82 in both
   * of its blocks, which is the same slip copied twice: the width cannot change because the print
   * turned sideways. */
  ok('the width follows the cloth, not the direction',
     A.fsSku('CPC', '004', 'Sheeting 72', 'Horizontal') === 'CPCSF004-H-72',
     A.fsSku('CPC', '004', 'Sheeting 72', 'Horizontal'));

  /* ELEVEN LINES PER COLOUR: cambric, and five widths each way up. */
  const lines = A.fsLinesFor('CPC', '004', 'Emerald Green');
  ok('a colour makes eighteen lines: cambric, ten sheeting, six voil, one canvas', lines.length === 18, String(lines.length));
  ok('…one of them cambric', lines.filter(l => l.fabric === 'Cambric').length === 1);
  ok('…and each width both ways up',
     A.FS_WIDTHS.every(w => lines.filter(l => l.width === w && /^Sheeting/.test(l.fabric)).length === 2), JSON.stringify(A.FS_WIDTHS));

  /* VOIL AND CANVAS, Ravi's reference for 327 Light Steel Blue, Ridhi, row for row (21 Sep 2026). */
  {
    const want = [['Voil 92', 'Horizontal', 'RQL327-T-Front'], ['Voil 92', 'Horizontal', 'RQL327-T-Back'],
      ['Voil 92', 'Vertical', 'RQL327-Q-Front'], ['Voil 92', 'Vertical', 'RQL327-Q-Back'],
      ['Voil 112', 'Horizontal', 'RQL327-K-Front'], ['Voil 112', 'Horizontal', 'RQL327-K-Back'],
      ['Canvas', 'Vertical', 'RBP-CANVAS-327']];
    const got = A.fsLinesFor('RBP', '327', 'Light Steel Blue').filter(l => /Voil|Canvas/.test(l.fabric))
      .map(l => [l.fabric, l.dir, l.sku]);
    ok('Ridhi voil and canvas are exactly the reference', JSON.stringify(got) === JSON.stringify(want), JSON.stringify(got));
    ok('…and Ridhi still has its cambric and sheeting', A.fsLinesFor('RBP', '327', 'x').length === 18);
    ok('a voil width or direction nobody makes has no SKU',
      A.fsSku('RBP', '327', 'Voil 112', 'Vertical', 'Front') === '' && A.fsSku('RBP', '327', 'Voil 92', 'Horizontal', '') === '');
    /* CPC, from its own quilt SKUs (CPCQ005-Q / -T): the same three voil lines and canvas. */
    ok('CPC voil and canvas follow its quilt SKUs', A.fsSku('CPC', '005', 'Voil 92', 'Horizontal', 'Front') === 'CPCQ005-T-Front'
      && A.fsSku('CPC', '005', 'Voil 112', 'Horizontal', 'Back') === 'CPCQ005-K-Back' && A.fsSku('CPC', '005', 'Canvas', 'Vertical') === 'CPC-CANVAS-005'
      && A.fsLinesFor('CPC', '005', 'x').length === 18, A.fsSku('CPC', '005', 'Voil 92', 'Horizontal', 'Front'));
    const v = A.fsOf('rql327-k-back');
    ok('a voil SKU typed in any case is found', v && v.fabric === 'Voil 112' && v.side === 'Back' && v.colour === 'Light Steel Blue',
      JSON.stringify(v && { f: v.fabric, s: v.side, c: v.colour }));
    const cv = A.fsOf('RBP-CANVAS-327');
    ok('…and so is canvas', cv && cv.fabric === 'Canvas' && cv.dir === 'Vertical');
  }

  /* THE CODE IS READ OUT OF THE PRODUCT SKUs, because nowhere else has it. */
  ok('a product SKU gives up its colour code',
     A.fsCodeOf('RTRE327-1690').code === '327' && A.fsCodeOf('RTRE327-1690').family === 'RBP',
     JSON.stringify(A.fsCodeOf('RTRE327-1690')));
  ok('…and CPC is its own family', A.fsCodeOf('CPCC004-18').family === 'CPC');
  ok('something with no code in it is not guessed at', A.fsCodeOf('MIXED-BUNDLE') === null);

  /* ON THE REAL MASTER DATABASE. */
  const codes = A.fsColourCodes();
  ok('the colour codes come out of the real catalogue', codes.length > 150, String(codes.length));
  const c327 = codes.find(c => c.code === '327' && c.family === 'RBP');
  ok('…327 is Light Steel Blue, as the reference says', c327 && c327.colour === 'Light Steel Blue',
     c327 && c327.colour);
  const c004 = codes.find(c => c.code === '004' && c.family === 'CPC');
  ok('…004 is Emerald Green', c004 && c004.colour === 'Emerald Green', c004 && c004.colour);
  /* A CODE THAT DISAGREES WITH ITSELF IS REPORTED, NOT GUESSED AT. 004 is Emerald Green on 82 rows
   * and Agate Green on one, and that one is worth somebody's eye. */
  ok('…and the one row that calls 004 something else is named',
     c004 && c004.alsoCalled.length > 0 && /Agate Green/.test(c004.alsoCalled.join(' ')),
     JSON.stringify(c004 && c004.alsoCalled));

  /* THE LOOKUP THE PRINTING ORDER NEEDS: type the SKU, get what to print. */
  const one = A.fsOf('RBPSF327-H-92');
  ok('a fabric SKU says what it is',
     one && one.colour === 'Light Steel Blue' && one.fabric === 'Sheeting 92' && one.dir === 'Horizontal',
     JSON.stringify(one && { c: one.colour, f: one.fabric, d: one.dir }));
  ok('…and a SKU nobody makes is nothing', A.fsOf('RBPSF327-H-999') === null);

  /* AND THE PICTURE COMES FROM A REAL PRODUCT IN THAT COLOUR. */
  const withPic = A.fsRows({ brand: 'RBP', colour: 'Light Steel Blue' });
  ok('every line of a colour carries the same reference picture',
     withPic.length === 18 && new Set(withPic.map(r => r.imageFrom)).size === 1,
     JSON.stringify({ n: withPic.length, from: withPic[0] && withPic[0].imageFrom }));
  ok('…and it is a real product SKU, not a made-up one',
     !!(A.PTG().mdb || []).find(r => r.sku === withPic[0].imageFrom), withPic[0] && withPic[0].imageFrom);
}

console.log('\n== and the screen actually draws it ==');
{
  /* THE MODEL WAS RIGHT AND THE SCREEN WAS DRAWING SOMETHING ELSE. Every test above passed while the
   * tab showed the ordinary master database: the branch that picks the catalogue had never been
   * written to the file, because the script that added it threw half way and writes only at the end.
   * A model test cannot catch that. This one drives the screen. */
  const wasView = els.ptmView.value;
  ['ptmQ', 'ptmCol', 'ptmBrandFs', 'ptmDir', 'ptmBrand', 'ptmArt', 'ptmSub', 'ptmSz', 'ptmCut']
    .forEach(i => { if (els[i]) els[i].value = ''; });

  els.ptmView.value = 'fabric';
  A.renderPmdb();
  const html = els.ptmTable.innerHTML;
  ok('choosing the fabric view draws the fabric catalogue',
     /Print direction/.test(html) && /Colour code/.test(html), html.slice(0, 120));
  ok('…with lines in it', (html.match(/<tr>/g) || []).length > 100,
     String((html.match(/<tr>/g) || []).length));
  ok('…and the message counts fabric SKUs, not master rows',
     /fabric SKU\(s\)/.test(els.ptmMsg.textContent), els.ptmMsg.textContent.slice(0, 80));
  ok('…and a real generated SKU is on the screen', /RBPSF327-V-72|CPCSF004-V-72/.test(html));

  /* The two filters it needs are shown, and the ones that mean nothing here are put away. */
  ok('the brand and direction pickers appear with it',
     els.ptmBrandFs.classList.contains('hide') === false && els.ptmDir.classList.contains('hide') === false);
  /* Ravi, 2026-09-25: "i can add manually fabric sku and detail via excel and one by one". */
  ok('…and the add button says what it adds here: a fabric SKU, with its template and import',
     els.ptmNew.textContent === '+ Fabric SKU' && (!A.mdbCanEdit() || (els.ptmNew.classList.contains('hide') === false
       && els.ptmTemplate.classList.contains('hide') === false && els.ptmImport.classList.contains('hide') === false)), els.ptmNew.textContent);

  /* Direction narrows it to half. */
  els.ptmDir.value = 'Horizontal';
  A.renderPmdb();
  ok('one direction is half the catalogue', !/-V-/.test(els.ptmTable.innerHTML)
     && /-H-/.test(els.ptmTable.innerHTML));
  els.ptmDir.value = '';

  /* And going back to the master database brings the master database back. */
  els.ptmView.value = 'master';
  A.renderPmdb();
  ok('going back shows the master database again',
     !/Print direction/.test(els.ptmTable.innerHTML) && /SKU\(s\)/.test(els.ptmMsg.textContent),
     els.ptmMsg.textContent.slice(0, 60));
  ok('…and its own buttons come back', els.ptmNew.classList.contains('hide') === false && els.ptmNew.textContent === '+ New SKU');

  /* FABRIC SKUs ADDED BY HAND (Ravi, 2026-09-25). */
  {
    const built = A.fsBuiltSkus();
    const one = [...built][0];
    ok('a SKU the catalogue already builds cannot be added by hand', /already in the catalogue/.test(A.fsManualCheck({ sku: one, colour: 'X', fabric: 'Y' }, built, null).err || ''));
    ok('colour and fabric are required, brand and direction are checked',
       /put in the colour/.test(A.fsManualCheck({ sku: 'ZZ-1', fabric: 'Voil 92' }, built).err)
       && /brand is CPC or Ridhi/.test(A.fsManualCheck({ sku: 'ZZ-1', brand: 'Acme', colour: 'Red', fabric: 'Voil 92' }, built).err)
       && /Vertical or Horizontal/.test(A.fsManualCheck({ sku: 'ZZ-1', colour: 'Red', fabric: 'Voil 92', dir: 'up' }, built).err));
    const ok1 = A.fsManualCheck({ sku: 'cpcsf999-v-62', brand: 'Ridhi', colour: 'Ocean Vine', fabric: 'Sheeting 62', dir: 'v' }, built);
    ok('a good row is tidied: capitals, Ridhi → RBP, v → Vertical', ok1.rec && ok1.rec.sku === 'CPCSF999-V-62' && ok1.rec.brand === 'RBP' && ok1.rec.dir === 'Vertical', JSON.stringify(ok1));
    const head = A.FS_MAN_COLS.map(c => c[1]);
    const plan = A.fsManualPlan([['Fabric sheet'], head,
      ['CPCSF999-V-62', 'CPC', '999', 'Ocean Vine', 'Sheeting 62', 'Vertical', '', '', ''],
      ['CPCSF999-V-62', 'CPC', '999', 'Ocean Vine', 'Sheeting 62', 'Vertical', '', '', ''],
      [one, 'CPC', '', 'X', 'Y', '', '', '', ''], []]);
    ok('the sheet is read under a title row; a twice-listed SKU and a built one are named with their rows',
       plan.add.length === 1 && plan.bad.length === 2 && /row 4: .*twice/.test(plan.bad[0]) && /row 5: .*already in the catalogue/.test(plan.bad[1]), JSON.stringify(plan.bad));
    const wasEdit = ME.admin, wasNet = NET.on; ME.admin = true; NET.on = true; NET.calls = [];
    ok('a good row saves', (await A.fsManualSave([ok1.rec])) === '');
    ok('…into pt_masters/fabricSku in one write', NET.calls.some(c => c.method === 'PATCH' && c.body && c.body['pt_masters/fabricSku/CPCSF999-V-62']));
    els.ptmView.value = 'fabric'; els.ptmQ.value = 'cpcsf999'; A.renderPmdb();
    ok('…and it is in the fabric catalogue, marked as added by hand, with Edit', /CPCSF999-V-62/.test(els.ptmTable.innerHTML) && /added<\/span>/.test(els.ptmTable.innerHTML)
       && /data-fs-edit="CPCSF999-V-62"/.test(els.ptmTable.innerHTML));
    ok('…and the vendor order form\'s fabric list knows it', !!A.fsOf('CPCSF999-V-62') && A.fsOf('CPCSF999-V-62').colour === 'Ocean Vine');
    const again = A.fsManualPlan([head, ['CPCSF999-V-62', 'CPC', '999', 'Ocean Vine', 'Sheeting 62', 'Horizontal', '', '', 'fixed']]);
    ok('uploading it again updates it rather than adding it twice', again.upd.length === 1 && again.add.length === 0);
    els.ptmQ.value = ''; ME.admin = wasEdit; NET.on = wasNet;
    A.setPTG(Object.assign({}, A.PTG(), { masters: Object.assign({}, A.PTG().masters, { fabricSku: {} }) }));
  }

  els.ptmView.value = wasView;
  A.renderPmdb();
}

console.log('\n== greige becomes RFD, and RFD becomes cut pieces ==');
{
  /* "RFD fabric me hum start karenge greige fabric se … then greige fabric convert hota h rfd me and
   * rfd running fabric mera convert hoga cut pcs me."
   *
   * The ledger already carried a state on all 517 of its rows, and every one of them said PRINTED —
   * the cloth's two earlier lives were simply never written down. */
  const wasFAB = A.FAB(), wasNet = NET.on, wasEdit = ME.prodEdit, wasAdmin = ME.admin;
  ME.admin = true; ME.prodEdit = true; NET.on = true; NET.store = {};
  A.setFAB({ rows: [], err: '', busy: false, at: '', shown: [] });

  /* A row written before any of this is printed cloth, and stays printed cloth. */
  ok('an old row is read as printed', A.fabState({ txnType: 'ISSUE_TO_CUTTING', state: 'PRINTED' }) === 'PRINTED');
  ok('…and a receipt of greige is greige, whatever the row says',
     A.fabState({ txnType: 'RECEIVE_GREIGE', state: 'PRINTED' }) === 'GREIGE');

  /* 1. THE MILL. */
  ok('greige comes in', (await A.fabSave({ txnType: 'RECEIVE_GREIGE', fabricType: 'CAMBRIC', qty: 1000,
    counterpartyName: 'Mill', date: '2026-09-12', rate: 55, challan: 'BILL-77' })) === '');
  ok('…and is greige stock', A.fabStockOf('CAMBRIC', 'GREIGE') === 1000, String(A.fabStockOf('CAMBRIC', 'GREIGE')));
  ok('…with the money on it, because a rate times metres is what the bill will say',
     Object.values(NET.store)[0].amount === 55000, JSON.stringify(Object.values(NET.store)[0].amount));

  /* THE DELIVERY OPENED A LOT, and the lot is what moves from here on. */
  const LOT = A.fabLots().find(g => g.greigeIn === 1000).lot;
  ok('the delivery opened a lot', !!LOT && /CAMBRIC-/.test(LOT), LOT);
  ok('…carrying the mill and the bill it came on',
     A.fabLot(LOT).mill === 'Mill' && A.fabLot(LOT).bill === 'BILL-77',
     JSON.stringify({ mill: A.fabLot(LOT).mill, bill: A.fabLot(LOT).bill }));

  /* 2. OUT TO BE PROCESSED — from a named lot, and not more than that lot holds. */
  ok('cloth cannot go for processing without saying which lot',
     /Which lot/.test(await A.fabSave({ txnType: 'ISSUE_TO_RFD', fabricType: 'CAMBRIC',
       qty: 100, counterpartyName: 'Shree Processors' })));
  ok('…nor from a lot that does not exist',
     /no greige against it/.test(await A.fabSave({ txnType: 'ISSUE_TO_RFD', fabricType: 'CAMBRIC',
       lot: 'MADE-UP-01', qty: 100, counterpartyName: 'Shree Processors' })));
  ok('more than the lot holds cannot be sent',
     /Only 1,000 m is left in lot/.test(await A.fabSave({ txnType: 'ISSUE_TO_RFD', fabricType: 'CAMBRIC',
       lot: LOT, qty: 1200, counterpartyName: 'Shree Processors' })));
  ok('…and it will not go out to nobody',
     /Who is processing/.test(await A.fabSave({ txnType: 'ISSUE_TO_RFD', fabricType: 'CAMBRIC', lot: LOT, qty: 100 })));
  ok('the lot goes out for processing', (await A.fabSave({ txnType: 'ISSUE_TO_RFD', fabricType: 'CAMBRIC',
    lot: LOT, qty: 600, counterpartyName: 'Shree Processors', date: '2026-09-12' })) === '');
  ok('…the greige stock comes down', A.fabStockOf('CAMBRIC', 'GREIGE') === 400);
  /* THE NUMBER THAT HAD NO HOME BEFORE: with the processor, neither greige nor RFD. */
  ok('…and it is not RFD stock yet', A.fabStockOf('CAMBRIC', 'RFD') === 0);
  ok('…it is with the processor', A.fabWithProcessor('CAMBRIC') === 600);
  ok('…and the lot says who has it', A.fabLot(LOT).processor === 'Shree Processors'
     && A.fabLot(LOT).withProcessor === 600, JSON.stringify(A.fabLot(LOT)));

  /* 3. BACK AS RFD, against the lot that went. */
  ok('nothing can come back from a lot that never went',
     /never sent for processing/.test(await A.fabSave({ txnType: 'RECEIVE_RFD', fabricType: 'CAMBRIC',
       lot: 'MADE-UP-01', qty: 10 })));
  ok('more cannot come back than that lot has out',
     /Only 600 m of lot/.test(await A.fabSave({ txnType: 'RECEIVE_RFD', fabricType: 'CAMBRIC', lot: LOT, qty: 700 })));
  ok('RFD comes back', (await A.fabSave({ txnType: 'RECEIVE_RFD', fabricType: 'CAMBRIC', lot: LOT, qty: 560,
    counterpartyName: 'Shree Processors', date: '2026-09-14' })) === '');
  ok('…as RFD stock', A.fabStockOf('CAMBRIC', 'RFD') === 560);
  ok('…and forty metres of that lot are still with them', A.fabLot(LOT).withProcessor === 40);
  /* THE LOSS IS THE LOT'S OWN — which is the whole point of asking which lot. */
  ok('…and the lot carries its own loss', A.fabLot(LOT).lossPct === 6.7, String(A.fabLot(LOT).lossPct));

  /* 4. OUT TO THE CUTTING TABLE, from that lot's RFD. */
  ok('more RFD than the lot holds cannot be cut',
     /Only 560 m of RFD is left in lot/.test(await A.fabSave({ txnType: 'ISSUE_TO_CUTTING',
       fabricType: 'CAMBRIC', lot: LOT, qty: 600, state: 'RFD', size: '60x90', pieces: 250 })));
  ok('RFD goes to cutting', (await A.fabSave({ txnType: 'ISSUE_TO_CUTTING', fabricType: 'CAMBRIC',
    lot: LOT, qty: 200, state: 'RFD', counterpartyName: 'Cutting Dept', size: '60x90', pieces: 85 })) === '');
  ok('…and the RFD stock comes down', A.fabStockOf('CAMBRIC', 'RFD') === 360);
  ok('…and the lot can still be traced back to the bill it arrived on',
     A.fabLot(LOT).bill === 'BILL-77' && A.fabLot(LOT).rfdOut === 200);

  /* A SECOND LOT OF THE SAME FABRIC IS A SEPARATE THING, which is why lots exist at all. */
  ok('a second delivery opens its own lot', (await A.fabSave({ txnType: 'RECEIVE_GREIGE',
    fabricType: 'CAMBRIC', lot: 'MILL-LOT-9', qty: 300, counterpartyName: 'Other Mill',
    challan: 'BILL-91', date: '2026-09-15' })) === '');
  ok('…and the same lot number cannot be opened twice',
     /already has 300 m against it/.test(await A.fabSave({ txnType: 'RECEIVE_GREIGE',
       fabricType: 'CAMBRIC', lot: 'MILL-LOT-9', qty: 50, counterpartyName: 'Other Mill' })));
  ok('…the two lots are counted apart',
     A.fabLot('MILL-LOT-9').greigeLeft === 300 && A.fabLot(LOT).greigeLeft === 400,
     JSON.stringify(A.fabLots().map(g => g.lot + ':' + g.greigeLeft)));
  ok('…while the fabric total is both of them', A.fabStockOf('CAMBRIC', 'GREIGE') === 700);
  ok('a lot that has gone nowhere is the one to send next',
     A.fabLotsWithGreige().some(g => g.lot === 'MILL-LOT-9'));
  ok('…and only the lot that is out is waiting to come back',
     A.fabLotsOut().length === 1 && A.fabLotsOut()[0].lot === LOT,
     JSON.stringify(A.fabLotsOut().map(g => g.lot)));

  /* THE WHOLE JOURNEY ON ONE LINE. */
  const flow = A.fabFlowRows(A.FAB().rows).find(g => g.fabricType === 'CAMBRIC');
  /* The fabric's own line adds the two lots up: 1,000 m on the first bill and 300 on the second. */
  ok('the flow reads mill to cutting table, across every lot of that cloth',
     flow.greigeIn === 1300 && flow.toRfd === 600 && flow.greigeLeft === 700
     && flow.rfdIn === 560 && flow.rfdLeft === 360 && flow.rfdOut === 200, JSON.stringify(flow));
  /* PROCESS LOSS IS A PERCENTAGE SOMEBODY CAN ARGUE WITH: 600 out, 560 back. */
  ok('…and names the process loss', flow.lossPct === 6.7, String(flow.lossPct));
  ok('…counting only what has come back, not what is still out there',
     flow.withProcessor === 40, String(flow.withProcessor));

  /* GREIGE AND RFD ARE NOT THE SAME CLOTH, so they are not the same balance. */
  const bal = A.fabBalances(A.FAB().rows).filter(b => b.fabricType === 'CAMBRIC');
  ok('greige and RFD are counted apart', bal.length === 2
     && bal.some(b => b.state === 'GREIGE' && b.qty === 700)
     && bal.some(b => b.state === 'RFD' && b.qty === 360),
     JSON.stringify(bal.map(b => b.state + ':' + b.qty)));

  /* And it is an entry, so it needs the right to make one. */
  ME.prodEdit = false; ME.admin = false;
  ok('somebody who may not change production entries cannot write the ledger',
     /permission/i.test(await A.fabSave({ txnType: 'RECEIVE_GREIGE', fabricType: 'CAMBRIC', qty: 10 })));

  A.setFAB(wasFAB); NET.on = wasNet; ME.prodEdit = wasEdit; ME.admin = wasAdmin;
}

console.log('\n== a month of fabric, uploaded at once ==');
{
  /* "RFD me bulk upload ka option." Thirty deliveries is not typed in one at a time — but a file that
   * skips the ceilings would put cloth in the ledger that does not exist, so it goes through the same
   * save every typed line goes through. */
  const wasFAB = A.FAB(), wasNet = NET.on, wasEdit = ME.prodEdit, wasAdmin = ME.admin;
  ME.admin = true; ME.prodEdit = true; NET.on = true; NET.store = {};
  A.setFAB({ rows: [], err: '', busy: false, at: '', shown: [] });

  const csv = [
    'Movement,Date,Fabric,Lot,Metres,Who,Colour,Bill,Rate,Remarks',
    'Greige received,2026-09-12,SHEETING 82,SH82/A,1000,Mill A,,B-100,52,',
    'Greige received,2026-09-12,SHEETING 82,SH82/B,400,Mill B,,B-101,54,',
    'Greige sent for RFD,2026-09-13,SHEETING 82,SH82/A,600,Shree,,,,',
    'RFD received,2026-09-16,SHEETING 82,SH82/A,570,Shree,,,,',
  ].join('\n');

  const read = A.fabCsvRows(csv);
  ok('the file is read', read.rows.length === 4 && !read.bad.length, JSON.stringify(read.bad));
  ok('…and the words are turned into movements',
     read.rows.map(r => r.txnType).join(' ') === 'RECEIVE_GREIGE RECEIVE_GREIGE ISSUE_TO_RFD RECEIVE_RFD',
     read.rows.map(r => r.txnType).join(' '));

  /* A LINE THAT CANNOT BE READ IS NAMED BY ITS LINE NUMBER, the way a spreadsheet counts. */
  const messy = A.fabCsvRows(['Movement,Date,Fabric,Lot,Metres',
    'Greige received,2026-09-12,CAMBRIC,,100',
    'Sent to the moon,2026-09-12,CAMBRIC,,50',
    'Greige received,2026-09-12,CAMBRIC,,not a number'].join('\n'));
  ok('a movement nobody recognises is refused by line', /Line 3/.test(messy.bad.join(' ')), messy.bad.join(' | '));
  ok('…and so is a quantity that is not a number', /Line 4/.test(messy.bad.join(' ')), messy.bad.join(' | '));
  ok('…while the good line is still read', messy.rows.length === 1);
  ok('a file with no Metres column is refused outright',
     /needs a Metres column/.test(A.fabCsvRows('Movement,Fabric\nGreige received,CAMBRIC').bad.join(' ')));

  /* THE ORDER OF THE LINES IS THE ORDER THEY HAPPEN. */
  const run = await A.fabCsvRun(read.rows);
  ok('the whole file goes in', !run.err && run.done.length === 4, run.err);
  ok('…and the lots are separate', A.fabLot('SH82/A').greigeIn === 1000 && A.fabLot('SH82/B').greigeIn === 400);
  ok('…with the flow followed through the file',
     A.fabLot('SH82/A').withProcessor === 30 && A.fabLot('SH82/A').rfdLeft === 570,
     JSON.stringify(A.fabLot('SH82/A')));

  /* A FILE THAT ASKS FOR MORE THAN THERE IS STOPS AT THAT LINE, and says which. */
  const bad = A.fabCsvRows(['Movement,Date,Fabric,Lot,Metres,Who',
    'Greige sent for RFD,2026-09-17,SHEETING 82,SH82/B,100,Shree',
    'Greige sent for RFD,2026-09-17,SHEETING 82,SH82/B,9000,Shree',
    'Greige sent for RFD,2026-09-17,SHEETING 82,SH82/B,50,Shree'].join('\n'));
  const run2 = await A.fabCsvRun(bad.rows);
  ok('the file stops where the ledger refuses it', !!run2.err && /Only 300 m is left in lot/.test(run2.err), run2.err);
  ok('…naming the line it stopped at', run2.stopped && run2.stopped.line === 3, JSON.stringify(run2.stopped && run2.stopped.line));
  ok('…and what went in before it stays in', run2.done.length === 1 && A.fabLot('SH82/B').toRfd === 100,
     JSON.stringify({ done: run2.done.length, sent: A.fabLot('SH82/B').toRfd }));

  A.setFAB(wasFAB); NET.on = wasNet; ME.prodEdit = wasEdit; ME.admin = wasAdmin;
}

console.log('\n== one article, several lots ==');
{
  /* "mera 1 hi article alag alag lot me aata h." The ordinary case: one cloth, a delivery a week,
   * four lots of it on the floor at once — each with its own bill, its own processor and its own
   * loss. */
  const wasFAB = A.FAB(), wasNet = NET.on, wasEdit = ME.prodEdit, wasAdmin = ME.admin;
  ME.admin = true; ME.prodEdit = true; NET.on = true; NET.store = {};
  A.setFAB({ rows: [], err: '', busy: false, at: '', shown: [] });

  /* THREE DELIVERIES OF THE SAME CLOTH ON THE SAME DAY. Nobody typed a lot number for two of them. */
  ok('first delivery', (await A.fabSave({ txnType: 'RECEIVE_GREIGE', fabricType: 'VOIL 112', qty: 500,
    counterpartyName: 'Mill A', challan: 'B-1', date: '2026-09-12' })) === '');
  ok('second delivery, same cloth, same day', (await A.fabSave({ txnType: 'RECEIVE_GREIGE',
    fabricType: 'VOIL 112', qty: 300, counterpartyName: 'Mill B', challan: 'B-2', date: '2026-09-12' })) === '');
  ok('third, with the mill\'s own lot number', (await A.fabSave({ txnType: 'RECEIVE_GREIGE',
    fabricType: 'VOIL 112', qty: 200, lot: 'MILLA/8812', counterpartyName: 'Mill A', challan: 'B-3',
    date: '2026-09-13' })) === '');

  const lots = A.fabLotsOfFabric('VOIL 112', '');
  ok('the same cloth has three lots', lots.length === 3, JSON.stringify(lots.map(g => g.lot)));
  /* THE AUTO-NUMBER DOES NOT COLLIDE on a day with two deliveries of one cloth. */
  const autos = lots.map(g => g.lot).filter(x => /^VOIL-112-260912-/.test(x)).sort();
  ok('…two of them numbered themselves, and differently',
     autos.length === 2 && autos[0] !== autos[1], JSON.stringify(autos));
  ok('…and the mill\'s own number was kept as it was',
     lots.some(g => g.lot === 'MILLA/8812'), JSON.stringify(lots.map(g => g.lot)));
  ok('each lot carries its own bill and mill',
     lots.every(g => !!g.bill) && new Set(lots.map(g => g.bill)).size === 3,
     JSON.stringify(lots.map(g => g.lot + '=' + g.bill)));

  /* THE PICKER OFFERS THIS CLOTH'S LOTS, not everything the factory owns. */
  await A.fabSave({ txnType: 'RECEIVE_GREIGE', fabricType: 'CANVAS', qty: 100,
    counterpartyName: 'Mill C', challan: 'B-9', date: '2026-09-12' });
  ok('a different cloth is not offered', A.fabLotsOfFabric('VOIL 112', '').length === 3
     && A.fabLotsOfFabric('CANVAS', '').length === 1);

  /* AND ONLY THE LOTS THAT CAN ACTUALLY SUPPLY THE MOVEMENT. */
  const first = autos[0];
  await A.fabSave({ txnType: 'ISSUE_TO_RFD', fabricType: 'VOIL 112', lot: first, qty: 500,
    counterpartyName: 'Shree', date: '2026-09-13' });
  ok('a lot with nothing left is not offered as a source',
     !A.fabLotsOfFabric('VOIL 112', 'greige').some(g => g.lot === first),
     JSON.stringify(A.fabLotsOfFabric('VOIL 112', 'greige').map(g => g.lot)));
  ok('…and it is the one waiting to come back',
     A.fabLotsOfFabric('VOIL 112', 'out').map(g => g.lot).join() === first);
  ok('…while nothing of that cloth is RFD yet', A.fabLotsOfFabric('VOIL 112', 'rfd').length === 0);

  /* THE LOSS BELONGS TO THE LOT, WHICH IS WHY ONE CLOTH IN FOUR LOTS IS NOT ONE NUMBER. */
  await A.fabSave({ txnType: 'RECEIVE_RFD', fabricType: 'VOIL 112', lot: first, qty: 450,
    counterpartyName: 'Shree', date: '2026-09-16' });
  await A.fabSave({ txnType: 'ISSUE_TO_RFD', fabricType: 'VOIL 112', lot: 'MILLA/8812', qty: 200,
    counterpartyName: 'Other Processor', date: '2026-09-16' });
  await A.fabSave({ txnType: 'RECEIVE_RFD', fabricType: 'VOIL 112', lot: 'MILLA/8812', qty: 160,
    counterpartyName: 'Other Processor', date: '2026-09-18' });
  ok('one processor lost 10%, the other 20%, and each lot says which',
     A.fabLot(first).lossPct === 10 && A.fabLot('MILLA/8812').lossPct === 20,
     JSON.stringify([A.fabLot(first).lossPct, A.fabLot('MILLA/8812').lossPct]));
  /* The fabric's own line is the two of them together, which is a different and coarser number. */
  const flow = A.fabFlowRows(A.FAB().rows).find(g => g.fabricType === 'VOIL 112');
  ok('…and the cloth as a whole reads 12.9%', flow.lossPct === 12.9, String(flow.lossPct));

  A.setFAB(wasFAB); NET.on = wasNet; ME.prodEdit = wasEdit; ME.admin = wasAdmin;
}

console.log('\n== the attendance register ==');
{
  /* "jitne bhi tailor h mujhe unka attendance register banana h and usme me 1 bande ko assign kar
   * dunga wo daily punch out or punch in kiya karega." The employee list already holds 121 people
   * with their department — 50 of them in Stitching — so the register is that list, not a new one. */
  const wasATT = A.ATT(), wasEmp = A.PTE().emp, wasNet = NET.on, wasAdmin = ME.admin, wasMark = ME.attendMark;
  ME.admin = false; ME.attendMark = true; NET.on = true; NET.store = {};
  A.setPTE(Object.assign(A.PTE(), { emp: [
    ['Company Role', 'Rinku Koli', 'Stitching', '+919829675604'],
    ['Company Contractor', 'Sher Singh', 'Stitching', ''],
    ['Company Role', 'Kamla Devi', 'Quality Control', ''],
  ] }));
  A.setATT({ rows: [], err: '', busy: false, at: '' });
  els.attDay.value = '2026-09-12'; els.attMonth.value = '2026-09';
  ['attDept', 'attType', 'attState', 'attQ'].forEach(i => { els[i].value = ''; });
  els.attView.value = 'day';

  ok('the register is the employee list, department and all',
     A.attPeople().length === 3 && A.attPeople()[0].dept === 'Quality Control',
     JSON.stringify(A.attPeople().map(p => p.name)));

  const rinku = A.attPeople().find(p => p.name === 'Rinku Koli');
  ok('a day starts unmarked', A.attState(A.attOfDay('2026-09-12').get('RINKU_KOLI')) === 'none');

  /* PUNCHING IN, then out. The row is addressed by day and person, so it cannot be made twice. */
  ok('punching in is saved', (await A.attSave('2026-09-12', rinku, { inAt: '09:05' })) === '');
  const id = A.attId('2026-09-12', 'Rinku Koli');
  ok('…under one row for that person and that day', id === '2026-09-12__RINKU_KOLI' && !!NET.store['pt_attend/' + id], id);
  ok('…and marked present', NET.store['pt_attend/' + id].status === 'P');
  ok('punching in again writes to the SAME row, it does not make a second one',
     (await A.attSave('2026-09-12', rinku, { outAt: '18:35' })) === ''
     && Object.keys(NET.store).filter(k => /^pt_attend\//.test(k)).length === 1,
     Object.keys(NET.store).join(', '));
  const row = () => (A.ATT().rows || []).find(r => r.id === id);
  ok('the hours are the two ends, not a guess', A.attHours(row()) === 9.5, String(A.attHours(row())));

  /* A DAY THAT CANNOT HAVE HAPPENED IS NOT SAVED — payroll reads these hours. */
  const sher = A.attPeople().find(p => p.name === 'Sher Singh');
  ok('an out time with no in time is refused',
     /Punch in first/.test(await A.attSave('2026-09-12', sher, { outAt: '18:00' })));
  ok('…and nothing was written for them', !NET.store['pt_attend/' + A.attId('2026-09-12', 'Sher Singh')]);
  /* ehHours wraps past midnight, so "zero hours" never happens — 10:00 to 10:00 is 24 hours to it.
   * A day that stands still or runs backwards is a typo, and is refused as one. */
  ok('the same time in and out is refused',
     /after the in time/.test(await A.attSave('2026-09-12', sher, { inAt: '10:00', outAt: '10:00' })));
  ok('…and so is an out time before the in time, which would book most of a day',
     /after the in time/.test(await A.attSave('2026-09-12', sher, { inAt: '18:00', outAt: '09:00' })));

  /* ABSENT IS A DECISION, not an empty row: it clears the times rather than leaving half a day. */
  ok('marking absent is saved', (await A.attSave('2026-09-12', rinku, { status: 'A' })) === '');
  ok('…and takes the times off, because they cannot both be true',
     !row().inAt && !row().outAt && A.attState(row()) === 'absent', JSON.stringify(row()));

  /* THE PUNCH BUTTONS say what is wrong rather than writing nonsense. */
  await A.attPunch('Sher Singh', 'out');
  ok('punching somebody out who never came in says so', /not been punched in/.test(els.attMsg.textContent),
     els.attMsg.textContent);
  await A.attPunch('Sher Singh', 'in');
  await A.attPunch('Sher Singh', 'in');
  ok('punching in twice says when they were punched in', /already punched in/.test(els.attMsg.textContent),
     els.attMsg.textContent);

  /* THE SCREEN SHOWS EVERYBODY, INCLUDING WHO IS NOT MARKED — that is the question it exists for. */
  A.renderAtt();
  ok('every person is a line, marked or not', (els.attTable.innerHTML.match(/<tr>/g) || []).length >= 3,
     String((els.attTable.innerHTML.match(/<tr>/g) || []).length));
  ok('…and the strip counts who has not been marked', /Not marked/.test(els.attKpis.innerHTML));
  els.attDept.value = 'Stitching'; A.renderAtt();
  ok('the tailors can be shown on their own',
     /Rinku Koli/.test(els.attTable.innerHTML) && !/Kamla Devi/.test(els.attTable.innerHTML));
  els.attDept.value = '';

  /* THE MONTH adds up what the days say. */
  els.attView.value = 'month'; A.renderAtt();
  ok('the month totals the days somebody was present', /Days present/.test(els.attTable.innerHTML));
  ok('…and counts the absent day', /Days absent/.test(els.attTable.innerHTML)
     && /1/.test(els.attKpis.innerHTML), els.attKpis.innerHTML.replace(/<[^>]*>/g, ' ').slice(0, 160));
  els.attView.value = 'day';

  /* AND IT IS A GRANT OF ITS OWN — the person who takes attendance needs nothing else. */
  ME.attendMark = false; ME.admin = false;
  ok('without the grant nobody can mark it', !A.attCanMark()
     && /needs permission/.test(await A.attSave('2026-09-12', rinku, { inAt: '09:00' })));
  ME.admin = true;
  ok('…and an admin has it without being given it', A.attCanMark());

  A.setATT(wasATT); A.setPTE(Object.assign(A.PTE(), { emp: wasEmp }));
  NET.on = wasNet; ME.admin = wasAdmin; ME.attendMark = wasMark;
}

console.log('\n== pieces come back from the tailor ==');
{
  /* The bit of Vimal's QC screen that is not here — and was never used there either: pt_qcReturns was
   * declared in the old tool and never written once. On the live data that leaves 250 pieces flagged
   * for alteration, all 250 issued, none booked back, 155 of them with one man. */
  const wasQC = A.QC(), wasNet = NET.on, wasEdit = ME.prodEdit, wasAdmin = ME.admin, wasEmp = A.PTE().emp;
  ME.admin = true; ME.prodEdit = true; NET.on = true; NET.store = {};
  A.setPTE(Object.assign(A.PTE(), { emp: [['Company Contractor', 'Kamla Devi', 'Quality Control', '']] }));
  A.setQC({ checks: [{ id: 'q1', sku: 'ALT-A', checked: 20, forAlteration: 11, rejected: 0, ok: 9,
      date: '10/09/2026, 10:00', checkedBy: 'Kamla Devi' }],
    issue: [{ id: 'i1', sku: 'ALT-A', pieces: 11, employee: 'Pradeep Contractor',
      employmentType: 'External Contractor', date: '10/09/2026, 12:00',
      articleType: 'Pillow Cover', subtype: 'Ruffle Pillow Cover', color: 'Sea Green', size: '18x18' }],
    ret: [], err: '', busy: false, at: '' });

  ok('eleven went out and nothing has come back', A.qcRetOf('i1') === 0 && A.qcPendingOf(A.QC().issue[0]) === 11);
  ok('…so it is on the list of what to chase', A.qcOutstanding().length === 1);

  els.qcrPick.value = 'i1'; els.qcrBy.value = 'Kamla Devi';
  els.qcrPcs.value = '7'; els.qcrOk.value = '5'; els.qcrRej.value = '2'; els.qcrRemarks.value = '';
  await A.qcSaveReturn();

  const saved = Object.entries(NET.store).find(([k]) => /^pt_qcReturns\//.test(k));
  ok('the receipt is written', !!saved, Object.keys(NET.store).join(', '));
  const row = saved ? saved[1] : {};
  ok('…against the issuance it settles, not just the SKU', row.issuanceId === 'i1' && row.sku === 'ALT-A');
  ok('…with the split that says whether the work was done',
     row.received === 7 && row.reworkedOk === 5 && row.stillRejected === 2, JSON.stringify(row));
  ok('…and who it came from and who took it in',
     row.employee === 'Pradeep Contractor' && row.receivedBy === 'Kamla Devi');
  ok('what is still out comes down', A.qcPendingOf(A.QC().issue[0]) === 4, String(A.qcPendingOf(A.QC().issue[0])));

  /* MORE BACK THAN WENT OUT would be somebody else's pieces. */
  els.qcrPcs.value = '9'; els.qcrOk.value = ''; els.qcrRej.value = '';
  await A.qcSaveReturn();
  ok('more than is out with them is refused', /Only 4 piece/.test(els.qcrMsg.textContent), els.qcrMsg.textContent);

  /* A SPLIT THAT DOES NOT ADD UP is not a rounding matter — it means one of the three numbers is
   * wrong, and whichever it is, the register would be too. */
  els.qcrPcs.value = '4'; els.qcrOk.value = '1'; els.qcrRej.value = '1';
  await A.qcSaveReturn();
  ok('a split that does not add up is refused', /must equal what came back/.test(els.qcrMsg.textContent),
     els.qcrMsg.textContent);

  /* …but it may be left blank: pieces came back and nobody has looked at them yet. */
  els.qcrPcs.value = '4'; els.qcrOk.value = ''; els.qcrRej.value = '';
  await A.qcSaveReturn();
  ok('coming back without a verdict is allowed', A.qcPendingOf(A.QC().issue[0]) === 0,
     String(A.qcPendingOf(A.QC().issue[0])));
  ok('…and then nothing is out with them any more', A.qcOutstanding().length === 0);

  /* The picker only ever offers what is really out. */
  A.renderQcRetForm();
  ok('the picker is empty once everything is back', !/i1/.test(els.qcrPick.innerHTML), els.qcrPick.innerHTML);

  /* Entering is one thing; this is a correction to somebody else's record of what they sent. */
  ME.prodEdit = false; ME.admin = false;
  els.qcrPcs.value = '1';
  await A.qcSaveReturn();
  ok('somebody without permission cannot book pieces back', /permission/i.test(els.qcrMsg.textContent),
     els.qcrMsg.textContent);

  A.setQC(wasQC); A.setPTE(Object.assign(A.PTE(), { emp: wasEmp }));
  NET.on = wasNet; ME.prodEdit = wasEdit; ME.admin = wasAdmin;
}

console.log('\n== an order can be moved to another printer ==');
{
  /* "koi current vendor order kis dusre printer ko shuffle krna chahta hu … usko portal se order
   * remove hokr me jisko assign karu wo ho jay but uska kuch record mere pas rahe."
   *
   * An order does not hold the printer's name — it LIVES under their code, which is the only branch
   * the rules let that printer read. So moving it is a write to the new branch and a delete from the
   * old, and anything less leaves it sitting in the first printer's portal. */
  const wasVO = A.VO(), wasNet = NET.on, wasAdmin = ME.admin, wasVend = (A.PTG().masters || {}).vendor;
  ME.admin = true; NET.on = true; NET.store = {}; NET.calls.length = 0;
  A.setPTG(Object.assign(A.PTG(), { masters: Object.assign({}, A.PTG().masters, { vendor: [
    { code: 'VND001', name: 'RBP-Bagru', category: 'Printer', active: true },
    { code: 'VND003', name: 'SS Hand Block', category: 'Printer', active: true }] }) }));
  const order = () => ({ id: 'vpo_m1', orderNo: 'VPO-260912-MOV', vendorCode: 'VND001',
    status: 'Placed', orderType: 'cut', service: 'Block print', orderDate: '12/09/2026',
    createdAt: '2026-09-12T05:00:00.000Z', vendorName: 'RBP-Bagru',
    lines: [{ lineId: 'l1', sku: 'MOV-A', qty: 40, kind: 'cut', dispatchedQty: 0 }] });
  A.setVO(Object.assign({}, wasVO, { rows: [order()] }));

  ok('it moves', (await A.voMoveTo('VND001/vpo_m1', 'VND003', 'Bagru is full this week')) === '');
  /* GONE FROM ONE PORTAL, IN THE OTHER — the two halves of the same act. */
  ok('…it is written into the new printer\'s branch',
     !!NET.store['pt_vendorOrders/VND003/vpo_m1'], Object.keys(NET.store).join(', '));
  ok('…and deleted from the old one',
     NET.calls.some(c => c.method === 'DELETE' && /pt_vendorOrders\/VND001\/vpo_m1/.test(c.url)),
     NET.calls.filter(c => c.method === 'DELETE').map(c => c.url.split('.app/')[1]).join(' '));
  ok('…keeping its number and its lines',
     NET.store['pt_vendorOrders/VND003/vpo_m1'].orderNo === 'VPO-260912-MOV'
     && (NET.store['pt_vendorOrders/VND003/vpo_m1'].lines || []).length === 1);
  ok('…and on screen it now belongs to the new printer',
     (A.VO().rows || []).length === 1 && A.VO().rows[0].vendorCode === 'VND003',
     JSON.stringify((A.VO().rows || []).map(x => x.vendorCode)));

  /* THE RECORD. Who had it, who has it, when, by whom and why — every move, not just the last. */
  const moved = A.VO().rows[0];
  const log = A.voMoveLog(moved);
  ok('the move is written on the order', log.length === 1, JSON.stringify(log));
  ok('…naming where it came from and where it went',
     log[0].from === 'VND001' && log[0].to === 'VND003'
     && log[0].fromName === 'RBP-Bagru' && log[0].toName === 'SS Hand Block', JSON.stringify(log[0]));
  ok('…who moved it and why', log[0].by === ME.email && log[0].why === 'Bagru is full this week');
  ok('…and the row says so without opening anything', /moved .*from RBP-Bagru/.test(A.voMovePill(moved)),
     A.voMovePill(moved));

  /* A SECOND MOVE KEEPS THE FIRST. */
  NET.calls.length = 0;
  ok('it can be moved again', (await A.voMoveTo('VND003/vpo_m1', 'VND001', 'back again')) === '');
  ok('…and both moves are on the record', A.voMoveLog(A.VO().rows[0]).length === 2,
     JSON.stringify(A.voMoveLog(A.VO().rows[0]).map(m => m.fromName + '>' + m.toName)));

  /* WHAT IT REFUSES. */
  ok('it will not move to the printer that already has it',
     /already with/.test(await A.voMoveTo('VND001/vpo_m1', 'VND001')));
  ok('…nor to somebody who is not in the vendor master',
     /not in the vendor master/.test(await A.voMoveTo('VND001/vpo_m1', 'VND999')));
  ok('…nor with no printer picked', /Pick the printer/.test(await A.voMoveTo('VND001/vpo_m1', '')));

  /* ANYTHING ALREADY SENT STAYS WHERE IT WAS SENT FROM: moving it would hand one printer's dispatches
   * to another and take the first one's own record away. */
  A.setVO(Object.assign({}, A.VO(), { rows: [Object.assign(order(), { lines: [
    { lineId: 'l1', sku: 'MOV-A', qty: 40, kind: 'cut', dispatchedQty: 0,
      deliveries: [{ date: '11/09/2026', qty: 12 }] }] })] }));
  const no = await A.voMoveTo('VND001/vpo_m1', 'VND003');
  ok('an order that has been part-delivered is not moved', /already sent/.test(no), no);
  ok('…and it says how much, and what to do instead', /12 pcs of MOV-A/.test(no) && /raise a new one/.test(no), no);
  ok('…and nothing was written', !NET.calls.some(c => c.method === 'DELETE'
     && /pt_vendorOrders\/VND001/.test(c.url)), 'a delete went out anyway');

  /* And it is an admin's decision. */
  ME.admin = false;
  ok('somebody who is not an admin cannot move an order',
     /Only an admin/.test(await A.voMoveTo('VND001/vpo_m1', 'VND003')));

  A.setVO(wasVO); NET.on = wasNet; ME.admin = wasAdmin;
  A.setPTG(Object.assign(A.PTG(), { masters: Object.assign({}, A.PTG().masters, { vendor: wasVend }) }));
}

console.log('\n== the printer is shown the oldest order first ==');
{
  /* "always vendor ko old to new order dikhe." Newest-first suits somebody watching what comes in; a
   * printer is working through a pile, and a pile is worked from the bottom. */
  const o = (id, iso, date) => ({ id, orderNo: id, status: 'Placed', orderType: 'cut',
    createdAt: iso, orderDate: date, lines: [{ lineId: id + 'l', sku: 'S-' + id, qty: 1, kind: 'cut' }] });
  const rows = [
    o('VPO-C', '2026-09-10T09:00:00.000Z', '10/09/2026'),
    o('VPO-A', '2026-09-01T09:00:00.000Z', '01/09/2026'),
    o('VPO-B', '2026-09-05T09:00:00.000Z', '05/09/2026'),
  ];
  ok('oldest at the top, newest at the bottom',
     A.vpVisible(rows).map(x => x.orderNo).join(' ') === 'VPO-A VPO-B VPO-C',
     A.vpVisible(rows).map(x => x.orderNo).join(' '));

  /* AN ORDER WITH NO createdAt still has to land in the right place — plenty carry only orderDate,
   * and read as text "01/12/2026" sorts before "02/01/2026", which is the wrong year entirely. */
  const noIso = [
    Object.assign(o('VPO-DEC', '', '01/12/2026'), { createdAt: '' }),
    Object.assign(o('VPO-JAN', '', '02/01/2026'), { createdAt: '' }),
  ];
  ok('a day-first date is read as a date, not as text',
     A.vpVisible(noIso).map(x => x.orderNo).join(' ') === 'VPO-JAN VPO-DEC',
     A.vpVisible(noIso).map(x => x.orderNo).join(' '));
  ok('…and the two ways of saying when agree', A.voWhenMs({ createdAt: '2026-09-05T00:00:00.000Z' })
     > A.voWhenMs({ orderDate: '01/09/2026' }));

  /* THE DUPLICATE RULE MUST NOT HAVE FLIPPED WITH THE SORT. Two rows under one number mean the order
   * was written twice and the later one is the truth — that used to ride on the sort direction. */
  const dupes = [
    Object.assign(o('VPO-D', '2026-09-02T09:00:00.000Z', '02/09/2026'), { notes: 'the stale one' }),
    Object.assign(o('VPO-D', '2026-09-09T09:00:00.000Z', '09/09/2026'), { notes: 'the real one' }),
    o('VPO-E', '2026-09-06T09:00:00.000Z', '06/09/2026'),
  ];
  const got = A.vpVisible(dupes);
  ok('a duplicated order still shows the newer copy', got.filter(x => x.orderNo === 'VPO-D').length === 1
     && got.find(x => x.orderNo === 'VPO-D').notes === 'the real one',
     JSON.stringify(got.map(x => x.orderNo + ':' + (x.notes || ''))));
  ok('…and it sits where its own date puts it, which is last',
     got.map(x => x.orderNo).join(' ') === 'VPO-E VPO-D', got.map(x => x.orderNo).join(' '));

  /* Cancelled and unapproved orders are still kept out — the sort did not change what is shown. */
  ok('a cancelled order is still not shown',
     A.vpVisible([Object.assign(o('VPO-X', '2026-09-03T09:00:00.000Z', '03/09/2026'), { status: 'Cancelled' })]).length === 0);
}

console.log('\n== a printer can see what they sent, and what was kept ==');
{
  /* "vendor apni history bhi dekh pay ki wo kya bhej raha h and uska kitna mal reject hua h but wo
   * sirf apna hi history dekh pay."
   *
   * Both halves are already on record — the printer's claim as they typed it, and the acceptance
   * written beside it. Only the factory could see them. */
  const wasVP = A.VP(), wasAdmin = ME.admin;
  ME.admin = false;
  const del = (date, qty, ok, no) => Object.assign({ date, qty, by: 'p@x', at: date }, ok ? { ok } : {}, no ? { no } : {});
  A.setVP(Object.assign({}, wasVP, { code: 'VND001', name: 'RBP-Bagru', err: '', busy: false, tab: 'hist',
    rows: [{ id: 'h1', orderNo: 'VPO-260901-AAA', status: 'Partially Dispatched', orderType: 'cut',
      vendorName: 'RBP-Bagru', orderDate: '01/09/2026', lines: [
        /* accepted short: 20 went, 18 were kept */
        { lineId: 'a', sku: 'HIS-A', qty: 50, kind: 'cut', articleSubtype: 'Ruffle Pillow Cover',
          color: 'Sea Green', size: '18x18',
          deliveries: [del('05/09/2026', 20, { qty: 18, by: 'ravi@x', at: '2026-09-05T10:00:00Z', note: 'two stained' })] },
        /* accepted in full */
        { lineId: 'b', sku: 'HIS-B', qty: 10, kind: 'cut', articleSubtype: 'Quilt', color: 'Indigo', size: 'King',
          deliveries: [del('06/09/2026', 10, { qty: 10, by: 'ravi@x', at: '2026-09-06T10:00:00Z' })] },
        /* nobody has answered it yet */
        { lineId: 'c', sku: 'HIS-C', qty: 8, kind: 'cut', articleSubtype: 'Runner', color: 'Rust', size: '14x72',
          deliveries: [del('07/09/2026', 8)] },
        /* and one the factory says never turned up */
        { lineId: 'd', sku: 'HIS-D', qty: 5, kind: 'cut', articleSubtype: 'Napkin', color: 'Olive', size: '20x20',
          deliveries: [del('08/09/2026', 5, null, { by: 'ravi@x', at: '2026-09-09T10:00:00Z', note: 'never came' })] },
      ] }] }));
  els.vpQ.value = '';
  A.renderVp();
  const h = A.vpHistRows();
  const by = s => h.find(r => r.sku === s) || {};

  ok('every delivery they recorded is there', h.length === 4, String(h.length));
  ok('what they SENT is what they typed, untouched', by('HIS-A').sent === 20 && by('HIS-D').sent === 5);
  ok('what was KEPT is what the factory accepted', by('HIS-A').kept === 18 && by('HIS-B').kept === 10);
  /* THE SHORTFALL IS THE ANSWER TO "kitna mal reject hua" — sent minus accepted, and nothing else. */
  ok('the shortfall is sent minus accepted', by('HIS-A').short === 2 && by('HIS-B').short === 0);
  /* AND AN UNANSWERED DELIVERY IS NOT A REJECTION. Calling it one would accuse the factory of
   * refusing goods nobody has even counted yet. */
  ok('a delivery nobody has checked is waiting, not rejected',
     by('HIS-C').kept === null && by('HIS-C').short === 0);
  ok('…and one marked as never arrived counts as nothing kept',
     by('HIS-D').kept === 0 && by('HIS-D').short === 5 && by('HIS-D').no === true);

  const html = els.vpBody.innerHTML;
  ok('the screen says which is which', /2 short/.test(html) && /accepted in full/.test(html)
     && /waiting to be checked/.test(html) && /did not arrive/.test(html), html.slice(0, 0) || 'a status is missing');
  ok('…and carries the note the factory left', /two stained/.test(html));
  ok('the strip adds up what went and what was kept',
     /43 pcs/.test(els.vpKpis.innerHTML) && /28 pcs/.test(els.vpKpis.innerHTML),
     els.vpKpis.innerHTML.replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').slice(0, 200));

  /* ONLY THEIRS, AND NOT BECAUSE THE SCREEN SAYS SO. It is built from VP.rows, which is one read of
   * their own branch — the rules refuse a vendor the root, so there is nothing else to read. */
  ok('it is built from their own orders and nothing else',
     A.vpHistRows().every(r => r.orderNo === 'VPO-260901-AAA'));
  A.setVP(Object.assign({}, A.VP(), { rows: [] }));
  ok('…so with no orders of their own there is no history at all', A.vpHistRows().length === 0);

  A.setVP(wasVP); ME.admin = wasAdmin;
}

console.log('\n== a refused order says who is holding the pieces ==');
{
  /* Ravi cancelled every order with the printer he was raising this one for, and was still refused.
   * The cap was right — the pieces sat on somebody else's order, VPO-260825-FJZ with SS Hand Block,
   * raised on 25 August and still open. The message did not say so, so there was nothing to act on. */
  const wasVO = A.VO(), wasSOX = A.SOX();
  /* The vendor list ONLY, kept by itself: Object.assign on PTG changes the object the test is
   * holding, so a "copy" of the whole thing is the same thing and restores nothing. */
  const wasVend = (A.PTG().masters || {}).vendor;
  A.setSOX({ rows: [{ _id: 'SO-1', status: 'approved', lines: [{ sku: 'CAP-A', qty: 15 }] }],
    err: '', busy: false, at: '', shown: [] });
  A.setPTG(Object.assign(A.PTG(), { masters: Object.assign({}, A.PTG().masters, { vendor: [
    { code: 'VND003', name: 'SS Hand Block', category: 'Printer', active: true },
    { code: 'VND001', name: 'RBP-Bagru', category: 'Printer', active: true }] }) }));
  A.setVO(Object.assign({}, wasVO, { rows: [
    /* The one he cancelled — it must stop counting, and it must not be named as a holder either. */
    { id: 'o_dead', orderNo: 'VPO-CANCELLED', vendorCode: 'VND001', status: 'Cancelled',
      service: 'Block print', orderDate: '01/09/2026', lines: [{ lineId: 'd1', sku: 'CAP-A', qty: 15, kind: 'cut' }] },
    /* …and the one that is really holding the pieces. */
    { id: 'o_live', orderNo: 'VPO-260825-FJZ', vendorCode: 'VND003', status: 'Placed',
      service: 'Block print', orderDate: '25/08/2026', lines: [{ lineId: 'l1', sku: 'CAP-A', qty: 15, kind: 'cut' }] },
  ] }));

  const bad = A.voValidateCut([{ sku: 'CAP-A', qty: 8 }]);
  ok('the cap still refuses, because somebody else is holding them', bad.length === 1, JSON.stringify(bad));
  const msg = A.voCapMsg(bad[0]);
  ok('…and the refusal names the order', /VPO-260825-FJZ/.test(msg), msg);
  ok('…and the printer holding it', /SS Hand Block/.test(msg), msg);
  ok('…with how many and since when', /15 with SS Hand Block on VPO-260825-FJZ \(25\/08\/2026\)/.test(msg), msg);
  /* THE CANCELLED ORDER IS NOT NAMED. Sending somebody to cancel what they already cancelled is
   * worse than saying nothing. */
  ok('…and never names an order that was already cancelled', !/VPO-CANCELLED/.test(msg), msg);
  ok('the figures themselves are unchanged', /asks for 15/.test(msg.replace('approved orders ask', 'asks'))
     && /making 23/.test(msg), msg);

  /* And with the real holder cancelled too, the same order goes through. */
  A.setVO(Object.assign({}, A.VO(), { rows: A.VO().rows.map(o =>
    o.id === 'o_live' ? Object.assign({}, o, { status: 'Cancelled' }) : o) }));
  ok('cancel the order that was really holding them and it is allowed',
     A.voValidateCut([{ sku: 'CAP-A', qty: 8 }]).length === 0);
  ok('…and nobody is listed as holding it any more', A.voHolders('CAP-A').length === 0,
     JSON.stringify(A.voHolders('CAP-A')));

  A.setVO(wasVO); A.setSOX(wasSOX);
  A.setPTG(Object.assign(A.PTG(), { masters: Object.assign({}, A.PTG().masters, { vendor: wasVend }) }));
}

console.log('\n== the register is in the order it is worked ==');
{
  /* Ravi gave the sequence himself. Written down here because a column order is the one thing a
   * later edit can scramble without breaking anything — the page still renders, the figures are
   * still right, and the person typing receipts all day is the one who finds out. */
  /* 2026-09-22: the same sequence in fewer columns — Employee+Type, SKU+Image+Subtype+Color+Size and
   * Receiving Date+Status each share one cell. Nothing dropped, nothing moved. */
  /* Third pass: pending and rejected live in Status; who entered it and remarks are last. */
  /* Fifth pass (Ravi's picture, 2026-09-22): a tick box first, both quantities in pieces, a progress ring. */
  const WANT = ['', 'Issue Date', 'Karigar', 'Item',
    'Qty Issued', 'Qty Received', 'Progress', 'Status', 'Actions', 'Entered by'];
  const wasBase = A.PT().base;
  A.setPT(Object.assign(A.PT(), { base: [
    { id: 'c1', sku: 'COL-A', empName: 'Ramesh', empType: 'Company Contractor', issuePieces: 10,
      receivedPieces: 4, pendingPieces: 6, rejectionPieces: 1, issueDate: '12/09/2026, 11:00',
      articleType: 'Pillow Cover', articleSubtype: 'Ruffle Pillow Cover', color: 'Sea Green',
      size: '18x18', addedBy: 'vikas.mahawar@thefabricrush.com' }] }));
  ['pbType', 'pbEmp', 'pbWho', 'pbArt', 'pbSub', 'pbCol', 'pbSz', 'pbStatus', 'pbQ', 'pbD1', 'pbD2']
    .forEach(i => { els[i].value = ''; });
  A.setBdKpi('');
  A.renderPbase();
  const html = els.pbTable.innerHTML;
  /* <th[^>]*> also matches <thead>, which dropped the whole opening tag into the first column name. */
  const heads = [...html.matchAll(/<th(?:\s[^>]*)?>(.*?)<\/th>/g)].map(m => m[1]).map(h => (/^<input/.test(h) ? '' : h));
  ok('the columns are in the order asked for', heads.join(' | ') === WANT.join(' | '), heads.join(' | '));
  /* A HEADER THAT PROMISES MORE THAN THE ROW DELIVERS silently shifts every figure one column left,
   * which is how a "received" figure ends up under "receive". */
  const cells = (html.match(/<tbody>([\s\S]*)<\/tbody>/) || ['', ''])[1];
  ok('…and the row has exactly that many cells',
     (cells.match(/<td/g) || []).length === WANT.length,
     String((cells.match(/<td/g) || []).length) + ' cells for ' + WANT.length + ' columns');
  /* The box you type a receipt into sits beside the figure it adds to — that is the whole point of
   * the move. */
  ok('quantities read in pieces, with a progress ring, and no boxes are left on the row',
     /[\d,]+ <span class="jw-u">pcs<\/span>/.test(cells) && /class="jw-ring"/.test(cells) && !/pt-recv-in|pt-rej-in/.test(cells));
  ok('…taking a receipt is one Receive button in Actions', /data-bd-recv="/.test(cells) && heads[8] === 'Actions');
  ok('…and every row can be picked', /class="jw-pick" data-id="/.test(cells) && /class="jw-pickall"/.test(html));
  /* THE EXPORT IS RAVI'S PIVOT SOURCE (2026-09-22: "export karu to data pahle jese hi chahiye"). The
   * screen may merge columns; the file keeps every field in its own column, in this order. */
  {
    const src = fs.readFileSync(APP, 'utf8');
    const m = src.match(/\$\('pbExport'\)\.onclick = \(\) => \{[\s\S]*?const lines = \[\[([^\]]*)\]/);
    const cols = m ? m[1].split(',').map(x => x.trim().replace(/^'|'$/g, '')).filter(Boolean) : [];
    ok('Export keeps one column per field, as before', cols.join('|') === ['Issue Date', 'Employee', 'Employment type', 'SKU', 'Article', 'Subtype',
      'Color', 'Size', 'Issued', 'Received', 'Rejected', 'Pending', 'Receiving Date', 'Status', 'Remarks', 'Entered by'].join('|'), cols.join('|'));
  }
  /* NOTHING DROPPED IN THE MERGE: every value the old columns showed is still in the rows. */
  {
    const shown = A.PT()._pbaseRows || [];
    const escd = v => String(v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
    const lost = [];
    shown.forEach(r => ['empType', 'articleSubtype', 'color', 'size', 'receivingDate', 'sku', 'empName', 'remarks'].forEach(k => {
      if (r[k] && cells.indexOf(escd(r[k])) < 0) lost.push(k + '=' + r[k]);
    }));
    ok('merging the columns lost nothing', shown.length > 0 && !lost.length, lost.slice(0, 5).join(', '));
    /* PENDING AND REJECTED, NOW ONLY IN STATUS: every row that has them still says so. */
    const miss = shown.filter(r => (A.ptNum(r.rejectionPieces) > 0 && cells.indexOf(A.ptNum(r.rejectionPieces) + ' rejected') < 0)
      || (!r.frozen && A.ptNum(r.pendingPieces) > 0 && cells.indexOf(A.ptNum(r.pendingPieces) + ' pending') < 0)).map(r => r.id);
    ok('pending and rejected are still shown, in Status', !miss.length, miss.join(','));
  }
  ok('article is gone from the row, and the subtype still says what it is',
     /Ruffle Pillow Cover/.test(cells) && !/>Pillow Cover</.test(cells));
  /* And the article filter it was dropped in favour of still narrows the register. */
  els.pbArt.value = 'Pillow Cover';
  A.renderPbase();
  ok('…and narrowing by article still works, which is why the column could go',
     /COL-A/.test(els.pbTable.innerHTML));
  els.pbArt.value = 'Quilt';
  A.renderPbase();
  ok('…both ways', !/COL-A/.test(els.pbTable.innerHTML));

  els.pbArt.value = '';
  A.setPT(Object.assign(A.PT(), { base: wasBase }));
  A.renderPbase();
}

console.log('\n== who entered it, and who changed it afterwards ==');
{
  /* Every row has carried addedBy and lastEditedBy all along; there was no way to LOOK. On the real
   * data 1,886 of 1,926 Base Data rows are Vikas's and 205 have been edited since — an edit moves the
   * order balance, the cutting cap, the weekly report and somebody's pay, and left no mark here. */
  const wasBase = A.PT().base;
  const rows = [
    { id: 'w1', sku: 'W-A', empName: 'Ramesh', empType: 'Company Contractor', issuePieces: 5,
      issueDate: '10/09/2026, 10:00', addedBy: 'vikas.mahawar@thefabricrush.com' },
    { id: 'w2', sku: 'W-B', empName: 'Suresh', empType: 'Company Contractor', issuePieces: 7,
      issueDate: '10/09/2026, 11:00', addedBy: 'vimal@thefabricrush.com',
      lastEditedBy: 'vikas.mahawar@thefabricrush.com', lastEditedAt: '2026-09-11T06:30:00.000Z' },
  ];
  A.setPT(Object.assign(A.PT(), { base: rows }));
  ['pbType', 'pbEmp', 'pbWho', 'pbArt', 'pbSub', 'pbCol', 'pbSz', 'pbStatus', 'pbQ', 'pbD1', 'pbD2']
    .forEach(i => { els[i].value = ''; });
  A.setBdKpi('');
  A.renderPbase();
  const html = () => els.pbTable.innerHTML;

  ok('the register says who entered each row', /vikas\.mahawar/.test(html()) && /vimal/.test(html()), html().slice(0, 0) || 'neither name');
  /* THE EDIT IS THE PART WORTH FINDING. Entering is open to everyone who can reach the register;
   * changing a row somebody has already counted on is not. */
  ok('…and marks the one somebody changed afterwards', /edited/.test(html()));
  ok('…naming who changed it and when',
     /Changed by vikas\.mahawar@thefabricrush\.com on 2026-09-11/.test(html()),
     (html().match(/title="Changed[^"]*"/) || [''])[0]);
  ok('a row nobody has touched since is not marked', (html().match(/edited/g) || []).length === 1);

  /* The picker offers the people who are really on these rows — entered or edited, nobody else. */
  ok('the picker lists everyone who touched these rows',
     A.whoList(rows).join(' ') === 'vikas.mahawar@thefabricrush.com vimal@thefabricrush.com',
     A.whoList(rows).join(' '));

  els.pbWho.value = 'vimal@thefabricrush.com';
  A.renderPbase();
  ok('picking a person narrows the register to what they entered',
     /W-B/.test(html()) && !/W-A/.test(html()));

  /* AND WHAT THEY CHANGED, which is the question being asked. Vikas did not ENTER w2; he edited it,
   * and a register that hid that would answer "who touched this" wrongly. */
  els.pbWho.value = 'vikas.mahawar@thefabricrush.com';
  A.renderPbase();
  ok('…and includes a row they only edited', /W-A/.test(html()) && /W-B/.test(html()), html().slice(0, 0) || 'missing one');

  els.pbWho.value = '';
  A.setPT(Object.assign(A.PT(), { base: wasBase }));
  A.renderPbase();
}

console.log('\n== handing work to a printer is its own permission ==');
{
  /* "jis person ko authorize kru ki ye printing par de sakta h wo only shopify orders ke liye printer
   * assign kar sake" — it was admin-only, which meant handing over deletions, payroll and rates so
   * that somebody could do one job. */
  const wasAdmin = ME.admin, wasAssign = ME.shopAssign, wasVP = A.VP(), wasOb = A.PTG().ob,
    wasSp = A.PTG().shopProd, wasNet = NET.on;
  NET.on = true; NET.store = {};
  A.setPTG(Object.assign(A.PTG(), { shopProd: {}, ob: [
    { id: 'p1', orderNo: 'SHP-7001', sku: 'PERM-A', qty: 3, src: 'SHP', orderDate: '2026-09-01' }] }));
  A.setVP(Object.assign({}, wasVP, { code: null }));

  ME.admin = false; ME.shopAssign = false;
  ok('without the grant, nobody can hand a line out', !A.spCanAssign());
  const no = await A.spAssign('SHP-7001', 'PERM-A', 'VND001');
  ok('…and it is refused in words that say what to ask for', /needs permission/.test(no), no);
  ok('…and nothing was written', !Object.keys(NET.store).some(k => /pt_vendorOrders/.test(k)),
     Object.keys(NET.store).join(', '));

  ME.shopAssign = true;
  ok('with the grant, they can', A.spCanAssign() && (await A.spAssign('SHP-7001', 'PERM-A', 'VND001')) === '');
  ok('…and the printer has it', !!NET.store['pt_vendorOrders/VND001/' + A.spShopOrderId('VND001')]);

  /* IT GRANTS ONE THING. The grant does not make anybody an admin, so what is admin-only stays so. */
  ok('…but it does not make them an admin', ME.admin === false);
  ok('…so they still cannot answer a deletion request',
     /Only an admin/.test(await A.apvAnswer('anything', true)));

  /* A PRINTER NEVER HAS IT, whatever is ticked: deciding who prints what is not theirs to do. */
  A.setVP(Object.assign({}, A.VP(), { code: 'VND001' }));
  ok('a printer cannot hand work out even with the box ticked', !A.spCanAssign());
  A.setVP(Object.assign({}, A.VP(), { code: null }));

  ME.admin = wasAdmin; ME.shopAssign = wasAssign;
  A.setPTG(Object.assign(A.PTG(), { ob: wasOb, shopProd: wasSp }));
  A.setVP(wasVP); NET.on = wasNet;
}

console.log('\n== the printer\'s custom orders, combined but still traceable ==');
{
  /* "shopify ke order ek custom order tab me with order number dikhane chahiye and yadi same product
   * h to wo combine hokar dikhana chahye jisase order wise tracking ho sake."
   *
   * A bulk order is one number for a hundred pieces. Shopify work is fifty orders of one piece, and
   * read line by line a printer prints the same cloth five times over. Combined for printing, split
   * for delivering. */
  const wasVP = A.VP(), wasNet = NET.on, wasAdmin = ME.admin;
  ME.admin = false; NET.on = true; NET.store = {};
  const line = (o, ref, sku, qty, colour) => ({ lineId: 'ln_' + o + '_' + sku, shopKey: o + '__' + sku,
    shopOrderNo: o, shopRef: ref, sku, qty, kind: 'cut', priority: 'P1', color: colour,
    size: '80X120', articleType: 'Tablecloth', articleSubtype: 'Rectangular Tablecloth', dispatchedQty: 0 });
  const shop = { id: 'vpo_shop_VND001', orderNo: 'VPO-SHOP-VND001', orderType: 'cut',
    status: 'In Production', demandSource: 'shopify', vendorName: 'RBP-Bagru', orderDate: '12/09/2026',
    lines: [
      line('SHP-3538', '#3538', 'RTC350-80120', 1, 'Dark Salmon Pink'),
      line('SHP-3589', '#3589', 'RTC350-80120', 2, 'Dark Salmon Pink'),
      line('SHP-3600', '#3600', 'RTCR384-90', 1, 'Sea Green'),
    ] };
  const bulk = { id: 'vpo_1', orderNo: 'VPO-260911-BRG', orderType: 'cut', status: 'In Production',
    vendorName: 'RBP-Bagru', orderDate: '11/09/2026',
    lines: [{ lineId: 'x', sku: 'RTC0009-5270', qty: 10, kind: 'cut', priority: 'P1',
      color: 'Indigo Floral', size: '52x70', dispatchedQty: 0 }] };
  ['vpStatus', 'vpType', 'vpAt', 'vpSub', 'vpCol', 'vpSz', 'vpPri', 'vpQ'].forEach(i => { els[i].value = ''; });
  A.setVP(Object.assign({}, wasVP, { code: 'VND001', name: 'RBP-Bagru', rows: [bulk, shop],
    err: '', busy: false, tab: 'bulk' }));
  A.renderVp();

  ok('the custom tab says how much is waiting on it', /Custom orders \(1\)/.test(els.vpTabShop.textContent),
     els.vpTabShop.textContent);
  ok('…and the bulk tab is the one on screen', /VPO-260911-BRG/.test(els.vpBody.innerHTML)
     && !/VPO-SHOP-VND001/.test(els.vpBody.innerHTML));

  A.setVP(Object.assign({}, A.VP(), { tab: 'shop' }));
  A.renderVp();
  const html = els.vpBody.innerHTML;
  ok('the custom tab holds the Shopify work, and only that',
     /VPO-SHOP-VND001/.test(html) && !/VPO-260911-BRG/.test(html));
  /* ONE ROW PER PRODUCT. Two customer orders for the same tablecloth are one thing to print. */
  const skuCells = s => (html.match(new RegExp('>' + s + '</td>', 'g')) || []).length;
  ok('the same product is one row, not two', skuCells('RTC350-80120') === 1, String(skuCells('RTC350-80120')));
  ok('…with the pieces added up', /3 <span class="muted"[^>]*>pcs<\/span>/.test(html), html.slice(0, 0) || 'no 3 pcs cell');
  /* AND STILL TRACEABLE. The order numbers are on the row — that is the whole point of combining. */
  ok('…and every customer order named on it', /#3538/.test(html) && /#3589/.test(html));
  ok('a product ordered once is still its own row', skuCells('RTCR384-90') === 1, String(skuCells('RTCR384-90')));

  /* One date on the row is the date for every order on it: printed together, finished together. */
  Object.keys(QS).forEach(k => delete QS[k]);
  QS['[data-vpmsg="vpo_shop_VND001"]'] = { className: '', textContent: '' };
  QS['[data-vppromg="vpo_shop_VND001"]'] = [{ value: '2026-09-20',
    getAttribute: k => (k === 'data-ix' ? '0,1' : null) }];
  els.vpPromDate.value = '';
  await A.vpPromiseAll();
  const back2 = (A.VP().rows || []).find(o => o.id === 'vpo_shop_VND001') || {};
  const ln2 = A.voLines(back2);
  ok('a date on the combined row covers every order on it',
     A.voProm(ln2[0]) === '2026-09-20' && A.voProm(ln2[1]) === '2026-09-20',
     A.voProm(ln2[0]) + ' / ' + A.voProm(ln2[1]));
  ok('…and not the product below it', !A.voProm(ln2[2]), A.voProm(ln2[2]));

  /* WHAT IS TYPED ON A COMBINED ROW IS SPLIT BACK ACROSS THE ORDERS, oldest first — two pieces
   * against 1 + 2 fills the first order and one of the second, not two against the first. */
  Object.keys(QS).forEach(k => delete QS[k]);
  QS['[data-vpmsg="vpo_shop_VND001"]'] = { className: '', textContent: '' };
  QS['[data-vpsendg="vpo_shop_VND001"]'] = [{ value: '2',
    getAttribute: k => (k === 'data-ix' ? '0,1' : null) }];
  els.vpSendDate.value = '2026-09-12';
  await A.vpRecordAll();

  const back = (A.VP().rows || []).find(o => o.id === 'vpo_shop_VND001') || {};
  const ln = A.voLines(back);
  ok('the oldest customer order is filled first', A.vpDone(ln[0]) === 1, String(A.vpDone(ln[0])));
  ok('…and what is left goes to the next one', A.vpDone(ln[1]) === 1, String(A.vpDone(ln[1])));
  ok('…and no more than was sent', A.vpDone(ln[0]) + A.vpDone(ln[1]) === 2);
  ok('…and a product nobody sent is untouched', A.vpDone(ln[2]) === 0);

  /* A printer with no Shopify work is not shown an empty tab. */
  A.setVP(Object.assign({}, A.VP(), { rows: [bulk], tab: 'shop' }));
  A.renderVp();
  ok('no custom work, no custom tab', els.vpTabShop._hidden === true);
  /* …but the strip stays: their own history is on it, and every printer has one. */
  ok('…and the strip stays, because their history is on it', els.vpTabs._hidden !== true);
  ok('…and they are put back on the bulk orders rather than left staring at nothing',
     A.VP().tab === 'bulk' && /VPO-260911-BRG/.test(els.vpBody.innerHTML));

  Object.keys(QS).forEach(k => delete QS[k]);
  A.setVP(wasVP); NET.on = wasNet; ME.admin = wasAdmin;
}

console.log('\n== the printer asks for their own row, at its own address ==');
{
  /* A printer opened the portal and was told the database refused the read — for data that is
   * theirs. The rules were right: their row is in pt_vendorByEmail under exactly the key the rules
   * build from their sign-in. The ADDRESS was wrong. The whole path was run through
   * encodeURIComponent, on top of a key the caller had already encoded, so
   *
   *     pt_vendorByEmail/p9982028893@vendors-tfr,app
   *
   * went out as pt_vendorByEmail%2Fp9982028893%2540vendors-tfr%252Capp — one root-level key with a
   * slash in its name. Against a database with no rules that answered null and the portal quietly
   * fell back to reading every vendor's details; against one with rules, both are refused. */
  ok('a path is spelled segment by segment, not as one key',
     A.ptPath('pt_vendorByEmail/p9982028893@vendors-tfr,app')
       === 'pt_vendorByEmail/p9982028893%40vendors-tfr%2Capp', A.ptPath('pt_vendorByEmail/p9982028893@vendors-tfr,app'));
  ok('…and something already spelled is not spelled twice',
     A.ptPath('pt_vendorByEmail/p9982028893%40vendors-tfr%2Capp')
       === 'pt_vendorByEmail/p9982028893%40vendors-tfr%2Capp');
  ok('…and a plain node is left as it is', A.ptPath('pt_baseData') === 'pt_baseData');

  const wasEmail = ME.email, wasVP = A.VP(), wasNet = NET.on, wasAdmin = ME.admin;
  ME.admin = false;
  ME.email = 'p9982028893@vendors-tfr.app';
  NET.on = true; NET.store = {}; NET.calls.length = 0;
  NET.store['pt_vendorByEmail/p9982028893@vendors-tfr,app'] = { code: 'VND006', name: 'Chhavi Printers' };
  NET.store['pt_vendorOrders/VND006'] = { vpo_1: { id: 'vpo_1', orderNo: 'VPO-260911-AAA',
    orderType: 'cut', status: 'Placed', vendorName: 'Chhavi Printers',
    lines: [{ lineId: 'l1', sku: 'RTC52-6090', qty: 5, kind: 'cut', dispatchedQty: 0 }] } };
  A.setVP(Object.assign({}, wasVP, { rows: null, code: null, name: '', err: '' }));
  await A.ensureVp();

  ok('the portal finds which printer this is, from their own row',
     A.VP().code === 'VND006', JSON.stringify({ code: A.VP().code, err: A.VP().err }));
  ok('…and their order is read', (A.VP().rows || []).length === 1, String((A.VP().rows || []).length));
  ok('…without a word of error', !A.VP().err, A.VP().err);
  /* THE READ THE RULES WOULD REFUSE IS NEVER MADE. pt_vendorMap holds every printer's contact
   * details; a printer is not allowed it, and does not need it. */
  ok('…and it never asks for the whole vendor map',
     !NET.calls.some(c => /pt_vendorMap/.test(c.url)),
     NET.calls.map(c => c.url.split('.app/')[1]).join(' '));

  /* AND WHEN THE ROW REALLY IS MISSING, say so in words somebody can act on rather than showing them
   * a database refusal for a read they were never meant to make. */
  NET.store = {}; NET.fail = new Error('The production database refused the read (permission denied).');
  A.setVP(Object.assign({}, A.VP(), { rows: null, code: null, name: '', err: '' }));
  await A.ensureVp();
  ok('an account nobody has linked is told that, not shown a permission error',
     /not linked to any printer/.test(A.VP().err || ''), A.VP().err);
  ok('…and it names the address to link, so the office can just do it',
     /p9982028893@vendors-tfr\.app/.test(A.VP().err || ''), A.VP().err);
  NET.fail = null;

  ME.email = wasEmail; A.setVP(wasVP); NET.on = wasNet; ME.admin = wasAdmin;
}

