console.log('\n== and the printer can actually see what they were given ==');
{
  /* "jo shopify order hum printer ko assign kar rahe h wo printer kese dekhega."
   *
   * They could not. The assignment lived in pt_shopProd, which decides who may type a printed figure
   * on a screen no printer has — and since the database moved, no printer CAN have it: the rules give
   * a vendor their own branch of pt_vendorOrders and nothing else, so that one printer can never read
   * another's work. So the line goes where they already look: their own order. */
  const wasOb = A.PTG().ob, wasSp = A.PTG().shopProd, wasVO = A.VO(), wasNet = NET.on, wasAdmin = ME.admin;
  ME.admin = true; NET.on = true; NET.store = {};
  A.setPTG(Object.assign(A.PTG(), { shopProd: {}, ob: [
    { id: 'q1', orderNo: 'SHP-8001', sku: 'PRINT-A', qty: 10, src: 'SHP', orderDate: '2026-09-01',
      shopOrderNo: '#8001', shopImg: 'https://cdn.shopify.com/s/files/1/0/eight.jpg' },
    { id: 'q2', orderNo: 'SHP-8002', sku: 'PRINT-B', qty: 4, src: 'SHP', orderDate: '2026-09-02' },
  ] }));
  A.setVO(Object.assign({}, wasVO, { rows: [] }));
  const theirs = code => NET.store['pt_vendorOrders/' + code + '/' + A.spShopOrderId(code)];

  ok('assigning a line works', (await A.spAssign('SHP-8001', 'PRINT-A', 'VND001')) === '');
  ok('…and it lands in the printer\'s OWN branch, which is the only thing their sign-in can read',
     !!theirs('VND001'), Object.keys(NET.store).join(', '));
  const o1 = theirs('VND001');
  ok('…as one line, for the pieces the order book says are owed',
     (o1.lines || []).length === 1 && o1.lines[0].sku === 'PRINT-A' && o1.lines[0].qty === 10,
     JSON.stringify(o1.lines));
  ok('…and the number the customer and Shopify both use', o1.lines[0].shopRef === '#8001', String(o1.lines[0].shopRef));
  ok('…and the photo the order was placed against, which the printer cannot look up for themselves',
     o1.lines[0].img === 'https://cdn.shopify.com/s/files/1/0/eight.jpg', String(o1.lines[0].img));
  ok('…carrying the Shopify order it came from, so the printer knows what it is for',
     /SHP-8001/.test(String(o1.lines[0].shopOrderNo) + ' ' + String(o1.lines[0].notes)));
  ok('…and the tie back to the Shopify line', o1.lines[0].shopKey === A.spKey('SHP-8001', 'PRINT-A'));
  ok('…on ONE standing order, not one order per Shopify order',
     o1.orderNo === A.spShopOrderNo('VND001'), o1.orderNo);

  /* A SECOND LINE JOINS THE SAME ORDER — and does not disturb the first, which by then may carry
   * what the printer has already sent back. */
  NET.store['pt_vendorOrders/VND001/' + A.spShopOrderId('VND001')].lines[0].dispatchedQty = 4;
  ok('a second line goes on the same order', (await A.spAssign('SHP-8002', 'PRINT-B', 'VND001')) === '');
  const o2 = theirs('VND001');
  ok('…so the printer has one list of two', (o2.lines || []).length === 2, JSON.stringify((o2.lines||[]).map(l=>l.sku)));
  ok('…and what they had already sent is still on it, not written over',
     (o2.lines.find(l => l.sku === 'PRINT-A') || {}).dispatchedQty === 4,
     JSON.stringify(o2.lines.map(l => l.sku + ':' + l.dispatchedQty)));

  /* HANDING IT TO SOMEBODY ELSE takes it off the first printer at the same moment. Two printers each
   * seeing the same line is how the same cloth gets printed twice. */
  ok('the line can be handed to another printer', (await A.spAssign('SHP-8002', 'PRINT-B', 'VND002')) === '');
  ok('…and the new printer has it', ((theirs('VND002') || {}).lines || []).length === 1);
  ok('…and the old one does not any more',
     ((theirs('VND001') || {}).lines || []).every(l => l.sku !== 'PRINT-B'),
     JSON.stringify(((theirs('VND001') || {}).lines || []).map(l => l.sku)));

  /* And taking the printer off entirely leaves them with no order at all, rather than an empty one
   * nobody can act on. */
  ok('taking the printer off is allowed while nothing is printed',
     (await A.spAssign('SHP-8002', 'PRINT-B', '')) === '');
  ok('…and their Shopify order goes with the last line', theirs('VND002') === undefined,
     JSON.stringify(theirs('VND002')));

  /* "I can assign printer also in bulk." Tick, choose one printer, done. */
  A.setORD_(Object.assign(A.ORD(), { pick: new Set(['SHP-8001|PRINT-A', 'SHP-8002|PRINT-B']) }));
  A.renderOrdShopify(false);
  ok('ticked lines offer a printer for all of them', /id="spAssignAll"/.test(els.odPickBar.innerHTML)
     && /Assign printer to 2/.test(els.odPickBar.innerHTML), els.odPickBar.innerHTML.slice(0, 200));
  ok('a bulk assign with no printer chosen is refused', /Choose the printer/.test(await A.spAssignPicked('')));
  ok('…as is one nothing knows', /not in the vendor master/.test(await A.spAssignPicked('VND999')));
  ok('both ticked lines go to one printer', (await A.spAssignPicked('VND002')) === '');
  ok('…each of them', A.spPrinter('SHP-8001', 'PRINT-A') === 'VND002' && A.spPrinter('SHP-8002', 'PRINT-B') === 'VND002');
  ok('…on that printer\'s portal, both lines', ((theirs('VND002') || {}).lines || []).length === 2,
     JSON.stringify(((theirs('VND002') || {}).lines || []).map(l => l.sku)));
  ok('…and off the one that had one of them', ((theirs('VND001') || {}).lines || []).every(l => l.sku !== 'PRINT-A'));
  ok('…with the ticks cleared and a message saying so', A.ORD().pick.size === 0 && /2 line\(s\) given to/.test(els.odMsg.textContent),
     els.odMsg.textContent);
  A.ORD().pick.add('SHP-8001|PRINT-A');
  ok('a line the printer already has is left alone and said so', (await A.spAssignPicked('VND002')) === ''
     && /1 already had them/.test(els.odMsg.textContent), els.odMsg.textContent);
  A.ORD().pick = new Set();

  A.setPTG(Object.assign(A.PTG(), { ob: wasOb, shopProd: wasSp }));
  A.setVO(wasVO); NET.on = wasNet; ME.admin = wasAdmin;
}

console.log('\n== a sales order or B2B order gets a printer the same way a Shopify one does ==');
{
  /* "add one thing like shopify order i can assign printer" — on the order book, not only Shopify. */
  const wasOb = A.PTG().ob, wasSp = A.PTG().shopProd, wasVO = A.VO(), wasNet = NET.on, wasAdmin = ME.admin, wasOrd = A.ORD();
  ME.admin = true; NET.on = true; NET.store = {};
  A.setPTG(Object.assign(A.PTG(), { shopProd: {}, ob: [
    { id: 'ob_so_SO-B2B-1_CB-CUST-260914-01', orderNo: 'SO-B2B-1', sku: 'CB-CUST-260914-01', qty: 120, src: 'SO', orderDate: '2026-09-10',
      shopImg: 'https://img.example/b.jpg', brand: 'Crate & Barrel', itemName: 'Border napkin', size: '20x20', needsSku: true },
    { id: 'ob_so_SO-7_PRINT-S', orderNo: 'SO-7', sku: 'PRINT-S', qty: 30, src: 'SO', orderDate: '2026-09-11' },
    { id: 's1', orderNo: 'SHP-8101', sku: 'PRINT-A', qty: 2, src: 'SHP', orderDate: '2026-09-12' },
  ] }));
  A.setVO(Object.assign({}, wasVO, { rows: [] }));
  A.setORD_(Object.assign({}, wasOrd, { pick: new Set(), busy: false }));
  const theirs = code => NET.store['pt_vendorOrders/' + code + '/' + A.spShopOrderId(code)];

  ok('a B2B line can be given to a printer', (await A.spAssign('SO-B2B-1', 'CB-CUST-260914-01', 'VND001')) === '');
  const bl = A.ordLines().find(l => l.orderNo === 'SO-B2B-1');
  ok('…and the order book line now names the printer', bl.printer === 'VND001' && bl.printed === 0 && bl.pendingPrint === 120, JSON.stringify(bl && [bl.printer, bl.pendingPrint]));
  ok('…without a Shopify handover deciding whether it is open', bl.open === true && bl.handedAt === '');
  const o = theirs('VND001');
  const ln = o && (o.lines || []).find(l => l.sku === 'CB-CUST-260914-01');
  ok('…the printer\'s portal has it, called a sales order, with its brand, item and picture',
     ln && /^Sales order SO-B2B-1 · Border napkin/.test(ln.notes) && ln.shopRef === 'Crate & Barrel' && ln.img === 'https://img.example/b.jpg'
     && ln.qty === 120 && ln.size === '20x20' && ln.itemName === 'Border napkin', JSON.stringify(ln));
  ok('the printer records printing on it like any other line', (await A.spPrint('SO-B2B-1', 'CB-CUST-260914-01', 50)) === ''
     && A.ordLines().find(l => l.orderNo === 'SO-B2B-1').pendingPrint === 70);

  /* THE ORDER BOOK SCREEN. */
  els.odView.value = 'book';
  A.renderOrd();
  ok('the order book shows a Printing column and an Assign button', /<th>Printing<\/th>/.test(els.odTable.innerHTML)
     && /data-spassign="SO-7\|PRINT-S"/.test(els.odTable.innerHTML) && /data-sppick="SO-7\|PRINT-S"/.test(els.odTable.innerHTML));
  ok('…with the printer\'s figure on the line they have', /<b>50<\/b> <span class="muted">of 120<\/span>/.test(els.odTable.innerHTML));
  ok('…and no handover button, which is Shopify\'s alone', !/data-sphand=/.test(els.odTable.innerHTML));
  A.ORD().pick = new Set(['SO-7|PRINT-S', 'SO-B2B-1|CB-CUST-260914-01']);
  A.renderOrd();
  ok('ticked order-book lines offer a printer for all of them', /Assign printer to 2/.test(els.odPickBar.innerHTML)
     && !/spHandAll/.test(els.odPickBar.innerHTML), els.odPickBar.innerHTML.slice(0, 200));
  ok('both go to one printer', (await A.spAssignPicked('VND002')) === '' && A.spPrinter('SO-7', 'PRINT-S') === 'VND002'
     && A.spPrinter('SO-B2B-1', 'CB-CUST-260914-01') === 'VND002');
  ok('…and the moved line leaves the first printer\'s portal', ((theirs('VND001') || {}).lines || []).every(l => l.sku !== 'CB-CUST-260914-01'));

  /* Somebody without the grant sees neither the tick nor the button. */
  ME.admin = false; const wasSA = ME.shopAssign; ME.shopAssign = false;
  A.renderOrd();
  ok('without the printer grant there is nothing to tick or assign', !/data-sppick=/.test(els.odTable.innerHTML)
     && !/data-spassign=/.test(els.odTable.innerHTML) && els.odPickBar.classList.contains('hide'), els.odTable.innerHTML.slice(0, 300));
  ME.shopAssign = wasSA; ME.admin = true;

  A.setPTG(Object.assign(A.PTG(), { ob: wasOb, shopProd: wasSp }));
  A.setVO(wasVO); A.setORD_(wasOrd); NET.on = wasNet; ME.admin = wasAdmin;
}

console.log('\n== vendor order requests: the team asks, an approver says yes, then the vendor sees it ==');
{
  /* "meri team ko ek sales order jesa tab ... jisko order dena chahte h wo de sake and assign bhi kar
   * sake, but pahle wo mere pas approval ke liye aay, then vendor ko send — just not printer, for all
   * vendors like quilt, embroidery — and related work ka view access bhi dekh sake." */
  const was = { admin: ME.admin, email: ME.email, vra: ME.vreqApprove, net: NET.on, masters: A.PTG().masters, vo: A.VO(), vof: A.VOF(), vp: A.VP() };
  A.setVP(Object.assign({}, was.vp, { code: '' }));
  ME.admin = false; ME.vreqApprove = false; ME.email = 'team@thefabricrush.com';
  NET.on = true; NET.store = {}; NET.calls = [];
  A.setPTG(Object.assign(A.PTG(), { masters: Object.assign({}, was.masters, { vendor: A.ptList(was.masters.vendor).concat([
    { code: 'VE01', desc: 'Noor Embroidery', category: 'Embroidery', active: true },
    { code: 'VQ01', desc: 'Friends Quilts', category: 'Filling', active: true },
  ]) }) }));
  A.setVO(Object.assign({}, was.vo, { rows: [] }));
  A.setVRQ({ rows: [], err: '', busy: false, at: '', shown: [] });
  const mdb = A.PTG().mdb || [];
  const jobSku = A.obUC((mdb.find(r => r && !A.voCutAllowed(r.articleType, r.subtype)) || {}).sku);
  const cutSku = A.obUC((mdb.find(r => r && A.voCutAllowed(r.articleType, r.subtype)) || {}).sku);

  /* RAISING ONE. */
  ok('somebody without the right cannot approve', A.vrqCanApprove() === false);
  await A.voFormOpen();
  ok('…so the order form opens as a request', A.VOF().mode === 'request' && els.ptDlgSave.textContent === 'Send for approval', els.ptDlgSave.textContent);
  ok('…and asks why it is needed', /id="vof_why"/.test(els.ptDlgBody.innerHTML));
  els.vof_vendor.value = 'VE01'; A.voOnVendorPick();
  ok('any kind of vendor can be asked — an embroidery firm here', els.vof_service.value === 'Embroidery' && A.VOF().kind === 'cut');
  els.vof_sku.value = jobSku; els.vof_qty.value = 10; els.vof_deliv.value = '2026-09-30'; els.vof_pri.value = 'P1'; els.vof_lnotes.value = '';
  A.voAddLine();
  ok('a line goes on it', A.VOF().lines.length === 1, els.vof_info.textContent);
  els.vof_notes.value = 'Logo in the corner'; els.vof_why.value = 'B2B order for Crate & Barrel';
  { const e = await A.voPlace(); ok('sending it works', e === '', e); }
  const reqKeys = Object.keys(NET.store).filter(k => /^pt_vendorOrderReqs\//.test(k));
  ok('it is stored as a request', reqKeys.length === 1, Object.keys(NET.store).join(', '));
  ok('…and NOTHING reaches a vendor\'s orders', !Object.keys(NET.store).some(k => /^pt_vendorOrders\//.test(k)));
  const r1 = NET.store[reqKeys[0]];
  ok('the request keeps who asked, why, the vendor, the work and the lines', r1.status === 'pending' && r1.requestedBy === 'team@thefabricrush.com'
     && r1.why === 'B2B order for Crate & Barrel' && r1.notes === 'Logo in the corner' && r1.vendorCode === 'VE01' && r1.category === 'Embroidery'
     && r1.service === 'Embroidery' && r1.lines.length === 1 && r1.lines[0].sku === jobSku && /^VRQ-\d{6}-[A-Z0-9]{3}$/.test(r1.reqNo), JSON.stringify(r1));
  ok('the form is emptied so it cannot be sent twice', A.VOF().lines.length === 0);

  A.renderVrq();
  ok('the list shows it waiting for approval', /Waiting for approval/.test(els.vrqTable.innerHTML) && new RegExp(r1.reqNo).test(els.vrqTable.innerHTML));
  ok('…with no approve button for the person who raised it, but a withdraw', !/data-vrqok=/.test(els.vrqTable.innerHTML) && /data-vrqwd=/.test(els.vrqTable.innerHTML));
  ok('…and no red count on the sidebar for them', els.vreqBadge.classList.contains('hide'));
  ok('they cannot approve it themselves', /needs permission/.test(await A.vrqApprove(r1.id, { vendor: 'VE01' })));

  /* NOR GO AROUND IT. */
  await A.voFormOpen('place');
  A.setVOF(Object.assign(A.VOF(), { kind: 'cut', service: 'Embroidery', lines: [{ lineId: 'x1', kind: 'cut', sku: jobSku, qty: 5 }] }));
  els.vof_vendor.value = 'VE01';
  ok('placing an order directly is refused without the right', /needs permission/.test(await A.voPlace()));
  ok('…and nothing was written for it', !Object.keys(NET.store).some(k => /^pt_vendorOrders\//.test(k)));

  /* ANSWERING IT. */
  ME.vreqApprove = true; ME.email = 'ravi@thefabricrush.com';
  A.renderVrq();
  ok('an approver is shown the count waiting', !els.vreqBadge.classList.contains('hide') && els.vreqBadge.textContent === '1');
  ok('…and the approve button', /data-vrqok=/.test(els.vrqTable.innerHTML));
  ok('rejecting with no reason is refused', /Say why/.test(await A.vrqReject(r1.id, '  ')));
  ok('approving to another vendor works', (await A.vrqApprove(r1.id, { vendor: 'VQ01', note: 'Noor is full this week' })) === '');
  const oid = 'vpo_' + r1.id;
  const order = NET.store['pt_vendorOrders/VQ01/' + oid];
  ok('the order is now on THAT vendor\'s portal branch', !!order && !NET.store['pt_vendorOrders/VE01/' + oid], Object.keys(NET.store).join(', '));
  ok('…Placed, with the lines, the work and the notes as asked', order && order.status === 'Placed' && order.lines.length === 1
     && order.lines[0].sku === jobSku && order.service === 'Embroidery' && order.notes === 'Logo in the corner' && /^VPO-/.test(order.orderNo));
  ok('…raised by the person who asked, approved by the approver', order && order.createdBy === 'team@thefabricrush.com'
     && order.approvedBy === 'ravi@thefabricrush.com' && order.requestId === r1.id && order.requestNo === r1.reqNo);
  const r1b = NET.store['pt_vendorOrderReqs/' + r1.id];
  ok('the request is marked approved and names the order', r1b.status === 'approved' && r1b.vendorOrderNo === order.orderNo && r1b.sentTo === 'VQ01');
  ok('…and its log says the vendor was changed, and why', /asked for Noor Embroidery/.test(JSON.stringify(r1b.log)) && /Noor is full/.test(JSON.stringify(r1b.log)));
  ok('approving it again does nothing', /not waiting for approval/.test(await A.vrqApprove(r1.id, { vendor: 'VQ01' })));

  /* THE RELATED WORK: what the vendor has sent, read from the order. */
  const liveOrder = A.VO().rows.find(o => o.id === oid);
  liveOrder.lines[0].vendorQty = 4;
  A.renderVrq();
  ok('the request shows what has come back', A.vrqStage(A.VRQ().rows[0]) === 'open' && /4 of 10 pcs sent/.test(els.vrqTable.innerHTML)
     && /6 to come/.test(els.vrqTable.innerHTML), els.vrqTable.innerHTML.slice(0, 400));
  liveOrder.lines[0].vendorQty = 10;
  ok('…and is completed once it has all come back', A.vrqStage(A.VRQ().rows[0]) === 'done');

  /* WITHDRAWING, REJECTING, RAISING AGAIN. */
  ME.vreqApprove = false; ME.email = 'team@thefabricrush.com';
  A.setVOF({ kind: 'running', lines: [{ lineId: 'r1', kind: 'running', fabricType: 'Cambric', color: 'White', printDirection: 'Horizontal', meters: 300 }], service: 'Block print', mode: 'request' });
  els.vof_vendor.value = 'VND001'; els.vof_notes.value = ''; els.vof_why.value = '';
  ok('a second request goes in', (await A.voPlace()) === '');
  const r2 = A.VRQ().rows.find(r => r.id !== r1.id);
  ME.email = 'somebody@thefabricrush.com';
  ok('somebody else cannot withdraw it', /Only the person who raised it/.test(await A.vrqWithdraw(r2.id)));
  ME.email = 'team@thefabricrush.com';
  ok('the person who raised it can', (await A.vrqWithdraw(r2.id)) === '' && A.VRQ().rows.find(r => r.id === r2.id).status === 'withdrawn');
  ok('…and a withdrawn request cannot be approved', /not waiting/.test((ME.vreqApprove = true, await A.vrqApprove(r2.id, { vendor: 'VND001' }))));

  A.setVOF({ kind: 'running', lines: [{ lineId: 'r3', kind: 'running', fabricType: 'Voil', color: 'Red', printDirection: 'Vertical', meters: 50 }], service: 'Block print', mode: 'request' });
  els.vof_vendor.value = 'VND001';
  await A.voPlace();
  const r3 = A.VRQ().rows.find(r => r.id !== r1.id && r.id !== r2.id);
  ok('an approver can reject with a reason', (await A.vrqReject(r3.id, 'Order 30 m, not 50')) === ''
     && NET.store['pt_vendorOrderReqs/' + r3.id].rejectReason === 'Order 30 m, not 50');
  await A.vrqCopy(r3.id);
  ok('a rejected request comes back into the form to fix', A.VOF().mode === 'request' && A.VOF().lines.length === 1
     && A.VOF().lines[0].meters === 50 && A.VOF().lines[0].lineId !== 'r3' && /Order 30 m, not 50/.test(els.ptDlgMsg.textContent), els.ptDlgMsg.textContent);

  /* THE PRINTER CAP IS CHECKED AGAIN AT APPROVAL. */
  const big = { id: 'vrq_cap', reqNo: 'VRQ-260914-CAP', status: 'pending', vendorCode: 'VND001', service: 'Block print', orderType: 'cut',
    lines: [{ lineId: 'c1', kind: 'cut', sku: cutSku, qty: 999999 }], requestedBy: 'team@thefabricrush.com', requestedAt: '2026-09-14T10:00:00Z' };
  A.VRQ().rows.push(big);
  ok('a printing request over the cap is not sent', /Over the printer cap now/.test(await A.vrqApprove('vrq_cap', { vendor: 'VND001' }))
     && !NET.store['pt_vendorOrders/VND001/vpo_vrq_cap']);

  /* THE TILES FILTER THE LIST. */
  A.setVRQ_KPI('rejected'); A.renderVrq();
  ok('the Rejected tile shows only rejected and withdrawn requests', /2 of 4 request/.test(els.vrqMsg.textContent), els.vrqMsg.textContent);
  A.setVRQ_KPI('');

  A.setPTG(Object.assign(A.PTG(), { masters: was.masters })); A.setVO(was.vo); A.setVOF(was.vof);
  ME.admin = was.admin; ME.email = was.email; ME.vreqApprove = was.vra; NET.on = was.net; A.setVP(was.vp);
}

console.log('\n== exports carry the priority ==');
