console.log('\n== karigar article mix: easy / medium / hard as Ravi sets them ==');
{
  /* "article wise kis karigar ne kitne pcs banaye ... kaun easy, kaun hard, uska %" — and "not just mark
   * easy article, I will let you know which is easy or hard." */
  const D = __dirname + '/mix/';
  const raw = JSON.parse(fs.readFileSync(D + 'pt_baseData.json', 'utf8'));
  const base = (Array.isArray(raw) ? raw : Object.values(raw)).filter(Boolean);
  const emp = JSON.parse(fs.readFileSync(D + 'pt_empList.json', 'utf8')).filter(Boolean);
  const rates = JSON.parse(fs.readFileSync(D + 'pt_rateList.json', 'utf8')).filter(Boolean);
  const wasPT = A.PT(), wasPTE = A.PTE(), wasHR = A.HR(), wasPA = A.PA(), wasKA = A.KA(), wasNet = NET.on, wasAdmin = ME.admin;
  A.setPT(Object.assign({}, wasPT, { base, cut: wasPT.cut || [] }));
  A.setPTE(Object.assign({}, wasPTE, { emp }));
  A.setHR(Object.assign({}, wasHR, { rate: rates }));
  A.setPA(Object.assign({}, wasPA, { team: {} }));
  Object.assign(A.KA(), { levels: {}, mixSort: null, pick: '' });

  const t0 = A.kaMix(8, '', '');
  ok('with no levels set, nothing is guessed: every piece is "Not set"', t0.all.pcs > 1000 && t0.all.lv.none === t0.all.pcs && t0.all.lv.easy === 0 && t0.all.lv.hard === 0,
     JSON.stringify(t0.all.lv));

  /* Ravi sets three articles. */
  ME.admin = true; NET.on = true; NET.calls = [];
  const K = A.kaLevelKey;
  const err = await A.kaLevelsSave({ [K('Napkin', 'Plain Napkin')]: 'easy', [K('Tablecloth', 'Square Tablecloth')]: 'easy',
    [K('Pillow Cover', 'Ruffle Pillow Cover')]: 'hard', [K('Tablecloth', 'Rectangular Tablecloth')]: 'mid' });
  ok('saving levels works', err === '', err);
  const patch = NET.calls.filter(c => c.method === 'PATCH').map(c => c.body)[0] || {};
  ok('…one update, keyed by article, with who set it', Object.keys(patch).length === 4
     && patch['pt_articleLevel/' + K('Pillow Cover', 'Ruffle Pillow Cover')].level === 'hard'
     && patch['pt_articleLevel/' + K('Pillow Cover', 'Ruffle Pillow Cover')].by === ME.email, JSON.stringify(Object.keys(patch)));
  ok('an article is read at its level', A.kaLevelOf('pillow cover', 'RUFFLE PILLOW COVER') === 'hard' && A.kaLevelOf('Napkin', 'Border Napkin') === 'none');

  const t = A.kaMix(8, '', '');
  ok('the levels now come from what was set', t.all.lv.hard > 0 && t.all.lv.easy > 0 && t.all.lv.mid > 0 && t.all.lv.none > 0, JSON.stringify(t.all.lv));
  ok('every karigar\'s levels add up to their pieces', t.rows.every(r => r.lv.easy + r.lv.mid + r.lv.hard + r.lv.none === r.pcs));
  ok('…and their percentages to 100', t.rows.every(r => Math.abs(r.easyPct + r.midPct + r.hardPct + r.nonePct - 100) < 0.01));
  ok('…and the article columns add up to their pieces too', t.rows.every(r => Object.values(r.byType).reduce((a, v) => a + v, 0) === r.pcs));
  ok('the All row is the sum of the karigars', t.all.pcs === t.rows.reduce((a, r) => a + r.pcs, 0));
  ok('no salaried Company Role name is among the karigars', t.rows.every(r => !/company role/i.test(r.type)));
  const kt = A.kaTable('recv', 'karigar', 8, '', '');
  const top = t.rows[0], same = kt.rows.find(r => r.key === top.key);
  ok('a karigar\'s pieces match the Pieces made study', same && same.total === top.pcs, top.name + ': ' + top.pcs + ' vs ' + (same && same.total));

  /* Taking a level off, and a change that is no change. */
  NET.calls = [];
  ok('clearing a level works', (await A.kaLevelsSave({ [K('Tablecloth', 'Rectangular Tablecloth')]: '' })) === ''
     && A.kaLevelOf('Tablecloth', 'Rectangular Tablecloth') === 'none'
     && (NET.calls.find(c => c.method === 'PATCH') || { body: {} }).body['pt_articleLevel/' + K('Tablecloth', 'Rectangular Tablecloth')] === null);
  NET.calls = [];
  ok('saving the same levels again writes nothing', (await A.kaLevelsSave({ [K('Napkin', 'Plain Napkin')]: 'easy' })) === '' && !NET.calls.some(c => c.method === 'PATCH'));
  ME.admin = false; const wasPE = ME.prodEdit; ME.prodEdit = false;
  ok('somebody without the edit right cannot set levels', /needs permission/.test(await A.kaLevelsSave({ [K('Napkin', 'Plain Napkin')]: 'hard' })));
  ME.prodEdit = wasPE; ME.admin = true;

  /* The screen. */
  els.kaGroup.value = 'mix'; els.kaWeeks.value = '8'; els.kaDept.value = ''; els.kaQ.value = '';
  A.renderKa();
  ok('the mix view draws Easy, Medium, Hard and Not set with each karigar\'s %', /Easy/.test(els.kaTable.innerHTML) && /Not set/.test(els.kaTable.innerHTML)
     && /All karigars/.test(els.kaTable.innerHTML) && /%<div/.test(els.kaTable.innerHTML));
  ok('…says how many pieces still have no level', /no level yet/.test(els.kaMsg.textContent), els.kaMsg.textContent);
  ok('…hides the metric picker and shows "Set easy / hard"', els.kaMetric.classList.contains('hide') && !els.kaBands.classList.contains('hide'));
  els.kaGroup.value = 'karigar'; A.renderKa();
  ok('…and the karigar study puts the picker back', !els.kaMetric.classList.contains('hide') && els.kaBands.classList.contains('hide'));

  A.setPT(wasPT); A.setPTE(wasPTE); A.setHR(wasHR); A.setPA(wasPA); Object.assign(A.KA(), { levels: wasKA.levels, mixSort: null });
  NET.on = wasNet; ME.admin = wasAdmin;
}

