  els.qcwSub.value = 'Square Tablecloth'; els.qcwCol.value = 'Red'; els.qcwSz.value = '90x90'; A.renderQcCheckForm();
  ok('the whole item, matching one SKU, fills it in', els.qcwSku.value === 'QA-RED-90', els.qcwSku.value);
  els.qcwSz.value = '60x60'; A.renderQcCheckForm();
  ok('two SKUs with the same description are not guessed between — the SKU is left to pick',
     els.qcwSku.value === '' && /2 SKUs share this description/.test(els.qcwInfo.textContent), els.qcwInfo.textContent);

  /* Typing the SKU fills the item back. */
