console.log('\n== Import: a column the file does not have changes nothing ==');
{
  /* "if i would feed a new sku using template, how can i do this ki mujhe sara data fill n karna pade" — 2026-09-22. */
  const live = { sku: 'KEEP-1', brand: 'Ridhi', articleType: 'Pillow Cover', subtype: 'Piping Pillow Cover', color: 'Blue', size: '18x18',
    fabric: 'Sheeting 82', consumption: 0.28, packOf: '2', cuttingRequired: true, isZip: true, zipQty: 1, chainLength: 18,
    isRuffle: false, ruffleMeters: null, ruffleFabric: '', isPiping: true, pipingMeters: 2.1, fillerFabricRequired: false,
    standardFillingQty: null, inventoryValuationPrice: 320, imageUrl: 'http://pic' };
  /* a file of five columns: SKU, Article, Subtype, Colour, Size */
  const ix = { sku: 0, article: 1, subtype: 2, color: 3, size: 4, brand: -1, fabric: -1, consumption: -1, pack: -1, cutting: -1,
    zip: -1, zipqty: -1, zipsize: -1, ruffle: -1, rufflem: -1, rufflefab: -1, piping: -1, pipingm: -1, filler: -1, fillqty: -1, valprice: -1, image: -1 };
  const v = A.mdbFromCsv(['KEEP-1', 'Pillow Cover', 'Piping Pillow Cover', 'Red', '18x18'], ix);
  ok('what the file leaves out comes back as "nothing said"', v.fabric === undefined && v.isZip === undefined && v.imageUrl === undefined);
  const merged = A.mdbMerge(v, live);
  ok('…so an update changes only the colour', merged.color === 'Red' && merged.fabric === 'Sheeting 82' && merged.isZip === 'yes'
     && merged.chainLength === '18' && merged.isPiping === 'yes' && merged.pipingMeters === '2.1' && merged.inventoryValuationPrice === '320', JSON.stringify(merged));
  const rec = A.mdbRecord(merged, false);
  ok('…and written back the SKU still has its cloth, zip, piping and price', rec.fabric === 'Sheeting 82' && rec.consumption === 0.28
     && rec.isZip === true && rec.chainLength === 18 && rec.zipQty === 1 && rec.isPiping === true && rec.pipingMeters === 2.1
     && rec.inventoryValuationPrice === 320 && rec.color === 'Red', JSON.stringify(rec));
  ok('a brand new SKU in such a file passes the checks', A.mdbValidate(A.mdbMerge(A.mdbFromCsv(['NEW-1', 'Pillow Cover', 'Piping Pillow Cover', 'Red', '18x18'], ix), null), '') === '');
  const src = fs.readFileSync(APP, 'utf8');
  ok('…and the import says so before writing', /a column your file does not have is left exactly as it is/.test(src)
     && /take fabric, consumption, zip, ruffle and piping from a recipe/.test(src)
     && /have NO recipe for their article, subtype and size/.test(src));
}
