console.log('\n== The store: what is on the shelf before stitching ==');
{
  /* Ravi, 2026-09-22: printers' goods land here with a cross-check, the opening stock is typed, job work
   * issues take pieces out, cutting takes cloth and gives back its waste. */
  const wasPT = A.PT(), wasPTG = A.PTG(), wasVO = A.VO(), wasStore = A.STORE(), wasNet = NET.on, wasEdit = ME.prodEdit, wasAdmin = ME.admin;
  ME.admin = true; ME.prodEdit = true; NET.on = true; NET.store = {}; NET.calls.length = 0;
  const T0 = '2026-09-22T10:00:00.000Z', before = '2026-09-22T09:00:00.000Z', after = '2026-09-22T11:00:00.000Z';
  /* RUN-1 is printed as cloth and cut here; CUT-1 is cut here and printed after, so its pieces come back. */
  A.setPTG(Object.assign({}, wasPTG, {
    masters: Object.assign({}, wasPTG.masters, { printRule: {
      a: { articleType: 'Tablecloth', subtype: 'Square Tablecloth', issueAs: 'running' },
      b: { articleType: 'Napkin', subtype: 'Plain Napkin', issueAs: 'cut' } } }),
    mdb: [{ sku: 'RUN-1', articleType: 'Tablecloth', subtype: 'Square Tablecloth', color: 'Sage Green', size: '60x60', fabric: 'Sheeting 62' },
      { sku: 'CUT-1', articleType: 'Napkin', subtype: 'Plain Napkin', color: 'Sage Green', size: '20x20', fabric: 'Cambric' }] }));
  A.setSTORE({ rows: [
    { id: 'o1', kind: 'OPENING', unit: 'pcs', sku: 'RUN-1', qty: 40, at: T0, by: 'store@x', date: '2026-09-22' },
    { id: 'o2', kind: 'OPENING', unit: 'm', fabric: 'Sheeting 62', colour: 'Sage Green', qty: 100, at: T0, by: 'store@x', date: '2026-09-22' },
  ], checks: {}, err: '', busy: false, at: '' });
  ok('the store opens when the first opening entry is typed', A.stStart() === T0);
  A.setVO(Object.assign({}, wasVO, { rows: [
    { id: 'vo1', vendorCode: 'V1', orderNo: 'VO-1', orderType: 'running', lines: [{ fabricType: 'Sheeting 62', color: 'Sage Green', meters: 300,
      deliveries: [{ qty: 120, date: '22/09/2026', at: after, by: 'p@x' }, { qty: 50, date: '21/09/2026', at: before, by: 'p@x' }] }] },
    { id: 'vo2', vendorCode: 'V1', orderNo: 'VO-2', lines: [{ sku: 'CUT-1', qty: 200, articleSubtype: 'Plain Napkin', color: 'Sage Green', size: '20x20',
      deliveries: [{ qty: 90, date: '22/09/2026', at: after, by: 'p@x', ok: { qty: 85, rej: 5, by: 'office@x', at: after } }] }] },
  ] }));
  A.setPT(Object.assign({}, wasPT, {
    cut: [{ id: 'c1', sku: 'RUN-1', pieces: 10, color: 'Sage Green', articleSubtype: 'Square Tablecloth', cutDate: '22/09/2026, 12:00', addedAt: after,
        fabricWidth: 'Sheeting 62', fabricUsed: 16, fabricWaste: 1.5, fabricWasteWidth: 22, addedBy: 'cut@x' },
      { id: 'c2', sku: 'CUT-1', pieces: 50, color: 'Sage Green', cutDate: '22/09/2026, 12:30', addedAt: after, fabricWidth: 'Cambric', fabricUsed: 9, addedBy: 'cut@x' },
      { id: 'c0', sku: 'RUN-1', pieces: 5, color: 'Sage Green', cutDate: '21/09/2026, 10:00', addedAt: before, fabricWidth: 'Sheeting 62', fabricUsed: 8, addedBy: 'cut@x' }],
    base: [{ id: 'j1', sku: 'RUN-1', empName: 'Asha', issuePieces: 12, issueDate: '22/09/2026, 13:00', addedAt: after, addedBy: 'jw@x' },
      { id: 'j0', sku: 'RUN-1', empName: 'Asha', issuePieces: 7, issueDate: '21/09/2026, 13:00', addedAt: before, addedBy: 'jw@x' }] }));
  const mv = A.stMoves();
  const find = id => mv.find(x => x.id === id);
  ok('a printer\'s cloth comes in', (x => x && x.qty === 120 && x.unit === 'm' && x.fabric === 'Sheeting 62' && x.colour === 'Sage Green')(find('V1/vo1/0/0')), JSON.stringify(find('V1/vo1/0/0')));
  ok('…the accepted figure wins over what was claimed, and rejects stay out', (x => x && x.qty === 85 && x.unit === 'pcs' && x.sku === 'CUT-1')(find('V1/vo2/0/0')));
  ok('…and a delivery from before the store opened is not counted', !find('V1/vo1/0/1'));

  /* NO OPENING STOCK IS NOT A REASON TO RECORD NOTHING (Ravi, 2026-09-23: "aaj printer se goods
   * receive hua to ye store stock balance me kyo nahi aaya"). 461 pieces came in from a printer and
   * the screen said 0 items, because every movement was gated behind the opening stock — which
   * nobody had uploaded. The register holds them; it simply is not the shelf until the opening
   * figure is there, and the screen says which of the two it is showing. */
  {
    const keep = A.STORE();
    A.setSTORE(Object.assign({}, keep, { rows: [] }));          // nothing typed, so no opening stock
    ok('with no opening stock the store has no start', A.stStart() === '');
    const bare = A.stMoves();
    ok('…the printer delivery is still recorded', bare.some(x => x.src === 'printer' && x.qty === 85),
       JSON.stringify(bare.map(x => x.src + ':' + x.qty)));
    ok('…so is the cutting that took cloth', bare.some(x => x.src === 'cut' && x.unit === 'm' && x.qty < 0));
    ok('…and the pieces given to a karigar', bare.some(x => x.src === 'jobwork' || (x.qty < 0 && x.unit === 'pcs')));
    /* And a delivery from BEFORE the opening stock is still dropped once there is one — the opening
     * figure already contains it. */
    /* BUT NOT THE WHOLE OF HISTORY (Ravi, 2026-09-24: "jab se store stock balance ko joda ye bahut
     * hang ho rha h"). Counting from the beginning of time made every karigar issue ever booked an OUT
     * against a store that never had its IN — 1,401 of 1,669 items below zero, -43,122 pieces, and an
     * 837 KB table that took the page down. With no opening stock it counts from the day the store was
     * set up, so today's delivery still shows and the years before the store existed do not. */
    const pt0 = A.PT();
    A.setPT(Object.assign({}, pt0, { base: pt0.base.concat([{ id: 'jold', sku: 'RUN-1', empName: 'Asha', issuePieces: 900,
      issueDate: '15/08/2026, 13:00', addedAt: '2026-08-15T07:30:00.000Z', addedBy: 'jw@x' }]) }));
    const bare2 = A.stMoves();
    ok('with no opening stock, an issue from before the store existed is NOT counted', !bare2.some(x => x.id === 'jw-jold'),
       JSON.stringify(bare2.filter(x => x.id === 'jw-jold')));
    ok('…while one from the store\'s first day still is', bare2.some(x => x.id === 'jw-j1'));
    A.setPT(pt0);
    A.setSTORE(keep);
    ok('once the opening stock is back, what came before it is dropped again', !A.stMoves().some(x => x.id === 'V1/vo1/0/1'));
  }
  {
    /* THE THREE WAYS THE STORE LOADED THE WHOLE PAGE, each held shut. */
    const src = fs.readFileSync(APP, 'utf8');
    const rs0 = src.indexOf('function renderStore(');
    const rs = src.slice(rs0, src.indexOf("$('fbTable').addEventListener('click', async", rs0));
    ok('the store\'s picture lookup patches the pictures in, it does not redraw the store',
       /ptImgFill\([^;]*ptIfTab\('fab', ptImgPatch\)\)/.test(rs) && !/ptImgFill\([^;]*, renderFab\)/.test(rs),
       (rs.match(/ptImgFill\([^;]*;/g) || []).join(' · '));
    ok('the Fabric screen draws only while the Fabric tab is on show — another screen reading the ledger does not set it off',
       /function renderFab\(\) \{[\s\S]{0,700}?TAB_NOW !== 'fab'\) return;/.test(src));
    ok('at most 600 items are drawn, and the line says how many more there are',
       /const drawn = bal\.slice\(0, ST_MAX_ROWS\)/.test(rs) && /ST_MAX_ROWS = 600/.test(src) && /search to find the rest/.test(rs));
  }
  ok('cutting cloth that was printed first takes metres out', (x => x && x.qty === -16 && x.unit === 'm')(find('cut-c1')));
  ok('…and puts the pieces it made in', (x => x && x.qty === 10 && x.unit === 'pcs' && x.sku === 'RUN-1')(find('cutp-c1')));
  ok('cutting for a piece printed AFTER cutting moves nothing — it comes back from the printer', !find('cut-c2') && !find('cutp-c2'));
  ok('the waste comes back, with how wide it is', (x => x && x.qty === 1.5 && /22" wide/.test(x.what))(find('waste-c1')));
  ok('pieces issued to a karigar go out', (x => x && x.qty === -12 && x.unit === 'pcs')(find('jw-j1')));
  ok('…and what came BACK from the karigar is not a store movement', !mv.some(x => /received|back from/i.test(x.what) && x.src === 'jobwork'));
  ok('nothing from before the opening is counted', !find('cut-c0') && !find('jw-j0'));
  const bal = A.stBalances(mv);
  const b = k => bal.find(x => x.key === k);
  ok('pieces: 40 opening + 10 cut − 12 issued = 38', (x => x && x.qty === 38)(b('P|RUN-1')), JSON.stringify(b('P|RUN-1')));
  ok('…and the printer\'s napkins are their own line', (x => x && x.qty === 85)(b('P|CUT-1')));
  ok('cloth: 100 opening + 120 printed − 16 cut + 1.5 waste = 205.5', (x => x && x.qty === 205.5)(b('M|SHEETING 62|SAGE GREEN')), JSON.stringify(b('M|SHEETING 62|SAGE GREEN')));
  /* ---- the cross-check ---- */
  ok('both deliveries are waiting to be cross-checked', A.stToCheck(mv).length === 2);
  ok('…ticking one is saved', (await A.stCheckSet('V1/vo1/0/0', true)) === '' && A.stChecked('V1/vo1/0/0'));
  ok('…and it drops off the list, without changing the balance', A.stToCheck(A.stMoves()).length === 1
     && A.stBalances(A.stMoves()).find(x => x.key === 'M|SHEETING 62|SAGE GREEN').qty === 205.5);
  ok('…and it can be undone', (await A.stCheckSet('V1/vo1/0/0', false)) === '' && !A.stChecked('V1/vo1/0/0'));
  /* ---- typing the opening stock ---- */
  const grid = [['Pieces or cloth', 'SKU', 'Fabric', 'Colour', 'Quantity', 'Remark'],
    ['Pieces', 'RUN-1', '', '', '25', 'shelf 2'], ['Cloth', '', 'Cambric', 'Sage Green', '12.5', 'rack'],
    ['Pieces', 'NOPE-9', '', '', '4', ''], ['Pieces', 'RUN-1', '', '', 'x', '']];
  const read = A.stSheetEntries(grid);
  ok('the sheet reads pieces and cloth, and names the line it cannot', read.entries.length === 3 && read.bad.length === 1 && /line 5/.test(read.bad[0]), JSON.stringify(read));
  const plan = A.stSheetPlan(read.entries);
  ok('…a SKU the master does not have is refused', plan.ok.length === 2 && /NOPE-9/.test(plan.bad.join(' ')));
  ok('…and the rest is written', (await A.stSheetRun(plan.ok)) === '' && A.STORE().rows.length === 4);
  ok('typing one in by hand needs a real SKU', /not in the master database/.test(await A.stSave({ kind: 'OPENING', unit: 'pcs', sku: 'NOPE-9', qty: 2 })));
  ok('…and whole pieces', /whole number/.test(await A.stSave({ kind: 'OPENING', unit: 'pcs', sku: 'RUN-1', qty: 2.5 })));
  ok('…a correction may be negative', (await A.stSave({ kind: 'ADJUST', unit: 'pcs', sku: 'RUN-1', qty: -3 })) === ''
     && A.stBalances(A.stMoves()).find(x => x.key === 'P|RUN-1').qty === 38 + 25 - 3);
  A.setPT(wasPT); A.setPTG(wasPTG); A.setVO(wasVO); A.setSTORE(wasStore);
  ME.prodEdit = wasEdit; ME.admin = wasAdmin; NET.on = wasNet; NET.store = {}; NET.calls.length = 0;
}
