console.log('\n== a cache that can actually hit ==');
{
  /* Ravi, 2026-09-24: "system bahut hang ho rha h." Seven indexes are kept until the list they were
   * built from is replaced, and they tell by identity. Written "FGI.rows || []" the fallback was a
   * NEW array every call, so while that list was still null the cache could never hit and the index
   * was rebuilt once per row — 1.4 seconds to redraw the Order Console, on every keystroke. */
  const src = fs.readFileSync(APP, 'utf8');
  const bad = (src.match(/const src = [^;\n]*\|\| \[\]/g) || []);
  ok('no identity-cached index falls back to a fresh empty array', bad.length === 0, bad.join(' · '));
  ok('they share one frozen empty list instead', /const PT_NONE = Object\.freeze\(\[\]\);/.test(src));
  /* The one that hurt most, proved rather than read: the index must be the SAME object twice when
   * Finished Goods has not loaded, which is the ordinary state of the Order Console. */
  const wasFgi = A.FGI();
  A.setFGI(Object.assign({}, wasFgi, { rows: null }));
  const a1 = A.ordFgAt('NO-SUCH-ORDER', 'NO-SUCH-SKU');
  const t0 = Date.now();
  for (let i = 0; i < 400; i++) A.ordFgAt('NO-SUCH-ORDER', 'NO-SUCH-SKU');
  const took = Date.now() - t0;
  ok('…so 400 lookups with nothing loaded cost almost nothing', took < 150, took + ' ms');
  ok('…and the answer is still the right one', a1 === null);
  A.setFGI(wasFgi);
}

console.log('\n== a screen you have left is not a screen you are paying for ==');
{
  /* Ravi, 2026-09-24, after two speed fixes: still hanging, and "poora computer hang hota hai".
   * showTab hid panes and never emptied one, so every table looked at today stayed in the document —
   * seven screens is about 50,000 cells and 4.5 MB of HTML nobody is looking at. */
  const src = fs.readFileSync(APP, 'utf8');
  const m = src.match(/const TAB_TABLES = \{([\s\S]*?)\};/);
  ok('the big tables are listed against their tab', !!m);
  const tabs = [...(m ? m[1] : '').matchAll(/(\w+):\s*\[/g)].map(x => x[1]);
  ok('…and it covers the heaviest screens',
    ['ord', 'pbase', 'pcut', 'ppress', 'fgi', 'fba', 'vlog'].every(t => tabs.includes(t)),
    tabs.join(','));
  const show = src.slice(src.indexOf('function showTab('), src.indexOf('$(\'tabRepl\').onclick'));
  /* A TAB EMPTIED ON THE WAY OUT MUST FILL ITSELF ON THE WAY IN, or it opens blank and reads as
   * broken. This is the rule that lets the list above be extended safely. */
  const orphan = tabs.filter(t => !new RegExp("which === '" + t + "'").test(show));
  ok('every tab that is emptied redraws itself when it is opened', orphan.length === 0,
    'no render on entry for: ' + orphan.join(', '));
  ok('and the emptying happens BEFORE the panes are shown',
    show.indexOf('tabShed(TAB_NOW)') > 0 && show.indexOf('tabShed(TAB_NOW)') < show.indexOf('classList.toggle(\'hide\''),
    String(show.indexOf('tabShed(TAB_NOW)')));
  /* The Replenishment screen draws once at sign-in and has nothing to draw it again. */
  ok('the one screen that cannot redraw itself is not emptied', tabs.indexOf('repl') < 0);

  /* A picture lookup takes seconds and asks for a whole re-render when it lands. Landing after
   * somebody has moved on, it rebuilt a megabyte of hidden table and undid the clearing. */
  ok('a background picture lookup does not redraw a screen nobody is on',
    /const ptIfTab = /.test(src) && !/ptImgFill\([^)]*, false, renderOrd\)/.test(src),
    (src.match(/ptImgFill\([^)]*, (?:false|force), render\w+\)/g) || []).join(' · '));

  /* tabShed lives in the sign-in and navigation block, which this harness does not evaluate, so it
   * is read rather than run: it must blank the table outright, not merely hide it. */
  ok('leaving a tab blanks its table outright',
    /function tabShed\(prev\) \{[\s\S]{0,240}?innerHTML = ''/.test(src),
    src.slice(src.indexOf('function tabShed('), src.indexOf('function tabShed(') + 240));
  /* The Order Console really does put a megabyte there — the thing being handed back. */
  els.odView.value = 'book';
  A.renderOrd();
  ok('…and the Order Console really is worth clearing', els.odTable.innerHTML.length > 1000,
    String(els.odTable.innerHTML.length));
}

console.log('\n== opening the store reads each thing once ==');
{
  /* Ravi, 2026-09-24: "jab se store stock balance ko joda ye bahut hang ho rha h … Could not read the
   * store book (Failed to fetch)." renderStore asked ensureStore to load; ensureStore drew "loading"
   * before marking itself as loading; drawing is renderStore, which asked again — fifteen hundred
   * levels deep, then every level read for itself. One open of the tab was 7,594 database reads, the
   * 2.2 MB Job Work register 1,518 times. */
  const wasPT = A.PT(), wasVO = A.VO(), wasStore = A.STORE(), wasFab = A.FAB(), wasNet = NET.on, wasView = els.fbView.value;
  NET.on = true; NET.store = {}; NET.calls.length = 0;
  A.setSTORE({ rows: null, checks: null, err: '', busy: false, at: '' });
  A.setFAB(Object.assign({}, wasFab, { rows: [], err: '', busy: false }));
  A.setVO({ rows: null, map: {}, err: '', busy: false, at: '', shown: [] });
  A.setPT(Object.assign({}, wasPT, { base: null }));
  els.fbView.value = 'store';
  A.renderFab();
  await new Promise(r => setTimeout(r, 300));
  const hits = p => NET.calls.filter(c => String(c.url || c).indexOf(p + '.json') >= 0).length;
  ok('opening the store reads the store book once', hits('pt_storeLedger') === 1, String(hits('pt_storeLedger')));
  ok('…the Job Work register once, not fifteen hundred times', hits('pt_baseData') === 1, String(hits('pt_baseData')));
  ok('…and the vendor orders once', hits('pt_vendorOrders') === 1, String(hits('pt_vendorOrders')));
  ok('altogether a handful of reads, not thousands', NET.calls.length < 30, String(NET.calls.length));
  ok('…and the store is loaded, not stuck on "loading"', A.STORE().rows !== null && !A.STORE().busy);

  /* Two things asking for the vendor orders in the same moment — the store and the Demand view do — get
   * one read between them. */
  NET.calls.length = 0;
  A.setVO({ rows: null, map: {}, err: '', busy: false, at: '', shown: [] });
  await Promise.all([A.ensureVo(), A.ensureVo()]);
  ok('two callers at once share one read of the vendor orders', hits('pt_vendorOrders') === 1, String(hits('pt_vendorOrders')));
  ok('…and both come back with it loaded', Array.isArray(A.VO().rows));

  A.setPT(wasPT); A.setVO(wasVO); A.setSTORE(wasStore); A.setFAB(wasFab);
  NET.on = wasNet; NET.store = {}; NET.calls.length = 0; els.fbView.value = wasView;
}

console.log('\n== zippers come off whichever screen issues the pieces ==');
{
  /* Ravi, 2026-09-24: "accessories me zip padi h but ye auto minus nahi ho rhi h." Two holes, found on
   * the live database: the six zippers had vanished from the accessories LIST on 22 Sep, so every
   * deduction failed; and an issue made from the Shopify screen had never deducted at all. */
  const wasPT = A.PT(), wasPTG = A.PTG(), wasPTE = A.PTE(), wasACC = A.ACC(), wasNet = NET.on,
    wasEdit = ME.prodEdit, wasAdmin = ME.admin;
  ME.admin = true; ME.prodEdit = true; NET.on = true; NET.store = {}; NET.calls.length = 0;

  /* ---- 1. a stale or empty copy of the list cannot wipe it ---- */
  NET.store['pt_masters/accessories'] = [{ code: '16', category: 'Zipper' }, { code: '18', category: 'Zipper' }];
  A.setACC(Object.assign({}, wasACC, { items: [{ code: 'THREAD CUT', category: 'Tool' }] }));
  await A.accSaveItems();
  const saved = (NET.store['pt_masters/accessories'] || []).map(x => x.code).sort();
  ok('adding an item from a stale copy keeps what the database already had',
     JSON.stringify(saved) === JSON.stringify(['16', '18', 'THREAD CUT']), JSON.stringify(saved));
  A.setACC(Object.assign({}, A.ACC(), { items: A.ACC().items.filter(x => x.code !== '16') }));
  await A.accSaveItems(['16']);
  const after = (NET.store['pt_masters/accessories'] || []).map(x => x.code).sort();
  ok('…while a real delete still removes the one it names', JSON.stringify(after) === JSON.stringify(['18', 'THREAD CUT']),
     JSON.stringify(after));

  /* ---- 2. the Shopify screen checks and deducts, as the form does ---- */
  A.setPTE(Object.assign({}, wasPTE, { emp: [['Company Contractor', 'Ramesh Kumar', 'Stitching', '']] }));
  A.setPT(Object.assign({}, wasPT, { base: [], cut: [] }));
  A.setPTG(Object.assign({}, wasPTG, { press: [],
    mdb: (wasPTG.mdb || []).concat([{ sku: 'ZIPPC-18', articleType: 'Pillow Cover', subtype: 'Zip Pillow Cover',
      color: 'Red', size: '18x18', isZip: true, chainLength: '18', zipQty: 1 }]),
    ob: [{ id: 'obz', orderNo: 'SHP-9601', sku: 'ZIPPC-18', qty: 10, src: 'SHP', orderDate: '2026-09-24',
      shopOrderNo: '#9601', articleType: 'Pillow Cover', articleSubtype: 'Zip Pillow Cover', color: 'Red', size: '18x18' }] }));
  ok('the pieces are cut', (await A.spCutReal('SHP-9601', 'ZIPPC-18', 10, '2026-09-24', 'CAMBRIC', '')) === '');

  /* No zipper of that length on the list: refused, the way the form refuses it. */
  A.setACC(Object.assign({}, A.ACC(), { items: [{ code: 'THREAD CUT', category: 'Tool' }], ledger: [] }));
  A.setPTE(Object.assign({}, A.PTE(), { acc: A.ACC().items, accLedger: [] }));
  const refused = await A.spIssueReal('SHP-9601', 'ZIPPC-18', 'Company Contractor', 'Ramesh Kumar', 4, '2026-09-24');
  ok('a Shopify issue of a zip SKU is refused when that zipper is not on the list', /not on the accessories list/.test(refused), refused);
  ok('…and nothing is booked', !Object.keys(NET.store).some(k => /^pt_baseData\//.test(k)));

  /* On the list, with stock: issued, and the zippers come off. */
  const items = [{ code: '18', category: 'Zipper' }], ledger = [{ _id: 'in1', txnType: 'IN', itemCode: '18', qty: 50 }];
  A.setACC(Object.assign({}, A.ACC(), { items, ledger }));
  A.setPTE(Object.assign({}, A.PTE(), { acc: items, accLedger: ledger }));
  ok('with the zipper stocked, the issue goes through',
     (await A.spIssueReal('SHP-9601', 'ZIPPC-18', 'Company Contractor', 'Ramesh Kumar', 4, '2026-09-24')) === '');
  const bd = Object.keys(NET.store).find(k => /^pt_baseData\//.test(k));
  const autoKey = bd && ('pt_accLedger/acc_auto_' + NET.store[bd].id);
  const auto = autoKey && NET.store[autoKey];
  ok('…and four 18" zippers come off the shelf, keyed on that issue',
     !!auto && auto.itemCode === '18' && auto.qty === 4 && auto.txnType === 'OUT' && auto.auto === true,
     JSON.stringify(auto || Object.keys(NET.store)));
  ok('…the balance says so', A.ptAccBalance('18') === 46, String(A.ptAccBalance('18')));

  /* Too few on the shelf: refused before anything is written. */
  const low = [{ _id: 'in2', txnType: 'IN', itemCode: '18', qty: 2 }];
  A.setACC(Object.assign({}, A.ACC(), { ledger: low }));
  A.setPTE(Object.assign({}, A.PTE(), { accLedger: low }));
  const short = await A.spIssueReal('SHP-9601', 'ZIPPC-18', 'Company Contractor', 'Ramesh Kumar', 5, '2026-09-24');
  ok('an issue the zipper stock cannot cover is refused', /Take in stock first/.test(short), short);

  A.setPT(wasPT); A.setPTG(wasPTG); A.setPTE(wasPTE); A.setACC(wasACC);
  ME.prodEdit = wasEdit; ME.admin = wasAdmin; NET.on = wasNet; NET.store = {}; NET.calls.length = 0;
}

