console.log('\n== printing cloth by colour and product ==');
{
  /* Ravi, 2026-09-24: "printing fabric color wise ki yadi mere pas ruffle tablecloth ke 60x60 me 100 pcs
   * ka order h to usme mujhe printing fabric kitna required rahega." */
  const was = { ob: A.PTG().ob, mdb: A.PTG().mdb, masters: A.PTG().masters, press: A.PTG().press,
    base: A.PT().base, cut: A.PT().cut, vo: A.VO(), view: els.odView.value };
  const mdb = [
    { sku: 'RTC-YC-6060', articleType: 'Tablecloth', subtype: 'Ruffle Tablecloth', color: 'Yellow Citrine', size: '60x60', fabric: 'Sheeting 62', consumption: 1.85, isRuffle: true, ruffleFabric: 'Sheeting 62', ruffleMeters: 0.9 },
    { sku: 'RTC-YC-6090', articleType: 'Tablecloth', subtype: 'Ruffle Tablecloth', color: 'Yellow Citrine', size: '60x90', fabric: 'Sheeting 62', consumption: 2.6 },
    { sku: 'RTC-AB-6060', articleType: 'Tablecloth', subtype: 'Ruffle Tablecloth', color: 'Apatite Blue', size: '60x60', fabric: 'Sheeting 62', consumption: 1.85 },
  ];
  const ob = [
    { orderNo: 'AMZ-C1', sku: 'RTC-YC-6060', qty: 100, orderDate: '2026-09-01', articleType: 'Tablecloth', articleSubtype: 'Ruffle Tablecloth', color: 'Yellow Citrine', size: '60x60' },
    { orderNo: 'AMZ-C2', sku: 'RTC-YC-6090', qty: 40, orderDate: '2026-09-01', articleType: 'Tablecloth', articleSubtype: 'Ruffle Tablecloth', color: 'Yellow Citrine', size: '60x90' },
    { orderNo: 'AMZ-C3', sku: 'RTC-AB-6060', qty: 10, orderDate: '2026-09-01', articleType: 'Tablecloth', articleSubtype: 'Ruffle Tablecloth', color: 'Apatite Blue', size: '60x60' },
  ];
  A.setPTG(Object.assign({}, A.PTG(), { ob, mdb, press: [], masters: Object.assign({}, A.PTG().masters || {}, { printRule: [] }) }));
  A.setPT(Object.assign({}, A.PT(), { base: [], cut: [] }));
  A.setVO({ rows: [{ vendorCode: 'V1', id: 'VO-C1', status: 'Placed', lines: [{ sku: 'RTC-YC-6060', qty: 30, deliveries: [{ qty: 10 }] }] }],
    map: {}, err: '', busy: false, at: '', shown: [] });
  A.setORD_DEM({ tried: true, busy: false, fabOk: false, voOk: true });

  const d = A.ordDemandColRows();
  const yc = d.cols.find(c => c.colour === 'Yellow Citrine');
  const p6060 = yc && yc.products.find(p => p.size === '60x60');
  ok('each fabric is split by colour', d.cols.length === 2 && !!yc, JSON.stringify(d.cols.map(c => c.fabric + '|' + c.colour)));
  ok('…and each colour by product and size', yc.products.length === 2, JSON.stringify(yc.products.map(p => p.what + ' ' + p.size)));
  ok('100 Ruffle Tablecloth 60x60 need 100 x 1.85 = 185 m of printing cloth',
     p6060 && p6060.pcs === 100 && Math.round(p6060.need * 100) === 18500, JSON.stringify(p6060 && { pcs: p6060.pcs, need: p6060.need }));
  ok('the colour adds its products up: 185 + 40 x 2.6', Math.round(yc.need * 100) === 18500 + 10400, String(yc.need));
  /* The ruffle comes off RFD cloth, so it is shown beside the product and not added to printing. */
  ok('the ruffle strip is shown beside the product — 100 x 0.9 m of Sheeting 62',
     Math.round(p6060.rufM) === 90 && p6060.rufFab === 'Sheeting 62', JSON.stringify({ f: p6060.rufFab, m: p6060.rufM }));
  ok('…and is NOT in the printing total', Math.round(yc.need * 100) === 28900);
  ok('what a printer holds comes off that colour: 20 pieces still owed = 37 m', yc.atPcs === 20 && Math.round(yc.atM) === 37
     && Math.round(yc.give * 100) === 28900 - 3700, JSON.stringify({ a: yc.atPcs, m: yc.atM, g: yc.give }));
  ok('…and the product shows its own pieces at the printer', p6060.atPcs === 20);
  ok('another colour of the same fabric is its own row, with nothing at a printer',
     (c => c && Math.round(c.need * 100) === 1850 && c.atPcs === 0)(d.cols.find(c => c.colour === 'Apatite Blue')));
  ok('the biggest print run comes first', d.cols[0].colour === 'Yellow Citrine');

  els.odView.value = 'democol';
  A.renderOrd();
  const h = els.odTable.innerHTML;
  ok('the view draws a colour row and its product rows under it',
     /Sheeting 62<\/b> · <b>Yellow Citrine/.test(h) && /Ruffle Tablecloth · 60x60/.test(h) && /1\.85 m/.test(h), h.slice(0, 400));
  ok('…with the ruffle cloth named', /Sheeting 62 · 90 m/.test(h));
  ok('…every row with as many cells as there are headings', (() => {
    const heads = (h.match(/<th[\s>]/g) || []).length;
    return (h.split('<tbody>')[1] || '').split('</tr>').filter(r => /<td/.test(r)).every(r => (r.match(/<td[\s>]/g) || []).length === heads);
  })());
  ok('no tick bar on a view with nothing to tick', els.odPickBar._hidden === true && els.odPickBar.innerHTML === '');

  /* Ravi, 2026-09-25: "sirf ye hi dikhe ki 62 ki sheeting me yellow citrine me total fabric kitna chahiye or
   * printer ke pas kitna h". */
  els.odView.value = 'demtot';
  A.renderOrd();
  const t = els.odTable.innerHTML;
  const trs = (t.split('<tbody>')[1] || '').split('</tr>').filter(r => /<td/.test(r));
  ok('the totals view has one line per fabric · colour and no product lines', trs.length === d.cols.length && !/Ruffle Tablecloth · 60x60/.test(t), trs.length + ' vs ' + d.cols.length);
  const ycRow = trs.find(r => /Sheeting 62/.test(r) && /Yellow Citrine/.test(r)) || '';
  ok('…Sheeting 62 · Yellow Citrine says the cloth it needs, what the printers hold, and what is still to give',
     ycRow.indexOf(nf(Math.round(yc.need)) + ' m') >= 0 && ycRow.indexOf(nf(Math.round(yc.atM)) + ' m') >= 0 && ycRow.indexOf(nf(Math.round(yc.give)) + ' m') >= 0, ycRow);
  ok('…every row with as many cells as there are headings', trs.every(r => (r.match(/<td[\s>]/g) || []).length === (t.match(/<th[\s>]/g) || []).length));

  /* Ravi, 2026-09-25: "mujhe pcs assign nahi krne, mujhe running assign karni h … only printer ko 285 assign krna
   * h". The totals view gives RUNNING cloth — the metres still to give — on an ordinary running vendor order. */
  {
    const wasAdmin = ME.admin, wasVO = A.VO(); ME.admin = true;
    A.setVO(Object.assign({}, wasVO, { rows: (wasVO.rows || []).concat([{ vendorCode: 'V2', vendorName: 'A R Textile Printer', id: 'VO-R1',
      status: 'Placed', orderType: 'running', lines: [{ kind: 'running', fabricType: 'Sheeting 62', color: 'Yellow Citrine', meters: 100, deliveries: [] }] }]) }));
    A.setORD({ req: {}, busy: false, at: '', rows: [], pick: new Set() });
    A.renderOrd();
    const t2 = els.odTable.innerHTML;
    const r = A.ORD().demRows.get('SHEETING 62|YELLOW CITRINE');
    const want = Math.round(r.give);
    ok('no piece tick on the totals view any more', !/data-demtot=/.test(t2) && !/Assign printer to/.test(els.odPickBar.innerHTML));
    ok('each colour offers its running cloth still to give — needed less what printers hold', want === Math.round(r.need - r.atM) && want > 0
       && new RegExp('data-demrun="SHEETING 62\\|YELLOW CITRINE"[^>]*>Add ' + nf(want) + ' m<').test(t2), want + ' / ' + (t2.match(/data-demrun="[^"]+"[^>]*>[^<]*</g) || []).join(' | '));
    ok('…and says which printer already has running cloth of it', /A R Textile Printer <span class="muted">100 m<\/span>/.test(t2));
    await A.demRunGive('SHEETING 62|YELLOW CITRINE');
    ok('"Give" opens the ordinary vendor order form, as running, with only what is still to give',
       A.VOF().kind === 'running' && els.vof_qty.value === String(want) && /still to give/.test(els.ptDlgMsg.textContent), els.vof_qty.value + ' · ' + els.ptDlgMsg.textContent);
    ok('…with that colour on that fabric already on an open order taken as known, not asked again', A.VOF().dupOk && A.VOF().dupOk['yellow citrine|sheeting 62|'] === true, JSON.stringify(A.VOF().dupOk));

    /* Ravi, 2026-09-25: "dropdown me printer ko name de dedo or select karke me printer ko assign kar pau". */
    {
      const wasM = A.PTG().masters, wasNet = NET.on, wasC = CONFIRM, wasVoRows = (A.VO().rows || []).slice();
      A.setPTG(Object.assign({}, A.PTG(), { masters: Object.assign({}, wasM, { vendor: [{ code: 'VNDQ', name: 'RBP-Bagru', desc: 'RBP-Bagru', category: 'Printer', active: true },
        { code: 'VNDF', name: 'Filling Co', category: 'Filling', active: true }] }) }));
      A.renderOrd();
      const t3 = els.odTable.innerHTML;
      ok('each row picks a printer by name — printers only — and a print direction, beside Give',
         /data-demprn="SHEETING 62\|YELLOW CITRINE"/.test(t3) && />RBP-Bagru<\/option>/.test(t3) && !/Filling Co/.test(t3) && /data-demdir="SHEETING 62\|YELLOW CITRINE"/.test(t3));
      /* Ravi, 2026-09-25: "yaha kya priority h and kya date h missing h, and … alag alag order open ho rhe h". Rows add to
       * one order per printer; Place order asks for the delivery date and priority once. */
      ok('without a direction nothing is added', /Pick the print direction/.test(A.demBasketAdd('SHEETING 62|YELLOW CITRINE', 'VNDQ', '')));
      const give = Math.round(A.ORD().demRows.get('SHEETING 62|YELLOW CITRINE').give);
      const giveAB = Math.round(A.ORD().demRows.get('SHEETING 62|APATITE BLUE').give);
      NET.on = true; NET.calls = []; CONFIRM = true; ME.admin = true;
      ok('adding a row writes nothing yet', A.demBasketAdd('SHEETING 62|YELLOW CITRINE', 'VNDQ', 'Vertical') === ''
         && A.demBasketAdd('SHEETING 62|APATITE BLUE', 'VNDQ', 'Horizontal') === '' && !NET.calls.some(c => /pt_vendorOrders\/VNDQ/.test(c.url || '')));
      ok('…the bar holds that printer\'s order with both lines, and the rows say they are in it',
         /RBP-Bagru<\/b><span class="muted"[^>]*>2 line\(s\)/.test(els.odPickBar.innerHTML) && els.odPickBar._hidden === false
         && /data-demrm="SHEETING 62\|YELLOW CITRINE"/.test(els.odTable.innerHTML), els.odPickBar.innerHTML);
      A.demBasketPlace('VNDQ');
      ok('Place order asks for the delivery date and the priority', A.PTD_().fields.some(f => f.key === 'deliv' && f.type === 'date') && A.PTD_().fields.some(f => f.key === 'pri'));
      ok('…and will not place without them', /delivery date/.test(await A.PTD_().onSave({ deliv: '', pri: 'P1' })) && /priority/.test(await A.PTD_().onSave({ deliv: '2026-09-30', pri: '' })));
      ok('with them, it places', (await A.PTD_().onSave({ deliv: '2026-09-30', pri: 'P1', notes: '' })) === '');
      const puts = NET.calls.filter(c => c.method === 'PUT' && /pt_vendorOrders\/VNDQ\//.test(c.url || ''));
      const put = puts.pop();
      ok('…ONE order to that printer with both lines, each carrying the date and the priority',
         puts.length === 0 && put && put.body.orderType === 'running' && put.body.lines.length === 2
         && put.body.lines.every(l => l.deliveryDate === '2026-09-30' && l.priority === 'P1')
         && put.body.lines[0].meters === give && put.body.lines[1].meters === giveAB
         && put.body.lines[0].printDirection === 'Vertical' && put.body.lines[1].printDirection === 'Horizontal', put && JSON.stringify(put.body.lines));
      const after = A.ORD().demRows.get('SHEETING 62|YELLOW CITRINE');
      ok('…the rows now count it as with printers, and the bar is empty', Math.round(after.give) === 0 && els.odPickBar._hidden === true, String(after.give));
      NET.on = wasNet; CONFIRM = wasC;
      A.setVO(Object.assign({}, A.VO(), { rows: wasVoRows }));
      A.setPTG(Object.assign({}, A.PTG(), { masters: wasM }));
    }

    /* Ravi, 2026-09-25: with Ordered 13–19 Sep the need was that week's, but "with printers" was everything the
     * printers hold — 300 m against 18 m. Narrowed, the printers' cloth is shared out oldest order first. */
    {
      const wasOb = A.PTG().ob;
      A.setPTG(Object.assign({}, A.PTG(), { ob: wasOb.concat([{ orderNo: 'AMZ-C9', sku: 'RTC-YC-6090', qty: 10, orderDate: '2026-09-15',
        articleType: 'Tablecloth', articleSubtype: 'Ruffle Tablecloth', color: 'Yellow Citrine', size: '60x90' }]) }));
      A.renderOrd();
      const all = A.ORD().demRows.get('SHEETING 62|YELLOW CITRINE');
      ok('unfiltered, "with printers" is all the running cloth the printers hold — 100 m running + 20 pcs × 1.85 m owed on a cut order', Math.round(all.atM) === 137, String(all.atM));
      els.odD1.value = '2026-09-10'; els.odD2.value = '2026-09-30';
      A.renderOrd();
      const wk = A.ORD().demRows.get('SHEETING 62|YELLOW CITRINE');
      ok('filtered to a later week, its order gets only its share — the 137 m went to the older orders first',
         Math.round(wk.need) === 26 && Math.round(wk.atM) === 0 && Math.round(wk.give) === 26, JSON.stringify({ need: wk.need, at: wk.atM, give: wk.give }));
      ok('…the screen says the figure is the orders\' share', /share of what the printers hold, oldest order first/.test(els.odMsg.textContent));
      ok('…and the printer is named without the whole-stock metres beside it', /A R Textile Printer<\/td>|A R Textile Printer</.test(els.odTable.innerHTML) && !/A R Textile Printer <span class="muted">100 m/.test(els.odTable.innerHTML));
      els.odD1.value = ''; els.odD2.value = '2026-09-05';
      A.renderOrd();
      const early = A.ORD().demRows.get('SHEETING 62|YELLOW CITRINE');
      ok('filtered to the older orders, they carry all 137 m the printers hold', Math.round(early.atM) === 137 && Math.round(early.give) === Math.round(early.need - 137), JSON.stringify({ at: early.atM, give: early.give }));
      els.odD1.value = ''; els.odD2.value = '';
      A.setPTG(Object.assign({}, A.PTG(), { ob: wasOb }));
    }
    A.setVO(wasVO);
    A.setORD({ req: {}, busy: false, at: '', rows: [], pick: new Set() });
    ME.admin = wasAdmin;
  }

  els.odView.value = was.view;
  A.setPTG(Object.assign({}, A.PTG(), { ob: was.ob, mdb: was.mdb, masters: was.masters, press: was.press }));
  A.setPT(Object.assign({}, A.PT(), { base: was.base, cut: was.cut }));
  A.setVO(was.vo);
  A.setORD_DEM({ tried: false, busy: false, fabOk: false, voOk: false });
}

console.log('\n== printer allocation: clear what was fed, to upload it again ==');
{
  /* Ravi, 2026-09-25: "ye sare delete krne h, m khud upload karunga" — "option do m khud kr lunga". */
  const wasAdmin = ME.admin, wasNet = NET.on, wasPAL = A.PAL();
  ME.admin = true; NET.on = true; NET.calls = [];
  NET.store['pt_colorGroups'] = { at: 'x', by: 'y', map: { 'CPC|Agate Green': 'CPC Green', 'RBP|White': 'RBP White' }, live: { 'CPC|Old Rose': false } };
  NET.store['pt_blockNeed'] = { map: { 'CPC|Agate Green': 4 } };
  NET.store['pt_blockHave'] = { p1: { 'CPC|Agate Green': 2 } };
  NET.store['pt_printers'] = { p1: { name: 'RBP-Bagru', pcsMonth: 13280 } };
  A.setPAL(Object.assign({}, wasPAL, { groups: NET.store['pt_colorGroups'], need: NET.store['pt_blockNeed'], have: NET.store['pt_blockHave'],
    printers: [{ key: 'p1', name: 'RBP-Bagru', pcsMonth: 13280 }] }));
  ok('nothing ticked is refused', /Tick what to delete/.test(await A.palClearRun([], true)));
  ok('saying no deletes nothing', /Not deleted/.test(await A.palClearRun(['groups'], false)) && !NET.calls.some(c => c.method === 'PATCH'));
  DOWNLOADS.length = 0;
  ok('ticked and confirmed, it deletes', (await A.palClearRun(['groups', 'need'], true)) === '');
  ok('…with no backup file (Ravi: not needed)', !DOWNLOADS.length, JSON.stringify(DOWNLOADS));
  const pt = NET.calls.filter(c => c.method === 'PATCH').pop();
  ok('…only what was ticked goes: groups emptied, stopped designs kept, blocks per design gone, printers and held blocks untouched',
     pt && pt.body.pt_colorGroups && Object.keys(pt.body.pt_colorGroups.map).length === 0 && pt.body.pt_colorGroups.live['CPC|Old Rose'] === false
     && pt.body.pt_blockNeed === null && !('pt_printers' in pt.body) && !('pt_blockHave' in pt.body), pt && JSON.stringify(pt.body));
  ok('…and the screen forgets them', Object.keys(A.PAL().groups.map).length === 0 && Object.keys(A.PAL().need.map).length === 0 && A.PAL().printers.length === 1);
  ME.admin = false; ME.prodEdit = false;
  ok('without the production edit right it refuses', /need the production edit right/.test(await A.palClearRun(['printers'], true)));
  ME.admin = wasAdmin; NET.on = wasNet; A.setPAL(wasPAL);
  ['pt_colorGroups', 'pt_blockNeed', 'pt_blockHave', 'pt_printers'].forEach(k => { delete NET.store[k]; });
}

console.log('\n== a printer\'s standing order sits where its newest lines are ==');
{
  /* Ravi, 2026-09-25: "mene order printer ko assign kiya but vendor order me show nahi ho rha h" — the lines had
   * gone onto VPO-SHOP-VND004, raised 19/09, sorted below every order raised since. */
  const standing = { id: 'vpo_shop_VND004', orderNo: 'VPO-SHOP-VND004', orderDate: '19/09/2026', staffUpdatedAt: '2026-09-25T06:01:00.107Z' };
  const today = { id: 'vpo_x', orderNo: 'VPO-260925-05S', orderDate: '25/09/2026' };
  const older = { id: 'vpo_y', orderNo: 'VPO-260923-5I3', orderDate: '23/09/2026' };
  ok('the standing order is known as one', A.voIsStanding(standing) && !A.voIsStanding(today));
  const sorted = [older, today, standing].sort((a, b) => A.voSortMs(b) - A.voSortMs(a)).map(o => o.orderNo);
  ok('…and sorts by when lines were last put on it, above orders raised earlier that day', sorted[0] === 'VPO-SHOP-VND004' && sorted[2] === 'VPO-260923-5I3', sorted.join(', '));
  ok('an ordinary order still sorts by the day it was raised', A.voSortMs(today) === A.ptDtMs('25/09/2026'));
  const src = fs.readFileSync(APP, 'utf8');
  ok('the list says it is the standing order, and when lines were last added', /assigned lines<\/span>\$\{o\.staffUpdatedAt \? ` <span class="muted" style="font-size:11px">added /.test(src));
  ok('the assign message names the order the lines went on', /on their order \$\{spShopOrderNo\(want\)\} in Vendor Orders/.test(src));
}

console.log('\n== what a SKU is comes from the master, not the copy on the order ==');
{
  /* Ravi, 2026-09-25: "master data me sku sahi h but order console me sku wrong aa rha h" — CPCRU006-4 showed
   * "Square Tablecloth", the name copied onto the order line; the master says Ruffle Square Tablecloth. */
  const was = { ob: A.PTG().ob, mdb: A.PTG().mdb };
  A.setPTG(Object.assign({}, A.PTG(), {
    mdb: [{ sku: 'CPCRU006-4', articleType: 'Tablecloth', subtype: 'Ruffle Square Tablecloth', color: 'Indigo Blue', size: '60x60' }],
    ob: [{ id: 'x1', orderNo: 'AMZ-24092026-02', sku: 'CPCRU006-4', qty: 30, src: 'SO', articleType: 'Tablecloth', articleSubtype: 'Square Tablecloth', color: 'Indigo Blue', size: '60x60' },
         { id: 'x2', orderNo: 'AMZ-24092026-02', sku: 'NOT-IN-MASTER', qty: 2, src: 'SO', articleType: 'Napkin', articleSubtype: 'Plain Napkin', color: 'Red', size: '18x18' }] }));
  const l = A.ordLines().find(x => x.sku === 'CPCRU006-4');
  ok('the Order Console shows the master\'s subtype for the SKU', l && l.articleSubtype === 'Ruffle Square Tablecloth', l && l.articleSubtype);
  ok('…and so does every screen reading the order book', (A.obLines().find(x => x.sku === 'CPCRU006-4') || {}).articleSubtype === 'Ruffle Square Tablecloth');
  ok('a SKU the master does not have keeps the order\'s own copy', (A.ordLines().find(x => x.sku === 'NOT-IN-MASTER') || {}).articleSubtype === 'Plain Napkin');
  A.setPTG(Object.assign({}, A.PTG(), { ob: was.ob, mdb: was.mdb }));
}

console.log('\n== metres to two places ==');
{
  /* Ravi, 2026-09-24: consumption showed as 1.2953999999999999 — "ye auto . ke bad only 2 digit me aay". */
  ok('a raw inch conversion comes out to two places', A.mdbM2(51 * 0.0254) === 1.3 && A.mdbM2Txt(51 * 0.0254) === '1.30',
     A.mdbM2(51 * 0.0254) + ' / ' + A.mdbM2Txt(51 * 0.0254));
  ok('…and float noise with it', A.mdbM2Txt('2.2352000000000003') === '2.24' && A.mdbM2Txt(1.78) === '1.78');
  ok('a blank stays blank', A.mdbM2('') === null && A.mdbM2Txt('') === '');
  const rec = A.mdbRecord({ sku: 'X-1', consumption: '1.2953999999999999', isRuffle: 'yes', ruffleMeters: '0.73659999999999992',
    isPiping: 'yes', pipingMeters: '2.2352000000000003', fillerFabricRequired: 'yes', standardFillingQty: '0.125' }, false);
  ok('a SKU is stored with its metres to two places', rec.consumption === 1.3 && rec.ruffleMeters === 0.74 && rec.pipingMeters === 2.24,
     JSON.stringify({ c: rec.consumption, r: rec.ruffleMeters, p: rec.pipingMeters }));
  ok('…and nothing that is not metres is touched', rec.standardFillingQty === 0.125, String(rec.standardFillingQty));
  const says = A.recipeSays([{ consumption: '1.2953999999999999' }, { consumption: 1.3 }, { consumption: '1.30' }], 'consumption');
  ok('the Recipe counts 1.2954 and 1.3 as one answer, not a disagreement', !says.conflict && says.agreed === '1.3', JSON.stringify(says.values));
  const src = fs.readFileSync(APP, 'utf8');
  ok('the Master Database cell shows two places', /mdbM2Txt\(r\.consumption\)/.test(src));
}

console.log('\n== cut pieces are printing demand in pieces, not metres ==');
{
  /* Ravi, 2026-09-24: "jo cut pcs like jisme cutting required nahi h wo direct cut pcs me printing ke liye
   * jate h, unki sheeting running me printing nahi hoti h, to usko direct pcs me track karenge." */
  const was = { ob: A.PTG().ob, mdb: A.PTG().mdb, masters: A.PTG().masters, press: A.PTG().press,
    base: A.PT().base, cut: A.PT().cut, vo: A.VO(), fab: A.FAB(), view: els.odView.value };
  const rules = [
    { articleType: 'Tablecloth', subtype: 'Square Tablecloth', issueAs: 'cut' },
    { articleType: 'Pillow Cover', subtype: 'Ruffle Pillow Cover', issueAs: 'running' },
    { articleType: 'Napkin', subtype: 'Embroidery Napkin', issueAs: 'running' },
  ];
  const mdb = [
    { sku: 'SQ-RED-6060', articleType: 'Tablecloth', subtype: 'Square Tablecloth', color: 'Red', size: '60x60', fabric: 'Sheeting 92', consumption: 1.6 },
    { sku: 'RT-RED-90', articleType: 'Tablecloth', subtype: 'Round Tablecloth', color: 'Red', size: '90 Round', fabric: 'Sheeting 92', consumption: 2.4, cuttingRequired: false },
    { sku: 'RPC-RED-1818', articleType: 'Pillow Cover', subtype: 'Ruffle Pillow Cover', color: 'Red', size: '18x18', fabric: 'Sheeting 92', consumption: 0.5 },
    { sku: 'EN-RED-1818', articleType: 'Napkin', subtype: 'Embroidery Napkin', color: 'Red', size: '18x18', fabric: 'Sheeting 92', consumption: 0.25, cuttingRequired: false },
    { sku: 'SQ-NOC-6060', articleType: 'Tablecloth', subtype: 'Square Tablecloth', color: 'Blue', size: '60x60', fabric: 'Sheeting 92' },
  ];
  const ln = (no, sku, qty) => { const m = mdb.find(x => x.sku === sku);
    return { orderNo: no, sku, qty, orderDate: '2026-09-01', articleType: m.articleType, articleSubtype: m.subtype, color: m.color, size: m.size }; };
  A.setPTG(Object.assign({}, A.PTG(), { mdb, press: [],
    masters: Object.assign({}, A.PTG().masters || {}, { printRule: rules }),
    ob: [ln('AMZ-P1', 'SQ-RED-6060', 100), ln('AMZ-P2', 'RT-RED-90', 20), ln('AMZ-P3', 'RPC-RED-1818', 200),
      ln('AMZ-P4', 'EN-RED-1818', 40), ln('AMZ-P5', 'SQ-NOC-6060', 10)] }));
  A.setPT(Object.assign({}, A.PT(), { base: [], cut: [] }));
  A.setVO({ rows: [{ vendorCode: 'V1', id: 'VO-P1', status: 'Placed',
    lines: [{ sku: 'SQ-RED-6060', qty: 30, deliveries: [{ qty: 5 }] }, { sku: 'RPC-RED-1818', qty: 40 }] }],
    map: {}, err: '', busy: false, at: '', shown: [] });
  A.setFAB({ rows: [{ fabricType: 'Sheeting 92', txnType: 'OPENING_RFD', qty: 100 }], err: '', busy: false, at: '', shown: [] });
  A.setORD_DEM({ tried: true, busy: false, fabOk: true, voOk: true });

  const sku = k => mdb.find(x => x.sku === k);
  ok('a subtype ruled "given to the printer as cut" is printed as pieces', A.ordPrintAsPcs(sku('SQ-RED-6060')) === true);
  ok('with no rule, "Cutting required: no" means cut pieces — Ravi\'s rule', A.ordPrintAsPcs(sku('RT-RED-90')) === true);
  ok('a rule that says running wins over the flag', A.ordPrintAsPcs(sku('EN-RED-1818')) === false);
  ok('everything else is running cloth', A.ordPrintAsPcs(sku('RPC-RED-1818')) === false);

  const d = A.ordDemandRows();
  const r = d.rows.find(x => x.fabric === 'Sheeting 92');
  ok('cut pieces to print are counted in pieces: 100 + 20 + 10', r.cutPcs === 130, String(r.cutPcs));
  ok('…and are NOT in the running metres: 200 x 0.5 + 40 x 0.25', Math.round(r.runNeed * 100) === 11000, String(r.runNeed));
  ok('a cut piece with no consumption is still a piece to print', r.cutPcs === 130 && d.cutNoConsPcs === 10, String(d.cutNoConsPcs));
  ok('pieces a printer still owes come off pieces to give: 25 owed', r.cutAtPcs === 25 && r.cutGive === 105, JSON.stringify({ a: r.cutAtPcs, g: r.cutGive }));
  ok('running cloth at a printer comes off running to give: 40 x 0.5 = 20 m', Math.round(r.runAtM) === 20 && Math.round(r.runGive) === 90,
     JSON.stringify({ a: r.runAtM, g: r.runGive }));
  /* The cloth is still cloth: cut pieces are cut from RFD, so they stay in what the shelf must cover. */
  ok('the RFD requirement still holds the cut pieces\' cloth: 100 x 1.6 + 20 x 2.4 + 110', Math.round(r.need) === 318, String(r.need));
  ok('…and Short by is all of it less the shelf', Math.round(r.short) === Math.round(318 - (25 * 1.6 + 20) - 100), String(r.short));

  const c = A.ordDemandColRows();
  const red = c.cols.find(x => x.colour === 'Red');
  const sq = red.products.find(p => p.what === 'Square Tablecloth');
  ok('by colour: the colour carries running metres and cut pieces apart', Math.round(red.need) === 110 && red.cutPcs === 120,
     JSON.stringify({ m: red.need, p: red.cutPcs }));
  ok('…a cut-piece product has no metres a piece, and says pieces to give', sq.asPcs === true && sq.need === 0 && sq.cutGive === 75,
     JSON.stringify({ as: sq.asPcs, need: sq.need, give: sq.cutGive }));
  els.odView.value = 'democol';
  A.renderOrd();
  ok('…and the row says it is printed as cut pieces', /Cut pieces/.test(els.odTable.innerHTML) && /75 pcs/.test(els.odTable.innerHTML));

  els.odView.value = was.view;
  A.setPTG(Object.assign({}, A.PTG(), { ob: was.ob, mdb: was.mdb, masters: was.masters, press: was.press }));
  A.setPT(Object.assign({}, A.PT(), { base: was.base, cut: was.cut }));
  A.setVO(was.vo); A.setFAB(was.fab);
  A.setORD_DEM({ tried: false, busy: false, fabOk: false, voOk: false });
}

console.log('\n== the Production menu is a mega menu ==');
{
  /* Ravi, 2026-09-24: "2 — Mega menu", and of the red 26 on Finished Goods, "yaha 26 kya indicate kar raha h". */
  const src = fs.readFileSync(APP, 'utf8');
  const a = src.indexOf('<div class="navsec navmega" id="secProd">');
  const sec = a < 0 ? '' : src.slice(a, src.indexOf('</div></div>', a));
  ok('Production opens as a mega menu', a > 0);
  const heads = [...sec.matchAll(/<div class="mg-h">([^<]+)<\/div>/g)].map(m => m[1]);
  ok('…in five columns, in the order work moves', heads.join('|') === 'Orders|Making|Finished &amp; dispatch|Materials|Setup', heads.join('|'));
  const tabs = ['tabSo', 'tabOrd', 'tabCx', 'tabPcut', 'tabPbase', 'tabPpress', 'tabQc', 'tabFgi', 'tabFba', 'tabFab', 'tabAcc', 'tabPmdb', 'tabMst'];
  ok('every Production screen is still there, once', tabs.every(t => (src.match(new RegExp('id="' + t + '"', 'g')) || []).length === 1 && sec.indexOf('id="' + t + '"') > 0),
     tabs.filter(t => sec.indexOf('id="' + t + '"') < 0).join(','));
  /* "26" alone told nobody what it counted. */
  const badges = [...sec.matchAll(/<span id="(\w+Badge)"[^>]*>/g)].map(m => m[0]);
  ok('every count in it carries the words for what it counts', badges.length === 4 && badges.every(b => /data-what="[^"]+"/.test(b)),
     badges.length + ': ' + badges.filter(b => !/data-what=/.test(b)).join(' | '));
  /* Ravi, 2026-09-25: "26 not amazon, 3 to approve, 11 over order ye listing ke andar aana chahiye". */
  ok('the three Finished Goods counts are not in the menu', !/fgiLstBadge|fgiCorrBadge|fgiOverBadge/.test(sec));
  /* Ravi, 2026-09-25: on a store account's phone the menu bar was gone, with nothing to bring it back. */
  ok('the menu bar is never shut: not by a remembered "closed", not by a narrow screen',
     /localStorage\.removeItem\('replNavShut'\); \} catch \(e\) \{\}\s*setNavOpen\(true, false\);/.test(src) && !/getItem\('replNavShut'\)/.test(src)
     && !/if \(NARROW\(\)\) setNavOpen\(false/.test(src) && !/\.shell\.navshut \.side\{display:none\}/.test(src)
     && !/\.side\{position:fixed;top:0;left:0;bottom:0/.test(src));
  {
    const fg = src.slice(src.indexOf('<div id="fgAlerts"'), src.indexOf('<div id="fgMsg"'));
    ok('…they are on the Finished Goods screen, each a button that opens its list',
       /<button type="button" id="fgiLstBadge"[^>]*data-fgview="alerts"[^>]*data-what="not on Amazon"/.test(fg)
       && /id="fgiCorrBadge"[^>]*data-fgview="corr"/.test(fg) && /id="fgiOverBadge"[^>]*data-fgview="over"/.test(fg), fg.slice(0, 300));
  }
  ok('…and the words are shown in the menu', /\.navmega \.navbadge\[data-what\]::after\{content:" " attr\(data-what\)/.test(src));
  ok('a column with nothing this account may open says nothing', /\.mg-col:not\(:has\(> \.nav:not\(\[style\*="none"\]\)\)\)\{display:none\}/.test(src));
}

console.log('\n== every menu item is a link a new tab can open ==');
{
  /* Ravi, 2026-09-24: "yaha right click kru to open to new window dikhay". The browser offers "open in
   * new tab / window" only on a link; the menu items were buttons. */
  const src = fs.readFileSync(APP, 'utf8');
  const side = src.slice(src.indexOf('<aside class="side">'), src.indexOf('</aside>'));
  const links = [...side.matchAll(/<a id="(tab\w+)" class="nav" href="#(\w+)"/g)];
  ok('all 35 menu items are links with an address', links.length === 35, String(links.length));
  ok('…and not one of them is still a button', !/<button id="tab\w+" class="nav"/.test(side));
  const navs = (src.match(/const navs = \{([^}]+)\};/) || [])[1] || '';
  ok('…each address is the screen its item opens', links.every(([, id, key]) => new RegExp('\\b' + key + ": '" + id + "'").test(navs)),
     links.filter(([, id, key]) => !new RegExp('\\b' + key + ": '" + id + "'").test(navs)).map(x => x[1]).join(','));
  ok('showTab writes the screen into the address', /history\.replaceState\(null, '', '#' \+ which\)/.test(src));
  ok('sign-in opens the screen the address names', /showTab\(navHashTab\(\) \|\| ME\.tabs\[0\]\)/.test(src));
  ok('a Ctrl or middle click opens the new tab without also switching this one',
     /e\.ctrlKey \|\| e\.metaKey \|\| e\.shiftKey \|\| e\.button > 0\)\) e\.stopPropagation\(\)/.test(src));
  ok('the Shopify-only name changes the words, not the icon and the count', /\(t \|\| b\)\.textContent = 'Shopify Orders'/.test(src));
}

console.log('\n== the installed app ==');
{
  /* "mobile me app install kar liya to wo mobile app ki tarah react kare" — 2026-09-22. */
  const src = fs.readFileSync(APP, 'utf8');
  const dir = require('path').dirname(APP);
  ok('a phone draws the desktop layout, scaled to fit, as before 22 Sep (Ravi asked for it back)', !/<meta name="viewport"/.test(src) && !/mob-fold/.test(src));
  ok('the manifest is linked', /<link rel="manifest" href="\/manifest\.webmanifest">/.test(src));
  const man = JSON.parse(fs.readFileSync(dir + '/manifest.webmanifest', 'utf8'));
  ok('it opens full screen, from its own icon', man.display === 'standalone' && man.start_url && man.icons.some(i => i.sizes === '512x512')
    && man.icons.some(i => i.purpose === 'maskable'));
  ok('…and every icon it names is there', man.icons.every(i => fs.existsSync(dir + i.src)) && fs.existsSync(dir + '/apple-touch-icon.png'));
  const sw = fs.readFileSync(dir + '/sw.js', 'utf8');
  ok('the service worker is registered', /navigator\.serviceWorker\.register\('\/sw\.js'\)/.test(src));
  ok('…fetches the page from the network first, so a fix reaches every phone', /fetch\(req\)\.then\(res =>/.test(sw) && /\.catch\(\(\) => caches\.match/.test(sw));
  ok('…and never stands in for a database or sign-in call', /if \(url\.origin !== self\.location\.origin\) return;/.test(sw) && /if \(req\.method !== 'GET'\) return;/.test(sw));
}
console.log('\n== Reports: Shopify dispatch ==');
{
  /* Ravi, 2026-09-24: "kitne order dispatch hue via mcf, via fedex, dhl and pending order as well and konse
   * article sabse jyada pending h". */
  const L = (sku, name, qty, extra) => Object.assign({ sku, name, qty, rq: 0, ffl: '' }, extra || {});
  const O = [
    { id: '1', shopBrand: 'SP', at: '2026-09-02', ff: 'fulfilled', trkCo: 'Amazon Logistics', items: [L('A', 'Napkins - Red', 2, { ffl: 'fulfilled' })] },
    { id: '2', shopBrand: 'SP', at: '2026-09-03', ff: 'fulfilled', trkCo: 'FedEx', items: [L('B', 'Runner - Blue', 1, { ffl: 'fulfilled' })] },
    { id: '3', shopBrand: 'CPC', at: '2026-09-04', ff: 'fulfilled', trkCo: 'DHL Express', items: [L('C', 'Tablecloth - Vine', 1, { ffl: 'fulfilled' })] },
    { id: '4', shopBrand: 'CPC', at: '2026-09-05', ff: 'fulfilled', trkCo: 'USPS', items: [L('C', 'Tablecloth - Vine', 1, { ffl: 'fulfilled' })] },
    { id: '5', shopBrand: 'SP', at: '2026-09-06', ff: 'fulfilled', trkCo: '', items: [L('A', 'Napkins - Red', 1, { ffl: 'fulfilled' })] },
    { id: '6', shopBrand: 'SP', at: '2026-09-07', ff: 'unfulfilled', items: [L('T1', 'Cotton Block Print Tablecloth - Autumn Vine', 3), L('N1', 'Napkins - Red', 1)] },
    { id: '7', shopBrand: 'CPC', at: '2026-09-01', ff: 'partial', items: [L('T1', 'Cotton Block Print Tablecloth - Autumn Vine', 2, { fq: 1 }), L('N1', 'Napkins', 4, { ffl: 'fulfilled' })] },
    { id: '8', shopBrand: 'CPC', at: '2026-09-08', ff: 'unfulfilled', cancelledAt: '2026-09-09', items: [L('T1', 'x', 5)] },
    { id: '9', shopBrand: 'SP', at: '2026-09-09', ff: 'unfulfilled', items: [L('T1', 'x', 2, { rq: 2, fq: 0 })] },
  ];
  const meta = { 5: { mcfId: 'SHOP-5' } };
  const d = A.repShopDispatch(O, id => meta[id]);
  ok('dispatched orders are counted by the carrier Shopify names', d.via.MCF.SP === 2 && d.via.FedEx.SP === 1 && d.via.DHL.CPC === 1 && d.via.Other.CPC === 1,
     JSON.stringify(d.via));
  ok('…an MCF id recorded in this app counts as MCF even when Shopify names no carrier', A.repShipVia({ trkCo: '' }, { mcfId: 'X' }) === 'MCF');
  ok('…and one with no carrier anywhere is said as such, not guessed', A.repShipVia({ trkCo: '' }, {}) === 'No carrier');
  ok('placed, shipped, pending, cancelled and refunded are told apart',
     d.st.placed.SP + d.st.placed.CPC === 9 && d.st.shipped.SP === 3 && d.st.shipped.CPC === 2 && d.st.pending.SP === 1 && d.st.pending.CPC === 1
     && d.st.cancelled.CPC === 1 && d.st.closed.SP === 1, JSON.stringify(d.st));
  ok('a partly shipped order is pending, and only what is left counts', A.repShopState(O[6]) === 'pending' && A.repShopLeft(O[6].items[0]) === 1 && A.repShopLeft(O[6].items[1]) === 0);
  const top = d.arts[0];
  ok('the most pending article comes first, with its pieces, orders and shops',
     top.art === 'Cotton Block Print Tablecloth' && top.pcs === 4 && top.orders === 2 && top.SP === 3 && top.CPC === 1 && top.oldest === '2026-09-01',
     JSON.stringify(d.arts));
  ok('…a cancelled or refunded order adds nothing to pending', d.arts.reduce((t, a) => t + a.pcs, 0) === 5, JSON.stringify(d.arts));
  const src = fs.readFileSync(APP, 'utf8');
  ok('Reports offers it', /<option value="shpd">Shopify dispatch<\/option>/.test(src));
  ok('the Order Console has a complete window beside the pending one',
     /<option value="shopdone">Shopify — complete &amp; handed over<\/option>/.test(src) && /Shopify — by order \(pending\)/.test(src));
}
